\begin{restatable}{corollaryx}{mainpropertiescount}
    \label{corollary:main-properties-count}
    Let $M \in \repf(\Zbb^2)$.
    \begin{enumerate}
        %\item $\Ncaltwo(M) \geq 0$.
        \item $\Ncaltwo(M) \geq \dim M_i$ for every $i \in \Zbb^2$.
        \item $\Ncaltwo(M) = 0$ if and only if $M \cong 0$.
        \item $\Ncaltwo(M) = 1$ if and only if $M$ is a spread representation.
        \item $\Ncaltwo(M) \geq \Ncaldec(M)$, and $\Ncaltwo(M) = \Ncaldec(M)$ if and only if $M$ is spread-decomposable.
    \end{enumerate}
\end{restatable}

