\subsection{Additive invariants and bases}
\label{section:additive-invariants}

The following definitions are based on \cite{blanchette-brustle-hanson,amiot-brustle-hanson}; see \cite{escolar-kim} for an essentially equivalent setup.

\begin{definition}
    Let $\Acal$ be an additive category.
    An \emph{additive invariant} on $\Acal$ is a function $\alpha : \Acal \to G$ mapping objects of $\Acal$ to an Abelian group $G$, which is isomorphism invariant (i.e., $\alpha(X) = \alpha(Y)$ whenever $X \cong Y \in \Acal$) and additive (i.e., $\alpha(X \oplus Y) = \alpha(X) + \alpha(Y)$ for all $X,Y \in \Acal$).
\end{definition}

\begin{definition}
    If $\alpha$ and $\beta$ are additive invariants on $\Acal$, we say that $\alpha$ \emph{is finer} than $\beta$, and write $\alpha \succcurlyeq \beta$, if $\alpha(X) = \alpha(Y)$ implies $\beta(X) = \beta(Y)$ for all $X,Y \in \Acal$.
    If $\alpha \succcurlyeq \beta$ and $\beta \succcurlyeq \alpha$, we say that $\alpha$ and $\beta$ are \emph{equivalent}, and write $\alpha \approx \beta$.
\end{definition}

\begin{definition}
    A \emph{basis} for an additive invariant $\alpha : \Acal \to G$ consists of an indexed collection of objects $\{M_i \in \Acal\}_{i \in I}$, such that for every $M \in \Acal$ there exists a unique indexed collection of integers $\{c^M_i \in \Zbb\}_{i \in I}$ such that $c_i \neq 0$ for finitely many $i \in I$, and such that
    \[
        \alpha(M) = \sum_{i \in I} c^M_i \cdot \alpha(M_i).
    \]
\end{definition}




\section{Counts for poset representations}
\label{section:counts}

By a \emph{count} we mean an additive invariant (\cref{section:additive-invariants}) taking values in $\Zbb$.

\subsection{An inclusion-exclusion type count}
Our first count is a natural generalization of $\Ncaltwo$.

\begin{definition}
    \label{definition:N-inclusion-exclusion}
    Let $n \geq 1 \in \Nbb$.
    The \emph{inclusion-exclusion count} $\Ninclexcl : \repf(\Zbb^n) \to \Zbb$ is
    \[
        \Ninclexcl(M) \coloneqq \sum_{S \subseteq \{1, \dots, n\}} (-1)^{|S|}\, \dim \left(\xbf_S\, M \right)\,,
    \]
    where, if $S = \{s_1, \dots s_\ell\}$, we let $\xbf_S = \xbf_{s_1} \cdots \xbf_{s_\ell}$.
\end{definition}

Note that, when $n = 2$, the count $\Ninclexcl$ specializes to $\Ncaltwo$.


\subsection{Counts from end-curves}
We define end-curves and their associated count.

%Recall that we have a fully faithful embedding $\rep(\Zbb^2) \hookrightarrow 2\text{-}\mathrm{gr.mod}_{\kbb[\xbf, \ybf]}$.

\begin{definition}
    A representation $M \in \Rep(\Zbb^2)$ is \emph{ephemeral} if $\xbf\ybf M = 0$.
\end{definition}

\begin{definition}
    A \emph{spread curve} is a spread $I \subseteq \Zbb^2$ such that $p \in I$ implies $p+(1,1) \notin I$.
    A \emph{spread curve representation} is a representation of the form $\kbb_I$ with $I$ a spread curve.
\end{definition}

Equivalently, a spread curve is a spread $I$ such that $\kbb_I$ is ephemeral.


