\begin{theorem}
    \label{theorem:decomposition-theorem-ephemeral}
    Every ephemeral representation in $\rep(\Zbb^2)$ decomposes in an essentially unique way as a direct sum of spread curve representations, which are indecomposable.
\end{theorem}
