\begin{definition}
    \label{definition:births-deaths}
    Let $\spreadcurves$ denote the set of spread curves of $\Zbb^2$.
    We define the additive invariants $\births,\deaths : \rep(\Zbb^2) \to \Zbb^{\spreadcurves}$ to be the unique ones satisfying
    \[
        \cokerxy{M} \cong \bigoplus_{I \in \spreadcurves} (\kbb_I)^{\births(M)(I)} \;\;\; \text{and} \;\;\;
        \kerxy{M} \cong \bigoplus_{I \in \spreadcurves} (\kbb_I)^{\deaths(M)(I)},
    \]
    for every $M \in \rep(\Zbb^2)$.
\end{definition}


The following is immediate.

\begin{lemma}
    \label{lemma:spread-curves-basis-for-birth-death}
    Let $\spreadcurvesf$ be the set of finite curves of $\Zbb^2$.
    The set $\{\kbb_I\}_{I \in \spreadcurvesf}$ forms a basis for both additive invariants $\births$ and $\deaths$ on $\repf(\Zbb^2)$.
    \qed
\end{lemma}

We can then define two counts for a representation $M\in \repf(\Zbb^2)$, which simply count the number of birth- and death-curves of $M$.

\begin{definition}
    We define two counts $\repf(\Zbb^2) \to \Zbb$ as
    \[
        \Ncal^{\births} \coloneqq \Ncal^{\left(\births,\, \{\kbb_I\}_{I \in \spreadcurvesf}\right)}
        \;\;\; \text{and} \;\;\;
        \Ncal^{\deaths} \coloneqq \Ncal^{\left(\deaths,\, \{\kbb_I\}_{I \in \spreadcurvesf}\right)}.
    \]
\end{definition}

