\subsection{Counts from additive invariants and bases}
The following is a natural way to produce a count from an additive invariant together with a basis; we prove \cref{corollary:standard-way-of-producing-count} that any count satisfying mild assumptions is of this form.

\begin{definition}
    \label{definition:counting-function-from-basis}
    Let $\Acal$ be an additive category, let $\Bcal = \{M_i \in \Acal\}_{i \in I}$ be a basis for an additive invariant $\alpha : \Acal \to G$, and let $f : \Bcal \to \Zbb$ be any function.
    The \emph{count associated} to $\alpha$, $\Bcal$, and $f$ is given by
    \[
        \Ncal^{(\alpha,\Bcal,f)}(M) \coloneqq \sum_{i \in I} c^M_i \cdot f(M_i).
    \]
    If $f$ is constantly $1$, then we simplify notation and write
    $\Ncal^{(\alpha,\Bcal)}(M) \coloneqq \sum_{i \in I} c^M_i$.
\end{definition}

This count satisfies the following useful characterization.


%Refinement is a transitive and reflexive relation on additive invariants on $\Acal$.

%\begin{notation}
%    If the rank invariant is determined by an additive invariant $\alpha$, we say that $\alpha$ is \emph{rank-determining}.
%\end{notation}


\begin{proposition}
    \label{lemma:basic-results-counts-basis}
    Let $\Acal$ be an additive category, let $\Bcal = \{M_i \in \Acal\}_{i \in I}$ be a basis for an additive invariant $\alpha : \Acal \to G$, and let $f : \Bcal \to \Zbb$.
    Then, the count $\Ncal^{(\alpha,\Bcal,f)}$ is the unique additive invariant $\Ncal  : \Acal \to \Zbb$ satisfying
    \begin{enumerate}
        \item $\alpha \succcurlyeq \Ncal$.
        \item $\Ncal(M_i) = f(M_i)$ for all $i \in I$.
    \end{enumerate}
\end{proposition}
\begin{proof}
    It is clear that $\Ncal^{(\alpha,\Bcal,f)}$ satisfies (1) and (2).
    Let $\Ncal$ also satisfy (1) and (2).
    Given $M \in \Acal$, let $\alpha(M) = \sum_{i \in I} c_i^M \cdot \alpha(M_i)$.
    By \cref{lemma:additivity-finer-invariant}, and the fact that $\Ncal$ equals $f$ on the elements of $\Bcal$, we have $\Ncal(M) = \sum_{i \in I} c_i^M \cdot \Ncal(M_i)= \sum_{i \in I} c_i^M \cdot f(M_i)$, which equals $\Ncal^{(\alpha, \Bcal,f)}(M)$, by \cref{definition:counting-function-from-basis}.
\end{proof}

%\begin{lemma}
%    Let $\Acal$ be an additive category, let $\alpha : \Acal \to G$ and $\Ncal : \Acal \to \Zbb$ be additive invariants, and let $\Bcal = \{M_i \in \Acal\}_{i \in I}$ be basis for $\alpha$.
%    If $\alpha \succcurlyeq \Ncal$, and $\Ncal(M_i) = 1$ for every $i \in I$, then $\Ncal = \Ncal^{(\alpha,\Bcal)}$.
%\end{lemma}
%\begin{proof}
%\end{proof}

\cref{lemma:basic-results-counts-basis} implies, in particular, that any count $\Ncal$ that can be computed from an invariant admitting a basis must be of the form of \cref{definition:counting-function-from-basis},
in the following sense:

\begin{corollary}
    \label{corollary:standard-way-of-producing-count}
    Let $\Acal$ be an additive category and let $\Ncal : \Acal \to \Zbb$ be a count.
    Suppose that there exists an additive invariant $\alpha$ on $\Acal$ that admits a basis $\Bcal = \{M_i\}_{i \in I}$, and such that $\alpha \succcurlyeq \Ncal$.
    Let $f : \Bcal \to \Zbb$ be defined by $f(M_i) = \Ncal(M_i)$.
    Then $\Ncal = \Ncal^{(\alpha, \Bcal, f)}$.\qed
\end{corollary}




\subsection{Counts from invariants in the literature}
\label{section:counts-from-known-invariants}

We first recall the definitions of several additive invariants and basis from persistence theory, and then use \cref{definition:counting-function-from-basis} to derive counts from these.


\begin{definition}
    \label{definition:three-basic-invariants-tda}
    %Let $\Pscr$ be a poset and let $I \subseteq \Pscr$ be a spread.
    %Given $M : \Pscr \to \vect$, let
    %\[
    %    \Rk_I(M) \coloneqq \rk\big(\lim M|_I \to \colim M|_I\big).
    %\]
    We define three families of additive invariants.
    \begin{itemize}
        \item
              Let $\Ical$ be a set of spreads of a poset $\Pscr$.
              The \emph{$\Ical$-rank invariant} \cite{botnan-oppermann-oudot,clause-kim-memoli}, denoted $\Rk_\Ical : \rep(\Pscr) \to \Zbb^\Ical$, is given by
              \[
                  \Rk_\Ical(M)(I) \coloneqq \mathrm{rank}\big(\lim M|_I \to \colim M|_I\big),
              \]
              for every spread $I \in \Ical$.
              The \emph{rank invariant} \cite{carlsson-zomorodian}, denoted $\Rk : \rep(\Pscr) \to \Zbb^{\rects}$ is the $\Ical$-invariant with $\Ical$ the set $\rects$ of all segments in $\Pscr$.
              Equivalently, the rank invariant is defined by $\Rk(M)([a,b]) = \rk(M_a \to M_b)$, for $a \leq b \in \Pscr$.
        \item Let $\Lambda$ be a finite dimensional $\kbb$-algebra and let $\Xcal$ be a set of pairwise non-isomorphic finite dimensional, indecomposable $\Lambda$-modules.
              The \emph{$\Xcal$-dimhom invariant} \cite{blanchette-brustle-hanson}, denoted $\dimhom_\Xcal : \mod_{\Lambda} \to \Zbb^{\Xcal}$, is given by
              \[
                  \dimhom_{\Xcal}(M)(X) \coloneqq \dim\left(\hom_{\Lambda}(X,M)\right).
              \]
              %If $\Lambda$ is a finite dimensional $\kbb$-algebra,
              The \emph{dimension vector} is the additive invariant $\dimhom_{\proj_\Lambda} : \mod_\Lambda \to \Zbb^{\proj_\Lambda}$.
        \item Let $\Lambda$ be a finite dimensional $\kbb$-algebra and let $\Xcal$ be a set of pairwise non-isomorphic finite dimensional, indecomposable $\Lambda$-modules.
              A sequence $A \to B \to C$ in $\mod_\Lambda$ is \emph{$\Xcal$-exact} if $\hom(X,A) \to \hom(X,B) \to \hom(X,C)$ is exact for every $X \in \Xcal$.
              The \emph{$\Xcal$-Grothendieck group invariant} \cite{blanchette-brustle-hanson}, denoted $\Ksf_\Xcal : \mod_\Lambda \to \Ksf(\Lambda, \Xcal)$, is given by
              \[
                  \Ksf_\Xcal(M) \coloneqq [M] \in \Ksf(\Lambda, \Xcal)
              \]
              mapping a module to its class in $\Ksf(\Lambda, \Xcal)$, the Grothendieck group relative to $\Xcal$, that is, the free Abelian group generated by isomorphism classes of $\Lambda$-modules, modulo relations $[B] = [A] + [C]$ for every short $\Xcal$-exact sequence $0 \to A \to B \to C \to 0$.
    \end{itemize}
\end{definition}

The following results give ways of producing bases for additive invariants; proofs are in \cref{section:appendix-additive-invariants-bases}, since they are standard.

\begin{proposition}[\cite{clause-kim-memoli,botnan-oppermann-oudot}]
    \label{proposition:I-is-basis-of-rk-I}
    Let $\Pscr$ be a finite poset, and let $\Ical$ be a set of spreads.
    Then, $\{\kbb_{I}\}_{I \in \Ical}$ is a basis for $\Rk_\Ical : \rep(\Pscr) \to \Zbb^{\Ical}$.
\end{proposition}
\begin{proof}
    See \cref{section:appendix-additive-invariants-bases}.
\end{proof}


\begin{proposition}[{cf.~\cite{blanchette-brustle-hanson}}]
    \label{proposition:projectives-are-basis}
    Let $\Lambda$ be a finite dimensional $\kbb$-algebra, and let $\Xcal$ be a set of pairwise non-isomorphic finite dimensional, indecomposable $\Lambda$-modules.
    We have $\dimhom_{\Xcal} \approx \Ksf_{\Xcal}$, and if every finite dimensional $\Lambda$-module admits a finite $\Xcal$-projective resolution (\cref{definition:relative-projective-resolution}), then $\Xcal$ is a basis for $\dimhom_{\Xcal}$ and $\Ksf_\Xcal$.
\end{proposition}
\begin{proof}
    See \cref{proposition:projectives-are-basis-2}.
\end{proof}

\begin{corollary}
    \label{remark:basis-for-known-invariants}
    Let $\Pscr$ be a finite poset, and let $\spreads$, $\rects$, and $\hooks$ be the sets of spreads, segments, and hooks of $\Pscr$ (\cref{section:spreads}).
    \begin{enumerate}
        \item The set $\{\kbb_I\}_{I \in \spreads}$ is a basis for $\Rk_{\spreads}$.
        \item The set $\{\kbb_I\}_{I \in \rects}$ is a basis for $\Rk$.
        \item The set $\{\kbb_I\}_{I \in \spreads}$ is a basis for $\dimhom_\spreads \approx \Ksf_\spreads$
        \item The set $\{\kbb_I\}_{I \in \hooks}$ is a basis for $\dimhom_\hooks \approx \Ksf_\hooks$
    \end{enumerate}
\end{corollary}
\begin{proof}
    See \cref{section:appendix-additive-invariants-bases}.
\end{proof}

\begin{definition}
    Let $\Pscr$ be a finite poset.
    \begin{itemize}
    \item The function mapping $M \in \rep(\Pscr)$ to the coefficients of $\Rk_{\spreads}(M)$ in the basis $\{\kbb_I\}_{I \in \spreads}$ is the \emph{generalized persistence diagram} \cite{kim-memoli}%
    \footnote{A variation of the generalized persistence diagram was first introduced in \cite{kim-memoli}.
    We use the more standard definition~\cite{dey-kim-memoli,clause-kim-memoli},
    also called minimal rank decomposition in \cite{botnan-oppermann-oudot}.}.
    \item The function mapping $M \in \rep(\Pscr)$ to the coefficients of $\Rk(M)$ in the basis $\{\kbb_I\}_{I \in \rects}$ is the \emph{signed barcode}
    %or \emph{minimal rank decomposition by rectangles}
    \cite{botnan-oppermann-oudot}.
    \item The function mapping $M \in \rep(\Pscr)$ to the coefficients of $\dimhom_{\spreads} \approx \Ksf_\spreads$ in the basis $\{\kbb_I\}_{I \in \spreads}$ is the \emph{interval approximation} \cite{asashiba-escolar-nakashima-yoshiwaki-2}%
    \footnote{The interval approximation was introduced for a particular poset in \cite{asashiba-escolar-nakashima-yoshiwaki-2} and extended to general finite posets in \cite[Example~2.39]{escolar-kim}, where it is called interval Euler characteristic.}
    \item
    The function mapping $M \in \rep(\Pscr)$ to the coefficients of $\dimhom_\hooks(M)$ in the basis $\{\kbb_I\}_{I \in \hooks}$ is the \emph{minimal rank decomposition by hooks} \cite{botnan-oppermann-oudot-scoccola}.
    \end{itemize}
\end{definition}



\begin{definition}
    \label{definition:known-counts}
    Let $\Pscr$ be a finite poset.
    We define four counts $\rep(\Pscr) \to \Zbb$ as
    \begin{align*}
        \chigpd         & \coloneqq \Ncal^{\left(\Rk_\spreads,\, \{\kbb_{I}\}_{I\in\spreads}\right)}   \\
        \chirkdec       & \coloneqq \Ncal^{\left(\Rk,\, \{\kbb_{I}\}_{I\in\rects}\right)}              \\
        \chispreadexact & \coloneqq  \Ncal^{\left(\dimhom_\spreads,\, \{\kbb_I\}_{I \in \spreads}\right)} = \Ncal^{\left(\Ksf_\spreads,\, \{\kbb_I\}_{I \in \spreads}\right)}  \\
        \chirkexact     & \coloneqq \Ncal^{\left(\dimhom_\hooks,\, \{\kbb_I\}_{I \in \hooks}\right)} = \Ncal^{\left(\Ksf_\hooks,\, \{\kbb_I\}_{I \in \hooks}\right)} . 
    \end{align*}
\end{definition}


%We could also define another count $\chirkexact \coloneqq \Ncal^{(\dimhom_\hooks, \hooks)}$, but this gives nothing new, as the next result shows.


\begin{remark}[Interpretation of counts]
    \label{remark:interpretation-of-counts}
    %\luis{adjust. we are saying this to conclude that we are taking poisitive - negative in what people have already considered}
    %\luis{also mention the Euler char interpretation in the case of exact structures}
    Let $\Pscr$ be a finite poset.
    \begin{enumerate}
        \item
             The count $\chigpd$ equals the number of positive summands minus the number of negative summands in the generalized rank invariant.
        \item
              The count $\chirkdec$ equals the number of positive bars minus the number of negative bars in the signed barcode.
        \item
              The count $\chispreadexact$ equals the number of positive summands minus the number of negative summands in the interval approximation.
              %, as well as the Euler characteristic relative to the \emph{spread exact structure}.
        \item
              The count $\chirkexact$ equals the number of positive bars minus the number of negative bars in the minimal hook decomposition.
              %, as well as the Euler characteristic of $M$ relative to the \emph{rank exact structure} of \cite{botnan-oppermann-oudot}.
    \end{enumerate}
\end{remark}

\begin{remark}
    Although $\Rk_{\spreads}$ and $\dimhom_\spreads \approx \Ksf_\spreads$ seem very related, since, for example, they admit the same basis $\spreads$, these invariants are not equivalent for a general poset $\Pscr$ (see \cite[Section~7.3]{blanchette-brustle-hanson} and \cite[Theorem~4.1]{escolar-kim}).
    Perhaps surprisingly, the counts $\chigpd$ and $\chispreadexact$ are equal in the case where $\Pscr$ is a two-dimensional grid poset, thanks to \cref{corollary:our-count-and-other-counts}.
\end{remark}




The following remark also allows us to interpret $\chispreadexact$ and $\chirkexact$ as relative Euler characteristics.

\begin{remark}
    Let $\Lambda$ be a finite dimensional algebra, and let $\Xcal$ be a set of pairwise non-isomorphic, finite dimensional $\Lambda$-modules, such that every finite dimensional $\Lambda$-module admits a finite $\Xcal$ resolution.
    By \cref{proposition:projectives-are-basis}, we get counts $\Ncal^{(\dimhom_\Xcal, \Xcal)} = \Ncal^{(\Ksf_\Xcal, \Xcal)}$.
    If $M \in \mod_{\Lambda}$, these can be interpreted as the Euler characteristic of $M$ relative to $\Xcal$, in the sense that if $0 \to A_k \to \cdots \to A_0 \to M$ is an $\Xcal$-projective resolution of $M$, then the counts are equal to $\sum_{i \in \Nbb} (-1)^i \cdot \Ncaldec(A_i)$, where $\Ncaldec$ counts indecomposable summands (with multiplicity).
\end{remark}


