\subsection{The signed barcode count equals the inclusion-exclusion count}

\begin{proposition}
    \label{proposition:signed-barcode-equals-inclusion-exclusion}
    Let $n \geq 1 \in \Nbb$.
    We have $\chirkdec = \Ninclexcl$ on $\rep(\Gcal^n)$.
\end{proposition}
\begin{proof}
    Applying \cref{lemma:basic-results-counts-basis}, it is enough to check that (1) 
    we have $\Rk \succcurlyeq \Ninclexcl$ as additive invariants on $\repf(\Zbb^n)$, and that (2)
    $\Ninclexcl(\kbb_{[a,b]}) = 1$ for every segment representation $\kbb_{[a,b]}$, $a\leq b \in \Zbb^n$.

    \smallskip

    \noindent\emph{(1)}
    It is sufficient to prove that, for every $S = \{s_1, \dots, s_\ell\} \subseteq \{1, \dots, n\}$, we can compute $\dim(\xbf_S M)$ using the ranks of the morphisms of $M$, where $\xbf_S = \xbf_{s_1} \cdots \xbf_{s_\ell}$.
    For this, let $b \in \Zbb^n$ be defined by $b_i = 1$ if $\xbf_i \in S$ and $b_i = 0$, otherwise, and note that
    \[
        \dim(\xbf_S M) = \sum_{a \in \Zbb^n} \mathrm{rank}\left(\phi^M_{a,a+b} : M_a \to M_{a + b}\right).
    \]

    \smallskip

    \noindent\emph{(2)}
    We proceed by induction on $n$.
    If $n = 1$, this is clear.
    For the inductive case, let $\kbb_{[a,b]}$ be a segment representation, with $a = (a_1, \dots, a_{n+1})$ and $b = (b_1, \dots, b_{n+1})$.
    Then, $\kbb_{[a,b]} \cong \kbb_{[a_1,b_1]} \otimes_{\kbb} \cdots \otimes_{\kbb} \kbb_{[a_{n+1},b_{n+1}]} = \kbb_{[a',b']} \otimes_{\kbb} \kbb_{[a_{n+1},b_{n+1}]}$, where the action of $\xbf_i \in \kbb[\xbf_1, \dots, \xbf_{n+1}]$ on the $i$th tensor factor.
    Unfolding the definition of $\Ninclexcl$, we get
    \begin{align*}
        \Ninclexcl\left(\kbb_{[a,b]}\right)
            &= \sum_{S \subseteq \{1, \dots, n+1\}} (-1)^{|S|}\,\, \dim(\xbf_S M) \\
            &=
             %\left(
                \sum_{S \subseteq \{1, \dots, n\}} (-1)^{|S|}\,\, \dim\left(\xbf_S M\right)
             %\right)
            \;+\;
            %\left(
                \sum_{T \subseteq \{1, \dots, n\}} (-1)^{|T|+1}\,\, \dim\left(\xbf_{T \cup \{n+1\}} M\right)
            %\right)
            \\
            &= \Ninclexcl(\kbb_{[a',b']}) \cdot \dim\left(\kbb_{[a_{n+1},b_{n+1}]}\right) - \Ninclexcl(\kbb_{[a',b']}) \cdot \dim\left(\kbb_{[a_{n+1} + 1,b_{n+1}]} \right)\\
            &= 1 \cdot (b_{n+1} - a_{n+1}) - 1 \cdot (b_{n+1} - (a_{n+1} + 1)) = 1,
    \end{align*}
    where in the fourth equality we used the inductive hypothesis.
\end{proof}

\subsection{The signed barcode count and the topological Euler characteristic}
The main result in this subsection is 
\cref{theorem:count-is-euler},
which says that, over finite lattices, the count $\chirkdec$ of a spread-representation $\kbb_I$ equals the topological Euler characteristic of $\Delta(I)$, the \emph{order complex} \cite[Section~9.3]{bjorner} of the spread.
We deduce from this an interesting universal property for $\chirkdec$
(\cref{theorem:universal-property-signed-barc}).

It is relevant to note that all spreads in $\Zbb^2$ are contractible, and thus their Euler characteristic is one (\cref{lemma:spread-contractible}), but this is not true already in $\Zbb^3$, where the Euler characteristic can even be negative (\cref{figure:three-parameter-negative}).


\begin{theorem}
    \label{theorem:count-is-euler}
    If $\Pscr$ is a finite lattice and $I \subseteq \Pscr$ is a spread, then $\chirkdec(\kbb_I) = \chi(\Delta(I))$.
\end{theorem}


\begin{proof}
    We will make use of the following easy claims;
    the first one is standard and follows from, e.g., \cite[Corollary~10.12]{bjorner},
    the second one is a consequence of \cref{lemma:any-decomposition-gives-count},
    and the third one is a straightforward check.
    \smallskip

    \noindent \emph{Claim 1.}
    %\label{lemma:rectangle-contractible}
    If $\Pscr$ is a finite poset with a minimum, then $\Delta(\Pscr)$ is contractible.

    \smallskip

    \noindent \emph{Claim 2.}
    %\label{lemma:rectangle-decomposition-gives-count}
    If $\Pscr$ be a finite poset, $M : \Pscr \to \vect$, and $A_1, \dots, A_k \subseteq \Pscr$ and $B_1, \dots, B_\ell \subseteq \Pscr$ are segments such that
    $\Rk(M) = \sum_{i = 1}^k \Rk(\kbb_{A_i}) - \sum_{j = 1}^\ell \Rk(\kbb_{B_j})$,
    then $\chirkdec(M) = k - \ell$.

    \smallskip

    \noindent \emph{Claim 3.}
    %\label{lemma:intersection-of-segments}
    Let $\Pscr$ be a lattice, and let $[x,y],[x',y'] \subseteq \Pscr$ be segments.
    Then $[x,y] \cap [x',y']$ is either empty or the segment $[x\vee x', y\wedge y']$.

    \medskip

    Let $\Ssf$ be the set of maximal segments included in $I$.
    Every chain in $I$ must lie entirely in a segment $R \in \Ssf$, so $C \coloneqq \{\Delta(R)\}_{R \in \Ssf}$ is a cover of $\Delta(I)$ by subcomplexes.
    Let $K$ be the nerve of $C$, so that the $i$th simplices $K$ are given by the subsets $T \subseteq \Ssf$ such that $|T|=i+1$ and $\cap T \neq \emptyset$.

    If $T \subseteq \Ssf$ is such that $\cap T \neq \emptyset$, then $\cap T$ is a segment (by Claim 3), so it has a minimum, and thus $\Delta(\cap T)$ is contractible, by Claim 1.
    This implies that all intersections of elements of $C$ are either empty or contractible, and thus, by the nerve lemma for simplicial complexes \cite[Theorem~10.6]{bjorner}, we get $K \simeq \Delta(I)$, which in turn implies that $\chi(K) = \chi(\Delta(I))$.

    It is thus sufficient to show that $\chirkdec(\kbb_I) = \chi(K)$.
    %\smallskip
    %\noindent\textit{Claim.}
    We claim that
    \begin{equation*}
        \label{equation:inclusion-exclusion-rank}
        \Rk(\kbb_I) = \sum_{i \in \Nbb}\; (-1)^i\; \sum_{T \subseteq \Ssf,\, |T|=i+1,\, \cap T \neq \emptyset}\; \Rk(\kbb_{\cap T}).
    \end{equation*}
    From this equation and Claim 2, it follows that
    \[
        \chirkdec(\kbb_I) =
        \big|\big\{ T \subseteq \Ssf : |T| \text{ odd},\; \cap T \neq \emptyset\big\}\big| -
        \big|\big\{ T \subseteq \Ssf : |T| \text{ even},\; \cap T \neq \emptyset\big\}\big|
        = \chi(K),
    \]
    so let us prove the equation.
    We do this by evaluating the left- and right-hand sides on each $a \leq b \in \Pscr$.
    If either $a$ or $b$ is not in $I$, then both sides are zero, so let us assume that $a, b \in I$.
    In this case, the left-hand side is one, so we need to show that the right-hand side is also one.

    Let $\Ssf_{a,b} \subseteq \Ssf$ be the set of segments in $\Ssf$ that contain both $a$ and $b$.
    All intersections of sets in $\Ssf_{a,b}$ must also contain $a$ and $b$, so we need to prove that
    \[
        \big|\big\{ T \subseteq \Ssf_{a,b} : |T| \text{ odd}\big\}\big| - \big|\big\{ T \subseteq \Ssf_{a,b} : |T| \text{ even}\big\}\big| = 1,
    \]
    which is true for any finite set $X$ in the place of $\Ssf_{a,b}$, since it follows from the fact that the alternating sum of binomial coefficients is $0$.
\end{proof}

\begin{corollary}
    \label{lemma:signed-barcode-hooks}
    If $\Pcal$ is a finite lattice, then $\chirkdec = \chirkexact\; :\; \rep(\Pcal) \to \Zbb$.
\end{corollary}
\begin{proof}
    It is clear that $\dimhom(\kbb_{\langle a, \infty \langle}, M) = \Rk(M)(a,a)$
    and we have
    $\Rk(M)(a,b) = \dimhom(\kbb_{\langle a, \infty \langle}, M) -  \dimhom(\kbb_{\langle a, b \langle},M)$ by rank-nullity (see \cite[Lemma~4.4(2)]{botnan-oppermann-oudot}).
    Thus, $\Rk$ is equivalent to $\dimhom_{\hooks}$.
    By \cref{lemma:basic-results-counts-basis}, it is thus enough to show that $\chirkdec(\kbb_{\langle a, b \langle}) = 1$ for every hook $\langle a, b \langle$ of $\Pcal$, which is true by \cref{theorem:count-is-euler}
    since $\Delta \langle a, b \langle$ is contractible, since $\langle a, b \langle$ has a minimum.
