\begin{corollary}
    \label{corollary:two-parameter-normalized}
    If $I \subseteq \Zbb^2$ is a finite spread, then $\Ncaltwo(I) = 1$.
\end{corollary}
\begin{proof}
    By translating $I$ if necessary, we can assume that $I$ belongs to a finite grid $I \subseteq \Gcal^2 \subseteq \Zbb^2$.
    Over this finite, two-dimensional grid we have $\Ncaltwo = \chirkdec$, by \cref{proposition:signed-barcode-equals-inclusion-exclusion}, so the result follows from \cref{lemma:spread-contractible}.
\end{proof}

