\subsection{Slice-monotonicity of the two-parameter count}


If $f : \Pscr \to \Qscr$ a monotonic function between posets, and $M : \Qscr \to \Vect$, we let $f^*(M) : \Pscr \to \Vect$ be defined by pre-composition with $f$, that is $f^*(M) \coloneqq M \circ f$.
The following is standard from the representation theory of quivers of type $A$.

\begin{lemma}
    \label{lemma:indecomposable-one-parameter}
    %If $\Lcal$ is a finite linear order, then $M : \Lcal \to \vect$ is indecomposable if and only if it is isomorphic to $\kbb_{[a,b]}$ for $a \leq b \in \Lcal$.
    A representation $M \in \repf(\Zbb)$ is indecomposable if and only if it is isomorphic to $\kbb_{[a,b)}$ for $a <b \in \Zbb$.
    \qed
\end{lemma}


Recall that the simple representation at $i \in \Zbb$ is $\kbb_i \coloneqq \kbb_{[i,i+1)}$.

\begin{lemma}
    \label{lemma:one-parameter-count-as-hom}
    If $M \in \repf(\Zbb)$, then $\Ncalone(M) = \dim \hom\left(M,\bigoplus_{i \in \Zbb} \kbb_i\right) = \dim \Hom\left(\bigoplus_{i \in \Zbb} \kbb_i, M\right)$.
\end{lemma}
\begin{proof}
    By \cref{lemma:indecomposable-one-parameter} and additivity, it is sufficient to prove this for $M = \kbb_{[a,b)}$, with $a < b \in \Zbb$.
    Then $\hom\left(\kbb_{[a,b)},\bigoplus_{i \in \Zbb} \kbb_i\right) \cong \hom(\kbb_{[a,b)}, \kbb_a) \cong \kbb$, and
    $\hom\left(\bigoplus_{i \in \Zbb} \kbb_i, \kbb_{[a,b)}\right) \cong \hom(\kbb_{b-1}, \kbb_{[a,b)}) \cong \kbb$, and both have dimension $1$, as required.
\end{proof}

The following is standard, see, e.g., \cite{bauer-lesnick}.

\begin{lemma}
    \label{lemma:one-parameter-monotonicity-inclusion}
    Let $M, M' \in \repf(\Zbb)$.
    If there exists a monomorphism $M \to M'$ or an epimorphism $M' \to M$, then $\Ncalone(M) \leq \Ncalone(M')$.
    %Let $\Lcal$ be a finite linearly ordered set, and let $M, M' : \Lcal \to \vect$.
    %If there exists monomorphism $M \to M'$ or an epimorphism $M' \to M$, then $\Ncalone(M) \leq \Ncalone(M')$.
\end{lemma}
\begin{proof}
    By duality (\cref{section:duality}), it is enough to do the case of a monomorphism, so let $f : M \to M'$ be a monomorphism.
    By \cref{lemma:one-parameter-count-as-hom}, we need to prove that
    $\dim \hom\left(\bigoplus_{i \in \Zbb} \kbb_i, M\right) \leq \dim \hom\left(\bigoplus_{i \in \Zbb} \kbb_i, M'\right)$, which follows from the fact that the morphism
    $f_* : \hom\left(\bigoplus_{i \in \Zbb} \kbb_i, M\right) \to \dim \hom\left(\bigoplus_{i \in \Zbb} \kbb_i, M'\right)$ induced by $f$ is a monomorphism.
\end{proof}




