\begin{definition}
    A monotonic function between finite posets $f : \Pscr \to \Qscr$ is \emph{contiguous} if whenever $x \leq y \in \Pscr$ is a cover relation, we have that $f(x) \leq f(y) \in \Qscr$ is a cover relation as well.
\end{definition}


\begin{lemma}
    \label{lemma:contiguous-death-relation}
    Let $\ell : \Zbb \to \Zbb^2$ be a contiguous monotonic function.
    Let $M \in \repf(\Zbb^2)$, let $i \in \Zbb$ and let $x \in M_{\ell(i)} = \ell^*(M)_i$.
    If $\zbf \cdot x = 0 \in \ell^*(M)$, then $\xbf\ybf \cdot x = 0 \in M$.
    It follows that there is a monomorphism of representations of $\Zbb$:
    \[
        \kerelem{\ell^*(M)}{\zbf} \hookrightarrow \ell^*(\kerxy{M}).
    \]
    %    Let $\Lcal = [n]$, and let $\ell : \Lcal \to \Gcal^2$ be a contiguous monotonic function mapping the maximum of $\Lcal$ to the maximum of $\Gcal^2$.
    %    Let $M : \Gcal^2 \to \vect$, let $i \in \Lcal$ and let $x \in M_{\ell(i)} = \ell^*(M)_i$.
    %    If $\zbf(x) = 0 \in \ell^*(M)$, then $\xbf\ybf(x) = 0 \in M$.
    %    It follows that there is a monomorphism of modules over $\Lcal$:
    %    \[
    %        \ell^*(M)[\zbf] \hookrightarrow \ell^*(M[\xbf\ybf]).
    %    \]
\end{lemma}
\begin{proof}
    We must have $\zbf \cdot x = \phi^{\ell^*(\kerxy{M})}_{i, i+1}(x) = 0$.
    The cover relations in $\Zbb^2$ are those of the form $(a,b) \leq (a+1, b)$ and $(a,b) \leq (a, b+1)$.
    So $\ell(i+1)$ is either $\ell(i) + (1,0)$ or $\ell(i) + (0,1)$; in either case, $\ell(i+1) \leq \ell(i) + (1,1)$.
    And thus, $\xbf\ybf \cdot x = \phi^{\kerxy{M}}_{\ell(i), \ell(i) + (1,1)}(x) = 0$, as required.
\end{proof}

\begin{lemma}
    \label{lemma:preimage-of-spread-in-linear-order}
    %Let $\Lcal$ be a finite linearly ordered set, and let $\ell : \Lcal \to \Pscr$ be a monotonic function into a poset $\Pscr$.
    Let $\Zbb \to \Pscr$ be a monotonic function into a poset $\Pscr$.
    If $I \subseteq \Pscr$ is a spread, then $\Ncalone(\ell^*(\kbb_I)) \leq 1$.
\end{lemma}
\begin{proof}
    We claim that $\ell^{-1}(I) \subseteq \Zbb$ must be either empty or an interval of $\Zbb$.
    The result follows from this, since $\Ncalone$ of an interval is $1$, and $\Ncalone$ of the zero representation is $0$.

    So let us prove that, if $\ell^{-1}(I)$ is not empty, then it is an interval.
    Let $a \leq b \leq c \in \Zbb$ and assume that $a,c \in \ell^{-1}(I)$.
    Then $\ell(a) \leq \ell(b) \leq \ell(c) \in \Pscr$ and $\ell(a), \ell(c) \in I$, so $\ell(b) \in I$ and $b \in \ell^{-1}(I)$, as required.
\end{proof}


\begin{lemma}
    \label{lemma:one-parameter-monotonicity-restriction}
    Let $f : \Zbb \hookrightarrow \Zbb$ be an injective monotonic function, and let $M \in \repf(\Zbb)$.
    We have $\Ncalone(f^*(M)) \leq \Ncalone(M)$.
    %    Let $\Lcal$ and $\Lcal'$ be finite linearly ordered sets, let $f : \Lcal \to \Lcal'$ be a monotonic function, and let $M : \Lcal' \to \vect$.
    %    \begin{enumerate}
