    %        \item If $f$ is surjective, then $\Ncalone(f^*(M)) = \Ncalone(M)$.
    %    \end{enumerate}
\end{lemma}
\begin{proof}
    Recall that $\Ncalone$ simply counts the number of indecomposable summands, so it is sufficient to prove the result for $M$ indecomposable.
    So, using \cref{lemma:indecomposable-one-parameter}, let $M = \kbb_{[a,b)}$ for $a< b \in \Zbb$.
    Now, if $S \coloneqq f^{-1}([a,b)) = \emptyset$, then $f^*(M) = 0$, and otherwise $M \cong \kbb_{[\min S, \max S]}$, by the same argument used in the proof of \cref{lemma:preimage-of-spread-in-linear-order}.
    The result follows.
\end{proof}



