Given $\ell \in \Zbb^2$ let $\sq(\ell) \subseteq \Zbb^2$ be the full four-element subposet spanned by $\{\ell, \ell-(0,1), \ell-(1,0), \ell-(1,1)\}$.
Given $M \in \rep(\Zbb^2)$, we can decompose the restriction $M|_{\sq(\ell)} \in \rep(\sq(\ell))$ as a direct sum of representations of the form of those in \cref{lemma:indecomposables-over-square}.
In that case, if $n \in \{a, b, \dots, j, k\}$, let $M^n_\ell$ be the number of indecomposables of type $(n)$.

\begin{lemma}
    \label{lemma:betti-tables-and-decomposition-on-square}
    Let $M \in \rep(\Zbb^2)$, and let $\ell \in \Zbb^2$.
    We have the following characterization of the Betti tables of $M$
    \[
        \beta_0^M(\ell) = M^d_\ell\, , \;\;\;\;\;\;\;\;\;
        \beta_1^M(\ell) = M^i_\ell + M^j_\ell + M^b_\ell + M^c_\ell\, , \;\;\;\;\;\;\;\;\;
        \beta_2^M(\ell) = M^a_\ell\, ,
    \]
    and the following set of equalities
    \begin{align*}
        M^a_\ell & = \dim \left\{z \in M_{\ell-(1,1)} : \xbf \cdot z = \ybf \cdot z = 0 \right\} \\
        M^b_\ell & = \dim \im\left(\,
        \left\{z \in M_{\ell-(0,1)} : \ybf \cdot z = 0\right\} \hookrightarrow M_{\ell-(0,1)} \twoheadrightarrow M_{\ell-(0,1)}/\xbf M_{\ell-(1,1)}\,
        \right)                                                                                  \\
        M^c_\ell & = \dim \im\left(\,
        \left\{z \in M_{\ell-(1,0)} : \xbf \cdot z = 0\right\} \hookrightarrow M_{\ell-(1,0)} \twoheadrightarrow M_{\ell-(1,0)}/\ybf M_{\ell-(1,1)}\,
        \right)                                                                                  \\
        M^d_\ell & = \dim M_\ell \, /\left(\xbf M_{\ell-(1,0)} \oplus \ybf M_{\ell-(0,1)}\right)    \\
        M^i_\ell & = \dim M_{\ell-(1,1)}\, /
        \left(
        \ker \left( M_{\ell-(1,1)} \xrightarrow{\xbf} M_{\ell - (0,1)} \right)
        \right)
        \oplus
        \left(
        \ker \left( M_{\ell-(1,1)} \xrightarrow{\ybf} M_{\ell - (1,0)} \right)
        \right)
        \\
        M^j_\ell & = \dim
        \left\{(w,z) \in
        \left( M_{\ell-(1,0)}/ \ybf M_{\ell-(1,1)} \right) \oplus
        \left( M_{\ell-(0,1)}/ \xbf M_{\ell-(1,1)} \right) : \xbf \cdot w = \ybf \cdot z \in M_{\ell}/\xbf\ybf M_{\ell-(1,1)}
        \right\}
    \end{align*}
\end{lemma}
\begin{proof}
    The Koszul complex for $M$ at $\ell$, which is what we use to define $\beta_\bullet^M(\ell)$ (\cref{section:betti-tables}) only depends on $M|_{\sq(\ell)}$, that is, we have $\beta_\bullet^M(\ell) = \beta_\bullet^{M|_{\sq(\ell)}}(\ell)$.
    The second set of equalities also only depends on $M|_{\sq(\ell)}$.
    Thus, it is enough to prove the result for $M \in \rep(\{0 < 1\}^2)$, $\ell = (1,1)$, and $M$ one of the indecomposables of \cref{lemma:indecomposables-over-square}.
    This is then a routine check.
    %So it is enough to prove the result for $M \in \rep(\{0,1\}^2)$, $i = (1,1)$, and $M$ one of the indecomposables of \cref{lemma:indecomposables-over-square}, which is straightforward.
\end{proof}

