\begin{definition}
    \label{definition:concave-convex-corners}
    Let $I \subseteq \Zbb^2$ be a spread curve.
    A point $i \in I$ is
    \begin{itemize}
        \item a \emph{convex corner} of $I$ if $i-(1,0) \notin I$ and $i-(0,1) \notin I$;
        \item an \emph{inner convex corner} of $I$ if $i+(1,0) \in I$ and $i+(0,1) \in I$;
        \item a \emph{concave corner} of $I$ if $i+(1,0) \notin I$ and $i+(0,1) \notin I$;
        \item an \emph{inner concave corner} of $I$ if $i-(1,0) \in I$ and $i-(0,1) \in I$.
    \end{itemize}
\end{definition}

Note that the set of convex (resp.~concave) corners of a spread curve coincides with its set of minimal (resp.~maximal) elements.

The proof of the following result is straightforward.

\begin{lemma}
    \label{lemma:convex-corner-algebraic}
    Let $I \subseteq \Zbb^2$ be a spread curve, let $M \coloneqq \kbb_I \in \rep(\Zbb^2)$, and let $\ell \in \Zbb^2$.
    \begin{enumerate}
        \item The point $\ell$ is a convex corner of $I$ if and only if $M^a_\ell = 1$.
        \item The point $\ell$ is an inner convex corner of $I$ if and only if $M^j_\ell = 1$.
              \qed
    \end{enumerate}
\end{lemma}

\curvesbettitables*
\begin{proof}
    We start with the equalities computing the Betti tables.
    Let $\ell \in \Zbb^2$.
    Using \cref{lemma:betti-tables-and-decomposition-on-square} and the definitions of $\topleft{M}$ and $\botright{M}$, we get $M^b_\ell = \dim (\topleft{M})_\ell$ and
    $M^c_\ell = \dim (\botright{M})_\ell$.

    To simplify notation, if $C$ is a finite multiset of spread curves, let $\conv(C)_\ell$, $\inconv(C)_\ell$, $\conc(C)_\ell$, $\inconc(C)_\ell \in \Nbb$ be the multiplicities of $\ell$ as a convex, inner convex, concave, and inner concave corner of the elements of $C$, respectively.
    It is then enough to prove
    \[
        \conv(\cokerxy{M})_\ell = M^a_\ell\,,\;\;\;\;
        \inconc(\kerxy{M})_\ell = M^i_\ell\,,\;\;\;\;
        \inconv(\cokerxy{M})_\ell = M^j_\ell\,,\;\;\;\;
        \conc(\kerxy{M})_\ell = M^d_\ell\, .
    \]
    We do the cases of $a$ and $j$, since $d$ is dual to $a$, and $i$ is dual to $j$ (in the sense of \cref{section:duality}).

    For the case of $a$, we have
    $\conv(\cokerxy{M})_\ell
        = \left(\cokerxy{M}\right)^a_\ell = M^a_\ell$,
    where in the first equality we used
    \cref{lemma:convex-corner-algebraic}(1).
    For the case of $j$ we have
    $\inconc(\kerxy{M})_\ell
        = \left(\kerxy{M}\right)^j_\ell = M^j_\ell$,
    where in the first equality we used
    \cref{lemma:convex-corner-algebraic}(2).

    \smallskip

    We now prove the isomorphisms relating the corners of $M$ to the corners of $\cokerxy{M}$.
    We prove $\topleft{M} \cong \topleft{\left(\cokerxy{M}\right)}$, the other isomorphism being analogous.
    Let $i \in \Zbb^2$.
    Let $\pi : M \to \cokerxy{M}$ be the quotient morphism, and consider the following diagram
    \[
    \begin{tikzpicture}
        \matrix (m) [matrix of math nodes,row sep=2.5em,column sep=3em,minimum width=1em,nodes={text height=1.75ex,text depth=0.25ex}]
        {
            \kery{M}[0,1] &  M & \cokerx{M} \\
             \kery{\left(\cokerxy{M}\right)}[0,1] &  \cokerxy{M} & \cokerx{\left(\cokerxy{M}\right)},\\};
        \path[line width=0.75pt, ->]
        (m-1-1) edge [above] node {$f$} (m-1-2)
        (m-1-2) edge [above] node {$g$} (m-1-3)
        (m-2-1) edge [above] node {$f'$} (m-2-2)
        (m-2-2) edge [above] node {$g'$} (m-2-3)
        (m-1-1) edge [left] node {$\kery{\pi}[0,1]$} (m-2-1)
        (m-1-2) edge [right] node {$\pi$} (m-2-2)
        (m-1-3) edge [right] node {$\cokerx{\pi}$} (m-2-3)
        ;
    \end{tikzpicture}
    \]
    so that $\topleft{M} = \im(g \circ f)$ and $\topleft{\left(\cokerxy{M}\right)} = \im(g' \circ f')$,
    and we need to prove that the image of the top row is isomorphic to the image of the bottom row.
    It is straightforward to see that $\cokerx{\pi}$ is an isomorphism, so we need to show that, given $\ell \in \Zbb^2$ and $z \in \kery{\left(\cokerxy{M}\right)}_{\ell-(0,1)}$, there exists $a \in \kery{M}_{\ell-(0,1)}$ such that $(\cokerx{\pi} \circ g \circ f)(a) = (g' \circ f')(z)$.
    Let $z' \in M_{\ell}$ be a representative for $z$, so that $\ybf z' = \xbf\ybf w$ for some $w \in M_{\ell- (1,0)}$.
    Let $a \coloneqq z' - \xbf w$, and note that $\ybf a = 0$, so that $a \in \kery{M}_{\ell-(0,1)}$.
    We have $(g' \circ f')(z) = (g' \circ \pi)(z') = (\cokerx{\pi} \circ g)(z)$, so it is sufficient to show that $g(a) = g(z) \in \left(\cokerx{M}\right)_{\ell}$, which is clear since $a - z' = \zbf w$.
