        (m-1-1) edge [left] node {$\kerxc{\psi}$} (m-3-1)
        (m-3-1) edge [above] node {$g'$} (m-3-3)
        (m-1-3) edge [right] node {$\cokery{\phi}$} (m-3-3)
        ;
    \end{tikzpicture}
    \]
    We denote the category of boundaries by $\boundaries$.
\end{definition}


\begin{construction}
    Define a functor $\partial : \rep(\Zbb^2) \to \boundaries$ by mapping $M \in \rep(\Zbb^2)$ to the boundary $(\cokerxy{M}, \kerxyc{M}, f,g)$, where $f$ and $g$ are the following composites, respectively:
    \begin{align*}
        \keryc{\left(\kerxyc{M}\right)} = \keryc{M} &\hookrightarrow M \twoheadrightarrow \cokerx{M} = \cokerx{\left(\cokerxy{M}\right)}\\
        \kerxc{\left(\kerxyc{M}\right)} = \kerxc{M} &\hookrightarrow M \twoheadrightarrow \cokery{M} = \cokery{\left(\cokerxy{M}\right)}
    \end{align*}
    The action of $\partial$ on morphisms is the evident one.
\end{construction}

\subsection{The boundary as a representation of a string algebra}
We now describe a fully faithful embedding of $\boundaries$ into the category of representations of the string algebra $R$ of \cref{figure:large-gentle-quiver}.

\begin{construction}
    Define a functor $\iota : \boundaries \to \rep(R)$ by mapping a boundary $(B,D,f,g)$ to the representation $X\in \rep(R)$ given as follows:
    \begin{itemize}
        \item On the down-left, left, and down vertices, we let $X_{d\ell_i} = B_i = \cokerxy{B_i}$, $X_{\ell_i} = \cokerx{B}_i$, and $X_{d_i} = \cokery{B}_i$.
        \item On the up-right, right, and up vertices, we let $X_{ur_i} = D_i = \kerxyc{D_i}$, $X_{r_i} = \kerxc{D}_i$, and $X_{u_i} = \keryc{D}_i$.
        \item The horizontal morphisms are induced by the natural morphisms $\keryc{D} \hookrightarrow D \xrightarrow{\xbf} \keryc{D}[1,0]$ and $\cokery{B}[-1,0] \xrightarrow{\xbf} B \twoheadrightarrow \cokery{B}$.
        \item The vertical morphisms are induced by the natural morphisms $\kerxc{D} \hookrightarrow D \xrightarrow{\ybf} \kerxc{D}[1,0]$ and $\cokerx{B}[-1,0] \xrightarrow{\ybf} B \twoheadrightarrow \cokerx{B}$.
        \item For the diagonal morphism, we let $X_{u_i,\ell_i} = f_i$ and $X_{r_i,d_i} = g_i$.
    \end{itemize}
    The action of $\iota$ on morphisms is the evident one.
\end{construction}

It is clear that, if $(B,D,f,g)$ is a boundary, then $\iota(B,D,f,g)$ contains the exact same information as $(B,D,f,g)$, that is:

\begin{lemma}
    \label{lemma:G-fully-faithful}
    The functor $\iota : \boundaries \to \rep(R)$ is fully faithful.
    \qed
\end{lemma}

\begin{notation}
    By identifying $\boundaries$ with its essential image $\iota(\boundaries) \subseteq \rep(R)$, we treat $\boundaries$ as a full subcategory of $\rep(R)$.
\end{notation}

