\begin{definition}
    Let $G$ be an oriented graph.
    \begin{itemize}
    \item An \emph{oriented cycle} in $G$ consists of a sequence of edges $e = \{e_0, \dots, e_{k-1}\}$ of $G$ such that $\ssf(e_{i+1}) = \tsf(e_i)$ for all $i \in \Zbb/k\Zbb$.
    \item If $n \geq 2 \in \Nbb$, the concatenation of an oriented cycle $e$ with itself $n$ times is again an oriented cycle, denoted by $e^n$.
    \item An oriented cycle is \emph{irreducible} if it cannot be written as $e^n$ for some oriented cycle $e$ and $n \geq 2$.
    \item Two oriented cycles $\{e_0, \dots, e_{k-1}\}$ and $\{e'_0, \dots, e'_{k-1}\}$ are \emph{rotationally equivalent} if there exists $j \in \Zbb$ such that $e_i = e'_{i+j}$ for all $i \in \Zbb/k\Zbb$.
    \end{itemize}
\end{definition}



\begin{construction}
    \label{construction:oriented-cycle-to-periodic-word}
    %We define a function $F$ mapping cycles in $S$ to periodic words in $R$.
    Given an oriented cycle $e = \{e_0, \dots, e_{k-1}\}$ in $S$, we define a $\Zbb$-word $F(e) \in R$ by concatenating $e$ with itself countably many times, as follows
    \[
    \dots, e^{s_{k-1}}_{k-1}, e^{s_0}_0, e^{s_1}_1, \dots, e^{s_{k-2}}_{k-2}, e^{s_{k-1}}_{k-1}, e^{s_0}_0, e^{s_1}_1, \dots, e^{s_{k-2}}_{k-2}, e^{s_{k-1}}_{k-1}, e^{s_0}_0, \dots,
    \]
    where $s_i = +1$ if the edge $e_i$ has the same orientation in $S$ and in $R$, and $s_i = -1$ otherwise.
\end{construction}


The proof of the next result is then straightforward.

\begin{lemma}
    \label{lemma:oriented-cycle-to-periodic-word}
    \cref{construction:oriented-cycle-to-periodic-word} induces a bijection between the set of irreducible oriented cycles in $S$ up to rotational equivalence, and the set of equivalence classes of periodic $\Zbb$-words in $R$.
    \qed
\end{lemma}

Next, we provide a correspondence between oriented cycles in $S$ and discrete closed plane curves, in the following sense.


\begin{definition}
    \label{definition:closed-curve}
    \begin{itemize}
    \item A \emph{discrete closed plane curve} consists of a sequence $\gamma = \{\gamma_0, \dots, \gamma_{k-1}\}$ with $\gamma_i \in \Zbb^2$, such that $\|\gamma_{i+1} - \gamma_i\|_1 \leq 1$ for all $i \in \Zbb/k\Zbb$.
    \item If $n \geq 2 \in \Nbb$, the concatenation of a closed curve $\gamma$ with itself $n$ times is again a closed curve, denoted by $\gamma^n$.
    \item A closed curve is \emph{irreducible} if it cannot be written as $\gamma^n$ for some closed curve $\gamma$ and $n \geq 2$.
    \item Two closed curves $\gamma$ and $\gamma'$ are \emph{rotationally equivalent} if there exists $j \in \Zbb$ such that $\gamma_i = \gamma'_{i+j}$ for all $i \in \Zbb/k\Zbb$.
    \end{itemize}
\end{definition}

Note that, in a discrete closed plane curve, the same vertex can appear consecutively.
In order to relate discrete closed plane curves and cycles in $S$, it is convenient to define the following.

%The next construction relies on the directed graph $S$, of \cref{figure:large-gentle-quiver}.
An \emph{up-right vertex} of $R$ (and of $S$) is a vertex of the form $ur_i$ for $i \in \Zbb^2$, while a \emph{down-left vertex} is a vertex of the form $d\ell_i$ for $i \in \Zbb^2$; a \emph{diagonal vertex} is either an up-right vertex or a down-left vertex.
If $v = ur_i$ or $v = d\ell_i$ is a diagonal vertex, its corresponding \emph{grade} is $\mathrm{idx}(v) \coloneqq i \in \Zbb^2$.
\emph{A full turn around} $i$ is an oriented cycle that is rotationally equivalent to $\{(ur_i, u_i), (u_i,\ell_i), (\ell_i,d\ell_i), (d\ell_i,d_i), (d_i, r_i), (r_i,ur_i)\}$ in $S$.


We observe that, if $e$ is an oriented cycle in $S$, then it must visit at least one (in fact at least two) diagonal vertices.
We also make the following simple observation.

\begin{lemma}
    If $v, w \in S$ are such that $\|\idx(v) - \idx(w)\|_1 = 1$, then there exists a unique shortest oriented path from $v$ to $w$ in $S$.
    \qed
\end{lemma}


\begin{construction}
    \label{construction:closed-curve-to-oriented-cycle}
    Given a discrete closed plane curve $\gamma = \{\gamma_0, \dots, \gamma_{k-1}\}$, we construct an oriented cycle $e$ in $S$ as follows.
    \begin{itemize}
    \item If $\gamma$ is constantly $i \in \Zbb$, then let $e$ be the concatenation of $k$ full turns around $i$.
    \item Otherwise, by grouping consecutive appearances of the same grade, we can write $\gamma = i_1^{t_1+1} \cdot i_2^{t_2+1} \cdots i_{j}^{t_j+1}$, so that consecutive grades satisfy $i_m \neq i_{m+1} \in \Zbb^2$, and such that $i_1 \neq i_j \in \Zbb^2$ as well.
    \begin{itemize}
        \item Pick the unique pair of diagonal vertices $v_1, v_2$ at shortest path distance in $S$, such that $\idx(v_1) = i_1$ and $\idx(v_2) = i_2$; let $p_1$ be the unique shortest path from $v_1$ to $v_2$ in $S$.
        \item Let $p_2$ be the unique shortest oriented path from $v_2$ to the closest diagonal vertex $v_3$ that satisfies $\idx(v_3) = i_3$.
        \item Let $p_3$ be the unique shortest oriented path from $v_3$ to the closest diagonal vertex $v_4$ that satisfies $\idx(v_4) = i_4$.
        \item Etc., until we reach $v_1$ again through a shortest path $p_j$.
    \end{itemize}
    \end{itemize}
    Construct the oriented cycle $e \coloneqq p_1 \cdots p_j$.
\end{construction}

See \cref{figure:drawing-boundary} for an example illustrating \cref{construction:closed-curve-to-oriented-cycle}.

\begin{construction}
    \label{construction:oriented-cycle-to-closed-curve}
    Given $e = \{e_0, \dots, e_{k-1}\}$ an oriented cycle in $S$, we construct a discrete closed plane curve $\gamma$ as follows.
    \begin{itemize}
        \item If all that $e$ is doing is $k$ full turns around some $i \in \Zbb^2$, then we construct the discrete closed plane curve $\gamma \coloneqq i^k$ given by $i$ repeated $k$ times.
        \item Otherwise, rotating $e$ if necessary, we can assume that $e$ starts at a diagonal vertex $v$, which has a different grade than the last diagonal vertex that it visits.
        Note that $e$ behaves as follows:
        \begin{itemize}
            \item Starting from $w_1 \coloneqq v$, it first does a number $t_1 \in \Nbb$ of full turns around $\idx(w_1) \in \Zbb^2$.
            \item It then gets to the first diagonal vertex $w_2$ with the property that $\idx(w_2) \neq \idx(w_1)$, and proceeds to do some number $t_2 \in \Nbb$ of full turns around $\idx(w_2) \in \Nbb$.
            \item It then gets to the first subsequent diagonal vertex $w_3$ such that $\idx(w_3) \neq \idx(w_2)$, and proceeds to do some number $t_3$ of full turns around $\idx(w_3) \in \Nbb$.
            \item Etc., until we reach $w_v$ again.
        \end{itemize}
        From this observation, we get a sequence of grades $\idx(w_1), \dots, \idx(w_{j})$ and a sequence of numbers $t_1, \dots, t_{j}$ (which are allowed to be zero), and we construct the concatenation
        \[
            \gamma \coloneqq \idx(w_1)^{t_1+1} \cdot \idx(w_2)^{t_2+1} \cdots \idx(w_{j})^{t_{j}+1}.
        \]
    \end{itemize}
\end{construction}

