The following proof is straightforward, but tedious, so we omit it.

\begin{lemma}
    \label{lemma:closed-curve-to-oriented-cycle}
    \cref{construction:closed-curve-to-oriented-cycle,construction:oriented-cycle-to-closed-curve}
    induce inverse bijections between the set of discrete closed curves up to rotational equivalence and the set of oriented cycles in $S$ up to rotational equivalence.
    The bijections respect irreducibility.
    \qed
\end{lemma}

\begin{proposition}
    \label{proposition:classification-of-bands}
    %The indecomposable band modules in $\rep(R)$ are classified by boundary components.
    %More specifically,
    There is a bijection between isomorphism classes of band modules over $R$ and equivalence classes of boundary components.
    The bijection is given by mapping a discrete closed plane curve to a periodic $\Zbb$-word in $R$ using \cref{construction:oriented-cycle-to-periodic-word,construction:closed-curve-to-oriented-cycle}.
\end{proposition}
\begin{proof}
    We apply the classification result for indecomposable representations of string algebras (\cref{theorem:string-algebra-module-classification}), which is in terms of pairs consisting of an equivalence class of periodic $\Zbb$-words and an isomorphism class of indecomposable $\kbb[T,T^{-1}]$-modules.
    The correspondence between equivalence classes of periodic $\Zbb$-words and irreducible discrete closed curves is obtained using the bijections of \cref{lemma:closed-curve-to-oriented-cycle,lemma:oriented-cycle-to-periodic-word}.
    The correspondence between isomorphism classes of finite dimensional indecomposable $\kbb[T,T^{-1}]$-modules and similarity classes of matrices as in \cref{definition:boundary-component} (invertible square matrices that are not similar to a block diagonal matrix with more than one block) is standard
    and is given by mapping such a matrix $\Tcal$ to the $\kbb[T,T^{-1}]$-module $M_\Tcal$ with underlying vector space $\kbb^\ell$ and action of $T$ given by $\Tcal$.
\end{proof}



