\begin{proposition}
    \label{proposition:ephemeral-pair-contains-bands}
    Every band representation of $R$ belongs to $\boundaries \subseteq \rep(R)$.
    %Thus, to each boundary component $(\gamma, \Tcal)$ we associate the unique representation (up to isomorphism) $\kbb_{(\gamma, \Tcal)} \in \boundaries$ such that the isomorphism type of $\iota(\kbb_{(\gamma,\Tcal)})$ is that classified by $(\gamma, \Tcal)$, according to \cref{proposition:classification-of-bands}.
\end{proposition}
\begin{proof}
    Specifically, we need to show that every band representation $R$ belongs to the essential image of $\iota : \boundaries \to \rep(R)$.
    Let $X \in \rep(R)$ be a band representation.
    We define $B, D \in \rep(\Zbb^2)$ as $B_i \coloneqq X_{d\ell_i}$ and $D_i \coloneqq X_{ur_i}$, with structure morphisms induced by those of $X$.
    Next, we define morphisms $f : \keryc{D} \to \cokerx{B}$ and $g : \kerxc{D} \to \cokery{B}$.
    Note that, if $X$ is a band representation, then $X_{u_i}$ is the kernel of the morphism $X_{ur_i} \to X_{ur_{i+(0,1)}}$, which implies that $\keryc{D}_i \cong X_{u_i}$.
    Similarly, we have $\kerxc{D}_i \cong X_{r_i}$, $\cokerx{B}_i \cong X_{\ell_i}$ and $\cokery{B}_{i} \cong X_{d_i}$.
    Then, the structure morphism $X_{u_i} \to X_{\ell_i}$ and $X_{r_i} \to X_{d_i}$ provide the morphisms
    $f : \keryc{D} \to \cokerx{B}$ and $g : \kerxc{D} \to \cokery{B}$.
    It is then straightforward to check that $\iota(B,D,f,g) \cong X$.
\end{proof}

The next definition is well-defined thanks to \cref{proposition:ephemeral-pair-contains-bands}.

\begin{definition}
    \label{remark:boundary-component-module}
    Given a boundary component $(\gamma, \Tcal)$, we define the \emph{boundary component representation} $\kbb_{(\gamma,\Tcal)} \in \boundaries$ as the isomorphism class of representations classified by $(\gamma, \Tcal)$, according to \cref{proposition:classification-of-bands}.
\end{definition}

\boundarytame*
\begin{proof}
    This follows directly from \cref{proposition:classification-of-bands,proposition:partial-is-band,proposition:ephemeral-pair-contains-bands}.
\end{proof}

