\begin{definition}
    \label{definition:closed-curve}
    Let $k \geq 1 \in \Nbb$.
    A \emph{closed curve} with $2k$ corners $\Omega = (B,D)$ consists of functions $B,D : \Zbb/k\Zbb \to \spreadcurvesf$, such that, for all $i \in \Zbb/k \Zbb$,
    we have
    $\botright{(B_i)} = \botright{(D_{i+1})}$ and
    $\topleft{(D_i)} = \topleft{(B_{i+1})}$.
\end{definition}

The idea behind \cref{definition:closed-curve} is that the union of the curves in $B_\bullet$ and $D_\bullet$ form a closed curve on the plane; for examples, see \cref{figure:boundary-of-spread,figure:main-figure,section:examples}.

\begin{definition}
    Let $\ell \geq 1 \in \Nbb$ and let $\Omega = (B,D)$ be closed curve with $2k$ corners.
    Define the \emph{$\ell$th power} of $\Omega$ as the closed curve with $2\ell k$ corners $\Omega^\ell = (B^\ell_\bullet, D^\ell_\bullet)$ by
    $B^\ell_j = B_{\overline{j}}$ and $D^\ell_j = D_{\overline{j}}$, where $j \in \Zbb/k\ell \Zbb$ and $\overline{j} = j \,\mod(k)$.
\end{definition}

\begin{construction}
    Let $\ell \geq 1 \in \Nbb$, and let $t : \kbb^\ell \to \kbb^\ell$ be a linear automorphism.
    \begin{enumerate}
    \item Let $M_t \in \Mod_{\kbb[T,T^{-1}]}$ have as underlying vector space $\kbb^\ell$, with the action of $T$ given by $t$.
    \item Let $N \in \Mod_{\Lambda}$ be a module over a $\kbb$-algebra $\Lambda$.
    The direct sum of countably many copies of $N$ given by $N^{\Zbb} = \bigoplus_{i \in \Zbb} N$ is a $(\kbb[T,T^{-1}], \Lambda)$-bimodule, where the action by $T$ is given by mapping the $i$th copy of $N^\Zbb$ to the $(i+1)$th copy.
    By tensoring $M_t \otimes_{\kbb[T,T^{-1}]} N^\Zbb$ we obtain a $(\kbb[T,T^{-1}], \Lambda)$-bimodule with underlying $\Lambda$-module given by $N^\ell$.
    The action of $T$ on $N^\ell$ is given by an endomorphism $N^\ell \to N^\ell$ of $\Lambda$-modules, which we denote by $N^t : N^\ell \to N^\ell$.
    \end{enumerate}
\end{construction}

\begin{definition}
    \begin{itemize}
        \item A closed curve is \emph{irreducible} if it is not the $\ell$th power of a closed curve for any $\ell \geq 2$.
        \item A \emph{boundary component} $(\Omega, t)$ consist of a closed curve $\Omega$ together with a linear automorphism $t : \kbb^\ell \to \kbb^\ell$ such that $M_t \in \Mod_{\kbb[T,T^{-1}]}$ is indecomposable.
        \item Two closed curves with $2k$ corners $\Omega = (B,D)$ and $\Omega' = (B',D')$ are \emph{equivalent} if there exists $j \in \Zbb/k\Zbb$ such that $B'_i = B_{i+j}$ and $D'_i = D_{i+j}$ for every $i \in \Zbb/k\Zbb$.
        \item Two boundary components $(\Omega, t)$ and $(\Omega', t')$ are \emph{equivalent} if $\Omega$ and $\Omega'$ are equivalent and $M_t \cong M_{t'} \in \Mod_{\kbb[T,T^{-1}]}$.
    \end{itemize}
\end{definition}


\begin{notation}
    When representing boundary components in diagrams (e.g., \cref{figure:boundary-of-spread,figure:main-figure,section:examples}), we omit the automorphism $t$ if it is the identity $\kbb \to \kbb$.
\end{notation}

\begin{remark}
    If the field $\kbb$ is algebraically closed,
    any boundary component is equivalent to one of the form $(\Omega, J_{\lambda, \ell})$
    where $J_{\lambda, \ell}$ is a Jordan block of rank $\ell$ and constant $\lambda \neq 0 \in \kbb$.
\end{remark}


