\section{Technical results about two-parameter spreads}

\begin{definition}
    If $I \subseteq \Zbb^2$ is a spread, we let $\min(I) \subseteq I$ denote the set of minimal elements of $I$.
    The \emph{$y$-ordering} on $\min(I)$ is the unique total ordering by increasing $y$-coordinate.
\end{definition}

The $y$-ordering is unique (i.e., no two elements of $\min(I)$ can have the same $y$-coordinate), since if $a,b \in \Zbb^2$ have the same $y$-coordinate, then they must be comparable, and thus they cannot both be minimal elements of $I$.
Note that the $y$-ordering on $\min(I)$ is, equivalently, the unique ordering by decreasing $x$-coordinate.

If $I$ is a finite spread, we denote the $y$-ordering of $\min(I)$ by $\{z_i\}_{i \in S}$ where $S = \{1, \dots, n\}$.

\begin{lemma}
    \label{lemma:join-of-consecutive-minima}
    Let $I \subseteq \Zbb^2$ be a finite spread, and let $\min(I) = \{z_i\}_{i \in S}$ be the $y$-ordering on its set of minimal elements.
    For every $i \in S$ such that $i+1 \in S$, the join $z_i \vee z_{i+1}$ is in $I$.
\end{lemma}
\begin{proof}
    %So given $1 \leq i \leq k-1$, we must show that $z_i \vee z_{i+1} \in I$.
    %Since $z_i$ is minimal, $z_i - (1,0) \notin I$.
    %Now, let $\ell > 0 \in \Nbb$ be the minimum such that $z' \coloneqq z_i + (0,\ell) - (1,0) \in I$, which must exist since $z_{i+1}$ has strictly larger $y$-coordinate, and strictly smaller $x$-coordinate, than $z_i$.
    %We claim that $z' 
    Choose a path from $z_i$ to $z_{i+1}$ contained in $I$ of minimum length:
    \[
        z_i \leq a_1 \geq a_2 \leq a_3 \geq a_4 \leq \cdots \geq a_{\ell-1} \leq a_\ell \geq z_{i+1}.
    \]
    Since every element in this path is in $I$, we can replace the $a_j$ with $j$ even by some $z_{i_j}$, to get a path
    \[
        z_i \leq a_1 \geq z_{i_2} \leq a_3 \geq z_{i_4} \leq \cdots \geq z_{i_{\ell-1}} \leq a_\ell \geq z_{i+1}
    \]
    contained in $I$.
    Next, since $I$ is poset-convex, we can replace the $a_j$ with $j$ odd by a join, as follows
    \[
        z_i \leq (z_i \vee z_{i_1}) \geq z_{i_2} \leq (z_{i_2} \vee z_{i_4}) \geq z_{i_4} \leq \cdots \geq z_{i_{\ell-1}} \leq (z_{i_{\ell-1}} \vee z_{i+1}) \geq z_{i+1},
    \]
    to again get a path contained in $I$.

    For every even $j$, it must be the case that the $y$-coordinate of $z_{i_{j+2}}$ is strictly larger than that of~$z_{i_{j}}$.
    This is because the $y$-coordinate of $z_{i+1}$ is larger than that of $z_i$, so if the path either decreases the $y$-coordinate at some point, or it keeps it the same, one could get a path of smaller length by skipping this.
    Finally, the only possible path of that form that strictly increases the $y$-coordinate is
    $z_i \leq (z_i \vee z_{i+1}) \geq z_{i+1}$, and thus $z_i \vee z_{i+1} \in I$.
    %For every even $\ell$, it must be the case that $i+1 \neq z_{i_\ell} \neq i$, since otherwise the path would not be of minimum length.
\end{proof}

\begin{definition}
    \label{definition:cokerxy-spread}
    Let $I \subseteq \Zbb^2$ be a spread.
    Define
    \begin{align*}
        %\cokerxyspread
        \cokerxyspread{I} = \left\{a \in I : a-(1,1) \notin I \right\}
        \;\; \text{and} \;\;\;
        %\kerxyspread
        \kerxyspread{I} = \left\{a \notin I : a-(1,1) \in I\right\}.
    \end{align*}
\end{definition}



\begin{lemma}
    \label{lemma:boundary-of-spread-is-spread}
    If $I \subseteq \Zbb^2$ is a finite spread, then $\cokerxyspread{I}$ and $\kerxyspread{I}$ are poset-connected.
\end{lemma}
\begin{proof}
    By duality (\cref{section:duality}), it is sufficient to prove that $\cokerxyspread{I}$ is poset-connected.

    Let $\min(I) = \{z_i\}_{i \in S}$ be the $y$-ordering on the set of minimal elements of $I$.
    Clearly, we have $\min(I) \subseteq \cokerxyspread{I}$.
    Now, for every $p \in \cokerxyspread{I}$, there exists a path from $p$ to some $z_i \in \min(I)$ in $\cokerxyspread{I}$: indeed, since $p \in I$, there exists $i \in S$ such that $z_i \leq p$.
    Thus, we need to prove that, for every $i < j \in S$ there exists a path from $z_i$ to $z_j$ in $\cokerxyspread{I}$.
    We claim that the following is a path from $z_i$ to $z_j$ in $\cokerxyspread{I}$:
    \[
        z_i \leq (z_i \vee z_{i+1}) \geq z_{i+1} \leq (z_{i+1} \vee z_{i+2}) \geq z_{i+2} \leq \dots \geq z_{j-1} \leq (z_{j-1} \vee z_j) \geq z_j.
    \]

    To prove the above, it suffices to show that, for every $k \in S$ such that $k+1 \in S$, we have that $z_k \vee z_{k+1}$ is in $\cokerxyspread{I}$.
    By \cref{lemma:join-of-consecutive-minima}, we know that $z_k \vee z_{k+1} \in I$, so we need to prove that $(z_k \vee z_{k+1}) - (1,1) \notin I$.
    If $(z_k \vee z_{k+1}) - (1,1)$ were in $I$, then there would exist $z_\ell \leq (z_k \vee z_{k+1}) - (1,1)$.
    But then either $\ell < k$ or $\ell > k+1$.
    In the first case, the $x$-coordinate of $z_\ell$ would be strictly larger than that of $z_k$, which contradicts $z_\ell \leq (z_k \vee z_{k+1}) - (1,1)$, since the $x$-coordinate of $z_k \vee z_{k+1}$ is that of $z_k$.
    In the second case, the $y$-coordinate of $z_\ell$ would be strictly larger than that of $z_{k+1}$, which also contradicts $z_\ell \leq (z_k \vee z_{k+1}) - (1,1)$, since the $y$-coordinate of $z_k \vee z_{k+1}$ is that of $z_{k+1}$.
    So $(z_k \vee z_{k+1}) - (1,1) \notin I$, concluding the proof.
\end{proof}

\begin{lemma}
    \label{lemma:birth-death-of-spread}
    If $I \subseteq \Zbb^2$ is a finite spread, then
    $\births(\kbb_I) = \{\cokerxyspread{I}\}$ and
    $\deaths(\kbb_I) = \{\kerxyspread{I}\}$.
    Equivalently, we have
    $\cokerxy{\kbb_I} = \kbb_{\cokerxyspread{I}}$ and $\kerxy{\kbb_I} = \kbb_{\kerxyspread{I}}$.
\end{lemma}
\begin{proof}
    By duality (\cref{section:duality}), it is sufficient to prove $\deaths(\kbb_I) = \{\kerxyspread{I}\}$.
    The support of $\kerxy{\kbb_I} = \ker\left(\kbb_I[-1,-1] \xrightarrow{\xbf\ybf} \kbb_I\right) \subseteq \kbb_I[-1,-1]$
    consists of those $a \notin I$ such that $a-(1,1) \in I$, which is equal to $\kerxyspread{I}$, by definition.
    Since any subrepresentation of a spread representation is spread-decomposable (\cref{lemma:submodule-of-spread-is-spread}), we have that $\births(\kbb_I)$ is equal to $\{\kbb_C\}$ with $C$ ranging over the poset-connected components of $\kerxyspread{I}$.
    To conclude the proof, we use \cref{lemma:boundary-of-spread-is-spread}, which implies that  $\kerxyspread{I}$ is poset-connected.
\end{proof}


\begin{lemma}
    \label{lemma:unique-minimum-below}
    Let $I \subseteq \Zbb^2$ be a finite spread curve, and let $\min(I) = \{z_i\}_{i \in S}$ be the $y$-ordering on the set of minimal elements of $I$.
    Suppose that $p \in I$ and $p \neq z_i \vee z_{i+1}$ for all $i \in S$ such that $i+1 \in S$.
    Then, there exists a unique $i \in S$ such that $z_i \leq p$.
\end{lemma}
\begin{proof}
    Since $p \in I$, there must exist at least one $i \in S$ such that $z_i \leq p$.
    Assume that there also exists $j \in S$ such that $z_j \leq p$, with $i \neq j$, and assume, without loss of generality, that $i < j$.
    Then, we must also have $z_{i+1} \leq p$, since the $x$-coordinate of $z_{i+1}$ is at most that of $z_i$, which is at most that of $p$; and the $y$-coordinate of $z_{i+1}$ is at most that of $z_j$, which is at most that of $p$.
    This implies that $(z_i \vee z_{i+1}) \leq p$.
    All elements between $z_i \vee z_{i+1}$ and $p$ must be in $I$, since $I$ poset-convex.
    Towards a contradiction, assume that $p \neq (z_i \vee z_{i+1})$.
    Then either $(z_i \vee z_{i+1}) + (1,0) \in I$ or
    $(z_i \vee z_{i+1}) + (0,1) \in I$.
    Let us assume $a = (z_i \vee z_{i+1}) + (1,0) \in I$ (the other case is analogous).
    Then, we have that $z_i \leq a - (1,1) \leq a$, so both $a$ and $a - (1,1)$ are in $I$, which violates the fact that $I$ is a spread curve.
    This means that $p = (z_i \vee z_{i+1})$, concluding the proof.
\end{proof}


