\subsection{Additive invariants and bases}
\label{section:appendix-additive-invariants-bases}

\begin{lemma}
    \label{lemma:additivity-finer-invariant}
    Let $\alpha \succcurlyeq \alpha'$ be additive invariants on an additive category $\Acal$.
    Let $\{M_i \in \Acal\}_{i \in I}$ and $\{c_i \in \Zbb\}_{i \in I}$ be such that $c_i \neq 0$ for finitely many $i \in I$, and $\sum_{i \in I} c_i \cdot \alpha(M_i) = 0$.
    Then, $\sum_{i \in I} c_i \cdot \alpha'(M_i) = 0$.
\end{lemma}
\begin{proof}
    Let $I = A \sqcup B \sqcup C$ be such that $c_i = 0$ if $i \in A$, $c_i > 0$ if $i \in B$, and $c_i < 0$ if $i \in C$.
    Then, by additivity of $\alpha$, we have
    \[
        \alpha\left( \bigoplus_{i \in B} M_i^{c_i} \right)
        =
        \alpha\left( \bigoplus_{i \in C} M_i^{-c_i} \right),
    \]
    which implies, by the fact that $\alpha \succcurlyeq \alpha'$, that
    \[
        \alpha'\left( \bigoplus_{i \in B} M_i^{c_i} \right)
        =
        \alpha'\left( \bigoplus_{i \in C} M_i^{-c_i} \right).
    \]
    By additivity of $\alpha'$, it follows that $\sum_{i \in I} c_i \cdot \alpha'(M_i) = 0$, as required.
\end{proof}



\begin{lemma}
    \label{lemma:any-decomposition-gives-count}
    Let $\alpha$ be an additive invariant on an additive category $\Acal$, let $\Bcal$ be a basis for $\alpha$, and let $f : \Bcal \to \Zbb$.
    If $M \in \Acal$, and $A_1, \dots, A_k, B_1, \dots, B_\ell \in \Bcal$ are such that
    \[
        \alpha(M) = \sum_{i = 1}^k \alpha(A_i) - \sum_{j = 1}^\ell \alpha(B_j),
    \]
    then $\Ncal^{(\alpha,\Bcal,f)}(M) = \sum_{i = 1}^k f(A_i) - \sum_{j = 1}^\ell f(B_j)$, and in particular $\Ncal^{(\alpha,\Bcal)}(M) = k - \ell$.
    \qed
\end{lemma}
\begin{proof}
    This is an immediate consequence of additivity and \cref{lemma:basic-results-counts-basis}(2).
\end{proof}

\begin{proof}[Proof of \cref{proposition:I-is-basis-of-rk-I}]
    Consider the partial order on $\Ical$ given by inclusion.
    If $I \in \Ical$, then the support of $\Rk_\Ical(\kbb_I) \in \Zbb^{\Ical}$ is the principal upset of $\Ical$ corresponding to $I$, where it is constantly $1$.
    By M\"obius inversion \cite[Chapter~3.7]{stanley}, the set $\{\Rk_{\Ical}(\kbb_{I})\}_{I \in \Ical}$ forms a basis of $\Zbb^{\Ical}$, and the result follows.
    Alternatively, one could use \cref{proposition:projectives-are-basis}(3), but we omit the details.
\end{proof}



\begin{definition}
    \label{definition:relative-projective-resolution}
    Let $\Lambda$ be a finite dimensional $\kbb$-algebra and let $\Xcal$ be a set of pairwise non-isomorphic finite dimensional, indecomposable $\Lambda$-modules.
    A \emph{$\Xcal$-projective resolution} of a $\Lambda$-module $M$ is an $\Xcal$-exact sequence
    $\cdots \to C_1 \to C_0 \to M \to 0$ such that $C_i$ is $\Xcal$-decomposable for every $i \geq 0$.
\end{definition}

In the following proposition, all modules are assumed to be finite dimensional.

\begin{proposition}
    \label{proposition:projectives-are-basis-2}
    Let $\Lambda$ be a finite dimensional $\kbb$-algebra.
    \begin{enumerate}
        \item The set $\indsimpl_\Lambda$ is a basis for $\dimhom_{\indproj_\Lambda}$ and $\Ksf_{\indproj_\Lambda}$.
        \item The additive invariants $\dimhom_{\indproj_\Lambda}$ and $\Ksf_{\indproj_\Lambda}$ are equivalent.
        \item If $\Lambda$ has finite global dimension, then $\indproj_\Lambda$ is a basis for $\dimhom_{\indproj_\Lambda}$.
        \item If $\Xcal$ is a set of pairwise non-isomorphic indecomposable $\Lambda$-modules, then $\dimhom_{\Xcal} \approx \Ksf_{\Xcal}$.
        \item Let $\Xcal$ be a set of pairwise non-isomorphic indecomposable $\Lambda$-modules.
              If every $\Lambda$-module admits a finite $\Xcal$-projective resolution,
              then $\Xcal$ is a basis for $\dimhom_{\Xcal} \approx \Ksf_\Xcal$.
    \end{enumerate}
    % containing one representative of each isomorphism class of indecomposable projective $\Lambda$-module.
\end{proposition}
\begin{proof}
    %    Recall that $\{X/rX\}_{X \in \Xcal}$ contains a representative of all isomorphism classes of simple modules, where $r$ denotes radical, and that no two of these modules are isomorphic \luis{cite}.
    Let $\indproj_\Lambda = \{P_i\}_{i \in I}$ and $\indsimpl_\Lambda = \{S_i\}_{i \in I}$ with $S_i = P_i/\mathrm{rad}(P_i)$.

    \medskip

    \noindent
    \emph{(1)}.
    The set $\{\dimhom_{\indproj_\Lambda}(S_i)\}_{i \in I}$ is linearly independent since $\dim \hom(P_i, S_j)\neq 0$ if and only if $i=j$.
    Let $M \in \mod_\Lambda$ and let $0 = J_0 \subset \cdots \subset J_k = M$ be a composition series of $M$.
    Then $\dimhom_{\indproj_\Lambda}(M) = \sum_{i = 1}^{k-1}\, \dimhom_{\indproj_\Lambda}(J_{i+1}/J_i)$ exhibits the dimension vector of $M$ as a sum of dimension vectors of simple modules, so
    $\{\dimhom_{\indproj_\Lambda}(S_i)\}_{i \in I}$ generates $\dimhom_{\indproj_\Lambda}$.

    Simples form a basis for $\Ksf_{\indproj}$, by \cite[Theorem~1.7]{auslander-reiten-smalo}.
    %is the usual Grothendieck group, that is, the free Abelian group on isomorphism of $\Lambda$-modules modulo relations induced by short exact sequences.
    %Thus, $\{[S_i]\}_{i \in I}$ generates $\Ksf_{\indproj_\Lambda}$ by the existence of decomposition series, and the set is linearly independent because the simple factors in the decomposition series are unique up to permutation and isomorphism.
    %So $\indsimpl_\Lambda$ is a basis for $\Ksf_{\indproj}$.

    \medskip

    \noindent
    \emph{(2)}.
    If $0 \to A \to B \to C \to 0$ is a short exact sequence of $\Lambda$-modules, then $\dimhom_{\indproj_\Lambda}(B)
        = \dimhom_{\indproj_\Lambda}(A)
        + \dimhom_{\indproj_\Lambda}(C)$, so the invariant $\dimhom_{\indproj_\Lambda}$ factors through $\Ksf_{\indproj_\Lambda}$, so that $\Ksf_{\indproj_\Lambda} \succcurlyeq \dimhom_{\indproj_\Lambda}$.
    Since the two invariants admit the same basis, by (1), they are equivalent.

    \medskip

    \noindent
    \emph{(3)}.
    Any two bases of $\dimhom_{\indproj_\Lambda}$ have the same number of elements.
    Since $\indproj_\Lambda$ has the same number of elements as $\indsimpl_\Lambda$, it is sufficient, by (1), to show that $\indproj_\Lambda$ generates $\dimhom_{\indproj_\Lambda}$.
    If $M \in \mod_\Lambda$, let $0 \to C_k \to \cdots \to C_0 \to M$ be a finite $\Lambda$-projective resolution of $M$.
    Then, by the exactness of $\hom(P_i,-)$ for every $1 \leq i \leq k$, we have $\dimhom_{\indproj_\Lambda}(M) = \sum_{i = 1}^k (-1)^i\, \dimhom_{\indproj_\Lambda}(C_i)$, so $\indproj_\Lambda$ generates $\dimhom_{\indproj_\Lambda}$.

    \bigskip

    In (4) and (5) we use the following construction, known as \emph{projectivization}, which allows us to reduce the case of arbitrary $\Xcal$ to the case where $\Xcal$ consists of indecomposable projectives.
    If $P \coloneqq \bigoplus_{X \in \Xcal} X$ and $E \coloneqq \End(P)$, the functor $(-)^P : \mod_{\Lambda} \to \mod_E$ restricts to an equivalence of categories $\add(\Xcal) \to \proj(E)$ \cite[Chapter~II,~Section~2]{auslander-reiten-smalo}; let $G : \proj(E) \to \add(\Xcal)$ be its inverse.
    This gives us a bijection $f : \Xcal \to \indproj_E$ such that $\dimhom_{\indproj_E}(M^P) \circ f = \dimhom_{\Xcal}(M) : \Xcal \to \Zbb$, for every $M \in \mod_\Lambda$.

    \medskip
    \noindent
    \emph{(4)}.
    This follows from projectivization and (2).

    \medskip
    \noindent
    \emph{(5)}.
    By projectivization, it is enough to prove that $\indproj_E$ is a basis for $\dimhom_{E} : \mod_E \to \Zbb^{\indproj_E}$.
    By (3), it is enough to show that $E$ has finite global dimension, which is equivalent to every $E$-module $M \in \mod_E$ admitting a finite $E$-projective resolution (this is because every $E$-module is an iterated extension by simple modules, of which there are finitely many isomorphism types, so the global dimension of $E$ is attained as the projective dimension of a simple \cite[Corollary~11]{auslander}).
    To build a finite projective resolution of any $M \in \mod_\Lambda$ we proceed as follows.
    Let $A \to B \to M$ be a finite $E$-projective presentation of $M$.
    Let $0 \to C_k \to \cdots \to C_0 \to \ker(G(A) \to G(B))$ be a finite $\Xcal$-projective resolution of $\ker(G(A) \to G(B)) \in \mod_\Lambda$.
    We have
    \[
        \ker\left(G(A) \to G(B)\right)^P
        \cong
        \ker\left(G(A)^P \to G(B)^P\right)
        \cong
        \ker(A \to B),
    \]
    by left-exactness of $(-)^P$.
    This allows us to splice the exact sequence of $E$-projectives
    $0 \to C_k^P \to \cdots \to C_0^P$ with $A \to B \to M$ to get a finite $E$-projective resolution $0 \to C_k^P \to \cdots \to C_0^P \to A \to B \to M$, as required.
    %    Moreover, if $S$ is a simple module and $X \in \Xcal$, then $\hom(X,S) \neq 0$
    %    Clearly, a choice of isomorphism class of each simple $\Lambda$-module gives a basis for $\dimhom_\Xcal$, since, if $S$ is a simple $\hom(X,S).$
