\end{proof}




\begin{proof}[Proof of \cref{remark:basis-for-known-invariants}]
    The first statement follows from \cref{proposition:I-is-basis-of-rk-I}.
    The second statement follows from \cref{proposition:I-is-basis-of-rk-I}.
    The third statement follows from \cref{proposition:projectives-are-basis} and the fact that the \emph{spread exact structure} (i.e., the exact structure whose indecomposable projectives are the spread representations) on the category of representations of a finite poset has finite global dimension \cite[Proposition~4.5]{asashiba-escolar-nakashima-yoshiwaki-2}.
    The fourth statement follows from \cref{proposition:projectives-are-basis} and the fact that the \emph{rank exact structure} (i.e., the exact structure whose indecomposable projectives are the hook representations) on the category of representations of a finite poset has finite global dimension \cite[Theorem~1.2]{blanchette-brustle-hanson}.
\end{proof}

\subsection{Spread representations}

\begin{lemma}[{cf. \cite[Lemma~4.4]{asashiba-escolar-nakashima-yoshiwaki-2}}]
    \label{lemma:submodule-of-spread-is-spread}
    Let $\Pscr$ be a poset, let $I \subseteq \Pscr$ be a spread, and let $M \subseteq \kbb_I$ be a subrepresentation.
    Then $M$ is spread-decomposable.
\end{lemma}
\begin{proof}
    Let $i \in \Pscr$.
    Note that, if $M_i \neq 0$, then $M_i = \kbb$.
    So it is sufficient to show that the support of $M$ is a disjoint union of spreads.
    We prove the stronger fact that the support of $M$ is poset-convex.
    Let $i \leq j \leq k \in \Pscr$, with both $i$ and $k$ in the support of $M$.
    The morphism $\phi^{M}_{i,k} : M_i \to M_k$ is the identity $\kbb \to \kbb$, so, since $\phi^{M}_{i,k} = \phi^M_{j,k} \circ \phi^M_{i,j}$, we have $M_j \neq 0$, and thus $j$ is in the support of $M$, as required.
\end{proof}


\begin{theorem}[{\cite[Theorem~24]{asashiba-buchet-escolar-nakashima-yoshiwaki}}]
    \label{theorem:indecomposable-think-is-spread}
    Let $M \in \repf(\Zbb^2)$.
    If $M$ is indecomposable and $\dim M_i \in \{0,1\}$ for every $i \in \Zbb^2$, then $M$ is a spread representation.
\end{theorem}
\begin{proof}
    By translating $M$ if necessary, we may assume that its support is contained in some finite grid $\Gcal^2$, and by the fully faithful embedding $\rep(\Gcal^2) \hookrightarrow \repf(\Zbb^2)$ induced by the inclusion $\Gcal^2 \hookrightarrow \Zbb^2$ and zero-padding, we may assume that $M \in \rep(\Gcal^2)$.
    The result then follows from \cite[Theorem~24]{asashiba-buchet-escolar-nakashima-yoshiwaki}, which states that, over a finite, two-dimensional grid, an indecomposable of pointwise dimension at most one is necessarily a spread.
\end{proof}

\subsection{Betti tables}

\begin{lemma}
    \label{lemma:inequalities-betti-tables-1}
    Let $\Pscr$ be a poset and let $M, N \in \rep(\Pscr)$ be finitely generated.
    If there exists a surjection $N \twoheadrightarrow M$, then $|\beta_0^M| \leq |\beta_0^N|$.
\end{lemma}
\begin{proof}
    Let $P \to N$ be a projective cover, so that $P$ is projective with $|\beta_0^N|$-many summands.
    Then $P \to N \to M$ is surjective, so that $|\beta_0^M| \leq |\beta_0^N|$.
\end{proof}

\begin{lemma}
    \label{lemma:inequalities-betti-tables-2}
    Let $M,N \in \rep(\Zbb^2)$ be finitely generated, projective representations, and let $\psi : M \hookrightarrow N$ be a monomorphism.
    The kernel $\ker(\psi)$ is finitely generated and projective, and $|\beta_0^{\ker(\psi)}| \leq |\beta_0^M|$.
\end{lemma}
\begin{proof}
    The global dimension of the category of finitely generated, bigraded $\kbb[\xbf,\ybf]$-modules is two, due to Hilbert's syzygy theorem.
    This implies that $\ker(\psi)$ is finitely generated and projective.
    Moreover, the representation $\ker(\psi)$ must have at most as many indecomposable summands as $M$, since we have a monomorphism $\ker(\psi) \hookrightarrow M$ and the number of indecomposable summands of any of these representations can be computed by evaluating at $(x,y) \in \Zbb^2$ with $x,y \gg 0$.
\end{proof}


