\section{Cauchy indices}\label{section:Cauchy.indices}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this section, we establish a generalisation (one direction)
of~\cite[Theorem~1 and Corollary~1]{CravenCsordasSmith} using the Cauchy indices
whose definition and basic properties we present first.

%In this section, we introduce a special counter known as the Cauchy index.

Consider a real rational function $R$ which may  have a pole at $\infty$.
%
\begin{definition}\label{Def.Cauchy.index.at.pole}
The quantity
%
\begin{equation}\label{Cauchy.index.at.odd.pole}
\Ind\nolimits_{\omega}(R)\eqbd
\begin{cases}
   \; +1&\;\text{if}\quad R(\omega-0)<0<R(\omega+0),\\
   \; -1&\;\text{if}\quad R(\omega-0)>0>R(\omega+0),
\end{cases}
\end{equation}
is called the \textit{index\/} of the function $R$ at its
\textit{real\/} pole $\omega$ of \textit{odd\/} order.
%

We also set
%
\begin{equation}\label{Cauchy.index.at.even.pole}
\Ind\nolimits_{\omega}(R)\eqbd 0
\end{equation}
if $\omega$ is a real pole of the function $R$ of \textit{even\/}
order.
\end{definition}




Suppose that the function $R$ has $m$ real poles in total, viz.,
$\omega_1<\omega_2<\dots<\omega_m$.

%
%\smallskip

\begin{definition}\label{Def.Cauchy.index.on.interval}
The quantity
%
\begin{equation}\label{Cauchy.index.on.interval}
\Ind\nolimits_a^b(R)\eqbd \sum\limits_{i\,\colon\,a<\omega_i<b}
\Ind\nolimits_{\omega_i}(R).
\end{equation}
%
is called the \textit{Cauchy index} of the function $R$ on the
interval~$(a,b)$.
\end{definition}

We are primarily interested in the quantity $\IndC(R)$, the Cauchy
index of $R$ on the real line. However, since the function $R$
may have a pole at the point $\infty$, it is convenient for us to
consider this pole as \textit{real}. From this point of view, let
us introduce the index at $\infty$ following, e.g.,~\cite{Barkovsky.2,Holtz_Tyaglov}.
To do so, we consider the function~$R$ as a map on the \textit{projective
line} $\PR^1\eqbd \mathbb{R}^1\cup\{\infty\}$ into itself. So, if the
function $R$ has a pole at~$\infty$, then we let
%
\begin{equation}\label{Cauchy.index.at.infty}
\IndI(R) \eqbd
\begin{cases}
\; +1 & \quad\text{if}\quad R(+\infty)<0<R(-\infty),\\
\; -1& \quad\text{if}\quad R(+\infty)>0>R(-\infty),\\
\; \quad\! 0 & \quad\text{if}\quad \sgn R(+\infty)=\sgn R(-\infty).
\end{cases}
\end{equation}
%
Thus, the generalised Cauchy  index of the function $R$ on the
projective real line is
%
\begin{equation}\label{Cauchy.index.on.projective.line}
\IndPR(R)\eqbd \IndC(R)+\IndI(R).
\end{equation}
%

\smallskip \begin{remark}\label{remark.2.1}
Obviously, if the function $R$ has no pole at $\infty$, then the generalised
Cauchy index  $\IndPR(R)$ coincides with the usual Cauchy index $\IndC(R)$.
\end{remark}

Following~\cite{Barkovsky.2}, we list a few properties of
generalised Cauchy indices, which will be of use later.
First, note that a polynomial $q(z)=cz^{\nu}+\cdots$
$(\nu=\deg q)$ can be viewed as a rational function with
a single pole at $\infty$, hence
%
\begin{equation}\label{Cauchy.index.of.poly}
\IndI(q)=
\begin{cases}
-\sgn c\; &\text{if}\quad\nu\quad\text{is odd},\\
\;\;\; 0     \; &\text{if}\quad\nu\quad\text{is even}.\\
\end{cases}
\end{equation}
%

The following theorem (see~\cite{Barkovsky.2,Holtz_Tyaglov} and references there)
collects all properties of Cauchy indices that we need.
%
\begin{theorem}\label{Th.Cauchy.index.properties}
Let $R$ be a real rational function.
\begin{itemize}
%
\item[1)] If $d$ is a real constant, then $\IndPR(d+R)=\IndPR(R)$.
%
\item[2)] If $q$ is a real polynomial and $|R(\infty)|<\infty$,
then $\IndPR(q+R)=\IndC(R)+\IndI(q)$.
%
\item[3)] If $R_1$ and $R_2$ are real rational functions that have no
real poles in common, then
%
\begin{equation*}%\label{Cauchy.index.of.functions.sum}
\IndC(R_1+R_2)=\IndC(R_1)+\IndC(R_2).
\end{equation*}
%
\item[4)] $\IndPR\left(-\dfrac1R\right)=\IndPR(R)$.
%
\end{itemize}
\end{theorem}
%


