Now we are in a position to establish an extension of an important result by T.\,Craven, G.\,Csordas
and W.\,Smith~\cite[Theorem~1 and Corollary~1]{CravenCsordasSmith} for polynomials (see also~\cite[Problem~133]{GunterKuzmin}
and~\cite[Problem~728]{FaddeevSominsky}).

%
\begin{theorem}\label{Theorem.real.zeroes.p.sigma}
Let $p$ be a real polynomial with $Z_{\mathbb{C}}(p)=2m$. If there exists $\sigma\in\mathbb{R}$ such that
$Q[p_{\sigma}](x)<0$ for all $x\in\mathbb{R}$ where it is defined, then
%
\begin{equation}\label{Number.real.zeroes.Q.ext}
Z_{\mathbb{R}}\left(Q[p]\right)=2m-2m_{\sigma},
\end{equation}
%
where $2m_{\sigma}=Z_{\mathbb{C}}\left(p_{\sigma}\right)$. Moreover, the real zeroes of $Q[p]$ different
from zeroes of $p_{\sigma}$ of multiplicity greater than $2$ (if any) are simple.
\end{theorem}
%
Note that $2m_{\sigma}\leqslant2m$ by~\eqref{Propos.sigma.p.zeroes}.
%
\begin{proof}
%Without loss of generality, we suppose that $p$ has only simple zeroes.

Suppose first that $\sigma\neq0$, so $\deg p_{\sigma}=\deg p=:n$. By assumption
%
\begin{equation}\label{Q1.negativity}
Q[p_{\sigma}](x)=\dfrac{p_{\sigma}(x)p''_{\sigma}(x)-[p'_{\sigma}(x)]^2}{p^2_{\sigma}(x)}<0
\end{equation}
%
for any $x\in\mathbb{R}$ such that $p_{\sigma}(x)\neq0$.


Consider the function
%
\begin{equation*}
H(z)=\dfrac{p_{\sigma}(z)}{p(z)}=\dfrac{p'(z)}{p(z)}+\sigma.
\end{equation*}
%
It is easy to see that
%
\begin{equation}\label{H.derivartive.1}
H'(z)=Q[p](z)=\dfrac{p(z)p''(z)-[p'(z)]^2}{p^2(z)},
\end{equation}
%
and
%
\begin{equation}\label{H.log.derivartive.1}
\dfrac{H'(z)}{H(z)}=\dfrac{p(z)p''(z)-[p'(z)]^2}{p(z)p_{\sigma}(z)}=\dfrac{p(z)p'_{\sigma}(z)-p'(z)p_{\sigma}(z)}{p(z)p_{\sigma}(z)}=\dfrac{p'_{\sigma}(z)}{p_{\sigma}(z)}-\dfrac{p'(z)}{p(z)}.
\end{equation}
%
Since $\dfrac{H'(z)}{H(z)}\to0$ as $|z|\to\infty$, from~\eqref{Cauchy.index.on.projective.line} we have
%
\begin{equation}\label{Theorem.real.zeroes.p.sigma.proof.0}
\IndPR\left(\dfrac{H'}{H}\right)=\IndC\left(\dfrac{H'}{H}\right)%=\IndC\left(\dfrac{p'_{\sigma}}{p_{\sigma}}\right)-\IndC\left(\dfrac{p'}{p}\right).
\end{equation}
%

Suppose that $p(z)$ has $d_1$ simple real zeroes and $d_2$ multiple real zeroes:
%
\begin{equation*}%\label{Theorem.real.zeroes.p.sigma.proof.0.0.1}
p(z)=a\prod\limits_{i=1}^{d_1}(z-\lambda_i)\prod\limits_{j=1}^{d_2}(z-\mu_j)^{n_j}q(z),
\end{equation*}
%
where $a>0$, $n_j\geqslant2$, $j=1,\ldots,d_2$, and $q(x)\neq0$ for $x\in\mathbb{R}$. Here $\deg q=2m$. Then
%
\begin{equation}\label{Theorem.real.zeroes.p.sigma.proof.0.1}
p_{\sigma}(z)=a\sigma\prod\limits_{j=1}^{d_2}(z-\mu_j)^{n_j-1}g(z)h(z),
\end{equation}
%
where $g(z)$ has only real zeroes by assumption, and $h(x)\neq0$ for $x\in\mathbb{R}$, $\deg h=2m_{\sigma}$. So we have
%
\begin{equation}\label{Theorem.real.zeroes.p.sigma.proof.1}
\deg g=n-\sum\limits_{j=1}^{d_2}(n_j-1)-2m_{\sigma}=d_1+d_2+\sum\limits_{j=1}^{d_2}(n_j-1)+2m-\sum\limits_{j=1}^{d_2}(n_j-1)-2m_{\sigma}=d_1+d_2+2m-2m_{\sigma}.
\end{equation}
%
Let
%
\begin{equation}\label{Theorem.real.zeroes.p.sigma.proof.2}
g(z)=\prod\limits_{k=1}^{l_1}(z-t_k)\prod\limits_{i=1}^{l_2}(z-s_i)^{r_i},
\end{equation}
%
where $r_i\geqslant2$, $i=1,\ldots,l_2$, and the numbers $t_k$ and $s_i$ are real and different from $\mu_j$.
Then we have
%
\begin{equation*}
\dfrac{p'_{\sigma}(z)}{p_{\sigma}(z)}=\sum\limits_{j=1}^{d_2}\dfrac{n_j-1}{z-\mu_j}+\sum\limits_{k=1}^{l_1}\dfrac{1}{z-t_k}+
\sum\limits_{i=1}^{l_2}\dfrac{r_i}{z-s_i}+\dfrac{h'(z)}{h(z)},
\end{equation*}
%
and
%
\begin{equation*}
\dfrac{p'(z)}{p(z)}=\sum\limits_{i=1}^{d_1}\dfrac{1}{z-\lambda_i}+\sum\limits_{j=1}^{d_2}\dfrac{n_j}{z-\mu_j}+\dfrac{q'(z)}{q(z)}.
\end{equation*}
%
Consequently, from~\eqref{H.log.derivartive.1} one gets
\begin{equation}\label{H.log.derivartive.2}
\dfrac{H'(z)}{H(z)}=\sum\limits_{k=1}^{l_1}\dfrac{1}{z-t_k}+\sum\limits_{i=1}^{l_2}\dfrac{r_i}{z-s_i}-
\sum\limits_{i=1}^{d_1}\dfrac{1}{z-\lambda_i}-\sum\limits_{j=1}^{d_2}\dfrac{1}{z-\mu_j}+\dfrac{h'(z)}{h(z)}-\dfrac{q'(z)}{q(z)}.
\end{equation}
%
The polynomials $h$ and $q$ have no real zeroes, so their logarithmic derivatives do not contribute to $\IndC\left(\dfrac{H'}{H}\right)$. Thus,
from Theorem~\ref{Th.Cauchy.index.properties} and from~\eqref{Theorem.real.zeroes.p.sigma.proof.1}--\eqref{H.log.derivartive.2} we obtain
%
\begin{equation}\label{Theorem.real.zeroes.p.sigma.proof.2.1}
\IndC\left(\dfrac{H'}{H}\right)=l_1+l_2-d_1-d_2=d_1+d_2+2m-2m_{\sigma}-\sum\limits_{i=1}^{l_2}(r_i-1)-d_1-d_2=2m-2m_{\sigma}-\sum\limits_{i=1}^{l_2}(r_i-1).
\end{equation}
%
Note that $s_i$, $i=1,\ldots,l_2$, is a zero of $Q[p]$ of multiplicity $r_i-1$ by Theorem~\ref{Thm.multiple.zero.Q}.

Furthermore, since
%
\begin{equation*}
-\dfrac{H(z)}{H'(z)}=Az^2+Bz+C+\sum\limits_{k=0}^{\infty}\dfrac{c_k}{z^k},
\end{equation*}
%
it follows that $\IndI\left(-\dfrac{H}{H'}\right)=0$. Now from Theorem~\ref{Th.Cauchy.index.properties}, \eqref{Cauchy.index.on.projective.line},
and~\eqref{Theorem.real.zeroes.p.sigma.proof.0} one has
%
\begin{equation}\label{H/H'.index.1}
\IndC\left(-\dfrac{H}{H'}\right)=\IndPR\left(-\dfrac{H}{H'}\right)=\IndPR\dfrac{H'}{H}=\IndC\dfrac{H'}{H}=2m-2m_{\sigma}-\sum\limits_{i=1}^{l_2}(r_i-1).
\end{equation}
%

Note that the numbers $s_i$, $i=1,\ldots,l_2$, are not poles of the function $-\dfrac{H}{H'}$, but they are simple
zeroes of $-\dfrac{H}{H'}$.


Let now $\lambda\in\mathbb{R}$ be a pole of $-\dfrac{H}{H'}$. Clearly, $p(\lambda)\neq0$ and $p_{\sigma}(\lambda)\neq0$, and by~\eqref{H.log.derivartive.1} we have
%
\begin{equation*}%\label{Theorem.real.zeroes.p.sigma.proof.3}
F[p](\lambda)=p(\lambda)p''(\lambda)-[p'(\lambda)]^2=0.
\end{equation*}
%

\vspace{2mm}

\noindent \textsc{I.}  If $p'(\lambda)=0$, then $p''(\lambda)=0$, so $p'_{\sigma}(\lambda)=0$. At the same time, $p'''(\lambda)\neq0$, since otherwise, we would
have $p''_{\sigma}(\lambda)=0$ that contradicts~\eqref{Q1.negativity}. Thus, in this case
%
\begin{equation*}
F'[p](\lambda)=p(\lambda)p'''(\lambda)-p'(\lambda)p''(\lambda)\neq0,
\end{equation*}
%
so $\lambda$ is a simple pole of $-\dfrac{H}{H'}$ (and a simple zero of $Q[p]$), and
%
\begin{equation}\label{Theorem.real.zeroes.p.sigma.proof.4}
-\dfrac{H(z)}{H'(z)}=\dfrac{A_{\lambda}}{z-\lambda}+O(1)\qquad\text{as}\quad z\to\lambda,
\end{equation}
%
where by~\eqref{Q1.negativity} and~\eqref{H.log.derivartive.1}, one has
%
\begin{equation}\label{Theorem.real.zeroes.p.sigma.proof.5}
%\begin{array}{l}
A_{\lambda}=\lim\limits_{z\to\lambda}\dfrac{p(z)p_{\sigma}(z)(z-\lambda)}{p'(z)p_{\sigma}(z)-p(z)p'_{\sigma}(z)}
=\dfrac{p(\lambda)p_{\sigma}(\lambda)}{p''(\lambda)p_{\sigma}(\lambda)-p(\lambda)p''_{\sigma}(\lambda)}=-\dfrac{p_{\sigma}(\lambda)}{p_{\sigma}''(\lambda)}>0,
\end{equation}
%
since $p'_{\sigma}(\lambda)=0$ as we showed above. Thus, \eqref{Theorem.real.zeroes.p.sigma.proof.4}--\eqref{Theorem.real.zeroes.p.sigma.proof.5} imply
%
\begin{equation}\label{Theorem.real.zeroes.p.sigma.proof.6}
\Ind\nolimits_{\lambda}\left(-\dfrac{H}{H'}\right)=1,
\end{equation}
%
according to~\eqref{Cauchy.index.at.odd.pole}.

\vspace{2mm}

\noindent\textsc{II.} Suppose now that $p'(\lambda)\neq0$. Let us show that this is a simple pole of $-\dfrac{H}{H'}$ (a simple zero of $Q[p]$), as well.
Indeed, from~\eqref{H.log.derivartive.1} we have
%
\begin{equation*}
F[p](\lambda)=p(\lambda)p''(\lambda)-[p'(\lambda)]^2=p(\lambda)p'_{\sigma}(\lambda)-p'(\lambda)p_{\sigma}(\lambda)=0,
\end{equation*}
%
so
%
\begin{equation}\label{Theorem.real.zeroes.p.sigma.proof.7}
\dfrac{p'_{\sigma}(\lambda)}{p_{\sigma}(\lambda)}=\dfrac{p'(\lambda)}{p(\lambda)}.
\end{equation}
%
At the same time, by~\eqref{Q1.negativity} and \eqref{Theorem.real.zeroes.p.sigma.proof.7}
%
\begin{equation}\label{Theorem.real.zeroes.p.sigma.proof.8}
\begin{array}{c}
\dfrac{F'[p](\lambda)}{p(\lambda)p_{\sigma}(\lambda)}=\dfrac{p(\lambda)p''_{\sigma}(\lambda)-p''(\lambda)p_{\sigma}(\lambda)}{p(\lambda)p_{\sigma}(\lambda)}=
\dfrac{p''_{\sigma}(\lambda)}{p_{\sigma}(\lambda)}-\dfrac{p''(\lambda)}{p(\lambda)}<
\left(\dfrac{p'_{\sigma}(\lambda)}{p_{\sigma}(\lambda)}\right)^2-\dfrac{p''(\lambda)}{p(\lambda)}=\\
\\
=\left(\dfrac{p'(\lambda)}{p(\lambda)}\right)^2-\dfrac{p''(\lambda)}{p(\lambda)}=\dfrac{F[p](\lambda)}{p^2(\lambda)}=0.
\end{array}
\end{equation}
%
Thus, $\lambda$ is a simple pole of $-\dfrac{H}{H'}$, and from~\eqref{Theorem.real.zeroes.p.sigma.proof.8} we have
%
\begin{equation*}
-\dfrac{H(z)}{H'(z)}=\dfrac{B_{\lambda}}{z-\lambda}+O(1)\qquad\text{as}\quad z\to\lambda,
\end{equation*}
%
with
%
\begin{equation*}
B_{\lambda}=\lim\limits_{z\to\lambda}\dfrac{p(z)p_{\sigma}(z)(z-\lambda)}{-F[p](z)}=-\dfrac{p(\lambda)p_{\sigma}(\lambda)}{F'[p](\lambda)}>0,
\end{equation*}
%
so~\eqref{Theorem.real.zeroes.p.sigma.proof.6} holds.

Thus, we obtained that all the real poles of $-\dfrac{H}{H'}$ are simple, and the Cauchy index of $-\dfrac{H}{H'}$ at every
real pole equals $1$. From~\eqref{H/H'.index.1} it follows now that the function $-\dfrac{H}{H'}$ has exactly
%
\begin{equation}\label{Theorem.real.zeroes.p.sigma.proof.9}
2m-2m_{\sigma}-\sum\limits_{i=1}^{l_2}(r_i-1)
\end{equation}
%
real poles, counting multiplicities. All these poles are real simple zeroes of the function~$Q[p]$,
according to~\eqref{H.derivartive.1}--\eqref{H.log.derivartive.1}. Additionally, the function $Q[p]$
has real zeroes at the points $s_i$, $i=1,\ldots,l_2$, and the number $s_i$ is a zero of $Q[p]$ of
multiplicity $r_i-1$. In particular, it is a multiple zero of $Q[p]$ if $r_i\geqslant3$. As we mentioned
above, at the points $s_i$, $i=1,\ldots,l_2$, the function $Q[p]$ has exactly
%
\begin{equation*}
\sum\limits_{i=1}^{l_2}(r_i-1)
\end{equation*}
%
real zeros, counting multiplicities, which together with~\eqref{Theorem.real.zeroes.p.sigma.proof.9}
gives~\eqref{Number.real.zeroes.Q.ext}.

\vspace{5mm}


Let now $\sigma=0$. Then the formula~\eqref{Number.real.zeroes.Q.ext} can be proved in a similar way.
The only difference is that for $\sigma=0$, $p_0=p'+0\cdot p=p'$, and $\deg p_0=n-1$. In this case,
the index of the logarithmic derivative of~$H$ on the real line is
%
\begin{equation*}
\IndC\left(\dfrac{H'}{H}\right)=2m-2m_{\sigma}-1-\sum\limits_{i=1}^{l_2}(r_i-1),
\end{equation*}
%
see~\eqref{Theorem.real.zeroes.p.sigma.proof.2.1}, and
%
\begin{equation*}
-\dfrac{H(z)}{H'(z)}=z+c_0+\sum\limits_{k=0}^{\infty}\dfrac{c_k}{z^k},
\end{equation*}
%
so it follows that $\IndI\left(-\dfrac{H}{H'}\right)=-1$, and from Theorem~\ref{Th.Cauchy.index.properties}, \eqref{Cauchy.index.on.projective.line},
and~\eqref{Theorem.real.zeroes.p.sigma.proof.0} we have
%
\begin{equation*}%\label{H/H'.index.2}
\begin{array}{l}
\IndC\left(-\dfrac{H}{H'}\right)-1=\IndC\left(-\dfrac{H}{H'}\right)+\IndI\left(-\dfrac{H}{H'}\right)=\IndPR\left(-\dfrac{H}{H'}\right)=\\
\\
=\IndPR\left(\dfrac{H'}{H}\right)=\IndC\left(\dfrac{H'}{H}\right)=2m-2m_{\sigma}-1-\sum\limits_{i=1}^{l_2}(r_i-1).
\end{array}
\end{equation*}
%
Therefore,
%
\begin{equation*}
\IndC\left(-\dfrac{H}{H'}\right)=2m-2m_{\sigma}-\sum\limits_{i=1}^{l_2}(r_i-1),
\end{equation*}
%
where $r_i$ and $l_2$ are defined in~\eqref{Theorem.real.zeroes.p.sigma.proof.0.1} and~\eqref{Theorem.real.zeroes.p.sigma.proof.2} with $p_0=p'$.
Consequently, the numbers $s_i$ are zeroes of~$p'$, so if $\lambda\in\mathbb{R}$ is a pole of $-\dfrac{H}{H'}$, then~$p'(\lambda)\neq0$.
In a similar way as above, one can show that every real pole of $-\dfrac{H}{H'}$ is simple, and the index of $-\dfrac{H}{H'}$
at each real pole is $1$. Thus, formula~\eqref{Number.real.zeroes.Q.ext} can be proved in the same way as for the case $\sigma\neq0$.
\end{proof}
\smallskip

As a by-product, from the proof of Theorem~\ref{Theorem.real.zeroes.p.sigma} we easily obtain the following fact.
%
\begin{theorem}\label{Theorem.real.zeroes.Q.lower.bound}
Let $p$ be a real polynomial with $Z_{\mathbb{C}}(p)=2m$, and let
%
\begin{equation*}
2m_{\sigma^{*}}=\min\limits_{\sigma\in\mathbb{R}}\left(Z_{\mathbb{C}}(p_\sigma)\right),
\end{equation*}
%
where the polynomial $p_{\sigma}$ is defined in~\eqref{p.sigma}. Then
%
\begin{equation}\label{Lower.bound.number.real.zeroes.Q}
Z_{\mathbb{R}}\left(Q[p]\right)\geqslant2m-2m_{\sigma^{*}}.
\end{equation}
\end{theorem}
%
\begin{proof}
Indeed, from the proof of Theorem~\ref{Theorem.real.zeroes.p.sigma} it follows that for
arbitrary $\sigma\in\mathbb{R}$
%
\begin{equation}\label{Theorem.real.zeroes.Q.lowert.bound.proof.1}
\IndC\left(-\dfrac{H}{H'}\right)=2m-2m_{\sigma}-\sum\limits_{i=1}^{l_2}(r_i-1),
\end{equation}
%
where $r_i$ are multiplicities of multiple zeroes $s_i$ of $p_{\sigma}$ which are not
zeroes of $p$. The poles of $-\dfrac{H}{H'}$ are zeroes of $Q[p]$. Moreover, according to
Definition~\ref{Def.Cauchy.index.at.pole}, the zeroes of $Q[p]$ of even multiplicity do
not contribute to the index~\eqref{Theorem.real.zeroes.Q.lowert.bound.proof.1}. Thus,
the index~\eqref{Theorem.real.zeroes.Q.lowert.bound.proof.1} is equal to the sum of
\textit{distinct} zeroes of $Q[p]$ of odd multiplicities with indices
of various signs (if any) at them. Consequently, we have
%
\begin{equation}\label{Theorem.real.zeroes.Q.lowert.bound.proof.2}
Z_{\mathbb{R}}\left(Q[p]\right)\geqslant2m-Z_{\mathbb{C}}(p_\sigma)-\sum\limits_{i=1}^{l_2}(r_i-1).
\end{equation}
%
Now recall that each zero $s_i$ of $p_{\sigma}$ of multiplicity $r_i$ is a zero of $Q[p]$
of multiplicity $r_i-1$, $i=1,\ldots,l_2$. Therefore, additionally to the zeroes guaranteed
by the index~\eqref{Theorem.real.zeroes.Q.lowert.bound.proof.1}, the function $Q[p]$ has
exactly
%
\begin{equation*}
\sum\limits_{i=1}^{l_2}(r_i-1)
\end{equation*}
%
zeroes, counting multiplicities, at the points $s_i$, $i=1,\ldots,l_2$. Now
from~\eqref{Theorem.real.zeroes.Q.lowert.bound.proof.2} it follows that
%
\begin{equation*}\label{Theorem.real.zeroes.Q.lowert.bound.proof.3}
Z_{\mathbb{R}}\left(Q[p]\right)\geqslant2m-Z_{\mathbb{C}}(p_\sigma)
\end{equation*}
%
for any $\sigma\in\mathbb{R}$. Since $2m-Z_{\mathbb{C}}(p_\sigma)\leqslant2m-2m_{\sigma^{*}}$, the lower bound~\eqref{Lower.bound.number.real.zeroes.Q} is true.
\end{proof}

It is interesting to find out if it is possible to establish Theorem~\ref{Theorem.Hawaii.base.ineq} using the Cauchy indices. However, we believe that a stronger fact is true.
%
\begin{conjecture}
Let $p$ be a real polynomial with $Z_{\mathbb{C}}(p)=2m>0$. Then there exists $\sigma\in\mathbb{R}$ such that
%
\begin{equation*}\label{Number.real.zeroes.Q.eq.Q1}
Z_{\mathbb{R}}\left(Q[p]\right)=2m-2m_{\sigma}+Z_{\mathbb{R}}\left(Q[p_{\sigma}]\right),
\end{equation*}
%
where $2m_{\sigma}=Z_{\mathbb{C}}\left(p_{\sigma}\right)\leqslant2m$, and the polynomial $p_{\sigma}$ is defined in~\eqref{p.sigma}. Moreover, if there exists $x,\sigma\in\mathbb{R}$ with
$Q[p_{\sigma}](x)>0$, then $\sigma$ can be chosen such that $2m_{\sigma}<2m$.

%Moreover, the real zeroes of $Q[p]$ different from zeroes of $p_{\sigma}$ and $Q[p_{\sigma}]$ of multiplicity greater than $2$ (if any) are simple.
\end{conjecture}

%However, we are not sure that in this conjecture $\sigma$ can always be chosen such that $2m_{\sigma}=\min\limits_{\sigma\in\mathbb{R}}\left(Z_{\mathbb{C}}(p_\sigma)\right)$.
%Seems to be not.


