\newcommand{\neutralmodule}[2]{%
  \begin{scope}[shift={(0,#1)}]
    \def\spacing{2} % More space between strands.
    \foreach \lab [count=\i] in {#2} {
      \draw[very thick,postaction=decorate,
             decoration={markings, mark=at position 0.5 with {\arrow{stealth}}}]
            (\i*\spacing,0) -- (\i*\spacing,1);
      \node[anchor=east] at (\i*\spacing - 0.1,.5) {\lab};
    }
  \end{scope}%
}

\newcommand{\capmodule}[3][0.2]{%
  \begin{scope}[shift={(0,#2)}]
    \def\spacing{2} % spacing matching that used in the braid module
    \def\tagheight{#1} % length of the tag
    \foreach \j in {1,...,#3} {%
      % For the j-th cup, the left endpoint is at x = (2j-1)*spacing,
      % and the right endpoint at x = (2j)*spacing.
      \pgfmathsetmacro{\xleft}{(2*\j - 1)*\spacing}
      \pgfmathsetmacro{\xright}{(2*\j)*\spacing}
      % Draw the semicircular cup.
      % This arc starts at (\xleft,0) and, with a radius of spacing/2, ends at (\xright,0)
      \draw[very thick] (\xleft,0) arc (180:0:{\spacing/2});
      % The midpoint of the semicircle is exactly at ( (\xleft+\xright)/2, spacing/2 ).
      \pgfmathsetmacro{\xmid}{(\xleft+\xright)/2}
      \draw[very thick] (\xmid, {\spacing/2}) -- ++(0,\tagheight);
    }%
  \end{scope}%
}

% Cup module: similar to the cup module but the arc is drawn below.
% #1 = tag height (optional, set to 0.2), #2 = y-offset, #3 = number n (i.e. n caps = 2n endpoints)
\newcommand{\cupmodule}[3][0.2]{%
  \begin{scope}[shift={(0,#2)}]
    \def\spacing{2} % must match the spacing in the braid module
    \def\tagheight{#1} % length of the tag
    \foreach \j in {1,...,#3} {%
      \pgfmathsetmacro{\xleft}{(2*\j - 1)*\spacing}
      \pgfmathsetmacro{\xright}{(2*\j)*\spacing}
      % Draw the semicircular cap (arc drawn downward).
      \draw[very thick] (\xleft,0) arc (180:360:{\spacing/2});
      % The midpoint of the arc is at (\xmid, -spacing/2).
      \pgfmathsetmacro{\xmid}{(\xleft+\xright)/2}
      \draw[very thick] (\xmid, -{\spacing/2}) -- ++(0,-\tagheight);
    }%
  \end{scope}%
}

% \Erung: draws a horizontal thin rung (with arrow in the middle)
% from the (i+1)-th to the i-th strand.
% #1: top height (rung is drawn at #1 - 0.2)
% #2: index i (rung spans from the i-th to the (i+1)-th strand)
\newcommand{\Erung}[2]{%
    \def\spacing{2} % must match the spacing in the braid module
  \pgfmathsetmacro{\rungy}{(#1 + .9)}%
  \pgfmathsetmacro{\leftx}{(#2)*\spacing}%
  \pgfmathsetmacro{\rightx}{((#2)+1)*\spacing}%
  \draw[thin,postaction={decorate},
    decoration={markings, mark=at position 0.5 with {\arrow{stealth}}}]
    (\rightx,\rungy) -- (\leftx,\rungy);
}

%-------------------------------------------------
