% from the i-th to the (i+1)-th strand.
% #1: top height (rung is drawn at #1 - 0.2)
% #2: index i
\newcommand{\Frung}[2]{%
    \def\spacing{2} % must match the spacing in the braid module 
  \pgfmathsetmacro{\rungy}{(#1 + .9)}%
  \pgfmathsetmacro{\leftx}{(#2)*\spacing}%
  \pgfmathsetmacro{\rightx}{((#2)+1)*\spacing}%
  \draw[thin,postaction={decorate},
    decoration={markings, mark=at position 0.5 with {\arrow{stealth}}}]
    (\leftx,\rungy) -- (\rightx,\rungy);
}

\newcommand{\braidmodule}[2]{%
  \begin{scope}[shift={(0,#1)}]
    \def\spacing{2} % spacing matching that used in the neutral module
    \def\totalstrands{4} % fixed total number of strands; adjust as needed
    \def\braidindex{#2} % the horizontal index of the braided pair
    % Draw vertical strands for all indices except the braided pair.
    \foreach \j in {1,...,\totalstrands} {%
      \ifnum\j=\braidindex
        % skip braided strand
      \else
        \ifnum\j=\numexpr\braidindex+1\relax
          % skip braided strand
        \else
          \draw[very thick] (\j*\spacing,0) -- (\j*\spacing,2);
        \fi
      \fi
    }%
    % Draw the braided pair:
    % Under strand: from the top of the (i+1)-th strand to the bottom of the i-th.
    \draw[very thick] ({\braidindex*\spacing},2) ..
      controls ({\braidindex*\spacing},1.5) and ({(\braidindex+1)*\spacing},0.5) ..
      ({(\braidindex+1)*\spacing},0); 
      % Draw a white disk at the approximate crossing.
    \pgfmathsetmacro{\xcross}{(\braidindex+0.5)*\spacing}
    \pgfmathsetmacro{\ycross}{1}
    \fill[white] (\xcross,\ycross) circle (0.1);
    % Over strand: from the top of the i-th strand to the bottom of the (i+1)-th.

      \draw[very thick] ({(\braidindex+1)*\spacing},2) ..
      controls ({(\braidindex+1)*\spacing},1.5) and ({\braidindex*\spacing},0.5) ..
      ({\braidindex*\spacing},0);
  \end{scope}%
}

