% Extended Erung: draws a horizontal thin rung (without a full-line arrow)
% that spans from the i-th to the j-th strand, with an arrow placed
% in the first interval (between the i-th and (i+1)-th strands).
% #1: top height (rung drawn at #1 - 0.2)
% #2: starting index (i)
% #3: ending index (j)
\newcommand{\Emrung}[3]{%
  \begin{scope}
    \def\spacing{2} % must match the spacing in your neutral module
    % Compute the vertical position: a bit below the top.
    \pgfmathsetmacro{\rungy}{(#1 - 0.2)}%
    % Compute x-coordinates for the start and end strands.
    \pgfmathsetmacro{\startx}{(#2)*\spacing}%
    \pgfmathsetmacro{\endx}{(#3)*\spacing}%
    % Compute the fraction along the line to place the arrow:
    % This puts the arrow in the first interval between strands.
    \pgfmathsetmacro{\arrowpos}{1/(2*(#3 - #2))}%
    % Draw the horizontal rung with an arrow decoration at the computed fraction.
    \draw[thin,postaction={decorate},
      decoration={markings, mark=at position \arrowpos with {\arrow{stealth}}}]
      (\endx,\rungy) -- (\startx,\rungy);
    % Draw white disks at the intermediate strands (if any) so the rung appears behind them.
    \foreach \k in {\numexpr#2+1\relax,...,\numexpr#3-1\relax} {%
      \draw[fill=white,draw=white] (\k*\spacing,\rungy) circle (0.1);
    }%
  \end{scope}%
}

% Extended Frung: same idea but the horizontal line is drawn from the i-th to the j-th strand
% with an arrow placed in the first interval (pointing right).
\newcommand{\Fmrung}[3]{%
  \begin{scope}
    \def\spacing{2} % must match the spacing in your neutral module
    \pgfmathsetmacro{\rungy}{(#1 - 0.2)}%
    \pgfmathsetmacro{\startx}{(#2)*\spacing}%
    \pgfmathsetmacro{\endx}{(#3)*\spacing}%
    \pgfmathsetmacro{\arrowpos}{1/(2*(#3 - #2))}%
    \draw[thin,postaction={decorate},
      decoration={markings, mark=at position \arrowpos with {\arrow{stealth}}}]
      (\startx,\rungy) -- (\endx,\rungy);
    \foreach \k in {\numexpr#2+1\relax,...,\numexpr#3-1\relax} {%
      \draw[fill=white,draw=white] (\k*\spacing,\rungy) circle (0.1);
    }%
  \end{scope}%
}

