    f_{2}^A = \omu e_{2}^A \, .
\end{equation}
We can also start with $f_{-;1,3}^U$ and pass it across $B_2^3$:
\begin{align}
    f_{-;1,3}^U \to f_{1} \to f_{+;1,3} = f_{-;1,3}-f_{1}f_{2} \to f_{1}^A - f_{+;1,3}^A e_{2}^A = f_{1}^A - f_{-;1,3}^A e_{2}^A + f_{1}^A f_{2}^A e_{2}^A\, .
