\section{Diagrammatic rules}\label{app:rules}

The diagrammatic rules for the fusing of antisymmetric powers of the fundamental representation of $SU(N)$ are extracted from \cite{Cautis_2014}. Below is a list of the rules relevant to our purposes.

\begin{gather}
  \tikz[baseline]{\draw[->] (0,0.5) node[above] {$k$} arc (45:-315:0.5cm);}
  = \qBinomial{n}{k}
  \label{eq:loop}
  \\[1em]
  \begin{tikzpicture}[baseline=20]
    \foreach \n in {0,...,3} {
      \coordinate (z\n) at (0.4*\n, 0.8*\n);
    }
    \draw[mid>] (z0) -- node[right] {$k+l$} (z1);
    \draw[mid>] (z2) -- node[right] {$k+l$} (z3);
    \draw[mid>] (z1) to[out=150,in=-190] node[left] {$k$} (z2);
    \draw[mid>] (z1) to[out=-30,in=0]   node[right] {$l$} (z2);
  \end{tikzpicture}
  = \qBinomial{k+l}{l}
  \tikz[baseline=20]{\draw[mid>] (0,0) -- node[right] {$k+l$} (1,2);}
  \qquad
  \begin{tikzpicture}[baseline=20]
    \foreach \n in {0,...,3} {
      \coordinate (z\n) at (0.4*\n, 0.8*\n);
    }
    \draw[mid>] (z0) -- node[right] {$k$} (z1);
    \draw[mid>] (z2) -- node[right] {$k$} (z3);
    \draw[mid<] (z1) to[out=150,in=-190] node[left] {$l$} (z2);
    \draw[mid>] (z1) to[out=-30,in=0]   node[right] {$k+l$} (z2);
  \end{tikzpicture}
  = \qBinomial{n-k}{l}
  \tikz[baseline=20]{\draw[mid>] (0,0) -- node[right] {$k$} (1,2);}
  \label{eq:bigon2}
  \displaybreak[1]
  \\[1em]
  \begin{tikzpicture}[baseline]
    \foreach \x/\y in {0/0,1/0,2/0,0/1,1/1,0/2} {
      \coordinate (z\x\y) at (\x+\y/2,\y/1.5);
    }
    \coordinate (z03) at (1,2);
    \draw[mid>] (z00) node[below] {$k$}      -- (z01);
    \draw[mid>] (z01)              -- node[left]  {$k+l$} (z02);
    \draw[mid>] (z10) node[below] {$l$}      -- (z01);
    \draw[mid>] (z20) node[below] {$m$}      -- (z02);
    \draw[mid>] (z02) -- node[left] {$k+l+m$} (z03);
  \end{tikzpicture}
  =
  \begin{tikzpicture}[baseline]
    \foreach \x/\y in {0/0,1/0,2/0,0/1,1/1,0/2} {
      \coordinate (z\x\y) at (\x+\y/2,\y/1.5);
    }
    \coordinate (z03) at (1,2);
    \draw[mid>] (z00) node[below] {$k$} -- (z02);
    \draw[mid>] (z10) node[below] {$l$} -- (z11);
    \draw[mid>] (z20) node[below] {$m$} -- (z11);
    \draw[mid>] (z11)              -- node[right] {$l+m$} (z02);
    \draw[mid>] (z02) -- node[left] {$k+l+m$} (z03);
  \end{tikzpicture}
  \label{eq:IH}
  \displaybreak[1]
  \\
  \label{eq:id1b}
  \tikz[baseline=40]{
    \laddercoordinates{1}{2}
    \ladderEn{0}{0}{$k-s$}{$l+s$}{$s$}
    \ladderEn{0}{1}{$k-s-r$}{$l+s+r$}{$r$}
    \node[left]  at (l00) {$k$};
    \node[right] at (l10) {$l$};
  }
  =
  \qBinomial{r+s}{r}
  \tikz[baseline=20]{
    \laddercoordinates{1}{1}
    \ladderEn{0}{0}{$k-s-r$}{$l+s+r$}{$r+s$}
    \node[left]  at (l00) {$k$};
    \node[right] at (l10) {$l$};
  }
  \displaybreak[1]
  \\
  \label{eq:commutation}
  \begin{tikzpicture}[baseline=40]
    \laddercoordinates{1}{2}
    \node[left]  at (l00) {$k$};
    \node[right] at (l10) {$l$};
    \ladderEn{0}{0}{$k{-}s$}{$l{+}s$}{$s$}
    \ladderFn{0}{1}{$k{-}s{+}r$}{$l{+}s{-}r$}{$r$}
  \end{tikzpicture}
  = \sum_t \qBinomial{k-l+r-s}{t}
  \begin{tikzpicture}[baseline=40]
    \laddercoordinates{1}{2}
    \node[left]  at (l00) {$k$};
    \node[right] at (l10) {$l$};
    \ladderFn{0}{0}{$k{+}r{-}t$}{$l{-}r{+}t$}{$r{-}t$}
    \ladderEn{0}{1}{$k{-}s{+}r$}{$l{+}s{-}r$}{$s{-}t$}
  \end{tikzpicture}
  \displaybreak[1]
  \\
  \begin{tikzpicture}[baseline=10]
    \node (C) at (-1,2) {$l$};
    \node (D) at (1,-1) {$l$};
    \node (A) at (1,2)  {$k$};
    \node (B) at (-1,-1){$k$};
    \node (i) at (intersection of A--B and D--C) {};
    \draw[mid>] (B) -- (A);
    \draw[mid>] (D) -- (i);
    \draw[mid>] (i) -- (C);
  \end{tikzpicture}
  = (-1)^{k+kl} q^{k-\frac{kl}{n}} \sum_{\substack{a,b\geq 0 \\ b-a = k-l}} (-q)^{-b}
  \begin{tikzpicture}[baseline=40]
    \laddercoordinates{1}{2}
    \node[left]  at (l00) {$k$};
    \node[right] at (l10) {$l$};
    \ladderEn{0}{0}{$k{-}b$}{$l{+}b$}{$b$}
    \ladderFn{0}{1}{$l$}{$k$}{$a$}
  \end{tikzpicture}
  \label{eq:braid}
\end{gather}


In particular, (\ref{eq:commutation}) has an important special case: if $k-s+r=l$ and thus $l+s-r=k$, as on the right-hand side of (\ref{eq:braid}), the sum on the right-hand side has a single term $t=0$. In particular, in (\ref{eq:braid}) we can permute the horizontal rungs. 

