\coordinate (i) at (0,-0.2) {};
\draw[mid>] (A) -- (i);
\draw[mid>,very thick] (D) -- (E);
\draw[mid>,very thick] (E) -- (C);
\end{tikzpicture}\quad=&\quad \omu\begin{tikzpicture}[baseline=-3]
\node (C) at (0,1) {};
\node (E) at (0,0) [circle,fill,inner sep=2pt] {};
\node (D) at (0,-1) {};
