In the $g\to 1$ limit, the tree-level augmentation variety of the torus knot $T(2,2l+1)$ is
\begin{equation} \label{eq:torus_tree}
    (\olambda^2-1)(1+\omu)^l(\omu-\olambda^{2(2l+1)})=0\, .
\end{equation}

\paragraph{Torus link $T(2,2l)$.} This link has a Schubert presentation in terms of 4 strands and the insertion of the braiding $B_2^{2l}$. In this case, the braiding does not keep $e_2$ and $f_2$ invariant, but denoting $e_2=e_2^{(0)}$ and $f_2=f_2^{(0)}$, it still leads to nice relations
\begin{align}
    f_2^{(2i)}&=\left(\frac{g}{\olambda_1\olambda_2}\right)^{2i}f_2 \cr
    e_2^{(2i)}&=\left(\frac{g}{\olambda_1\olambda_2}\right)^{-2i}e_2\, .
\end{align}
We can get relations between vevs in a similar way as for $T(2,2l+1)$. Keeping track of the new factors in various places, we obtain
\begin{align}
    \omu_1 {g^2 f_2\choose g^2-\olambda_1^2} &= M_1\cdots M_l\; {gf_2 \left(\frac{g}{\olambda_1\olambda_2}\right)^{2l} \choose -g \left(\olambda_1^2-1\right)}\cr
    \omu_2{g^2 f_2\choose g^2-\olambda_2^2} &= M_1\cdots M_l\; {gf_2 \left(\frac{g}{\olambda_1\olambda_2}\right)^{2l} \choose -g \left(\olambda_2^2-1\right)}\, ,
\end{align}
where the matrix $M_i$ is
\begin{equation}
    M_i = \left(\begin{array}{cc}
 1 & -f_2\left(\frac{g}{\olambda_1\olambda_2}\right)^{2i}  \\
 -e_2\left(\frac{g}{\olambda_1\olambda_2}\right)^{1-2i} & 1+\frac{g}{\olambda_1\olambda_2}e_2f_2 \\
\end{array}\right)\, .
\end{equation}

There is always a disconnected saddle in which the vev of $e_2f_2$ is zero, and this part of the variety takes the same form as for two unknots. The interesting saddles are in the connected part of the augmentation variety. 

For the Hopf link $T(2,2)$
\begin{equation}
    \omu_1=\frac{g}{\olambda_2^2}\qquad \qquad \omu_2=\frac{g}{\olambda_1^2}\, ,
\end{equation}
For $T(2,4)$
\begin{align}
    -g^4-g \olambda _2^2(\olambda_1^2-\olambda_2^2) \omu_1 +\olambda_1^2 \olambda_2^6 \omu_1^2&=0 \cr
    -g^4+g \olambda _1^2(\olambda_1^2-\olambda_2^2) \omu_2 +\olambda_1^6 \olambda_2^2 \omu_2^2&=0\, .
\end{align}
In the $g\to 1$ limit, the disconnected part of the tree-level augmentation variety of $T(2,4)$ reduces to two solutions for $(\omu_1,\omu_2)$:
\begin{equation}
    \omu_1 =\frac{1}{\olambda_2^4} \qquad \qquad \omu_2=\frac{1}{\olambda_1^4}\, ,
\end{equation}
and
\begin{equation}
    \omu_1 = \omu_2=-\frac{1}{\olambda_1^2\olambda_2^2}\, .
\end{equation}

