\subsection{Additional considerations}

\paragraph{Mirrors.}
For every chiral knot, one can associate a mirror knot, which is obtained by replacing all its braid group elements by their inverses. For example, the mirror of the Stevedore knot is given by \( B_2^{-2} B_3^{3} B_{2}^{-2} \). See Figure \ref{fig:61b}. One can easily compute the augmentation of a mirror knot by performing the following transformation
\begin{align}
    \mathcal{A}_{\text{mirror}} (\omu, \olambda, g) &= \mathcal{A} \left( \frac{1}{\omu}, \frac{\olambda}{g}, \frac{1}{g} \right)\, ,
\end{align}
which is consistent with the fact that the mirror of the mirror is the original knot.

\paragraph{Symmetric vs antisymmetric powers.} 
The augmentation polynomial of symmetric powers of the fundamental representation can be obtained from the one of antisymmetric powers by replacing $N$ with $-N$, i.e. $\fq\to -\fq$, and vice versa. This means
\begin{align}
    \mathcal{A}_{S^{\bullet} \mathbb{C}^N} (\omu, \olambda, g) &= \mathcal{A}_{\Lambda^{\bullet} \mathbb{C}^N} \left( \omu, \frac{1}{\olambda}, \frac{1}{g} \right)\, .
\end{align}

\paragraph{Symmetry.}
The augmentation variety has a ${k}\to{N-k}$ symmetry
\begin{align}
    \mathcal{A}(\omu, \olambda, g) &= \mathcal{A}\left(\dfrac{1}{\omu}, \dfrac{g}{\olambda}, g\right)\, .
\end{align}

\paragraph{Framing.} All our calculations are done in vertical framing. To change to canonical framing, we have to add the twisting factor to $\omu$ 
\begin{align}
    \mathcal{A}_{\text{canonical}} (\omu, \olambda, g) &= \mathcal{A} \left( \omu \left(\frac{g}{\olambda^2} \right)^x, \olambda, g \right) \, 
\end{align}
where $x$ is the self-linking number of the given presentation of the knot in vertical framing, which can be computed by counting crossings with signs given by Figure \ref{fig:cross}.

