\section{Preliminaries} 
\label{sec:Preliminaries}
\textbf{Notation}. Vectors are denoted by boldface lowercase letters, e.g., $\mathbf{a}$. Matrices are denoted by boldface uppercase letters, e.g., $\mathbf{A}$. Polynomials are denoted by lowercase letters, for example, $a$. We denote the inner product between two vectors by $\left <\mathbf{a}, \mathbf{b} \right >$. For a finite field $\mathbb{F}$, a group $\mathbb{G}$, a  given vector $\mathbf{a} \in \mathbb{F}^n$, and a vector $\mathbf{g} \in \mathbb{G}^n$ of generators, $\mathbf{g}^\mathbf{a} = \prod_{i=1}^n g_i^{a_i}$. For two vectors $\mathbf{a}, \mathbf{b} \in \mathbb{F}^n$, the element-wise product is represented by $\mathbf{a} \circ \mathbf{b}$ which is equal to $\left (a_1 b_1, \dots, a_n b_n \right )$. For $a, b\in \mathbb{R}$, $\left [a,b \right ]$ denotes the set of all numbers $x \in \mathbb{R}$, where  $a \leq x \leq b$. For integers $1 \leq u \leq v \leq n$, and a vector  $\mathbf{a} = (a_1, \dots, a_n)$, then $\mathbf{a}[u-1, v]$ denotes the sub-vector $(a_{u}, \dots ,a_{v})$ of the vector $\mathbf{a}$. Similarly, $a[:u]:= (a_1, \dots,a_u)$, and $\mathbf{a}[u:]:=(a_{u+1}, \dots ,a_n)$.


\begin{defn} 
For any prime number \( p > 2 \), the \textbf{symmetric finite field}, denoted \( \mathbb{F}_p \) (or simply \( \mathbb{F} \)), can be represented by the symmetric complete residue system 
$\left\{ -\frac{p-1}{2}, \ldots, \frac{p-1}{2} \right\}$,
which serves as an alternative to the standard system \( \{0, 1, \ldots, p-1\} \). Field operations such as addition and multiplication are performed modulo \( p \), with the results mapped back into this symmetric representative set.
\end{defn}

% If $v = \log n$, we can interpret a vector $\mathbf{e} = \left [e_1, \dots, e_n \right ]$ as a function $e \left (x_1, \dots, x_v \right )$ mapping $\left \{0,1 \right \}^{v} \rightarrow \mathbb{F}$ via $e \left (b_1, \dots, b_v \right ) = e_i$ for $b_1, \dots, b_v \in \left \{0,1 \right \}$. By the definition below, we can transform this function with the $v$-dimensional Boolean hypercube domain to another function with extended domain $\mathbb{F}^v$.

\begin{defn}
\label{MLEdef}
Let \( e: \{0,1\}^v \rightarrow \mathbb{F} \) be a function defined over the Boolean hypercube for some integer \( v \). The \textbf{multilinear extension} (MLE) of \( e \), denoted \( \tilde{e}: \mathbb{F}^v \rightarrow \mathbb{F} \), is a multivariate polynomial satisfying the following properties:
\begin{itemize}
    \item For all \( b_1, \dots, b_v \in \{0,1\} \), we have \( \tilde{e}(b_1, \dots, b_v) = e(b_1, \dots, b_v) \).
    \item The polynomial \( \tilde{e}(x_1, \dots, x_v) \) is \emph{multilinear}, i.e., it is linear in each input variable individually.
\end{itemize}
\end{defn}


It has been shown that $\tilde{e}$ can be uniquely written as~\cite{thaler2022proofs}: 
\begin{equation} 
\label{equation_MLE} 
\tilde{e} \left (x_1, \dots, x_v \right ) := \sum_{\mathbf{y} \in \left \{0,1 \right \}^v} e(\mathbf{y}) . \prod_{i=1}^{v} \left (x_i y_i + \left (1 - x_i \right ) \left (1 - y_i \right ) \right ),
\end{equation} 
for any $\left(x_1, \dots, x_v \right )\in \mathbb{F}^v$.

\begin{lem}
\label{Schwartz} 
\textbf{(Schwartz–Zippel Lemma~\cite{schwartz1980fast, zippel1979probabilistic})}  
Let \( f, g: \mathbb{F}^v \rightarrow \mathbb{F} \) be distinct multilinear polynomials. If \( \mathbf{r} \) is sampled uniformly at random from \( \mathbb{F}^v \), then the probability that \( f(\mathbf{r}) = g(\mathbf{r}) \) is at most \( \frac{v}{|\mathbb{F}|} \); that is,
\[
\Pr[f(\mathbf{r}) = g(\mathbf{r})] \leq \frac{v}{|\mathbb{F}|}.
\]
\end{lem}

