\begin{minipage}{\textwidth} 
\begin{algorithm}[H] 
\caption{Verification of Inner-product}\label{Innerproduct} 
\begin{algorithmic}[1] 
\Require{The algorithm inputs are: $\mathbf{g}, \mathbf{h} \in \mathbb{G}^n$, $u, P \in \mathbb{G}$, $c \in \mathbb{F}$, $\mathbf{a}, \mathbf{b} \in \mathbb{F}^n$.} 
\Require{Verifier has $\mathbf{g}, \mathbf{h} \in \mathbb{G}^n$, $u, P \in \mathbb{G}$, $c \in \mathbb{F}$.}
\Require{Prover has $\mathbf{g}, \mathbf{h} \in \mathbb{G}^n$, $u, P \in \mathbb{G}$, $c \in \mathbb{F}$, $\mathbf{a}, \mathbf{b} \in \mathbb{F}^n$}. 

\Ensure{Verifier accepts $P = \mathbf{g}^\mathbf{a}\mathbf{h}^\mathbf{b}$ and $c = \left <\mathbf{a}, \mathbf{b} \right >$.} 

\State Verifier sends a random number $x \in \mathbb{F}$ to Prover. 
\State Both Prover and Verifier compute $u_{\text{new}} = u^x$ and $P_{\text{new}} = P u_{\text{new}}^{c} \in \mathbb{G}$. \Comment{$u$ is a generator of the group $\mathbb{G}$.} 
\State Run the function INNERPRODUCT on the input $\left (\mathbf{g}, \mathbf{h}, u_{\text{new}}, P_{\text{new}}, \mathbf{a}, \mathbf{b} \right )$. 

\Function{INNERPRODUCT}{$\mathbf{g}, \mathbf{h}, u, P, \mathbf{a}, \mathbf{b}$} \Comment{Verifier accepts $P = \mathbf{g}^\mathbf{a}\mathbf{h}^\mathbf{b} u^{\left <\mathbf{a}, \mathbf{b} \right >}$.}
\If{$n = 1$} 
\State Prover sends $a , b \in \mathbb{F}$ to Verifier.  
\State Verifier checks whether $P = g^a h^b u^{ab}$. If the equation is true, Verifier accepts; otherwise Verifier rejects.
\Else
\State Prover computes $n' = \frac{n}{2}$, 
$c_L = \left <\mathbf{a}_{\left [:n' \right ]}, \mathbf{b}_{\left [n': \right ]} \right > \in \mathbb{F}$, 
$c_R = \left <\mathbf{a}_{\left [n': \right ]}, \mathbf{b}_{\left [:n' \right ]} \right > \in \mathbb{F}$, 
$L = \mathbf{g}_{\left [n': \right ]}^{\mathbf{a}_{\left [:n' \right ]}} \mathbf{h}_{\left [:n' \right ]}^{\mathbf{b}_{\left [n': \right ]}}u^{c_L} \in \mathbb{G}$, 
$R = \mathbf{g}_{\left [:n' \right ]}^{\mathbf{a}_{\left [n': \right ]}} \mathbf{h}_{\left [n': \right ]}^{\mathbf{b}_{\left [:n' \right ]}} u^{c_R} \in \mathbb{G}$.
\State Prover sends $L, R \in \mathbb{G}$ to Verifier. 
\State Verifier sends a random number $x \in \mathbb{F}$ to Prover. 
\State Both Prover and Verifier compute $\mathbf{g}' = \mathbf{g}_{[:n']}^{x^{-1}} \circ \mathbf{g}_{[n':]}^{x} \in \mathbb{G}^{n'}$, $\mathbf{h}' = \mathbf{h}_{[:n']}^{x} \circ \mathbf{h}_{[n':]}^{x^{-1}} \in \mathbb{G}^{n'}$, $P' = L^{x^2}PR^{x^{-2}} \in \mathbb{G}$. 
\State Prover computes $\mathbf{a'} = x \mathbf{a}_{[:n']} + x^{-1} \mathbf{a}_{[n':]} \in \mathbb{F}^{n'}$ and $\mathbf{b'} = x^{-1} \mathbf{b}_{[:n']} + x \mathbf{b}_{[n':]} \in \mathbb{F}^{n'}$.
\State Recursively run the function INNERPRODUCT on the input $\left (\mathbf{g}', \mathbf{h}', u, P', \mathbf{a}', \mathbf{b}' \right )$. 
\EndIf
\EndFunction
\end{algorithmic}
\end{algorithm}
\end{minipage}
\end{figure*}


\begin{algorithm}
\caption{Polynomial commitment scheme}\label{Polycommit}
\begin{algorithmic}[1]
\Require The algorithm inputs are: $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{2^v}$, $u, P_1 \in \mathbb{G}$, the $v$-variate multilinear polynomial $q: \mathbb{F}_p^v \rightarrow \mathbb{F}_p$, $\mathbf{z} \in \mathbb{F}^v$.
\Require Verifier has $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{2^v}$, $u, P_1 \in \mathbb{G}$, $\mathbf{z} \in \mathbb{F}^v$.
\Require Prover has $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{2^v}$, $u, P_1 \in \mathbb{G}$, the $v$-variate multilinear polynomial $q: \mathbb{F}_p^v \rightarrow \mathbb{F}_p$, $\mathbf{z} \in \mathbb{F}^v$. 
\Ensure Verifier accepts $P_1 = \mathbf{g}^\mathbf{a}$ and obtains $q(\mathbf{z})$. 

% \State Prover sends $P_1$ to Verifier. 
% \State Verifier sends $\mathbf{z}$ to Prover. 
\State Prover and Verifier compute $P = P_1 \times \mathbf{h}^{\mathbf{b}}$, where $\mathbf{b} = \left (\chi_1(\mathbf{z}), \dots, \chi_{2^v}(\mathbf{z}) \right )$. \Comment{$\chi_i$ are defined in the subsection~\ref{secPolycommit}.}
\State Prover computes $q(\mathbf{z})$ and sends it to Verifier.
\State Prover and Verifier run Algorithm~\ref{Innerproduct} on the input $\left (\mathbf{g}, \mathbf{h}, u, P, q(\mathbf{z}), \mathbf{a}, \mathbf{b} \right )$.  \Comment{$u \in \mathbb{G}$ and $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{2^v}$ are some generators of $\mathbb{G}$.} 
\end{algorithmic}
\end{algorithm}


\begin{figure*}[htbp] 
\centering 
\begin{minipage}{\textwidth} 
\begin{algorithm}[H]
\caption{Verification protocol for matrix multiplication}\label{sumcheck_alg0}
\begin{algorithmic}[1] 
\Require The algorithm inputs are: $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{2^v}$, $u, P_1, P_2 \in \mathbb{G}$, and the $v$-variate multilinear polynomial $f: \mathbb{F}_p^v \rightarrow \mathbb{F}_p$. 

\Require Verifier has $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{2^v}$, $u, P_1, P_2 \in \mathbb{G}$. 
\Require Prover has $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{2^v}$, $u, P_1, P_2 \in \mathbb{G}$, and the $v$-variate multilinear polynomial $f: \mathbb{F}_p^v \rightarrow \mathbb{F}_p$. 

\Ensure Verifier receives $w$ and accepts $w = \sum_{x_1\in\{0,1\}} \sum_{x_2\in\{0,1\}} \dots \sum_{x_v\in\{0,1\}} f\left ( x_1, \dots x_v \right)$.

\State Prover sends $w = \sum_{x_1\in\{0,1\}} \sum_{x_2\in\{0,1\}} \dots \sum_{x_v\in\{0,1\}} f\left ( x_1, \dots x_v \right)$ to Verifier. 
\State Prover sends the polynomial $f_1(X) = \sum_{\left (x_2, \dots, x_v \right ) \in \{ 0, 1 \}^{v-1} } f \left (X,x_2, \dots, x_v \right )$

\State Verifier checks $w = f_1(0) = f_1(1)$. 
\State Verifier sends a random number $r_1 \in \mathbb{F}_p$ to Prover. 

\For{$i = 2, \dots, v-1$}
	\State Prover sends the polynomial $f_i \left ( X \right ) = \sum_{x_{i+1} \in\{0,1\}}  \dots \sum_{x_v \in\{0,1\}} f \left ( r_1, \dots, r_{i-1}, X, x_{i+1}, \dots, x_v \right ) $ to Verifier.

	\State Verifier checks $g_{i-1} \left ( r_{i-1} \right ) = f_i \left (0 \right) + f_i \left (1 \right)$.
	\State Verifier sends a random number $r_i \in \mathbb{F}_p$ to Prover.
\EndFor

\State Prover sends $f_v \left ( X \right ) = f(r_1, \dots, r_{v-1}, X)$ to Verifier. 
\State Verifier checks $f_{v-1} \left (r_{v-1} \right ) = f_v \left (0 \right ) + f_v \left (1 \right )$. 
\State Verifier selects a number $r_v \in \mathbb{F}_p$ uniformly at random from $\mathbb{F}_p$. 

\State Verifier computes $f \left (r_1, \dots, r_v \right )$ and checks $f_v \left (r_v \right ) = f \left (r_1, \dots, r_v \right )$.  % \Comment{Computing $f \left (r_1, \dots, r_v \right )$ is heavy for Verifier.}
\Statex If all checks pass, Verifier accepts that $w$ is correctly calculated. 
\end{algorithmic}
\end{algorithm}
\end{minipage}
\end{figure*}



