\begin{minipage}{\textwidth} 
\begin{algorithm}[H]
\caption{Aggregated Range Proof Protocol}\label{rangeproof}
\begin{algorithmic}[1]
\Require{The algorithm inputs are:  $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{mn}$, $u, P \in \mathbb{G}$, $\mathbf{v} \in \mathbb{F}^m$}
\Require{Verifier has $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{mn}$, $u, P \in \mathbb{G}$.}
\Require{Prover has $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{mn}$, $u, P \in \mathbb{G}$, $\mathbf{v} \in \mathbb{F}^m$.} 

\Ensure{Verifier accepts $P = \mathbf{g}_{\left [:m \right ]}^\mathbf{v}$ and $v_j \in \left [0, 2^n - 1 \right ]$ for all $j \in \left [1,m \right ]$.}   

\State Prover forms $\mathbf{a_L} \in  \mathbb{F}^{mn}$ by concatenating the bits of all $v_j$ such that $\left <\mathbf{2}^n, \mathbf{a}_{L \left [ (j-1)n : jn - 1 \right ]} \right > = v_j$ for all $j \in \left [1, m \right ]$. 
\State Prover computes $\mathbf{a}_R = \mathbf{a}_L - \mathbf{1}^{mn} \in \mathbb{F}^{mn}$ and $A = \mathbf{g}^{\mathbf{a}_L} \mathbf{h}^{\mathbf{a}_R} \in \mathbb{G}$.
\State Prover sends $A$ to Verifier. 
\State Verifier sends two random numbers $y,z \in \mathbb{F}$ to Prover.  
\State Prover forms $\boldsymbol{\ell} = \left (\mathbf{a}_L - z \times \mathbf{1}^{nm} \right ) \in \mathbb{F}^{nm}$, $\mathbf{r} = \mathbf{y}^{nm} \circ \left (\mathbf{a}_R + z \times \mathbf{1}^{nm} \right ) + \sum_{j=1}^{m} z^{1+j} \left (\mathbf{0}^{(j-1)n} || \mathbf{2}^n || \mathbf{0}^{(m-j)n} \right ) \in \mathbb{F}^{nm}$. 
\State Prover computes $q(z) = \left < \mathbf{z}^m, \mathbf{v} \right >$ and sends it to Verifier.
\State Verifier and Prover compute $P' = \mathbf{h}_{\left [:m \right ]}^{\mathbf{z^m}}$.
\State Verifier and Prover run Algorithm~\ref{Innerproduct} on the inputs $\left (\mathbf{g}_{\left [:m \right ]}, \mathbf{h}_{\left [:m \right ]}, u, P \times P', q(z), \mathbf{v}, \mathbf{z}^m \right )$. \Comment{To ensure the correctness of $q(z)$.}   
\State Verifier and Prover compute $\delta (y,z) = (z - z^2) \times \left <\mathbf{1}^{mn}, \mathbf{y}^{mn} \right > - \sum_{j = 1}^{m} z^{j + 2} \times \left <\mathbf{1}^n , \mathbf{2}^n \right >$ and $\mathbf{h}' = \left (h_1, h_2^{\left (y^{-1} \right)}, h_3^{\left (y^{-2} \right)}, \dots, h_{mn}^{\left (y^{-mn+1} \right)} \right )$.
\State Verifier and Prover compute $t = \delta(y,z) + z^2 \times q(z)$ \Comment{$t$ is the claimed $\left <\boldsymbol{\ell}, \mathbf{r} \right >$.}
\State Verifier and Prover compute $P'' = A \times \mathbf{g}^{-z} \times \mathbf{h'}^{z \times \mathbf{y}^{mn}} \times \prod_{j = 1}^{m} \mathbf{h'}^{z^{j+1}\times \mathbf{2}^n}_{\left [(j-1)n : jn-1 \right ]}$. \Comment{$P''$ is the claimed commitment for $\boldsymbol{\ell}$ and $\mathbf{r}$.}
\State Verifier and Prover run Algorithm~\ref{Innerproduct} on the inputs $\left (\mathbf{g}, \mathbf{h}', u, P'', t, \mathbf{r}, \boldsymbol{\ell} \right )$. \Comment{To ensure $t = \left <\boldsymbol{\ell}, \mathbf{r} \right >$ and $P''$ is correct.} 
\end{algorithmic}
\end{algorithm}
\end{minipage}
\end{figure*}

\begin{figure*}[htbp] 
\centering 
\begin{minipage}{\textwidth} 
\begin{algorithm}[H]
\caption{Sum-check protocol for equality check}\label{sumcheck_alg2}
\begin{algorithmic}[1] 
\Require The algorithm inputs are: $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{2^v}$, $u, P_1, P_2 \in \mathbb{G}$, and the $v$-variate multilinear polynomial $f: \mathbb{F}_p^v \rightarrow \mathbb{F}_p$ 
\Statex We have $f(\mathbf{x}) = \tilde{I}  \left (\mathbf{s}, \mathbf{x} \right ) . \left ( \tilde{a}^2 \left (\mathbf{x} \right ) - \tilde{y}^2 \left (\mathbf{x} \right ) \right ) $, where \( \tilde{a} \) and \( \tilde{y} \) are two MLEs, and \( \mathbf{s} \) is a fixed vector.

\Require Verifier has $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{2^v}$, $u, P_1, P_2 \in \mathbb{G}$. 
\Require Prover has $\mathbf{g}, \mathbf{h} \in \mathbb{G}^{2^v}$, $u, P_1, P_2 \in \mathbb{G}$, and the $v$-variate multilinear polynomial $f: \mathbb{F}_p^v \rightarrow \mathbb{F}_p$. 

\Ensure Verifier accepts $0 = \sum_{x_1\in\{0,1\}} \sum_{x_2\in\{0,1\}} \dots \sum_{x_v\in\{0,1\}} f\left ( x_1, \dots x_v \right)$.

\State Prover sends $w = \sum_{x_1\in\{0,1\}} \sum_{x_2\in\{0,1\}} \dots \sum_{x_v\in\{0,1\}} f\left ( x_1, \dots x_v \right)$ to Verifier. 
\State Prover sends the polynomial $f_1(X) = \sum_{\left (x_2, \dots, x_v \right ) \in \{ 0, 1 \}^{v-1} } f \left (X,x_2, \dots, x_v \right )$

\State Verifier checks $w = f_1(0) = f_1(1)$. 
\State Verifier sends a random number $r_1 \in \mathbb{F}_p$ to Prover. 

\For{$i = 2, \dots, v-1$}
	\State Prover sends the polynomial 
	\Statex $f_i \left ( X \right ) = \sum_{x_{i+1} \in\{0,1\}}  \dots \sum_{x_v \in\{0,1\}} f \left ( r_1, \dots, r_{i-1}, X, x_{i+1}, \dots, x_v \right ) $ to Verifier.

	\State Verifier checks $g_{i-1} \left ( r_{i-1} \right ) = f_i \left (0 \right) + f_i \left (1 \right)$.
	\State Verifier sends a random number $r_i \in \mathbb{F}_p$ to Prover.
\EndFor

\State Prover sends $f_v \left ( X \right ) = f(r_1, \dots, r_{v-1}, X)$ to Verifier. 
\State Verifier checks $f_{v-1} \left (r_{v-1} \right ) = f_v \left (0 \right ) + f_v \left (1 \right )$. 
\State Verifier sends a random number $r_v \in \mathbb{F}_p$ to Prover. 

\State Prover and Verifier run Algorithm~\ref{Polycommit} on the input $\left (\mathbf{g}, \mathbf{h}, u, P_1, \tilde{a}, \left (r_1, \dots, r_v \right ) \right )$ for Verifier to obtain $\tilde{a} \left (r_1, \dots, r_v \right )$. 

\State Prover and Verifier run Algorithm~\ref{Polycommit} on the input $\left (\mathbf{g}, \mathbf{h}, u, P_2, \tilde{y}, \left (r_1, \dots, r_v \right ) \right )$ for Verifier to obtain $\tilde{y} \left (r_1, \dots, r_v \right )$. 

\State Verifier computes $\tilde{I} (s_1, \dots, s_v, r_1, \dots, r_v)$. 

\State Verifier commputes $f \left (r_1, \dots, r_v \right ) = \tilde{I} (s_1, \dots, s_v, r_1, \dots, r_v) \left (\tilde{a} \left (r_1, \dots, r_v \right ) - \tilde{y} \left (r_1, \dots, r_v \right ) \right )$ and checks $f_v \left (r_v \right ) = f \left (r_1, \dots, r_v \right )$.  % \Comment{Computing $f \left (r_1, \dots, r_v \right )$ is heavy for Verifier.}
\Statex If all checks pass, Verifier accepts $0 = \sum_{x_1\in\{0,1\}} \sum_{x_2\in\{0,1\}} \dots \sum_{x_v\in\{0,1\}} f\left ( x_1, \dots x_v \right)$. 
\end{algorithmic}
\end{algorithm}
