\section*{Appendix B. Theorems and Proofs} 
\label{appendix2}

\begin{thm}
\label{Range_arithmetic_correctness}
Let \( a \) be a fixed-point number with 1 sign bit, \( t \) integer bits, and \( s \) fractional bits. Suppose the prover sends integers \( a'_1 \) and \( e_1 \) such that the following conditions hold:

\begin{itemize}
    \item \textbf{Condition 1:} \( a \equiv e_1 + 2^s \cdot a'_1 \pmod{p} \), where \( p \) is a prime with at least \( t + s + 3 \) bits.
    \item \textbf{Condition 2:} \( -2^{t+1} \leq a'_1 < 2^{t+1} \).
    \item \textbf{Condition 3:} \( -2^{s-1} \leq e_1 < 2^{s-1} \).
\end{itemize}

Then the verifier can conclude that \( a'_1 = \mathfrak{R}(a) \).
\end{thm}

\begin{proof}
According to the definition, 
\[
\mathfrak{R}(a) = \frac{a + 2^{s-1} - (a + 2^{s-1} \mod 2^s)}{2^s},
\]
if the prover has performed the calculations correctly, they would obtain the values \( a'_2 = \mathfrak{R}(a) \) and \( e_2 = (a + 2^{s-1} \mod 2^s) - 2^{s-1} \). It is straightforward to verify that these two values satisfy the aforementioned conditions. We will now proceed to demonstrate that \( a'_2 = a'_1 \) and \( e_1 = e_2 \).

From Condition 1, we observe that
\[
a \equiv e_1 + 2^s \cdot a'_1 \equiv e_2 + 2^s \cdot a'_2 \pmod{p},
\]
which implies that 
\[
p \mid (e_2 - e_1) + 2^s \times (a'_2 - a'_1).
\]
Moreover, from Condition 2, it follows that
\[
-2^{t+1} \leq a'_2 \leq 2^{t+1} - 1,
\]
and
\[
-2^{t+1} + 1 \leq -a'_1 \leq 2^{t+1},
\]
which leads to
\[
-2^{t+2} + 1 \leq a'_2 - a'_1 \leq 2^{t+2} - 1.
\]
In addition, from Condition 3, we know that
\[
-2^{s-1} \leq e_2 \leq 2^{s-1} - 1,
\]
and
\[
-2^{s-1} + 1 \leq -e_1 \leq 2^{s-1},
\]
which implies that
\[
-2^{s} + 1 < e_2 - e_1 < 2^s - 1.
\]
Thus, we have the following inequality:
\[
-2^{t+s+2} + 2^s \leq 2^s (a'_2 - a'_1) \leq 2^{t+s+2} - 2^s.
\]
From these inequalities, we deduce that
\[
-2^{t+s+2} + 1 \leq (e_2 - e_1) + 2^s \times (a'_2 - a'_1) \leq 2^{t+s+2} - 1.
\]
Since \( p \) has at least \( s + t + 3 \) bits, we can conclude that
\[
2^{s+t+2} \leq p.
\]
Thus, since \( p \) divides \( (e_2 - e_1) + 2^s \times (a'_2 - a'_1) \), and this expression is smaller in magnitude than \( p \), the only possible solution is
\[
(e_2 - e_1) + 2^s \times (a'_2 - a'_1) = 0.
\]
Given the bounds on \( e_1 \) and \( e_2 \) as well as the multiple of \( 2^s \), it follows that
\[
e_1 = e_2,
\]
and consequently,
\[
a'_1 = a'_2.
\]
\end{proof}



