\subsection{The model's differential topology, differential chains, and Jacobian}\label{ssec:modelsDifferentialTopologyDifferentialChainsAndJacobian}

In order to derive an appropriate Jacobian transformation and suitable Taylor approximations of the inter-modal interference, it is necessary to first carefully consider the model's differential topology.  The general spatially-dependent propagation angles that are mapped by invariance relations, $\(\tht(z|y),\phi(y)\)$, are conceptually distinct from the initial propagation angles defined at the source, $\(\tht_0,\phi_0\)$.  

Under the adiabatic approximation, the modenumbers $\Im$ and $\In$ are invariant throughout the waveguide and uniquely identify individual modes.  Each $(m,n)$-mode has modal eigenvalues $k_{xym}(y)$ and $k_{xmn}$, and each eigenvalue pair corresponds to a mapping of propagation angles $\theta_{m}(z|y)$ (elevation) and $\phi_{mn}(y)$ (azimuth) along the wave's unique trajectory identified by the source take-off angles $\tht_0=\tht(z_0,y_0)$ and $\phi_0=\phi(y_0)$.

This implies the existence of a common reference manifold, $\CM\in\IR^4$ with a canonical basis of the model's independent parameters $\{y,z,\tht_0,\phi_0\}$, from which all other variables in the model may be considered homotopically equivalent to an immersed submanifold of $\CM$. Immersions that are further constrained to be structure-preserving injective mappings are called embeddings, and two differentiable variables that are homeomorphic to the same embedded submanifold of $\CM$ are implicitly diffeomorphic to each other.

Derivatives need only be defined as differentials of a quantity with respect to differentials of the independent parameters, so the only explicit derivatives that need to be defined are those that traverse these relations in reverse order back to the independent parameters.  Any two subsets of variables that are diffeomorphic to the same embedded submanifold of $\CM$ must also be diffeomorphic to each other.  Only derivatives between diffeomorphic submanifolds are considered invertible, and since all manifolds of variables in the model are diffeomorphic to submanifolds of $\CM$, then derivatives between any two diffeomorphic manifolds in the model can be defined through a submanifold of $\CM$ by inverting either one of their total derivatives, i.e. the Jacobian matrices.

The modenumbers, $\(\Im,\In\)$, or closed phase integrals, $\(\IPhi_z,\IPhi_y\)$, are diffeomorphic to the initial propagation angles, $\(\tht_0,\phi_0\)$.  At any fixed receiver position, $(y,z)$, the open phase integrals, $(\IPhi_z(z|y),\IPhi_y(y))$, are diffeomorphic to submanifolds of $(\tht_0,\phi_0)$.  Then a multivariate change of variables between these manifolds is uniquely defined by invertible linear transformations of differentials.

\begin{figure}[!htb]
  \includegraphics[width=\textwidth]{./fig/Fig02_DifferentialChains.png}
  \caption{Univariate differential chains between the cycle integrals and the model's independent parameters}
  \label{fig:DifferentialChains}
\end{figure}

\Cref{fig:DifferentialChains} shows the flow of calculations (black arrows) beginning from the model's canonical basis of parameters (top row).  It should be noted that the relation deriving $k_{xy}(y)$ from $\wtil{\IPhi}_z$ is implicitly defined by the vertical modenumber invariance of the adiabatic modes approximation.  The closed and open phase integrals are the quantities of interest that need their differentials mapped back to the source propagation angles.  The univariate differential chains that flow from a single phase integral to a single source propagation angle are depicted as colored arrows tracing back up in the opposite direction: $\d\IPhi_y/\d\phi_0$ is red, $\d\IPhi_y/\d\theta_0$ is yellow, and $\d\IPhi_z/\d\theta_0$ is blue.  There is no differential chain for $\d\IPhi_z/\d\phi_0$ because the vertical mode expansion is defined independently of azimuthal angles and before the transverse modes are introduced, hence $\d\IPhi_z/\d\phi_0=0$ always.  Using the differential chains illustrated in \cref{fig:DifferentialChains}, multivariate coordinate transformations can be defined that are topologically consistent under the model's assumptions and constraints.  The necessary intermediary univariate derivatives are defined and evaluated in \crefrange{eq:dkxy0dth0}{eq:dPhiydkx}.

\begin{align}
    k_{xy0} &= k_0\cos\tht_0 &\Raro&& \dd{k_{xy0}}{\tht_0} &= -k_0\sin\tht_0 = -k_{z0} \label{eq:dkxy0dth0} \\ \spacedline{5}
    k_z(z|y) &= \sqrt{k^2(z|y)-k_{xy}^2(y)} &\Raro&& \dd{k_z}{k_{xy}} &= \frac{-k_{xy}}{k_z} \label{eq:dkzdkxy} \\
    &&\Raro&& \dd{k_z(z|y_0)}{k_{xy0}} &= \frac{-k_{xy0}}{k_z(z|y_0)} \label{eq:dkzdkxy0} \\ \spacedline{5}
    \wtil{\IPhi}_z(y) &= \int_{z^\lwr(y)}^{z^\upr(y)}k_z(\zet|y)\dzet &\Raro&& \dd{\wtil{\IPhi}_z(y)}{k_{xy}} &= -k_{xy}\wtil{\IL}_{z} \label{eq:dTPhizdkxy} \\
    &&\Raro&& \dd{\wtil{\IPhi}_{z0}}{k_{xy0}} &= -k_{xy0}\wtil{\IL}_{z0} \label{eq:dTPhiz0dkxy0} \\ \spacedline{5}
    \IPhi_z(z|y) &= \int_{z^\lwr(y)}^zk_z(\zet|y)\dzet &\Raro&& \dd{\IPhi_z(z|y)}{k_{xy}} &= -k_{xy}\IL_{z} \label{eq:dPhizdkxy} \\ \spacedline{5}
    \evalat{\wtil{\IPhi}_z}{y_0} &= \evalat{\wtil{\IPhi}_z}{y} &\overset{\ndd{}{\tht_0}}{\Raro}&& \dd{k_{xy}}{k_{xy0}} &= \frac{k_{xy0}\wtil{\IL}_{z0}}{k_{xy}\wtil{\IL}_{z}} \label{eq:dkxydkxy0} \\ \spacedline{5}
    k_x &= k_{xy0}\cos\phi_0 &\Raro&& \pp{k_x}{k_{xy0}} &= \cos\phi_0 = \frac{k_x}{k_{xy0}} \label{eq:dkxdkxy0} \\
    &&\Raro&& \pp{k_x}{\phi_0} &= -k_{xy0}\sin\phi_0 = -k_{y0} \label{eq:dkxdphi0} \\ \spacedline{5}
    k_y(\ups) &= \sqrt{k_{xy}^2(\ups)-k_x^2} &\Raro&& \pp{k_y}{k_{xy}} &= \frac{k_{xy}}{k_y} \label{eq:dkydkxy} \\
    &&\Raro&& \pp{k_y}{k_x} &= \frac{-k_x}{k_y} \label{eq:dkydkx} \\ \spacedline{5}
    \wtil{\IPhi}_y &= \int_{y^\lwr}^{y^\upr}k_y(\ups)\dups &\Raro&& \pp{\wtil{\IPhi}_y}{k_{xy}} &= \int_{y^\lwr}^{y^\upr}\frac{k_{xy}(\ups)}{k_y(\ups)}\dups \label{eq:dTPhiydkxy} \\
    &&\Raro&& \pp{\wtil{\IPhi}_y}{k_x} &= -k_x\wtil{\IL}_y \label{eq:dTPhiydkx} \\ \spacedline{5}
    \IPhi_y(y) &= \int_{y^\lwr}^yk_y(\ups)\dups &\Raro&& \pp{\IPhi_y}{k_{xy}} &= \int_{y^\lwr}^y\frac{k_{xy}(\ups)}{k_y(\ups)}\dups \label{eq:dPhiydkxy} \\
    &&\Raro&& \pp{\IPhi_y}{k_x} &= -k_x\IL_y \label{eq:dPhiydkx}
\end{align}

Using these derivatives and following the differential chains depicted in \cref{fig:DifferentialChains}, the total directional derivatives of the phase integrals along differentials of the independent parameters $\tht_0$ and $\phi_0$ may be constructed.  New convenience notation is introduced in \cref{eq:phaseIntegralConvenienceNotation} to keep the expressions compact.  In some cases, taking derivatives of functionals (the cycle integrals) requires using Leibniz differentiation under the integral. Alternatively they can be evaluated more rigorously using functional calculus, but careful consideration of the differential topology shows that the differentials may be simplified to standard techniques of multivariate calculus.

\begin{gather}\label{eq:phaseIntegralConvenienceNotation}
    %\Given f(x,y) \tlet \nabla_x f &= \hgrad f \cdot \hvec{e}_{\dx} = \hgrad f \cdot \frac{\hvec{\dx}}{\abs{\hvec{\dx}}} = \pp{f}{x} \tand \p_x f = \hgrad f \cdot \hvec{\dx} = \pp{f}{x}\dx \\
    \Let \left\{\q \begin{gathered}\tau_{z} = \tan\tht = \frac{k_{z}}{k_{xy}} \tand \tau_{y} = \tan\phi = \frac{k_{y}}{k_x} \\
    \wtil{\ILam}_y = k_x^2\wtil{\IL}_y \comma \wtil{\ILam}_z(y) = k_{xy}^2(y)\wtil{\IL}_{z}(y) \command \wtil{\ILam}_{z0} = k_{xy0}^2\wtil{\IL}_{z0} \\
    \ILam_y(y) = k_x^2\IL_y(y) \tand \ILam_z(z|y) = k_{xy}^2(y)\IL_z(z|y) \\
    \wtil{\IL}_{yz} = \int_{y^\lwr}^{y^\upr}\frac{1}{k_y(\ups)\wtil{\IL}_z(\ups)}\dups \tand \IL_{yz}(y) = \int_{y^\lwr}^{y}\frac{\dups}{k_y(\ups)\wtil{\IL}_z(\ups)} \end{gathered} \right.
\end{gather}

\begin{equation}\begin{aligned}
  \d\wtil{\IPhi}_z &= \int_{z^\lwr(y)}^{z^\upr(y)} \pp{k_z}{k_{xy}}\pp{k_{xy}}{k_{xy0}}\pp{k_{xy0}}{\tht_0}\dzet\d\tht_0 + \cancelto{0}{\[k_z(\zet|y)\pp{\zet}{\tht_0}\]_{z^\lwr(y)}^{z^\upr(y)}}\d\tht_0 + \cancelto{0}{\p_{\phi_0}\wtil{\IPhi}_z}\dphi_0 \\
  &= \tau_{z0}\wtil{\ILam}_{z0}\dtht_0 + 0\dphi_0
\end{aligned}\end{equation}

\begin{equation}\begin{aligned}
  \d\wtil{\IPhi}_y &= \cancelto{0}{\[k_y(\ups)\pp{\ups}{\tht_0}\]_{y^\lwr}^{y^\upr}}\dtht_0 + \int_{y^\lwr}^{y^\upr}\[\pp{k_y}{k_{xy}}\pp{k_{xy}}{k_{xy0}}+\pp{k_y}{k_x}\pp{k_x}{k_{xy0}}\]\pp{k_{xy0}}{\tht_0}\dups\dtht_0 \\
  &\q + \cancelto{0}{\[k_y(\ups)\pp{\ups}{\phi_0}\]_{y^\lwr}^{y^\upr}}\dphi_0 + \int_{y^\lwr}^{y^\upr}\pp{k_y}{k_x}\pp{k_x}{\phi_0}\dups\dphi_0 \\
  &= \tau_{z0}\(\wtil{\ILam}_y-\wtil{\ILam}_{z0}\wtil{\IL}_{yz}\)\dtht_0 + \tau_{y0}\wtil{\ILam}_y\dphi_0
\end{aligned}\end{equation}

