The closed phase integrals are directly proportional to the modenumbers by a constant factor of $\pi$, so their Jacobian, \cref{eq:closedPhaseIntegralJacobian}, and its inverse, \cref{eq:inverseClosedPhaseIntegralJacobian}, are used as a Jacobian determinant, \cref{eq:modenumberJacobianDeterminant}, to transform between differentials on the $(\Im,\In)$-manifold and differentials on the $(\tht_0,\phi_0)$-manifold.

\begin{align}
    \bmat{\d\Im \\ \d\In} &= \pi^{-1}\pmat{\tau_{z0}\wtil{\ILam}_{z0} & 0 \\ \tau_{z0}\(\wtil{\ILam}_y-\wtil{\ILam}_{z0}\wtil{\IL}_{yz}\) & \tau_{y0}\wtil{\ILam}_y}\bmat{\d\tht_0 \\ \d\phi_0} = \(\frac{\D(\Im,\In)}{\D(\tht_0,\phi_0)}\)\bmat{\d\tht_0 \\ \d\phi_0} \label{eq:closedPhaseIntegralJacobian} \\
    \bmat{\d\tht_0 \\ \d\phi_0} &= \pi\pmat{\[\tau_{z0}\wtil{\ILam}_{z0}\]^{-1} & 0 \\[6pt] \frac{\wtil{\ILam}_{z0}\wtil{\IL}_{yz}-\wtil{\ILam}_y}{\tau_{y0}\wtil{\ILam}_y\wtil{\ILam}_{z0}} & \[\tau_{y0}\wtil{\ILam}_y\]^{-1}}\bmat{\d\Im \\ \d\In} = \(\frac{\D(\tht_0,\phi_0)}{\D(\Im,\In)}\)\bmat{\d\Im \\ \d\In} \label{eq:inverseClosedPhaseIntegralJacobian} \\
    \d\Im\d\In &= \abs{\frac{\D(\Im,\In)}{\D(\tht_0,\phi_0)}}\d\tht_0\d\phi_0 = \pi^{-2}\tau_{z0}\tau_{y0}\wtil{\ILam}_y\wtil{\ILam}_{z0}\d\tht_0\d\phi_0 = \pi^{-2}k_xk_{y0}k_{z0}k_{xy0}\wtil{\IL}_y\wtil{\IL}_{z0}\d\tht_0\d\phi_0 \label{eq:modenumberJacobianDeterminant}
\end{align}

The Jacobian for the open phase integrals is defined and evaluated similarly, yielding \cref{eq:openPhaseIntegralJacobian}.

\begin{equation}\label{eq:openPhaseIntegralJacobian}
  \bmat{\d\IPhi_z(z|y) \\ \d\IPhi_y(y)} = \pmat{\tau_{z0}\frac{\wtil{\ILam}_{z0}}{\wtil{\ILam}_z}\ILam_z & 0 \\ \tau_{z0}\(\ILam_y-\wtil{\ILam}_{z0}\IL_{yz}\) & \tau_{y0}\ILam_y} \bmat{\d\tht_0 \\ \d\phi_0}
\end{equation}

