Derivation of the convergence factor will require an expression for the total derivative of the open phase integrals with respect to the modenumbers, \cref{eq:openClosedPhaseIntegralJacobian}, which is the product of the Jacobians from \cref{eq:openPhaseIntegralJacobian} and \cref{eq:inverseClosedPhaseIntegralJacobian}.  Two new symbols are introduced for notational convenience in \cref{eq:fractionalCyclePhaseOffsetDefinition}, which are the cycle phase offsets for the vertical and transverse cycles expressed as fractional cycles or ``turns'' instead of radians.  The cross-domain spectral cycle distances, $\IL_{yz}$ and $\wtil{\IL}_{yz}$, are accumulating the elapsed vertical cycles per partial or total transverse cycle respectively, and thus effectively function as a cross-domain correction to the cycle phase offsets due to the interdependence of the double mode summation.  Changes in the modal interference at some fixed $(y,z)$-position due to varying the ray's initial propagation angles, $(\tht_0,\phi_0)$, can be approximated using the vertical cycle phase, transverse cycle phase, and this cross-domain proportion of elapsed cycles accumulated along the wave's horizontal trajectory.  The physical meaning of the differential transformation in \cref{eq:openClosedPhaseIntegralJacobian} is that small changes in modenumbers, $\d\Im$ and $\d\In$, can be converted to small changes in modal phases, $\d\IPhi_z$ and $\d\IPhi_y$, for all $(y,z)$-positions within the environment.

\begin{equation} \label{eq:fractionalCyclePhaseOffsetDefinition}
  \Let \IChi_y(y) = \frac{\IL_y(y)}{\abs{\wtil{\IL}_y}} = \frac{\ILam_y(y)}{\abs{\wtil{\ILam}_y}} \tand \IChi_z(z|y) = \frac{\IL_z(z|y)}{\abs{\wtil{\IL}_z(y)}} = \frac{\ILam_z(z|y)}{\abs{\wtil{\ILam}_z(y)}} \\
\end{equation}

\begin{gather}\begin{aligned}\label{eq:openClosedPhaseIntegralJacobian}
    \bmat{\d\IPhi_z(z|y)\\\d\IPhi_y(y)} &= \DD{(\IPhi_z,\IPhi_y)}{(\tht_0,\phi_0)}\[\DD{(\Im,\In)}{(\tht_0,\phi_0)}\]^{-1}\bmat{\dtht_0\\\dphi_0} \\
    %&= \pi\pmat{ \tau_{z0}\frac{\wtil{\ILam}_{z0}}{\wtil{\ILam}_z}\ILam_z & 0 \\[6pt] \tau_{z0}\(\ILam_y-\wtil{\ILam}_{z0}\IL_{yz}\) & \tau_{y0}\ILam_y} \pmat{\[\tau_{z0}\wtil{\ILam}_{z0}\]^{-1} & 0 \\[6pt] \frac{\wtil{\ILam}_{z0}\wtil{\IL}_{yz}-\wtil{\ILam}_y}{\tau_{y0}\wtil{\ILam}_y\wtil{\ILam}_{z0}} & \[\tau_{y0}\wtil{\ILam}_y\]^{-1}} \bmat{\d\Im \\ \d\In} \\
    &= \pi\pmat{ \IChi_z & 0 \\[6pt] \IChi_y\wtil{\IL}_{yz}-\IL_{yz} & \IChi_y }\bmat{\d\Im \\ \d\In}
\end{aligned}\end{gather}

The convergence factor derivation also uses one other derivative of the forward wavenumber component with respect to the modenumbers, provided here in \cref{eq:dkxdmn}.

\begin{gather}\begin{aligned}\label{eq:dkxdmn}
    %\bmat{\dk_x} &= \pmat{\pp{k_x}{\tht_0} & \pp{k_x}{\phi_0}}\pmat{\pp{\Im}{\tht_0} & \pp{\Im}{\phi_0} \\ \pp{\In}{\tht_0} & \pp{\In}{\phi_0}}^{-1}\bmat{\d\Im \\ \d\In} \\
    %&= -\pi\pmat{\frac{k_xk_{z0}}{k_{xy0}} & k_{y0}}\pmat{\[\tau_{z0}\wtil{\ILam}_{z0}\]^{-1} & 0 \\ \frac{\wtil{\ILam}_{z0}\wtil{\IL}_{yz}-\wtil{\ILam}_y}{\tau_{y0}\wtil{\ILam}_y\wtil{\ILam}_{z0}} & \[\tau_{y0}\wtil{\ILam}_y\]^{-1}}\bmat{\d\Im \\ \d\In} \\
    \bmat{\dk_x} &= \frac{-\pi k_x}{\wtil{\ILam}_y}\pmat{\wtil{\IL}_{yz} & 1}\bmat{\d\Im \\ \d\In}
\end{aligned}\end{gather}

