%
\includegraphics[width=0.8\textwidth]{Dstar0Xic0.eps}
%\includegraphics[width=1.0\textwidth]{Dstar0Xic0z.eps}
%
\caption{$1/|H_\rho^{(2)}(\alpha)|^2$ .vs. the complex energy $E$ with $\alpha=3.73$ and $m_\sigma=440$ MeV in the $\Xi_c^0 \bar{D}^{*0}$ case. The pole of $1/|H_\rho^{(2)}(\alpha)|^2$ corresponds to a zero point of the second kind of Hankel function $H_\rho^{(2)}(\alpha)$, which represents a resonance state of $\Xi_c^0 \bar{D}^{*0}$, as labeled in the figure.}
\label{fig:Dstar0Xic0}
