%     If $X$ is not compact, the above proof can be altered to show that the derivatives of the finitary approximation of $L\Sigma^\infty R_X$ are $(X^\vee)^{\wedge \ast}$. Interestingly, this means that if $X$ is dualizable but not compact, there is still an equivalence
%     \[\nat(L\Sigma^\infty R_X|_{L\s^\omega},\mathrm{Id}_{L\s}^{\wedge n}|_{L\s^\omega}) \simeq X^{\wedge n}\]
%     even though the functor $L\Sigma^\infty R_X|_{L\s^\omega}$ is not represented by $X$ (since $X$ is not in $L\s^\omega$).
% \end{remark}





\begin{lem}\label{lem: coend is retract of dual derivatives}
    For $C$ differentially dualizable, the symmetric sequence
    $\mathrm{CoEnd}(\Sigma^\infty_C)$  is a retract of $\partial_\ast (\Sigma^\infty_C\Omega^\infty_C)^\vee$. In particular, $\mathrm{CoEnd}(\Sigma^\infty_C)$ is levelwise dualizable.
\end{lem}

\begin{proof}




    The functors $\Sigma^\infty_C$ and $(\Sigma^\infty_C)^{\wedge n}$ are homogeneous and finitary, and so by \cite[Proposition B.4]{HeutsGoodwillieApprox} an extra codegeneracy argument implies that taking the comonadic $\Sigma^\infty_C \Omega^\infty_C$-resolution of these functors provides a retraction:
    \[\mathrm{RComod}_{\Sigma_C^\infty \Omega^\infty_C}(\Sigma^\infty_C \circ \Omega_C^\infty, (\Sigma^\infty_C)^{\wedge n} \circ \Omega_C^\infty  ) \rightarrow \nat(\Sigma^\infty_C,(\Sigma^\infty_C)^{\wedge n}).\]

    The right $\Sigma^\infty_C \Omega^\infty_C$-comodule $(\Sigma^\infty_C)^{\wedge n} \circ \Omega_C^\infty$ can be equivalently written as  $\mathrm{Id}_{L\s}^{\wedge n} \circ \Sigma^\infty_C \Omega_C^\infty$ which is the cofree right comodule on $\mathrm{Id}_{L\s}^{\wedge n}$. Hence,
    \[\mathrm{RComod}_{\Sigma_C^\infty \Omega^\infty_C}(\Sigma^\infty_C \circ \Omega_C^\infty, (\Sigma^\infty_C)^{\wedge n} \circ \Omega^\infty_C ) \simeq \nat(\Sigma_C^\infty \Omega^\infty_C,\mathrm{Id}_{L\s}^{\wedge n}).\]
Applying Lemma \ref{lem:dualizable natural trans spec} and the levelwise dualizability of $\partial_\ast (\Sigma^\infty_C \Omega^\infty_C)$ yields:
    \[\nat(\Sigma_C^\infty \Omega^\infty_C,\mathrm{Id}_{L\s}^{\wedge n})\simeq (\partial_n \Sigma^\infty_C \Omega^\infty_C)^\vee.\]
This demonstrates the claimed retraction.
\end{proof}
\begin{remark}
Proposition \ref{prop:product rule implies coend is koszul dual to identity} shows these are actually equivalent
\[\mathrm{CoEnd}(\Sigma^\infty_C) \simeq \partial_\ast (\Sigma^\infty_C \Omega^\infty_C)^\vee.\]
\end{remark}


\begin{definition}
    The Koszul dual derivatives of $F\in \mathrm{Fun}^\omega (C,L\s)$ are
    \[\partial^\ast F := \mathrm{Hom}^\Sigma(F,\Sigma^\infty_C).\]
    These define a contravariant functor
    \[\partial^\ast:\mathrm{Fun}^\omega(C,L\s) \rightarrow \mathrm{RMod}^\mathrm{op}_{\mathrm{CoEnd}(\Sigma^\infty_C)}.\]
\end{definition}

More generally, $\partial^\ast (-)$, somewhat tautologically, is defined for nonfinitary functors as long as the given natural transformation objects exist. For instance, if $F$ is left Kan extended from a small subcategory, the natural transformation objects exist because they can be computed by restricting to a subcategory where size issues are not a concern. In particular, this includes all representable functors.

There are a few immediately accessible facts about Koszul dual derivatives. The operad $\mathrm{CoEnd}(\Sigma^\infty_C)$ is reduced by elementary properties of homogeneous functors. The Yoneda lemma \cite{HinichYoneda} allows one to compute the operad action on Koszul dual derivatives of representables.

\begin{prop}\label{prop: koszul dual derivatives of rep}
    If $c \in C$, there is a natural equivalence of right modules \[\partial^\ast L\Sigma^\infty R_C \simeq (\Sigma^\infty_C c)^{\wedge \ast}\] where $\Sigma^\infty_C c^{\wedge \ast}$ is equipped with the tautological action of $\mathrm{CoEnd}(\Sigma^\infty_C)$.
\end{prop}
Note this proposition holds even when $c\in C$ is not compact. In order to understand the Koszul dual derivatives of general finitary functors, we start by understanding them for homogeneous functors. 
\begin{prop}\label{prop: dual derivatives of homogeneous}
    Suppose $X \in L\s^{B\Sigma_n}$ is dualizable. There is an equivalence of right modules \[\partial^\ast (X \wedge_{h\Sigma_n}( \Sigma^\infty_C)^{\wedge n}) \simeq \mathrm{Free}^\mathrm{RMod}_{\mathrm{CoEnd}(\Sigma^\infty_C)}(X^\vee) . \]
\end{prop}

\begin{proof}
    We will compute $ \nat(X \wedge_{h\Sigma_n} (\Sigma^\infty_C)^{\wedge n},(\Sigma^\infty_C)^{\wedge m})$ by decomposing the domain and codomain. Given a function $\phi:m \rightarrow n$, there is a preferred identification \[(\Sigma^\infty_C)^{\wedge m}\simeq \bigwedge^n_{i=1} (\Sigma^\infty_C)^{\wedge \phi^{-1} (i)}.\] 

The symmetric monoidal structure on $\mathrm{Fun}^\omega (C,L\s)$ induces a map
  \[X^\vee \wedge_{h\Sigma_n} \bigvee_{ \phi \in \sf{FinSet}(m,n)} \bigwedge_{i=1}^n \nat(\Sigma^\infty_C,(\Sigma^\infty_C)^{\wedge{ \phi^{-1}(i)}}) \rightarrow \nat(X \wedge_{h\Sigma_n} (\Sigma^\infty_C)^{\wedge n},(\Sigma^\infty_C)^{\wedge m}).\]
  The left hand side is $\mathrm{Free}^\mathrm{RMod}_{\mathrm{CoEnd}(\Sigma^\infty_C)}(X^\vee)(m)$. As before, we resolve by the $\Sigma^\infty_C \Omega^\infty_C$-comonad and use cofreeness to instead check the following is an equivalence
   \[X^\vee \wedge_{h\Sigma_n} \bigvee_{ \phi \in \sf{FinSet}(m,n)} \bigwedge_{i=1}^n \nat(\Sigma^\infty_C \Omega^\infty_C,\mathrm{Id}_{L\s}^{\wedge ^{\wedge{\phi^{-1}(i)}}}) \rightarrow \nat(X \wedge_{h\Sigma_n} (\Sigma^\infty_C \Omega^\infty_C)^{\wedge n},\mathrm{Id}_{L\s}^{\wedge m}),\]
which suffices because the original map is a retract of this new map. This new map is an equivalence by the $L$-local version of the weak dual stable chain rule \cite[Lemma 2.5.9]{ACOperads} applied to \[(X \wedge_{h\Sigma_n} (-)^{\wedge n} ) \circ \Sigma^\infty_C \Omega^\infty_C.\]
\end{proof}

In our study of the Goodwillie tower of $F(c)$, two different finiteness criteria will arise. The first is the levelwise dualizability of $\partial_\ast F$. The second is the compactness of $c \in C$. These two hypotheses play dual roles, and we will define two different approximations of $P_\infty(F)$ which agree when $\partial_\ast(F)$ is levelwise dualizable and $c$ is compact, but not in general.


\begin{definition}\label{definition: upper tower}
    Suppose $F \in \mathrm{Fun}^\omega(C,L\s)$. We  define the upper fake Goodwillie tower of $F$ as a filtered object of $\mathrm{Fun}(C,L\s)$ given by
    \[P_n^\mathrm{fake}(F)(c):=\mathrm{RMod}_{\mathrm{CoEnd}(\Sigma^\infty_C)}(\partial^{\ast} F ,(\Sigma^\infty_C(c)^{\wedge \ast})^{\leq n}).\]
\end{definition}

 There is a map $F(c) \rightarrow P_n^\mathrm{fake}(F)(c)$ which is constructed by via the Yoneda lemma and Proposition \ref{prop: koszul dual derivatives of rep}:
 \[F(c) \simeq \nat(L\Sigma^\infty R_c,F) \rightarrow \mathrm{RMod}_{\mathrm{CoEnd}(\Sigma^\infty_C)}(\partial^\ast F,(\Sigma^\infty_C(c)^{\wedge \ast})^{\leq n}) ).\]

 When $c$ is compact, this map may be constructed as the unit of the adjunction
\[
\adjunction{\partial^{\leq n}}{\mathrm{Fun}(C^{\omega},L\s)}{\sf{RMod}^{\leq n}_{\mathrm{CoEnd}(\Sigma^\infty_C)}}{\Theta^{\leq n}_K}.
\]

We define $D^\mathrm{fake}_n(F)$ as $n$th fiber of this filtered object. The map $F \rightarrow P^\mathrm{fake}_n(F)$ factors through $P_n(F)$, and we get an induced maps 
\[D_n(F) \rightarrow D_n^\mathrm{fake}(F).\]
The upper fake tower is often more accessible than the Goodwillie tower. By identifying the maps between the layers, one can pull back calculations in the upper fake Goodwillie tower to the Goodwillie tower. 

It is no surprise that we will soon introduce a ``lower fake Goodwillie tower''. One studies the elementary properties of the upper and lower fake Goodwillie towers in a rather formal manner, following \cite[Sections 6.2, 6.4]{MTOrthogonal}:
\begin{enumerate}
    \item Construct the upper (lower) fake tower as the unit of an adjunction between $\mathrm{Fun}(C^\omega,L\s)$ and $\mathrm{RMod}^\mathrm{op}_O$ $(\mathrm{RMod}_{K(O)})$. 
    \item For $X \in L\s^{B\Sigma_n}$, compute that the right module associated to $X \wedge_{h\Sigma_n} (\Sigma^\infty_C)^{\wedge n}$ is free (trivial).
    \item  Demonstrate that $D^\mathrm{fake}_n(F)$ $(D_\mathrm{fake}^n(F))$ depends only on $\partial_n F$.
    \item Compute that the map between the layers of the Goodwillie tower and either fake Goodwillie tower for the homogeneous functor $X \wedge_{h\Sigma_n} (\Sigma^\infty_C)^{\wedge n}$ is the norm map.
\end{enumerate}

Koszul duality enters the picture in the analysis of the fibers $D^\mathrm{fake}_n(F)$, and informs the types of finiteness assumptions required on $\partial_\ast F$ for the fake tower to be well behaved.


For $P^\mathrm{fake}_n$ we have already demonstrated the first two elements as Definition \ref{definition: upper tower} and Proposition \ref{prop: dual derivatives of homogeneous}. The latter two items are rather formal and appear several times in various forms throughout \cite{ACOperads,MTOrthogonal}; we will not reproduce such arguments here and rather state the final result.



