\[\begin{tikzcd}
	& {\mathrm{RMod}_{O}} \\
	{\mathrm{Fun}(C^\omega,L\s)} & {\mathrm{SymSeq}(L\s)}
	\arrow["{\mathrm{Forget}_O}", from=1-2, to=2-2]
	\arrow[from=2-1, to=1-2]
	\arrow["{\partial_\ast}"', from=2-1, to=2-2]
\end{tikzcd}\]
\end{center}
for some $O$ in $\mathrm{Operad}(L\s)$. 

\begin{definition}
    We say that for a differentially dualizable $C$
    \[\partial_\ast: \mathrm{Fun}(C^\omega,L\s) \rightarrow \mathrm{RMod}_O\]
classifies Goodwillie towers if the adjunction
\[
\adjunction{\partial_{\leq n}}{\mathrm{Fun}(C^{\omega},L\s)}{\sf{RMod}^{\leq n}_{O}}{\Theta^{\mathrm{RMod}}_{\leq n}}
\]
restricts to an equivalence of categories for all $n<\infty$
\[
\adjunction{\partial_{\leq n}}{\mathrm{Poly}_n(C^{\omega},L\s)}{\sf{RMod}^{\leq n}_{O}}{\Theta^{\mathrm{RMod}}_{\leq n}}.
\]
This is equivalent to asking that it restricts to an equivalence
\[
\adjunction{\partial_{\ast}}{\mathrm{Poly}(C^{\omega},L\s)}{\sf{RMod}^{<\infty}_{O}}{\Theta^{\mathrm{RMod}}}.
\]
\end{definition}
One might notice that we have abusively referred to both $\partial_\ast$ and its adjoint $\Theta^{\mathrm{RMod}}$ using the same names as in Section \ref{section: right module construction}. This is because, under mild conditions, right module structures on derivatives are essentially unique.


\begin{definition}\label{definition: quasiequivalence}
    A quasi-equivalence of $O,P \in \mathrm{Operad}(L\s)$ is an equivalence of enriched categories
    \[\mathrm{Env}(O)\simeq \mathrm{Env}(P). \]
\end{definition}

If $O$ is quasi-equivalent to $P$, their categories of right modules are canonically equivalent, and the obstruction to upgrading a quasi-equivalence to an equivalence is whether or not the equivalence of right module categories can be made symmetric monoidal.

\begin{prop}\label{prop: right module classification quasi}
    If 
    \[\partial_\ast:\mathrm{Fun}(C^\omega,L\s) \rightarrow \mathrm{RMod}_O\]
    classifies Goodwillie towers, then there is a quasi-equivalence of operads \[O \simeq K(\mathrm{CoEnd}(\Sigma^\infty_C))\] under which the right module structure on $\partial_\ast$ agrees with Definition \ref{definition: right module derivatives}. If $\partial_\ast$ can be made symmetric monoidal, the quasi-equivalence may be lifted to an equivalence of operads.
\end{prop}
\begin{proof}
    From Proposition \ref{prop: dual derivatives of homogeneous}, one may identify $\mathrm{Env}(\mathrm{CoEnd}(\Sigma^\infty_C) )$ with the opposite of the full subcategory of polynomial functors on $(\langle \Sigma^\infty_C )^{\wedge n}\rangle_{n \in \mathbb{N}}$.

There is then a quasi-equivalence of operads
    \[\mathrm{CoEnd}(\Sigma^\infty_C) \rightarrow K(O)\]
constructed by applying $\partial_\ast$ to this subcategory and using the assumption that the right $O$-module structure classifies Goodwillie towers. If $\partial_\ast$ satisfies a product rule, this is symmetric monoidal and so induces an equivalence of operads.

In the same way, there is a compatible map
    \[\partial^\ast F \rightarrow K(\partial_\ast F)\]
which is an equivalence by the same reasoning. The Koszul duality between derivatives and Koszul dual derivatives completes the result, with the usual caveat that one should first restrict to representables of compacts, which satisfy the necessary level-dualizability, and then Kan extend.
\end{proof}

\begin{definition}
 A stable category $C$ is $1$-semiadditive if for all finite groups $G$ the Tate construction
\[X^{tG}:= \mathrm{cofiber}(X_{G} \rightarrow X^{G})\]
is contractible.
\end{definition}

\begin{lem} \label{lem: semiadditive sigma norm}
   The category $C$ is $1$-semiadditive, if and only if, all Tate constructions vanish for all symmetric groups $\Sigma_n$.

\end{lem}
\begin{proof}
The forward implication is immediate from the definition of $1$-semiadditivity. 

For the latter implication, fix an embedding $G \hookrightarrow \Sigma_n$. By the equivalence between induction and coinduction for finite groups \cite{Fausk2003}, we have an equivalence of cofiber sequences
