\[\begin{tikzcd}
	& {\mathrm{RMod}^\mathrm{dp}_{O}} \\
	{\mathrm{Fun}(C^\omega,L\s)} & {\mathrm{SymSeq}(L\s)}
	\arrow["{\mathrm{Forget}^\mathrm{RMod}_O}", from=1-2, to=2-2]
	\arrow[from=2-1, to=1-2]
	\arrow["{\partial_\ast}"', from=2-1, to=2-2]
\end{tikzcd}\]
