\begin{eqnarray}\label{m3}
  m_1(t) &=& \frac{\alpha}{N} \left( \sum_{i=1}^K \int_0^t \phi_i(t-\eta) V_i'(\eta) d\eta  \right) + \frac{(1-b)}{N}{\int_0^t \psi(t-\eta) R_n(\eta) d\eta}, \nonumber\\
\end{eqnarray}
% \color{black}
and the effective immunity at time $t$ coming from vaccination of comorbid class $P(t)$ is given by:
% \begin{equation}\label{mm3}
%   m_2(t) = \frac{1-\alpha}{N} \left( \int_0^t \phi_{12}(t-\eta) V_{12}'(\eta) d\eta  + \int_0^t \phi_3(t-\eta) V_3'(\eta) d\eta  \right),
% \end{equation}


% \color{red}
\begin{eqnarray}\label{mm3}
  m_2(t) &=& \frac{1-\alpha}{N} \left( \sum_{i=1}^K \int_0^t \phi_i(t-\eta) V_i'(\eta) d\eta  \right) +  \frac{b}{N}{\int_0^t \epsilon \psi(t-\eta) R_n(\eta) d\eta},\nonumber\\
\end{eqnarray}
% \color{black}
where, $0< \epsilon <1 $ is a constant, $\alpha$ is the proportion of healthy susceptible $S$ who are newly vaccinated. \textcolor{black}{The value of $\epsilon<1$ signifies that the infection acquired immunity for the comorbid individuals is less than that for the non-comorbid individuals.} Parameter $b$ characterizes the proportion of comorbidity among the newly recovered individuals while the function $\psi(t)$ describes how acquired immunity changes over time.
We choose functions $\phi_j$ and $\psi_j$ focusing on multiple criteria, prioritizing the acquisition-fading function, exponential fading function and the power law function. The functional fits are parameterized against epidemiological data comprising the epidemic form. Assuming homogeneity, we consider $\phi_j \equiv \phi$ and $\psi_j \equiv \psi$, for $j=1, 2, \cdots, K$. Moreover, to account for \enquote{bounded} infection growth, we impose a constraint on the population immunity level: $0<m_1(t)+m_2(t)<1$.

\subsubsection{Impact of Multiple Strains}
Immunity in the population corresponds to the decrease of the number of susceptible individuals. As such, instead of equality (\ref{n0}), we have
\begin{equation}\label{m4}
 S(t)   = N - (I(t) + D(t) + P(t)+ m_1(t) N).
\end{equation}
Note that $m_2(t)$ does not appear in the equation \eqref{m4} because $m_2(t)$ is the level of immunity in the comorbid class; it is only considered later in the equation for $P(t)$, where $P(t)$ is the predisposed comorbid population. Let, $J_1(t)$ represents the number of daily new infection in the healthy susceptible class $S(t)$ and $J_2(t)$ represents the number of daily new cases in the comorbid class $P(t)$. Then the total number of daily new cases is given by $$J(t)=J_1(t)+J_2(t),$$ where,
$$J_1(t)=\frac{S(t)}{N} \int_0^t \beta(t-\eta) J(\eta) d \eta,$$
$$J_2(t)=\frac{\kappa P(t)}{N} \int_0^t \beta(t-\eta) J(\eta) d \eta,$$
$\kappa>1$ is a constant, \textcolor{black}{which signifies that the comorbid individuals are more prone to the infection as compared to the non-comorbid individuals}.

The governing equation for the comorbid class $P(t)$ is given by
% \begin{equation}
% P(t) =  b \int_0^t R(\eta) d \eta - \int_0^t J_2(\eta)d \eta - m_2(t) N.\label{n2}
% \end{equation}
% \color{red}
\begin{equation}
P(t) =  b \int_0^t R_n(\eta) d \eta - \int_0^t J_2(\eta)d \eta - m_2(t) N.\label{n2}
\end{equation}
% \color{black}
%\begin{equation}
%\frac{d P}{dt}  =  b R(t)  - \frac{\kappa P}{N} \int_0^t \beta(t-\eta) J(\eta) d \eta - m_2(t) N.\label{n2}
%\end{equation}
The equation for the infected compartment is given by
\begin{equation}
  \frac{d I}{dt} =  \textcolor{black}{\frac{S(t)+\kappa P(t)}{N} \int_0^t \beta(t-\eta) J(\eta) d \eta} -   \int_0^t r(t-\eta) J(\eta) d \eta - \int_0^t d(t-\eta) J(\eta) d \eta . \label{m5}
\end{equation}
 Finally the equations for the recovered and death compartments are 
\begin{equation}
   \frac{d R}{dt}   =  (1-b)R_n(t), \;\;\;
\frac{d D}{dt}  = \int_0^t d(t-\eta) J(\eta) d \eta \;(= D_n(t)), \label{m6}
\end{equation}


where, $$R_n(t)=\int_0^t r(t-\eta) J(\eta) d \eta,$$ which represents the daily sum of completely recovered individuals (with proportion $(1-b)$) and comorbid individuals (with proportion $b$). We obtain complete model (\ref{m3})-(\ref{m6}) with distributed infection, recovery and death rates, and population immunity. The corresponding flowchart is shown in Figure~\ref{fig_diag_1}.

