\section{Analysis of the Approximation Error}\label{sec:analysis}
In this section, we study the difference between the cost function approximation $\tilde J$ of Eq.~\eqref{eq:j_tilde} relative to the optimal cost function $J^*$. We first consider the values $\Tilde{J}(b)$ for beliefs in $\tilde B$; cf.~Eq.~\eqref{eq:btilde}. Based on the analysis of these values, we quantify the differences between $\tilde J$ and the optimal cost $J^*$. Moreover, when the set $\tilde B$, the mapping $\Phi$ [cf.~Eq.~\eqref{eq:phi}], and the belief aggregation probabilities $\psi$ [cf.~Eq.~\eqref{eq:blf_agg}] satisfy certain conditions, we show that $\tilde J$ is a lower bound of $J^*$ within a certain error.

\subsection{Cost Function Approximation for Beliefs in $\tilde B$}
Starting from some representative feature belief $\Tilde{q}$, our method generates deterministically a belief $b\in \tilde B$ according to $b=D(\tilde q)$, where the mapping $D:\tilde Q\mapsto B$ is defined in Eq.~\eqref{eq:D_map}, and $\tilde B$ is the image of the mapping $D$, i.e.,
$$\tilde B=\big\{b\in B\,|\,b=D(\tilde q)\hbox{ for some }\tilde q\in \tilde Q\big\},$$
cf. Eq.~\eqref{eq:btilde}. To represent the belief space $B$ sufficiently well by the representative feature belief space $\tilde Q$, it is desirable for different representative feature beliefs $\tilde q$ and $\tilde q'$ to map to different belief states $\tilde b$ and $\tilde b'$. In other words, the mapping $D$, when viewed as a mapping from $\tilde Q$ to $\tilde B$, should be one-to-one. Indeed this is the case, thanks to the assumption that the nonempty sets $I_x$ are disjoint, as we show next.

\begin{proposition}\label{prop:unique_beliefs}
Let $\tilde q$ and $\tilde q'$ be two representative feature beliefs that are different, i.e., $\tilde q,\tilde q'\in \tilde Q$ and $\tilde q\neq \tilde q'$. Then the belief states $b=D(\tilde q)$ and $b'=D(\tilde q')$ are also different.
\end{proposition}

\begin{proof}
    For every $x\in \mathcal{F}$, let us select some $i_x\in \{1,2,\dots,n\}$ such that $i_x\in I_x$ and $d_{xi_x}>0$. Since the nonempty sets $I_x$ are disjoint, we have that for every $i_x$,
    \begin{equation}
        \label{eq:ix_disjoint}
        i_x\not\in I_{x'},\qquad \hbox{for all }x'\neq x
    \end{equation}
    Recall that for every feature state $x$, its disaggregation probabilities satisfy $d_{xi}>0$ only if $i\in I_x$; cf. Eq.~\eqref{eq:disagg}. Therefore, Eq.~\eqref{eq:ix_disjoint} implies that for every $i_x$,
    \begin{equation}
        \label{eq:disagg_ix}
        d_{x'i_x}=0,\qquad \hbox{for all }x'\neq x.
    \end{equation}
    Since $\tilde q\neq\tilde q'$, there exists some $\tilde x\in \mathcal{F}$ such that $\tilde q(\tilde x)\neq \tilde q'(\tilde x)$.
    We will show that $b(i_{\tilde x})\neq b'(i_{\tilde x})$, which implies that $b\neq b'$. 

    Indeed, by definition, we have
$$b(i)=\sum_{x\in\mathcal{F}}\tilde q(x)d_{xi},\quad b'(i)=\sum_{x\in\mathcal{F}}\tilde q'(x)d_{xi},\qquad i=1,2,\dots,n.$$
Let us focus on the component $b(i_{\tilde x})$ corresponding to $i_{\tilde x}\in I_{\tilde x}$. It is given by
    $$b(i_{\tilde x})=\sum_{x\in\mathcal{F}}\tilde q(x)d_{xi_{\tilde x}}=\tilde q(\tilde x)d_{\tilde xi_{\tilde x}},$$
    where the last equality follows from Eq.~\eqref{eq:disagg_ix}. Similarly, $b'(i_{\tilde x})=\tilde q'(\tilde x)d_{\tilde xi_{\tilde x}}$. Since $\tilde q(\tilde x)\neq \tilde q'(\tilde x)$, we obtain $b(i_{\tilde x})\neq b'(i_{\tilde x})$.
\end{proof}

Note that without the sets $I_x$ being disjoint, different $\tilde q$ and $\tilde q'$ may be mapped to the same $b$ via the mapping $D$. Let us provide such an example. 

\begin{example}[Pathology without $I_x$ being disjoint]
Suppose that representative feature beliefs $\tilde q$ and $\tilde q'$ satisfy
\begin{equation}
    \label{eq:ix_disjoint_p1}
    \tilde q(\tilde x)\neq\tilde q'(\tilde x),\quad \tilde q(x')\neq\tilde q'(x'),\qquad  \hbox{for some }\tilde x,\,x',
\end{equation}
and 
\begin{equation}
    \label{eq:ix_disjoint_p2}
    \tilde q(x)=\tilde q'(x), \qquad \hbox{for all }x\neq \tilde x\hbox{ and }x\neq x'.
\end{equation}
Suppose further that the sets $I_{\tilde x}$ and $I_{x'}$ and some state $\tilde i$ satisfy 
\begin{equation}
    \label{eq:tilde_i}
    \{\tilde i\}= I_{\tilde x}= I_{x'},\qquad \tilde i\not\in I_{x},\quad \hbox{for all }x\neq \tilde x\hbox{ and }x''\neq x'.
\end{equation}
We claim that $D(\tilde q)=D(\tilde q')$. Indeed, from Eq.~\eqref{eq:ix_disjoint_p2}, we have
\begin{equation}
    \label{eq:tilde_q_tilde_q_p}
    \tilde q(\tilde x)+\tilde q(x')=\tilde q'(\tilde x)+\tilde q'(x').
\end{equation}
Moreover, Eq.~\eqref{eq:tilde_i} implies that 
\begin{equation}
    \label{eq:d_xi_d_x_p_i}
    d_{\tilde x\tilde i}=d_{x'\tilde i}=1,\qquad d_{x\tilde i}=0,\quad \hbox{for all }x\neq \tilde x\hbox{ and }x'.
\end{equation} 
Consider the component of $D(\tilde q)$ that corresponds to the state $\tilde i$. It is given by
\begin{align*}
    \sum_{x\in\mathcal{F}}\tilde q(x)d_{x\tilde i}=&\tilde q(\tilde x)d_{\tilde x\tilde i}+\tilde q(x')d_{x'\tilde i}=\tilde q(\tilde x)+\tilde q(x')\\
    =&\tilde q'(\tilde x)+\tilde q'(x')=\tilde q'(\tilde x)d_{\tilde x\tilde i}+\tilde q'(x')d_{x'\tilde i}\\
    =&\sum_{x\in\mathcal{F}}\tilde q'(x)d_{x\tilde i},
\end{align*}
where the first and the second equalities follow from Eq.~\eqref{eq:d_xi_d_x_p_i}, the third equality is Eq.~\eqref{eq:tilde_q_tilde_q_p}, and the fourth and fifth equalities follow from Eq.~\eqref{eq:d_xi_d_x_p_i}. The last term $\sum_{x\in\mathcal{F}}\tilde q'(x)d_{x\tilde i}$ is the component of $D(\tilde q')$ that corresponds to the state $\tilde i$.

As for every other component of $D(\tilde q)$ that corresponds to some state $i\neq \tilde i$, we have
\begin{align*}
    \sum_{x\in\mathcal{F}}\tilde q(x)d_{xi}=&\sum_{x\in\mathcal{F},x\neq \tilde x,x\neq x'}\tilde q(x)d_{xi}\\
    =&\sum_{x\in\mathcal{F},x\neq \tilde x,x\neq x'}\tilde q'(x)d_{xi}=\sum_{x\in\mathcal{F}}\tilde q'(x)d_{xi},
\end{align*}
where the first and the last equality follow from the condition $\{\tilde i\}= I_{\tilde x}= I_{x'}$ and Eq.~\eqref{eq:ix_disjoint_p2}.
Clearly, the last term is the component of $D(\tilde q')$ that corresponds to $i$. Therefore, we have $D(\tilde q)=D(\tilde q')$.
\end{example}

The preceding proposition states that through the disaggregation process, each representative feature belief $\tilde q$ maps to a unique belief state $b$ that belongs to the set $ \tilde B$. In other words, the mapping $D$, when viewed as a mapping from $\tilde Q$ to $\tilde B$, is one-to-one. As our next result, we show that the aggregation process defines the inverse of such a mapping.   

\begin{proposition}\label{prop:consistency}
Let $b$ be a belief state belonging to the set $\tilde B$ and $\tilde q$ be a representative belief. Then $b=D(\tilde q)$ if and only if  $\tilde q=\Phi(b)$, i.e.,
$$b(i)=\sum_{x\in\mathcal{F}}\tilde q(x)d_{xi},\qquad i=1,2,\dots,n,$$
if and only if
$$\tilde q(y)=\sum_{j=1}^nb(j)\phi_{jy},\qquad \hbox{for all }y\in\mathcal{F}.$$
\end{proposition}

\begin{proof}
   We first prove the only if part. Let us denote by $q$ the vector $\Phi(b)$. In what follows, we will show that $q=\tilde q$. By applying the relation $b=D(\tilde q)$, we have for every $y\in \mathcal{F}$,
    \begin{equation}
    \label{eq:one_to_one_blf}
        \begin{aligned}
        q(y)=&\sum_{j=1}^nb(j)\phi_{jy}=\sum_{j=1}^n\sum_{x\in\mathcal{F}}\tilde q(x)d_{xj}\phi_{jy}\\
        =&\sum_{x\in\mathcal{F}}\tilde q(x)\sum_{j=1}^nd_{xj}\phi_{jy}=\sum_{x\in\mathcal{F}}\tilde q(x)\sum_{j\in I_x}d_{xj}\phi_{jy},
        \end{aligned}
    \end{equation}
    where the last equality holds because $d_{xj}=0$ for all $j\not\in I_x$; cf.~Eq.~\eqref{eq:disagg}.

    Let us now focus on the sum $\sum_{j\in I_x}d_{xj}\phi_{jy}$. We claim that
    \begin{equation}
    \label{eq:agg_disagg}
        \sum_{j\in I_x}d_{xj}\phi_{jy}=\begin{cases}1\quad &\hbox{if }x=y,\\
        0&\hbox{otherwise}.\end{cases}
    \end{equation}
    Suppose $x=y$. We have $\phi_{jy}=1$ for all $j\in I_x=I_y$ according to Eq.~\eqref{eq:agg}. Since $\sum_{j\in I_x}d_{xj}=\sum_{j=1}^nd_{xj}=1$, we obtain the desired equality. Suppose $x\neq y$. Using the fact that $I_x$ and $I_y$ are disjoint and that $\phi_{jx}=1$ for $j\in I_x$, we have $\phi_{jy}=0$ for $j\in I_x$. Therefore, $\sum_{j\in I_x}d_{xj}\phi_{jy}=0$. Combining Eq.~\eqref{eq:one_to_one_blf} with Eq.~\eqref{eq:agg_disagg} leads to the equality $q(y)=\Tilde{q}(y)$. Since $y$ is arbitrary, we obtain $q=\tilde q$.

    Next, we show the if part. Suppose $\tilde q=\Phi(b)$. Since $b\in \tilde B$, there exists some $\tilde q'$ such that $b=D(\tilde q')$. By the only if of the statement, the equality $b=D(\tilde q')$ implies $\tilde q'=\Phi(b)$. However, $\tilde q=\Phi(b)$ by assumption. Therefore, $\tilde q'=\tilde q$, or equivalently, $\tilde q=\Phi(b)$.
\end{proof}

Having investigated the properties of the mappings $D$ and $\Phi$, we are ready to characterize the cost function approximation $\tilde J$ for beliefs in $\tilde B$.

\begin{proposition}\label{prop:j_tilde_b_tilde}
    Let $b$ be a belief state belonging to the set $\tilde B$ such that $b=D(\tilde q)$ for some $\tilde q\in \tilde Q$. We have
    \begin{equation}
        \label{eq:blf_agg_phi_b}
        \psi_{\Phi(b)\tilde p}=1,\qquad \psi_{\Phi(b)\tilde p'}=0, \quad \hbox{for all }\tilde p'\neq \tilde p.
    \end{equation}
    Moreover, 
    $$\tilde J(b)=r^*_{\tilde q}.$$
\end{proposition}
\begin{proof}
    By Prop.~\ref{prop:consistency}, $b=D(\tilde q)$ implies $\tilde q=\Phi(b)$. In view of the definitions of belief aggregation probability $\psi$ [cf. Eq.~\eqref{eq:blf_agg}], we obtain Eq.~\eqref{eq:blf_agg_phi_b}. Moreover, 
    $$\tilde J(b)=\sum_{\tilde q'\in\tilde Q}\psi_{\Phi(b) \tilde q'}r^*_{\tilde q'}=\sum_{\tilde q'\in\tilde Q}\psi_{\tilde q \tilde q'}r^*_{\tilde q'}=r^*_{\tilde q},$$
    where the last equality follows from Eq.~\eqref{eq:blf_agg_phi_b}.
\end{proof}

In summary, for every $b$ such that $b=D(\tilde q)$ for some $\tilde q$, its corresponding cost function approximation value $\tilde J(b)$ depends solely on the component of $r^*$ that corresponds to the representative feature belief $\tilde q$.  

\subsection{Error Bound of The Cost Function Approximation $\tilde J$}
We will now quantify the difference between the cost function approximation $\tilde J$ and the optimal cost function $J^*$; cf.~Eqs.~\eqref{eq:j_tilde} and~\eqref{eq:optimal_cost}. To this end, we define a \textit{footprint set} of each representative feature belief $\tilde q \in \tilde{Q}$ as
\begin{equation}
    \label{eq:s_def}
    S_{\tilde q}=\{b\in B\,|\,\psi_{\Phi(b)\tilde q}>0\}.
\end{equation}
In other words, for every belief state $b\in S_{\tilde q}$, the cost function approximation $\tilde J(b)$ depends on $r^*_{\tilde q}$ with weight $\psi_{\Phi(b)\tilde q}$; cf.~Eq.~\eqref{eq:blf_agg}. Similarly, for every belief state $b\in B$, we associate a \textit{representative set} $R_b$ defined as
\begin{equation}
    \label{eq:r_def}
    R_b=\{\tilde q\in \tilde Q\,|\,\psi_{\Phi(b)\tilde q}>0\}.
\end{equation}
In view of Props.~\ref{prop:consistency} and \ref{prop:j_tilde_b_tilde}, we have
\begin{equation}
    \label{eq:s_r_b_tilde}
    D(\tilde q)\in S_{\tilde q},\qquad \hbox{for all }\tilde q\in \tilde Q.
\end{equation}

We now characterize the approximation error of $\tilde J$. Our analysis relies critically on the condition \eqref{eq:s_r_b_tilde}.
\begin{proposition}\label{prop:error_bound}
    The cost function approximation $\tilde J$ defined in Eq.~\eqref{eq:j_tilde} and the optimal cost function $J^*$ satisfy
\begin{align}\label{eq:error_bound_form}
|\tilde J(b)-J^*(b)|\leq \frac{\epsilon}{1-\alpha},\qquad \hbox{for all }b\in B,
\end{align}  
    where $\epsilon$ is the scalar defined by
    \begin{equation}
        \label{eq:ep_def}
        \epsilon=\max_{\tilde q \in \Tilde{Q}}\sup_{b,b'\in S_{\tilde q}}|J^*(b)-J^*(b')|.
    \end{equation}
\end{proposition}

\begin{proof}
First, we show that $\epsilon$ is finite. Since the number of states and controls is finite and the cost function $g$ is bounded, it follows that the function $\hat g$ in Eq.~\eqref{eq:g_hat_p_hat} is bounded. Thus, from the theory of discounted cost DP problems, it follows that $J^*$ is bounded; see \cite[Section~1.2]{bertsekas2012dynamic}. As a result, for every $\tilde q$, $\sup_{b,b'\in S_{\tilde q}}|J^*(b)-J^*(b')|$ is finite, and the finiteness of $\epsilon$ follows from the finiteness of the set $\tilde Q$.

    Next, we consider the operator $H$ defined by Eq.~\eqref{eq:h_oprator} and the $m$-dimensional vector $\overline{r}$ with components defined by
    \begin{equation}
        \label{eq:r_bar_def}
        \overline{r}_{\tilde q}=\inf_{b\in S_{\tilde q}}J^*(b)+\frac{\epsilon}{1-\alpha},\qquad \tilde q\in \tilde Q.
    \end{equation}
    These components are finite, and therefore, we have $\overline{r}\in \Re^m$. In view of the definitions of $S_{\tilde q}$, $R_b$, and $\overline{r}_{\tilde q}$ given in Eqs.~\eqref{eq:s_def}, \eqref{eq:r_def}, and \eqref{eq:r_bar_def} we have
    \begin{equation}
        \label{eq:r_bar_j_star}
        \overline{r}_{\tilde q}\leq J^*(b)+\frac{\epsilon}{1-\alpha},\qquad \hbox{for all }\tilde q\in R_b, \,b\in B.
    \end{equation}

    For every $\tilde q\in \tilde Q$, we have
\begin{align*}
    &(H\overline{r})(\tilde q)\\
    =&\min_{u\in U}\bigg[\hat{g}\big(D(\tilde q),u\big)+\alpha\sum_{z\in Z}\hat{p}\big(z\,|\,D(\tilde q),u\big)\sum_{\tilde q'\in \tilde Q}\psi_{G(\tilde q,u,z)\tilde q'}\overline{r}_{\tilde q'}\bigg]\\
    =&\min_{u\in U}\Bigg[\hat{g}\big(D(\tilde q),u\big)+\alpha\sum_{z\in Z}\hat{p}\big(z\,|\,D(\tilde q),u\big)\sum_{\tilde q'\in \tilde Q}\psi_{\Phi\big(F(D(\tilde q),u,z)\big)\tilde q'}\overline{r}_{\tilde q'}\Bigg]\\
    =&\min_{u\in U}\Bigg[\hat{g}\big(D(\tilde q),u\big)+\alpha\sum_{z\in Z}\hat{p}\big(z\,|\,D(\tilde q),u\big)\sum_{\tilde q'\in R_{F(D(\tilde q),u,z)}}\psi_{\Phi\big(F(D(\tilde q),u,z)\big)\tilde q'}\overline{r}_{\tilde q'}\Bigg]\\
    \leq&\min_{u\in U}\bigg[\hat{g}\big(D(\tilde q),u\big)+\alpha\sum_{z\in Z}\hat{p}\big(z\,|\,D(\tilde q),u\big)J^*\Big(F\big(D(\tilde q),u,z\big)\Big)\bigg]+\frac{\alpha \epsilon}{1-\alpha}\\
    =&J^*\big(D(\tilde q)\big)+\frac{\alpha \epsilon}{1-\alpha}\\
    \leq &\inf_{b\in S_{\tilde q}}J^*(b)+\epsilon +\frac{\alpha \epsilon}{1-\alpha}\\
    =&\overline{r}_{\tilde q},
\end{align*}
where the second equality is due to the definition of $G$; cf.~Eq.~\eqref{eq:g_def}. The third equality is due to the definition of $R_{F\big(D(\tilde q),u,z\big)}$; cf.~Eq.~\eqref{eq:r_def}. The first inequality follows from Eq.~\eqref{eq:r_bar_j_star} with $F\big(D(\tilde q),u,z\big)$ in place of $b$ and the fact that $\sum_{z\in Z}\hat{p}\big(z\,|\,D(\tilde q),u\big)=1$. The fourth equality holds because $J^*$ satisfies Bellman's equation of the original problem; cf.~Eq.~\eqref{eq:optimal_cost}. The last inequality follows from the definition of $\epsilon$ and the fact that $D(\tilde q)\in S_{\tilde q}$, as stated in Eq.~\eqref{eq:s_r_b_tilde}; cf.~Eq.~\eqref{eq:ep_def}. From this inequality, we obtain $H\overline{r}\leq \overline{r}$. 

Due to the monotonicity of $H$ [cf.~Prop.~\ref{prop:h_op}], we have that the sequence $\{r^k\}$ with $r^0=\overline{r}$ and $r^{k+1}=Hr^k$ is monotonically decreasing. Moreover, from the contractivity of $H$ [cf.~Prop.~\ref{prop:h_op}], we have $\lim_{k\to\infty}r^k=r^*$. Combining these properties with Eq.~\eqref{eq:r_bar_j_star}, we obtain
$$r^*_{\tilde q}\leq \overline{r}_{\tilde q}\leq J^*(b)+\frac{\epsilon}{1-\alpha},\qquad \hbox{for all }\tilde q\in R_b, \,b\in B.$$
As a result, we have
$$\tilde J(b)=\sum_{\tilde q\in\tilde Q}\psi_{\Phi(b) \tilde q}r^*_{\tilde q}=\sum_{\tilde q\in R_b}\psi_{\Phi(b) \tilde q}r^*_{\tilde q}\leq J^*(b)+\frac{\epsilon}{1-\alpha}.$$

The converse inequality can be shown by considering the $m$-dimensional vector $\underline{r}$ with components
$$\underline{r}_{\tilde q}=\sup_{b\in S_{\tilde q}}J^*(b)-\frac{\epsilon}{1-\alpha},\qquad \tilde q\in \tilde Q.$$
The proof is thus complete.
\end{proof}
The scalar $\epsilon$ of Eq.~\eqref{eq:ep_def} is the maximum variation of the optimal cost function $J^{*}$ within the footprint sets $\{S_{\tilde{q}} \mid \tilde{q} \in \tilde{Q}\}$; see Fig.~\ref{fig:epsilon}. Thus, the meaning of the preceding proposition is that if $J^{*}$ varies by at most $\epsilon$ within each footprint set, then the interpolation formula in Eq.~\eqref{eq:j_tilde} yields a cost function approximation that is within $\frac{\epsilon}{1-\alpha}$ of the optimal.
