\subsection{The Cost Function Approximation as a Lower Bound}
In the preceding section, we quantified the difference between the cost function approximation $\tilde J$ [cf.~Eq.~\eqref{eq:j_tilde}] and the optimal cost function $J^*$. Within the context of POMDP, it is well-known (cf. \cite{aggregation_yu_dp} and \cite[Example 6.5.5]{bertsekas2012dynamic}) that a cost function approximation constructed with a suitably defined aggregation scheme can serve as a lower bound of the optimal cost function $J^*$. In what follows, we delineate conditions under which the cost function approximation $\tilde J$ computed via our approach can serve as a lower bound of $J^*$.

In particular, we require that the disaggregation, aggregation, and belief aggregation probabilities satisfy
\begin{equation}
\label{eq:con_hull_2}
    b=\sum_{b'\in \tilde B}\psi_{\Phi(b)\Phi(b')}b',\qquad \hbox{for all }b\in B.
\end{equation}
In other words, the convex hull of $\tilde B$ [cf.~Eq.~\eqref{eq:btilde}] equals $B$, and the convex combination coefficient associated with $b\in B$ and $b'\in \tilde B$ is the belief aggregation probability $\psi_{\Phi(b)\Phi(b')}$. Under this condition, we have the following result.

\begin{proposition}\label{prop:lower_bound}
    Let the disaggregation, aggregation, and belief aggregation probabilities satisfy Eq.~\eqref{eq:con_hull_2}. The cost function approximation $\tilde J$ defined in Eq.~\eqref{eq:j_tilde} and the optimal cost function $J^*$ satisfy
    \begin{equation}
        \label{eq:j_tilde_l_b}
        0\leq J^*(b)-\tilde J(b)\leq \frac{\epsilon}{1-\alpha},\qquad \hbox{for all }b\in B,
    \end{equation}
    where $\epsilon$ is given by Eq.~\eqref{eq:ep_def}. In addition, if $\tilde Q$ contains $n$ representative feature beliefs, $\tilde J$ is linear.
\end{proposition}
\begin{proof}
In what follows, we prove that $\tilde J(b)\leq J^*(b)$ for all $b\in B$. The other side of Eq.~\eqref{eq:j_tilde_l_b} follows directly from Prop.~\ref{prop:error_bound}. From Prop.~\ref{prop:consistency}, we have that for every $b\in \tilde B$, $b=D(\tilde q)$ if and only if $\tilde q=\Phi(b)$. As a result, the relation given in Eq.~\eqref{eq:con_hull_2} can be stated equivalently as
    \begin{equation}
\label{eq:con_hull_1}
    b=\sum_{\tilde q\in \tilde Q}\psi_{\Phi(b)\tilde q}D(\tilde q),\qquad \hbox{for all }b\in B.
\end{equation}
    It is well-known that the optimal cost function $J^*$ is concave in $b$; see, e.g., \cite[Thm.~2]{smallwood_1}, \cite[Thms.~7.6.1-7.6.2]{krishnamurthy_2016}, or \cite[Section~6.5.1]{bertsekas2012dynamic}. The concavity of $J^*$ and Eq.~\eqref{eq:con_hull_1} imply that
    \begin{equation}
        \label{eq:j_star_concave}
        J^*(b)=J^*\Bigg(\sum_{\tilde q\in \tilde Q}\psi_{\Phi(b)\tilde q}D(\tilde q)\Bigg)\geq \sum_{\tilde q\in \tilde Q}\psi_{\Phi(b)\tilde q}J^*\big(D(\tilde q)\big),\qquad \hbox{for all }b\in B.
    \end{equation}
    Since $J^*$ also satisfies Bellman's equation of the POMDP [cf.~Eq.~\eqref{eq:optimal_cost}], we obtain
    \begin{equation}
    \label{eq:ineq_1}
        \begin{aligned}
        J^*(b)=&\min_{u\in U}\bigg[\hat{g}(b,u)+\alpha\sum_{z\in Z}\hat{p}(z\,|\,b,u)J^*\big(F(b,u,z)\big)\bigg]\\
        = &\min_{u\in U}\Bigg[\hat{g}(b,u)+\alpha\sum_{z\in Z}\hat{p}(z\,|\,b,u)J^*\bigg(\sum_{\tilde q\in \tilde Q}\psi_{\Phi\big(F(b,u,z)\big)\tilde q}D(\tilde q)\bigg)\Bigg]\\
        \geq & \min_{u\in U}\Bigg[\hat{g}(b,u)+\alpha\sum_{z\in Z}\hat{p}(z\,|\,b,u)\sum_{\tilde q\in \tilde Q}\psi_{\Phi\big(F(b,u,z)\big)\tilde q}J^*\big(D(\tilde q)\big)\Bigg],
    \end{aligned}
    \end{equation}
    where the second equality follows from Eq.~\eqref{eq:con_hull_1} with $F(b,u,z)$ in place of $b$, and the inequality follows from Eq.~\eqref{eq:j_star_concave} with $F(b,u,z)$ in place of $b$. In particular, for every $b\in \tilde B$ so that $b=D(\tilde q)$ for some $\tilde q\in \tilde Q$, Eq.~\eqref{eq:ineq_1} becomes
    \begin{equation}
    \label{eq:ineq_2}
        J^*\big(D(\tilde q)\big)\geq \min_{u\in U}\bigg[\hat{g}\big(D(\tilde q),u\big)+\alpha\sum_{z\in Z}\hat{p}\big(z\,|\,D(\tilde q),u\big)\sum_{\tilde q'\in \tilde Q}\psi_{G(\tilde q,u,z)\tilde q'}J^*\big(D(\tilde q')\big)\bigg].
    \end{equation}
    From the definition of $\tilde B$, we have that Eq.~\eqref{eq:ineq_2} holds for all $\tilde q\in \tilde Q$.

    Let us consider a vector $\hat{r}\in \Re^m$ with components defined by
    $$\hat{r}_{\tilde q}=J^*\big(D(\tilde q)\big),\qquad \tilde q\in \tilde Q.$$
    By definition of $H$ [cf.~Eq.~\eqref{eq:h_oprator}], Eq.~\eqref{eq:ineq_2} can be written equivalently as
    \begin{equation}
        \label{eq:h_hat_monotone}
        H\hat{r}\geq \hat{r}.
    \end{equation}
    Using arguments similar to those in the proof for Prop.~\ref{prop:error_bound}, Eq.~\eqref{eq:h_hat_monotone} implies that $\hat{r}\geq r^*$, where $r^*$ is the fixed point of $H$. Then for every $b\in B$, we have
$$\tilde J(b)=\sum_{\tilde q\in\tilde Q}\psi_{\Phi(b) \tilde q}r^*_{\tilde q}\leq \sum_{\tilde q\in\tilde Q}\psi_{\Phi(b) \tilde q}\hat{r}_{\tilde q}=\sum_{\tilde q\in \tilde Q}\psi_{\Phi(b)\tilde q}J^*\big(D(\tilde q)\big).$$
Combining this inequality with Eq.~\eqref{eq:j_star_concave} yields the desired inequality.

Suppose that $\tilde Q$ contains $n$ representative feature beliefs. Since the set $\tilde B$ spans $B$ [cf.~Eq.~\eqref{eq:con_hull_2}], and $B$ is the belief space over $n$ states, we have that $\tilde B$ is linearly independent; cf.~Eq.~\eqref{eq:btilde}. Consider three belief states $b_1$, $b_2$, and $b_3$, where $b_3=\gamma b_1+(1-\gamma)b_2$ and $\gamma\in [0,1]$. Due to the linear independence of $\tilde B$, the aggregation probability $\psi_{\Phi(b_3)\Phi(b')}$ of $b_3$ satisfies
    $$\psi_{\Phi(b_3)\Phi(b')}=\gamma \psi_{\Phi(b_1)\Phi(b')}+(1-\gamma)\psi_{\Phi(b_2)\Phi(b')},\qquad b'\in \tilde B.$$
    Therefore, we have $\tilde J(b_3)=\gamma \tilde J(b_1)+(1-\gamma)\tilde J(b_2)$.
\end{proof}

\begin{example}\label{ex:running_lower_bound}
Let us illustrate Prop.~\ref{prop:lower_bound} through the treasure hunting problem in Example~\ref{ex:treasure} with a single search site. We construct the representative feature belief space using the method described in Example~\ref{ex:numerical_ex_1}, employing varying discretization resolutions. The belief aggregation probabilities $\psi_{q\tilde q}$ are computed to satisfy the condition given in Eq.~\eqref{eq:con_hull_2}. Additional computational details are provided in Appendix~\ref{appendix:setup}.

We show in Fig.~\ref{fig:treasure_2} a comparison between the cost function approximation $\Tilde{J}$ and the optimal cost function $J^{*}$ [cf.~Eq.~\eqref{eq:optimal_cost}] for varying discretization resolutions $\rho$ [cf.~Eq.~\eqref{eq:aggregate_belief_space}]. We note that the cost function approximations $\tilde{J}$ are lower bounds to the optimal cost, i.e., $\tilde{J} \leq J^{*}$, as asserted in Prop.~\ref{prop:lower_bound}. In contrast, the cost function approximations computed in Example~\ref{ex:numerical_ex_1} may not be lower bounds of $J^*$, as shown in Fig.~\ref{fig:treasure_1}. This is because the belief aggregation probabilities used in Example~\ref{ex:numerical_ex_1} do not satisfy the conditions in Eq.~\eqref{eq:con_hull_1}. Moreover, when $\rho=1$, the function $\tilde J$ computed here becomes a linear function of $b$. 

