\begin{algorithm}[t]
    \caption{Union-Find Data Structure with Path Compression and Union by Rank}
    \label{alg:unionfind}
    \begin{algorithmic}[1]

        \State Initialize $\texttt{parent}[i] = i$ for all $i$
        \State Initialize $\texttt{rank}[i] = 0$ for all $i$

        \Function{find}{$x$}
            \While{$\texttt{parent}[x] \neq x$}
                \State $\texttt{parent}[x] \gets \texttt{parent}[\texttt{parent}[x]]$ \Comment{Path compression}
                \State $x \gets \texttt{parent}[x]$
            \EndWhile

            \Return $x$
        \EndFunction

        \Function{batch\_union}{$\texttt{x\_arr}, \texttt{y\_arr}$}
            \For{$(x, y) \in \texttt{zip}(\texttt{x\_arr}, \texttt{y\_arr})$}
                \State $x_{\text{root}} \gets \textbf{find}(x)$
                \State $y_{\text{root}} \gets \textbf{find}(y)$
                \If{$x_{\text{root}} = y_{\text{root}}$}
                    \State \textbf{continue}
                \EndIf
                \If{$\texttt{rank}[x_{\text{root}}] < \texttt{rank}[y_{\text{root}}]$}
                    \State $\texttt{parent}[x_{\text{root}}] \gets y_{\text{root}}$
                \Else
                    \State $\texttt{parent}[y_{\text{root}}] \gets x_{\text{root}}$
                    \If{$\texttt{rank}[x_{\text{root}}] = \texttt{rank}[y_{\text{root}}]$}
                        \State $\texttt{rank}[x_{\text{root}}] \gets \texttt{rank}[x_{\text{root}}] + 1$
                    \EndIf
                \EndIf
            \EndFor
        \EndFunction
    \end{algorithmic}
\end{algorithm}

\section{Algorithms Analysis}
\label{sec: algorithms}
% In this section, we
\subsection{Union-Find Data Structure}
% 并查集（Union-Find）是一种高效的数据结构，用于处理不相交集合的合并与查找问题。其核心操作包括：Find：查找某个元素所属的集合（根节点）。Union：将两个集合合并为一个集合。 在实践中，常使用路径压缩（Path Compression）和按秩合并（Union by Rank）进行优化。具体来说，路径压缩在 Find 操作时，将查询路径上的所有节点直接连接到根节点，从而减少后续查询的时间。按秩合并在 Union 操作时，总是将较小的树连接到较大的树上，避免树的高度增长过快。 我们将具体数据结构的定义展示在\algref{alg:unionfind}中。
The Union-Find is an efficient data structure designed to manage and merge disjoint sets. It supports two fundamental operations: the `Find' operation to determine the root of the set for a particular element and the `Union' operation to merge two disjoint sets into one.

% In practice, Union-Find is commonly optimized using path compression and union-by-rank. Specifically, path compression 在`Find'时将查询路径上的所有节点直接连接到根节点，从而减少后续查询的时间. Union by Rank则是 在 Union 操作时，总是将较小的树连接到较大的树上，避免树的高度增长过快。
In practice, the Union-Find data structure is typically optimized using path compression and union-by-rank. Specifically, path compression flattens the tree structure during the `Find' operation by directly linking all nodes along the query path to the root, thereby reducing the time complexity of subsequent queries. Union-by-rank, on the other hand, attaches the smaller tree to the root of the larger tree during the `Union' operation, preventing excessive growth in tree height. We provide the detailed the Union-Find structure in \agref{alg:unionfind}.
\label{sec: unionfind}


\subsection{Approximate Connected Components Algorithm}
\label{sec: approximate components}
% Equipped with the Union-Find data structure, we 进一步利用它来求解图的连通分量， detailed in \agref{alg:approximate_components}。 具体来说，给定一个有$\textbf{N}$个节点的图，我们的Approximate Connected Components算法首先每个顶点单独作为一个集合，初始化并查集。之后，从中抽取$\textbf{N}'$个样本，建立邻接list，并标记其中的每一条边。之后对每条边执行一次 Union 操作，完成连通分量的合并。最后，遍历所有顶点，调用 Find 操作确定每个顶点所属的集合，统计得到最终的连通分量。值得注意的是，对于采样后连通关系没有覆盖到的节点，我们将其视为一个单独的连通分量。最后，考虑到每一个节点代表的token之间存在relative positional relationships ，e sort the connected components based on the vertex ID with the highest degree within each cluster.
Equipped with the Union-Find data structure, we further leverage it to compute the connected components of a graph, as detailed in \agref{alg:approximate_components}. Specifically, given a graph with $\textbf{N}$ nodes, our approximate connected components algorithm begins by initializing the Union-Find structure with each node as an individual set. We then sample $\textbf{N}'$ nodes from the graph to construct an adjacency list and mark each corresponding edge. For each edge in this sampled graph, a Union operation is performed to iteratively merge connected components. After all edges have been processed, we traverse all nodes and invoke the Find operation to determine the root set to which each node belongs, thereby identifying the final connected components. It is important to note that nodes not covered by the sampled connections are treated as single connected component. Finally, considering the relative positional relationships between tokens represented by the nodes, we sort the connected components based on the node with the highest degree within each cluster.
\begin{algorithm}[t]
    \caption{Approximate Connected Components via Union-Find}
    \label{alg:approximate_components}
    \begin{algorithmic}[1]
        \Require Adjacency matrix $\texttt{adj\_matrix}$, error tolerance $\epsilon$
        \Ensure List of connected components

        \State $n \gets \texttt{adj\_matrix.shape[0]}$
        \State Initialize $\texttt{nodes\_flag}[i] = 1$ for all $i$
        \State $\texttt{uf} \gets UnionFind(n)$  \Comment{Create an Union-Find set with n nodes}

        \State $\texttt{sample\_size} \gets \min(n, \lceil \log(n) / \epsilon^2 \rceil)$
        \State $\texttt{sampled\_nodes} \gets \texttt{random.sample}(\{1, 2, ..., n\}, \texttt{sample\_size})$
        \State Set $\texttt{nodes\_flag}[i] = 0$ for all $i \in \texttt{sampled\_nodes}$

        \State $\texttt{neighbor\_dict} \gets [] $ \Comment{ Initialize adjacency list for $\texttt{sampled\_nodes}$}
        \For{$i \in \texttt{sampled\_nodes}$}         
            \State $\texttt{neighbors} \gets \{j \mid \texttt{adj\_matrix}[i][j] \neq 0\}$ 
            \State $\texttt{neighbor\_dict}[i] \gets \texttt{neighbors}$
            \State Set $\texttt{nodes\_flag}[j] = 0$ for all $j \in \texttt{neighbors}$
        \EndFor


        \State $\texttt{all\_x}, \texttt{all\_y} \gets [], []$
        \For{$i \in \texttt{sampled\_nodes}$}
            \For{$j \in \texttt{neighbor\_dict}[i]$}
                \State $\texttt{all\_x.append}(i)$
                \State $\texttt{all\_y.append}(j)$
            \EndFor
        \EndFor
        \State $\texttt{uf.batch\_union}(\texttt{all\_x}, \texttt{all\_y})$ \Comment{Merge subgraphs of all \texttt{sampled\_nodes} }

        \State $\texttt{sampled\_roots} \gets [\texttt{uf.find}(i) \text{ for } i \in \texttt{sampled\_nodes}]$ \Comment{Find root for \texttt{sampled\_nodes}}
        \State $\texttt{unique\_roots} \gets \texttt{Unique}(\texttt{sampled\_roots})$ \Comment{Find every unique connected component root}

        \State $\texttt{components} \gets []$
        \For{$\texttt{root} \in \texttt{unique\_roots}$}
            \State $\texttt{cluster} \gets \texttt{np.where}(\texttt{uf.parent} == \texttt{root})[0].\texttt{tolist}()$
            \State $\texttt{components.append}(\texttt{cluster})$

        \EndFor
        \State $\texttt{remain\_nodes} \gets \{i \mid \texttt{nodes\_flag}[i] = 1\}$ \Comment{In case there are any unconsidered nodes.}
        \State $\texttt{components.extend}(\texttt{remain\_nodes})$ \Comment{Treat unconsidered nodes as independent components}

        \State $\texttt{components.sort()}$ \Comment{Sort by the node ID with the highest degree in each cluster. }

    \end{algorithmic}
    % \vspace{-10pt}
\end{algorithm}


