	\section{Lump with one-kink}\label{lump1kink}
	Adding one exponential function \cite{nd2} to the positive quadratic expression \eqref{lump1}, one can determine the lump structure with the single kink wave. So, we consider the auxiliary functions $f(x,t)$ and $g(x,t)$ as follows  
	\begin{equation}\label{lump1kink1}
		f(x,t)=(c_0 x+t)^2 +(c_1 x+t)^2 +c_2+d_0 e^{c_4 x+t};~~ g(x,t)=(c_0 x+t)^2 +(c_1 x+t)^2 +c_3+d_0 e^{c_5 x+t}, 
	\end{equation}
	where $d_0$ and $c_i~(0 \leq i \leq 5)$ are the parameters to be determined. The following relations among the parameters are obtained by substituting the expressions \eqref{lump1kink1} into Eq. \eqref{quadratic}. \\
	\textbf{Set 1:} 
	\begin{equation*}
		\begin{cases}
			\begin{split}
				& c_1=-c_0, c_4=0; \\
				& c_0=\frac{1}{6} (-3 i \mp \sqrt{3}), c_1= \frac{1}{6} (-3i \pm \sqrt{3}), c_4=-i; \\ 
