\section{Relation to the discrete dispersive order of Eberl and Klar} \label{sec:disc-disp}

We begin with some definitions and results necessary to understand the discrete dispersive order of \cite{ek-2024}, which serves as a fundamental order for defining measures of dispersion for discrete distributions in an axiomatic way.

\begin{definition}
\label{def:PDdists}
Let $\Ddists$ denote the set of discrete distributions, and let $F \in \Ddists$ be a cdf with probability mass function $f$ and let $X \sim F$. The class $\PDdists \subseteq \Ddists$ is defined by
    \begin{align*}
        F \in \PDdists \Leftrightarrow& \ \supp(F) \text{ is order-isomorphic to a subset of } \Z \text{ with at least two }\\
        & \, \text{ elements} \\
        \Leftrightarrow & \ \exists \text{ a subset } A \subseteq \Z, |A| \geq 2, \text{and a bijection } \varphi: \supp(F) \to A\\
        & \ \text{such that } x \leq y \Leftrightarrow \varphi(x) \leq \varphi(y) \ \forall x, y \in \supp(F).
    \end{align*}
\end{definition}

\begin{proposition}
\label{thm:IS-char}
	Define $\indsetset = \{\Z, \N, -\N\} \cup \{ \{1, \ldots, n\}: n \in \Nz \}$ and
\begin{align*}
	\idnseqset_A =& \Big\{ (x_j, p_j)_{j \in A} \subseteq \R \times (0, 1]: x_i < x_j \text{ for } i < j, p_j > 0 \text{ for } j \in A, \sum_{j \in A} p_j = 1 \Big\}\\
        \intertext{for $A \in \indsetset \setminus \Z$ as well as}
	\idnseqset_{\Z} =& \Big\{ (x_j, p_j)_{j \in \Z} \subseteq \R \times (0, 1]: x_i < x_j \text{ for } i < j, p_j > 0 \text{ for } j \in \Z, \sum_{j \in \Z} p_j = 1,\\
	& \; \hphantom{\Big\{ (x_j, p_j)_{j \in \Z} \subseteq \R \times (0, 1]:} \inf\{j \in \Z: \sum_{i \leq j} p_i \geq \tfrac{1}{2}\} = 0 \Big\}.
\end{align*}
	For any $F \in \PDdists$, there exists a unique index set $A \in \indsetset$ that is order-isomorphic to $\supp(F)$, and there exists a unique sequence 
    $(x_j, p_j)_{j \in A} \in \idnseqset_A$ such that $\Pr(X = x_j) = p_j$ for all $j \in A$.
	This unique association is denoted by $F \cdfis \left( A, (x_j, p_j)_{j \in A} \right)$. $A$ is said to be the {\em indexing set} of $F$ and $(x_j, p_j)_{j \in A}$ is said to be the {\em identifying sequence} of $F$.
\end{proposition}

In the following, let $F \cdfis \left( A, (x_j, p_j)_{j \in A} \right)$ and $G \cdfis$ $\left( B, (y_j, q_j)_{j \in B} \right)$. Furthermore, we use the conventions $x_a = -\infty$ and $F(x_a) = 0$ for $a < \min A$ as well as $x_a = \infty$ and $F(x_a) = 1$ for $a > \max A$, provided that the minimum and the maximum exist, respectively. \cite{ek-2024} defined the following relations, where $\smi{A}=A \setminus \{\min A\}$. 

%\as{I am studying your definition. So I might ask a silly question... Why in b) you use $\underline{A}\times \underline{B}$ instead of $A\times B$ }
%\bk{I added the definition of $\smi{A}$. The reason is simply that $x_a-x_{a-1}$ or $F(x_a)-F(x_{a-1})$ are considered in the relations, so $a$ can't be the minimum of the support.}

\begin{definition} \label{def:compj}
    Let $F, G \in \PDdists$.
 \begin{enumerate}
     \item The relation $\stdCompj$ on the set $A \times B$ is defined by
	\begin{align*}
		  a \stdCompj b &\Leftrightarrow (F(x_{a-1}), F(x_a)) \cap (G(y_{b-1}), G(y_b)) \neq \emptyset.
	\end{align*}
	for $a \in A, b \in B$. The set $R(\stdCompj)$ of all $(a, b) \in A \times B$ with $a \stdCompj b$ is said to be the set of $(F, G)$-{\em dispersion-relevant} pairs of indices.
    \item The relation $\stdCompja$ on the set $\smi{A} \times \smi{B}$ is defined by
		\begin{equation*}
			a \stdCompja b \Leftrightarrow (a \stdCompj b) \land (a-1 \stdCompj b-1)
		\end{equation*}
		for $a \in \smi{A}, b \in \smi{B}$. The set $R(\stdCompja)$ of all $(a, b) \in \smi{A} \times \smi{B}$ with $a \stdCompja b$ is said to be the set of $(F, G)$-{\em $\land$-dispersion-relevant} pairs of indices.
 \end{enumerate}
\end{definition}

\cite{ek-2024} proposed the following discrete dispersive order. 

\begin{definition} \label{def:disco}
Let $F, G \in \PDdists$. $G$ is said to be {\em at least as $\land$-discretely dispersed} as $F$, denoted by $F \discoa G$, if the following two conditions are satisfied:
        \begin{enumerate}
            \item[(i)] $q_b \leq p_a \quad \forall (a, b) \in R(\stdCompj)$,
            \item[(ii)] $x_a - x_{a-1} \leq y_b - y_{b-1} \quad \forall (a, b) \in R(\stdCompja)$.
        \end{enumerate}
\end{definition}

Now, we can formulate the main result of this section. It shows that for distributions in $\PDdists$, the weak dispersive order is indeed weaker than the discrete dispersive order.

\begin{theorem} \label{th:disc-disp}
    Let $F, G \in \mathcal{D}_0$, where $\mathcal{D}_0$ is defined as in \citet[][Def. 3.1]{ek-2024}. Then, $F \discoa G$ implies $F \leq_{\text{wd}} G$.

    \begin{proof}
        In this proof, we utilize the notation from \citet{ek-2024}. In particular, let $F \cdfis \left( A, (x_j, p_j)_{j \in A} \right)$ and $G \cdfis \left( B, (y_j, q_j)_{j \in B} \right)$.

        In the following, we will prove that, for all $y^* \in \R$ and all $\varepsilon > 0$, there exists a $x^* \in \R$ such that $F(x^* + \varepsilon) - F(x^*) \geq G(y^* + \varepsilon) - G(y^*)$. This then directly implies $F \leq_{\text{wd}} G$.

        Let $y^* \in \R$ and $\varepsilon > 0$. Choose $b, \beta \in B \cup \{\min B - 1\}$ with $b \leq \beta$ such that $y_{b+1} = \sup\{y \in \R: G(y) = G(y^*)\}$ and $y_\beta = \inf\{y \in \R: G(y) = G(y^* + \varepsilon)\}$. Since the case $b = \beta$ is trivial, we assume $b < \beta$. Furthermore, choose $a \in A \cup \{\min A - 1\}$ such that $F(x_a) = \max\left( [0, G(y_b)] \cap F(\R) \right)$. Then, we have $F(x_a) \leq G(y_b) < F(x_{a+1})$.

        Let $k_{a+1} = b+1$ and note that $a+1 \stdCompja k_{a+1}$. Now, exactly one of the following two conditions is satisfied:
        \begin{enumerate}
            \item[(i)] $G(y_{b+1}) \leq F(x_{a+1})$,
            \item[(ii)] $G(y_{b+1}) > F(x_{a+1})$. 
        \end{enumerate}
        In case (i) under the condition $F(x_{a+1}) < 1$, we choose $k_{a+2} \in B \cap [k_{a+1}+1, \infty)$ such that $G(y_{k_{a+2}-1}) = \min \nn{a+2}{F}{G}$. This implies $G(y_{k_{a+2}-1}) \leq F(x_{a+1})$ and $a+2 \stdCompja k_{a+2}$. If $F(x_{a+2}) < 1$, we choose $k_{a+3} \in B$ such that $G(y_{k_{a+3}-1}) = \min \nn{a+3}{F}{G}$. According to \citet[][Lemma A.2 in the supplement]{ek-2024}, we have $k_{a+3} > k_{a+2}$. As long as $F(x_{a+i}) < 1, i = 2, 3, \ldots,$ we can keep on choosing $k_{a+i+1} \in B \cap [k_{a+i}+1, \infty)$ such that $G(y_{k_{a+i+1}-1}) = \min \nn{a+i+1}{F}{G}$.

        In case (ii), we choose $k_{a+2} = b+2$, which is equivalent to $G(y_{k_{a+2}-1}) = \max \nn{a+2}{F}{G}$. (Note that $G(y_{b+1}) < 1$, because assuming $G(y_{b+1}) = 1$ implies $F(x_{a+2}) = G(y_{b+1}) = 1$ and thus $p_{a+2} < q_{b+1}$ in spite of $a+2 \stdCompj b+1$, which contradicts $F \discoa G$.) This implies $G(y_{k_{a+2}-1}) > F(x_{a+1})$ and $a+2 \stdCompja k_{a+2}$ as well as
        \begin{align*}
            0 &< G(y_{k_{a+2}-1}) - F(x_{a+1})\\
            &= G(y_{b+1}) - F(x_{a+1})\\
            &= (G(y_b) - F(x_a)) + (q_{b+1} - p_{a+1})\\
            &\leq G(y_b) - F(x_a).
        \end{align*}
        Then, we make the same distinction as previously, just increasing the indices by one. Again, exactly one of the following conditions is true:
        \begin{enumerate}
            \item[(i')] $G(y_{b+2}) \leq F(x_{a+2})$,
            \item[(ii')] $G(y_{b+2}) > F(x_{a+2})$. 
        \end{enumerate}
        In case (i') under the condition $F(x_{a+2}) < 1$, we proceed as in case (i), just starting with one index higher, i.e. by choosing $k_{a+3} \in B \cap [k_{a+2}+1, \infty)$ such that $G(y_{k_{a+3}-1}) = \min \nn{a+3}{F}{G}$. In case (ii'), we proceed as in case (ii), just starting with one index higher, i.e. by choosing $k_{a+3} = b+3$.

        Overall, we iteratively obtain
        \begin{equation}
        \label{eqn:iterResult1}
            \forall j \in A \cap [a+1, \infty) \; \exists \, \text{pairwise distinct } k_j \in B \cap [b+1, \infty): j \stdCompja k_j. 
        \end{equation}
        In this iteration, we either remain in cases (ii), (ii'), (ii''), \ldots\ or we at some point get into cases (i), (i'), (i''), \ldots\ and remain there from that point on out. Let $\tilde{\beta} = \max\{k \in B \cap (-\infty, \beta]\,|\, \exists j \in A: k = k_j\}$ and define $\alpha \in A$ by $\tilde{\beta} = k_{\alpha}$. Then, (\ref{eqn:iterResult1}) can be made more specific in the following sense:
        \begin{equation*}
        \label{eqn:iterResult2}
            \forall j \in \{a+1, \ldots, \alpha\} \; \exists \, \text{pairwise distinct } k_j \in \{b+1, \ldots, \tilde{\beta}\}: j \stdCompja k_j. 
        \end{equation*}
        It follows that
        \begin{align*}
            x_{\alpha} - x_{a+1} &= \sum_{j=a+2}^{\alpha} x_j - x_{j-1}\\
            &\leq \sum_{j=a+2}^{\alpha} y_{k_j} - y_{k_j-1} \leq \sum_{k=b+2}^{\tilde{\beta}} y_k - y_{k-1}\\
            &= y_{\tilde{\beta}} - y_{b+1} \leq y_\beta - y_{b+1} < \varepsilon.
        \end{align*}
        Choose $\delta > 0$ small enough such that $x^* = x_{a+1} - \delta$ and $x^* + \varepsilon \geq x_\alpha$.

        If the pair of $\alpha$ and $k_\alpha = \tilde{\beta}$ is in case (i'\ldots'), then we have $G(y_{\tilde{\beta}-1}) \leq F(x_{\alpha-1}) < G(y_{\tilde{\beta}}) \leq G(y_\beta)$. If $F(x_\alpha) = 1$, then $G(y_\beta) \leq F(x_\alpha)$ obviously holds; if $F(x_\alpha) < 1$, then $G(y_{\beta-1}) < \min \nn{\alpha+1}{F}{G}$ and thus $G(y_\beta) = \min \nn{\alpha+1}{F}{G} \leq F(x_\alpha)$ holds because of the maximality of $\tilde{\beta}$. Overall, it follows that
        \begin{align*}
            F(x^* + \varepsilon) - F(x^*) &\geq F(x_\alpha) - F(x_a) \geq G(y_\beta) - G(y_b) = G(y^* + \varepsilon) - G(y^*),
        \end{align*}
        concluding the proof if the pair of $\alpha$ and $k_\alpha = \tilde{\beta}$ is in case (i'\ldots').

        If the pair of $\alpha$ and $k_\alpha = \tilde{\beta}$ is in case (ii'\ldots'), then we have $F(x_{\alpha-1}) < G(y_{\tilde{\beta}-1}) < F(x_\alpha)$ and $G(y_{\tilde{\beta}-1}) - F(x_{\alpha-1}) \leq G(y_b) - F(x_a)$. If $F(x_\alpha) = 1$, then $G(y_\beta) \leq F(x_\alpha)$ obviously holds. If $F(x_\alpha) < 1$, then either $\alpha+1$ and $k_{\alpha+1} > \beta$ are in case (i'\ldots'), which implies $G(y_\beta) \leq G(y_{k_{\alpha+1}-1}) \leq F(x_\alpha)$; or $\alpha+1$ and $k_{\alpha+1} = \beta+1$ are in case (ii'\ldots'), which implies $0 < G(y_{\beta}) - F(x_{\alpha}) \leq G(y_b) - F(x_a)$. Overall, it follows that
        \begin{align*}
            F(x^* + \varepsilon) - F(x^*) &\geq F(x_\alpha) - F(x_a)\\
            &= (G(y_\beta) - G(y_b)) + (G(y_b) - F(x_a)) - (G(y_\beta) - F(x_\alpha))\\
            &\geq G(y_\beta) - G(y_b) = G(y^* + \varepsilon) - G(y^*),
        \end{align*}
        concluding the proof if the pair of $\alpha$ and $k_\alpha = \tilde{\beta}$ is in case (ii'\ldots').
    \end{proof}
\end{theorem}


The next example shows that several common dispersion measures do not preserve the weak dispersive order.

\begin{example}
The interquartile range (IQR) does not preserve the order $\discoa$ \citep[Theorem 4.7]{ek-2024}. Since, by Theorem~\ref{th:disc-disp}, the order $\leq_{\text{wd}}$ is weaker than $\discoa$, it follows that the IQR also does not preserve $\leq_{\text{wd}}$.

Other common measures of dispersion do preserve $\discoa$ \citep{ek-2024}. However, the following three-point distributions illustrate that this is not generally true for $\leq_{\text{wd}}$. Consider two distributions:  
\[
p = \{p_0 = 0.6,\ p_1 = 0.2,\ p_2 = 0.2\}, \quad
q = \{q_0 = 0.3,\ q_1 = 0.5,\ q_2 = 0.2\}.
\]
It is straightforward to verify that $p \leq_{\text{wd}} q$.
On the other hand, the dispersion measures for these distributions yield:
\begin{itemize}
    \item Standard deviations: $\mathrm{SD}_p = 0.80$, $\mathrm{SD}_q = 0.65$;
    \item Mean absolute deviations from the mean: $\mathrm{MAD}_p = 0.72$, $\mathrm{MAD}_q = 0.54$;
    \item Gini mean differences: $\mathrm{GMD}_p = 0.80$, $\mathrm{GMD}_q = 0.74$.
\end{itemize}
All differences $\mathrm{SD}_p - \mathrm{SD}_q$, $\mathrm{MAD}_p - \mathrm{MAD}_q$, and $\mathrm{GMD}_p - \mathrm{GMD}_q$ are strictly positive. Based on these classical measures, the distribution $p$ would be considered to be more dispersed than $q$, despite $p \leq_{\text{wd}} q$.
% sd-difference: 0.15, mad-difference: 0.18, gmd-difference: 0.06
\end{example}

As the empirical illustrations in Section~\ref{sec6} show, such discrepancies are relatively rare but stem from deeper conceptual differences, which are discussed in further detail in the next section.


\section{New measures of variability based on the concentration function} \label{sec5}

The preceding example highlights an important conceptual distinction: the Lévy concentration function captures concentration rather than deviation from a central location. Traditional dispersion measures such as the standard deviation (SD) and the median absolute deviation (MAD) quantify variability with respect to a fixed location parameter, typically the mean or median. In contrast, the Gini mean difference (GMD) assesses variability by averaging the absolute differences between all pairs of independent copies of the random variable. Formally, for a random variable \( X \), the GMD is defined as:
\[
\mathrm{GMD}_X = \mathbb{E}_{X'}\left[ \mathbb{E}_{X|X'} \left[ |X - X'| \right] \right],
\]
where \( X' \) is an independent copy of \( X \).

In the example under discussion, although all three classical dispersion measures are larger for distribution \( p \) than for distribution \( q \), both distributions share the same support. Thus, the higher concentration of \( p \) indicates a lower level of uncertainty or randomness. From a practical perspective, if one had to predict a likely value, choosing for \( p \) would be more straightforward than for \( q \), suggesting that \( p \) is more "predictable." This interpretation is supported by the Shannon entropy values: \( H(p) = -\sum p_i \log_2(p_i) = 1.371 \), while \( H(q) = 1.485 \). The lower entropy for \( p \) reflects reduced uncertainty.

This relationship is underpinned by the fact that the vector $p$ majorizes $q$ (i.e. $q \preceq p$); that is, 
$\sum_{i=1}^k x_{[i]} \geq \sum_{i=1}^k y_{[i]}$ for all $k$, where $x_{[i]}$ denotes the $i$-th largest entry of $x$. 
Since entropy is Schur-concave - that is, $f(q) \geq f(p)$ if $q \preceq p$ - it decreases as the distribution becomes more concentrated. 
Hence, in this example, greater concentration corresponds to lower entropy, providing a compelling case where classical dispersion measures may fail to capture the perceived variability in discrete distributions. This underscores the relevance of concentration-based and entropy-based approaches, particularly when comparing distributions with identical support.

However, concentration can be viewed both as a lower bound for several classical measures of variability - those that quantify deviation from a central point - and as a dispersion measure in its own right. Using the formula  
\[ \mathbb{E}[Z^r] = \int_0^\infty rt^{r-1} \Pr(Z > t)\,dt \]  
for a non-negative random variable $Z$ and $r \geq 1$, we obtain
$$
E[|X-a|^r] \geq r\int_{0}^{\infty}t^{r-1}(1-Q_X(2t))dt \quad \forall a \in \mathbb{R}, \, \forall r\geq 1.
$$
Therefore, 
$$
E[|X-a_r|^r] \geq \frac{r}{2^r} \int_{0}^{\infty} \varepsilon^{r-1} (1-Q_X(\varepsilon)) \, d\varepsilon \quad  \forall r \geq 1,
$$
where $a_r = \arg \min\limits_{a} E[|X-a|^r]$, $r\geq 1$. In fact, any functional $\nu_r(X)$ defined as 
$$
\nu_r(X) = \frac{\sqrt[r]{r}}{2} \left ( \int_{0}^{\infty} \varepsilon^{r-1} (1-Q_X(\varepsilon)) d\varepsilon \right )^{1/r}, 
$$
can also be used as a measure of the variability of $X$, preserving the weak dispersive order $\leq_{\text{wd}}$.

To describe the properties of this functional, recall that a measure of variability $\nu$ is a map from the set of random variables to $\mathbb{R}$, such that given a random variable $X,$ $\nu(X)$  quantifies the variability of $X$. Next, we list a number of properties that a measure of variability should reasonably satisfy: 

\begin{itemize}
\item{P1}  Law invariance: if $X$ and $Y$ have the same distribution, then $\nu(X)=\nu(Y).$ 
\item{P2} Translation invariance: $\nu(X+k)=\nu(X)$ for all $X$ and all constant $k$.
%\item{P3} Positive homogeneity: $\nu(0)=0$ and $\nu(\lambda X)=\lambda \nu(X)$ for all $X$ and all $\lambda>0$.
\item{P3} Absolute homogeneity: $\nu(\lambda X)= |\lambda| \nu(X)$ for all $X$ and all $\lambda\in\R$.
%\bk{Condition (2.3) in B/L (1979) assumes $\nu(-X)=\nu(X)$, leading to absolute homogeneity, see also p.2. I have replaced positive by absolute homogeneity, okay?}
\item{P4} Non-negativity: $\nu(X) \geq 0$, with  equality {\color{red}if} $X$ is degenerate at $c \in \mathbb{R}$.
%\item{P5} Consistency with dispersive order: if $X \leq_{\text{disp}}Y$, then $\nu(X) \leq \nu(Y)$. 
\item{P5} Consistency with some dispersion order $\leq_D$: if $X \leq_{D}Y$, then $\nu(X) \leq \nu(Y)$. 
\end{itemize}

%\bk{ Property P5 used the classical dispersive order; this contradicts our arguments that this order is too restrictive in the discrete case. Hence, a measure of variability for discrete distributions should be consistent with some dispersion order applicable for discrete distributions. I have formulated P5 more generally.}
%\as{Ok to boths comments. However, I'm not sure whether the original P5, which involves the dispersive order, actually contradicts our arguments. We have verified that this strict ordering also implies the weak dispersive order. That said, I agree that this property can only be used in a limited number of cases.}
%\bk{I fully agree with your comment, "contradicts" is the wrong wording here.}

A functional $\nu$ satisfying the properties P1-P5  - using $\leq_{\text{disp}}$ as the dispersion order in P5 - is called a measure of variability or spread in the sense of Bickel and Lehmann; see \cite{BiLe-1979}. It is obvious that $\nu_r(X)$ satisfies P1, P2, and P4. To prove P3, we need only observe that $Q_{\lambda X}(\varepsilon)=Q_{X}(\varepsilon/ |\lambda|)$, from which $\nu_r(\lambda X)=|\lambda |\nu_r(X)$, $\lambda \in \mathbb{R}$, follows. Property P5 - whether using $\leq_{\text{disp}}$ or the discrete dispersive order $\discoa$ - follows directly from Corollary \ref{cordisp} and Theorem \ref{th:disc-disp}, respectively.
%The converse in P4 - $\nu(X)=0$ implies $X=c$ - also holds for $\nu_r$. (?)

Note that for many discrete distributions, $\nu_r(X)$ is not difficult to compute. For a random variable $X$ with values in $\mathbb{N}_0$, we obtain 
\begin{align*}
\nu_r(X) &= \frac{1}{2} \left ( \sum_{k=0}^{\infty} \left( (k+1)^r - k^r \right) (1-Q_X(k)) \right )^{1/r}.
\end{align*}
and, in particular, $\nu_1(X) = 1/2 \sum_{k=0}^{\infty} (1-Q_X(k))$.
Thus, $\nu_r$ is essentially the sum over the minimum probability outside an interval of length $k$; if this is small, the distribution is highly concentrated and its variability is low. 

\begin{example}
\begin{enumerate}
\item
If $X\sim Be(p)$, we obtain $\nu_1(X) = \min\{p, 1-p\}/2, \ \nu_2(X) = \sqrt{\min\{p, 1-p\}}/2$.
% $MAD=2p(1-p), SD=\sqrt{p(1-p)}$ 
\item
Let $X \sim Geom(p)$ with $F_X(k)=1-(1-p)^k, k\in\mathbb{N}$. Then, $1-Q_X(k)=(1-p)^{k+1}$, which entails 
$\nu_1(X)=(1-p)/(2p),  \ \nu_2(X)=\sqrt{(1-p)(2-p)}/(2p).$
% $MAD = 2(or 1?) (1-p)^{\floor(1/p)} \floor(1/p), SD=\sqrt{(1-p)}/p$
\end{enumerate}
\end{example}


\begin{definition}
\begin{enumerate}
\item Let $X$ and $Y$ be discrete random variables and let $p$ and $q$ be their probability mass functions (defined on the union of their supports). $X$ is said to be {\itshape less random} than $Y$ (written $X\leq_{rand} Y$) if $q \preceq p$, where $\preceq$ denotes the order of majorization \citep{hickey:1983}. %\citep[Def. 1.5.38]{mueller-stoyan}.
\item A distribution $p$ with support on the lattice of integers is unimodal if there exists at least one integer $M$ such that 
$$
p_k\geq p_{k-1}, \ \forall k\leq M, \qquad   p_{k+1}\leq p_k, \ \forall k\geq M.
$$
\end{enumerate}
\end{definition}

Closely related characterizations of discrete unimodality are studied in \cite{berthe1984}. To compare distributions in terms of randomness, \cite{hickey:1984} and \cite{hickey:1986} introduce a notion of majorization for absolutely continuous distributions via the decreasing rearrangement of their density functions. For the absolutely continuous case, \cite{fersur2003} shows that comparison in terms of randomness is equivalent to the weak dispersive order for unimodal distributions, as defined in \cite{sudku1988}. The following proposition serves an analogous purpose for discrete distributions.

\begin{proposition} \label{prob:rand}
Let $p$ and $q$ be unimodal distributions on the non-negative integers, and let $X$ and $Y$ be distributed according to $p$ and $q$. Then,
\begin{align*}
X\leq_{\text{wd}} Y &\Leftrightarrow X\leq_{rand} Y.
\end{align*}
\end{proposition}

\begin{proof}
By the unimodality assumption, 
\begin{align*}
\max_{i\in\mathbb{N}_0} \left\{ \sum_{k=i}^{i+m} p_k \right\} &= p_{[0]}+\ldots+p_{[m]},
\end{align*}
where $p_{[0]}\geq p_{[1]} \geq \ldots$ are the components of $p$ in decreasing order, and the assertion follows.
\end{proof}

\begin{remark} \label{rem:unimod}
\begin{enumerate}
\item With the help of Prop. \ref{prob:rand}, one can recover the results in Example \ref{ex:convolution} a)-c) and Example \ref{ex:decreasing} a), since it is known that the corresponding distributions are ordered with respect to randomness \citep{hickey:1983}.
\item 
Consider two unimodal distributions on the non-negative integers with $p_{[i]}=q_{[i]}, i\in\mathbb{N}_0$.
Then, $X=_{rand} Y$, and $X =_{wd} Y$ follows by Prop. \ref{prob:rand}. Hence, all unimodal distributions with the same ordered probabilities are equivalent with respect to $=_{wd}$.
\item 
Of course, without the unimodality assumption, the orders $\leq_{rand}$ and $\leq_{\text{wd}}$ are not equivalent. Consider the distributions $X \equiv \{p_0=0.1, p_1=0.4, p_2=0.4, p_3=0.1\}$ and $Y \equiv \{q_0=0.4, q_1=0.1, q_2=0.1, q_3=0.4\}$. It is clear that $X=_{rand} Y$, but $X \leq_{\text{wd}} Y$ while $Y \not \leq_{\text{wd}} X$.
\item
\begin{sloppypar}
Consider the class of unimodal distributions whose support is a subset of $\{1,\ldots,M\}$. 
In this class, the discrete uniform distribution $U\{1,M\}$ is the unique maximizer with respect to $\nu_1$, with 
\end{sloppypar}
\begin{align*}
    \nu_1 &= \frac{1}{2} \sum_{k=0}^{M-2} (1-Q_X(k)) 
    = \frac{1}{2} \sum_{k=1}^{M-1} \left(1-\frac{k}{M} \right) = \frac{M-1}{ 4}.
\end{align*}
%cp. standard deviation $SD=((M^2-1)/12)^{1/2}$
Without the unimodality assumption, there is no maximal element: the two-point distribution with mass $1/2$ at $1$ and $M$ and the uniform distribution are not comparable with respect to $\leq_{\text{wd}}$. Note that for the latter distribution $\nu_1=(M-1)/4$ holds, as it does for the uniform distribution.
\item
The measure $\nu_r$ is finite if $\mathbb{E}|X|^r < \infty$, i.e., it is not robust with respect to outliers. %\bk{A reviewer of \cite{ek-2024} asked for robust dispersion measures, so this remark could be of some interest}
%\as{Ok. I never used the empirical influence  function.}
However, it is straightforward to define robust dispersion measures based on a similar construction. For a random variable $X$ taking values in $\mathbb{N}_0$, consider the measure  
\[
\nu_{\text{rob}}(X) = \sum_{k=0}^{\infty} \frac{1 - Q_X(k)}{1+k^2},
\]
which satisfies properties P1, P2, P4, and property P5 with respect to $\leq_{\text{disp}}$, $\discoa$ and $\leq_{\text{wd}}$ (note that P3 is not meaningful for lattice distributions). 

Let $x_1, \ldots, x_n$ be an independent sample from $X$, and define $M = \max\{x_1, \ldots, x_n\}$. Then, $1 - Q(k) = 0$ for all $k \geq M$. Suppose now that a new observation $x>M$ is added. The empirical influence function satisfies  
\[
n\left(\nu_{\text{rob}}(x_1, \ldots, x_{n-1}, x) - \nu_{\text{rob}}(x_1, \ldots, x_n)\right) 
= c + n \sum_{k=M}^x \frac{1/n}{1+k^2} \leq c + \sum_{k=0}^{\infty} \frac{1}{1+k^2},
\]
for some constant $c$. That is, the empirical influence function is bounded, demonstrating the robustness of $\nu_{\text{rob}}$ with respect to outliers.
\end{enumerate}
\end{remark}


