\subsection{Wavelet Enhanced Edge Head}

\noindent The original MEGANet \cite{Bui2023} detects boundaries using a $5\times5$ Gaussian–Laplacian pyramid, which is isotropic and sensitive to noise. In contrast, we adopt a directional multilevel‐level 2D DWT using orthogonal Haar bases. This enable both fine and coarser boundary cues are being captured without adding learnable parameters. We cascade two fixed $2\times2$ Haar DWTs and fuse their high-frequency sub-bands. Let $\mathbf{X}\in\mathbb{R}^{C\times H\times W}$ denote a decoder feature map at spatial resolution $H\times W$ with $C$ channels.

\noindent \textbf{Level-1 decomposition} applies a standard 2D Haar DWT:
\begin{equation}
\{A^{(1)},\,D^{(1)}_{LH},\,D^{(1)}_{HL},\,D^{(1)}_{HH}\}
= \operatorname{DWT}_{\mathrm{Haar}}(\mathbf{X}),
\label{eq:level1_decomp}
\end{equation}
where 
\begin{equation}
\begin{aligned}
A^{(1)} &\in \mathbb{R}^{\,C \times \tfrac{H}{2} \times \tfrac{W}{2}}, \\[4pt]
D^{(1)}_{XY} &\in \mathbb{R}^{\,C \times \tfrac{H}{2} \times \tfrac{W}{2}}
\quad\text{for }XY\in\{LH,HL,HH\}\,.
\end{aligned}
\label{eq:subband_dims}
\end{equation}
are the low-frequency approximation and the three high-frequency detail sub-bands, respectively.

\noindent \textbf{Level-2 decomposition} is recursively applied to the approximation:
\begin{equation}
\{A^{(2)},\,D^{(2)}_{LH},\,D^{(2)}_{HL},\,D^{(2)}_{HH}\}
= \operatorname{DWT}_{\mathrm{Haar}}\bigl(A^{(1)}\bigr),
\label{eq:level2_decomp}
\end{equation}
yielding a coarser set of detail sub-bands and approximation 

\begin{equation}
A^{(2)} \in \mathbb{R}^{C \times \tfrac{H}{4} \times \tfrac{W}{4}}.
\label{eq:level2_dims}
\end{equation}


% \begin{equation}
% \{D_{LH},\,D_{HL},\,D_{HH}\}
% \;=\;
% \mathrm{DWT}_{\mathrm{Haar}}(X),
% \end{equation}
% where $LH$, $HL$, and $HH$ correspond to vertical, horizontal, and diagonal high‐frequency responses, respectively.\\

\noindent Implementation‐wise, these coefficients are obtained via depth‐wise $2\times2$ convolutions with fixed Haar high‐pass filters:

\begin{equation}
\resizebox{\columnwidth}{!}{%
  $\begin{aligned}
    k_{LH} &= \tfrac12\begin{bmatrix}+1&+1\\-1&-1\end{bmatrix},\quad
    k_{HL} &= \tfrac12\begin{bmatrix}+1&-1\\+1&-1\end{bmatrix},\quad
    k_{HH} &= \tfrac12\begin{bmatrix}+1&-1\\-1&+1\end{bmatrix}.
  \end{aligned}$
}
\end{equation}

\noindent At each level $\ell\in\{1,2\}$, we concatenate the three detail subbands to form
\begin{equation}
W^{(\ell)}
= \bigl[D_{LH}^{(\ell)},\;D_{HL}^{(\ell)},\;D_{HH}^{(\ell)}\bigr]
\;\in\;
\mathbb{R}^{3C \times \frac{H}{2^\ell} \times \frac{W}{2^\ell}}.
\end{equation}
Each tensor $W^{(\ell)}$ is then bilinearly upsampled to the original resolution:
\begin{equation}
\widetilde{W}^{(\ell)}
= \mathrm{Upsample}\bigl(W^{(\ell)},\,\text{scale}=2^\ell\bigr)
\;\in\;
\mathbb{R}^{3C \times H \times W}.
\end{equation}
The final multi-scale edge representation is obtained by summation:
\begin{equation}
\widetilde{W}_{\text{sum}} = \widetilde{W}^{(1)} + \widetilde{W}^{(2)}
\in \mathbb{R}^{3C\times H\times W}.
\end{equation}
This tensor serves as input to the subsequent W-EGA modules. The orthonormality of the Haar kernels ensures energy preservation while extracting directional edge bands. This head operates end-to-end with three fixed 2 × 2 filters, adds no learnable parameters, and introduces high-frequency priors absent from conventional CNN features. The resulting multi-scale edge representation is richer, enable it  effectively encode structural boundaries across multiple resolutions. 


\subsection{Wavelet Edge-Guided Attention}
\label{sec:w-ega}
\noindent We redesign the original EGA module \cite{Bui2023} to accommodate our tri‐channel wavelet cues, yielding W‐EGA. At decoder depth $i\le4$, the W‐EGA gate fuses three information sources, all spatially aligned to $H_i\times W_i$:

\paragraph{Reverse‐Attention Branch.}
The sigmoid of the incoming side‐prediction $P_{i+1}$ is inverted to highlight background pixels:
\begin{equation}
\begin{aligned}
R_i &= 1 - \sigma\bigl(P_{i+1}\bigr)
       \;\in\;\mathbb{R}^{B\times1\times H_i\times W_i},\\
F_{\mathrm{bg}} &= F_i \odot R_i.
\end{aligned}
\end{equation}
where $F_i\in\mathbb{R}^{B\times c_i\times H_i\times W_i}$ is the incoming decoder feature and $\sigma(\cdot)$ denotes the sigmoid function. The mask $R_i$ suppresses already‐confident foreground predictions, mirroring the reverse‐attention idea in MEGANet.

\paragraph{Boundary‐Attention Branch.}
Wavelet detail coefficients of the same prediction provide boundary evidence. We collapse wavelet edges of the current probability map across sub‐bands to form a soft contour mask:
\begin{equation}
\begin{aligned}
B_i &= \sum_{c} E_{c}\bigl(\sigma(P_{i+1})\bigr)
       \;\in\;\mathbb{R}^{B\times1\times H_i\times W_i},\\
F_{\mathrm{edge}} &= F_i \odot B_i.
\end{aligned}
\end{equation}

\noindent where $E_c(\cdot)$ extracts the $c$-th wavelet detail channel. The mask $B_i$ highlights boundary regions for enhanced edge guidance.

\paragraph{Input‐Edge Branch.}
Wavelet edges of the grayscale input supply high‐frequency priors, see Fig.\ref{fig:input-edge-branch}:
\begin{equation}
\begin{aligned}
H_i &= \sum_{c} E_{c}\bigl(\bar{F}_i\bigr),\\
F_{\mathrm{inp}} &= F_i \odot H_i,
\end{aligned}
\quad
\bar{F}_i = \tfrac{1}{C_i}\sum_{k=1}^{C_i}F_i^{(k)},
\end{equation}
where $\bar{F}_i$ is the channel‐wise mean of $F_i$. This branch injects texture cues independent of the current logits.\\


