\section{\label{sec:CEex}The Chapman-Enskog expansion of the vibrational kinetic model}
For simplicity, the following denotation for integrals in velocity space and substantial derivative are used
\begin{equation}
    {\mathcal{D}}=\frac{\partial}{\partial t} + {U}_{i}\frac{\partial}{\partial x_{i}}.
\end{equation}
And the translational degrees of freedom $K_{\rm{tr}}$ and rotational degrees of freedom $K_{\rm{rot}}$ are defaulted to 3 and 2 respectively.

The governing equations of the vibrational kinetic model is Eq.(\ref{eq:dfuncVib}). The forms of the distribution functions are Eq.(\ref{eq:thefuncTr}), Eq.(\ref{eq:thefuncRot}) and Eq.(\ref{eq:thefuncVib}). Introduce the formal small parameter $\varepsilon$, which indicates the order of the term before which it stands. Eq.(\ref{eq:dfuncVib}) can be rewritten as:
\begin{equation}   \label{eq:epsFuncVib}
\varepsilon \left( \mathcal{D}{{f}_{{}}}+{\boldsymbol{c}}\frac{\partial {{f}_{{}}}}{\partial {\boldsymbol{x}}} \right)=\frac{{{f}^{\text{tr}}}-{{f}_{{}}}}{\tau }+\frac{{{f}^{\text{rot}}}-{{f}^{\rm{tr}}}}{{{Z}_{\rm{rot}}}\tau }+\frac{{{f}^{\text{vib}}}-{{f}^{\rm{tr}}}}{{{Z}_{\rm{vib}}}\tau }.
\end{equation}

By taking moments of Eq.~(\ref{eq:epsFuncVib}), the conservation equations are obtained:
\begin{equation}   \label{eq:conFuncVib}
\begin{aligned}
  & \mathcal{D}\rho +\rho \frac{\partial {{U}_{i}}}{\partial {{x}_{i}}}=0, \\ 
 & \rho \mathcal{D}{{U}_{i}}+\frac{\partial {{p}_{ij}}}{\partial {{x}_{j}}}=0, \\ 
 & \rho \mathcal{D}\left( \frac{3}{2}R{{T}_{\rm{tr}}}+R{{T}_{\mathrm{rot}}}+\frac{{{K}_{\mathrm{vib}}}\left( {{T}_{\mathrm{vib}}} \right)}{2}R{{T}_{\mathrm{vib}}} \right)+\frac{\partial {{q}_{i}}}{\partial {{x}_{i}}}+{{p}_{{\rm{tr}},ij}}\frac{\partial {{U}_{i}}}{\partial {{x}_{j}}}=0, \\ 
\end{aligned}
\end{equation}
where, the energy equation can be separated into the following components:
\begin{equation}   \label{eq:energyFuncDivide}
\begin{aligned}
  & \frac{3}{2}\rho R\mathcal{D}{{T}_{\mathrm{tr}}}+\frac{\partial {{q}_{\mathrm{tr,}i}}}{\partial {{x}_{i}}}+{{p}_{{\rm{tr}},ij}}\frac{\partial {{U}_{i}}}{\partial {{x}_{j}}}={{s}_{\mathrm{tr}}}, \\ 
 & \rho R\mathcal{D}{{T}_{\mathrm{rot}}}+\frac{\partial {{q}_{\mathrm{rot,}i}}}{\partial {{x}_{i}}}={{s}_{\mathrm{rot}}}, \\ 
 & \frac{{{K}_{\mathrm{vib}}}\left( {{T}_{\mathrm{vib}}} \right)}{2}\rho R\mathcal{D}{{T}_{\mathrm{vib}}}+\frac{\partial {{q}_{\mathrm{vib,}i}}}{\partial {{x}_{i}}}={{s}_{\mathrm{vib}}}. \\ 
\end{aligned}
\end{equation}

Expanded the distribution function and the time derivative as follows
\begin{equation}   \label{eq:expansionDandF}
\begin{aligned}
  &\mathcal{D}={{\mathcal{D}}^{\left( 0 \right)}}+\varepsilon {{\mathcal{D}}^{\left( 1 \right)}}+{{\varepsilon }^{2}}{{\mathcal{D}}^{\left( 2 \right)}}+\ldots, \\ 
 & f={{f}^{\left( 0 \right)}}+\varepsilon {{f}^{\left( 1 \right)}}+{{\varepsilon }^{2}}{{f}^{\left( 2 \right)}}+\ldots .\\ 
\end{aligned}
\end{equation}

By neglecting all terms of order higher than the zeroth order in the expansion of Eq.(\ref{eq:expansionDandF}), Eq.(\ref{eq:epsFuncVib}) can be expressed as
\begin{equation}   \label{eq:epsFuncVib0}
\begin{aligned}
\varepsilon \left( \mathcal{D}f_{{}}^{\left( 0 \right)}+{{\boldsymbol{c}}_{{}}}\frac{\partial f_{{}}^{\left( 0 \right)}}{\partial \mathbf{x}} \right)=\frac{{{f}^{\rm{tr}}}-f^{\left( 0 \right)}}{\tau }+\frac{{{f}^{\rm{rot}}}-{{f}^{\rm{tr}}}}{{{Z}^{\rm{rot}}}\tau }+\frac{{{f}^{\rm{vib}}}-{{f}^{\rm{tr}}}}{{{Z}^{\rm{vib}}}\tau },\\ 
\end{aligned}
\end{equation}
where
\begin{equation}   \label{eq:funcF0}
{{f}^{\left( 0 \right)}}=n{{\left( \frac{1}{2\pi R{{T}_{\rm{tr}}}} \right)}^{\frac{3}{2}}}\exp \left( -\frac{{{\boldsymbol{c}}^{2}}}{2R{{T}_{\rm{tr}}}} \right)\frac{1}{mR{{T}_{\rm{rot}}}}{ \exp \left( {-\frac{{{\eta }_{\rm{rot}}}}{mR{{T}_{\rm{rot}}}}} \right) }\Re \left( {{T}_{\rm{vib}}} \right).
\end{equation}

By taking the moments of the distribution function $f=f^{\left(0 \right)}$, one obtains ${{p}_{{\rm{tr}},ij}}-\delta_{ij} p_{\rm{tr}}/3=0$, and ${{q}_{{\rm{tr}},i}}={{q}_{{\rm{rot}},i}}={{q}_{{\rm{vib}},i}}=0$ (The $\delta_{ij}$ is Kronecker symbol). Therefore, Eq.~(\ref{eq:conFuncVib}) can be simplified as:
\begin{equation}   \label{eq:conFuncVibSim}
\begin{aligned}
  & \mathcal{D}\rho +\rho \frac{\partial {{U}_{i}}}{\partial {{x}_{i}}}=0, \\ 
 & \rho \mathcal{D}{{U}_{i}}+\frac{\partial {{p}_{\rm{tr}}}}{\partial {{x}_{i}}}=0, \\ 
 & \rho R\mathcal{D}\left( \frac{3}{2}{{T}_{\rm{tr}}}+{{T}_{\rm{rot}}}+\frac{{{K}_{\rm{vib}}}\left( {{T}_{\rm{vib}}} \right)}{2}{{T}_{\rm{vib}}} \right)+{{p}_{\rm{tr}}}\frac{\partial {{U}_{i}}}{\partial {{x}_{i}}}=0, \\ 
\end{aligned}
\end{equation}
where, the energy equation can be separated into the following components:
\begin{equation}   \label{eq:energyFuncDivideSim}
\begin{aligned}
  & \frac{3}{2}\rho R\mathcal{D}{{T}_{\rm{tr}}}+{{p}_{\rm{tr}}}\frac{\partial {{U}_{i}}}{\partial {{x}_{i}}}=\frac{1}{\tau }\frac{3}{2}\rho R\left( \frac{{{T}_{\rm{eq}}}-{{T}_{\rm{tr}}}}{{{Z}_{\rm{vib}}}}+\frac{{{T}_{\rm{tr,rot}}}-{{T}_{\rm{tr}}}}{{{Z}_{\rm{rot}}}} \right), \\ 
 & \rho R\mathcal{D}{{T}_{\rm{rot}}}=\frac{1}{\tau }\rho R  \left( \frac{{{T}_{\rm{eq}}}-{{T}_{\rm{rot}}}}{{{Z}_{\rm{vib}}}}+\frac{{{T}_{\rm{tr,rot}}}-{{T}_{\rm{rot}}}}{{{Z}_{\rm{rot}}}} \right), \\ 
 & \frac{{{K}_{\rm{vib}}}\left( {{T}_{\rm{vib}}} \right)}{2}\rho R\mathcal{D}{{T}_{\rm{vib}}}=\frac{1}{\tau }\frac{{{K}_{\rm{vib}}}\left( {{T}_{\rm{vib}}} \right)}{2}\rho R\frac{{{K}_{\rm{vib}}}\left( {{T}_{\rm{eq}}} \right){{T}_{\rm{eq}}}-{{K}_{\rm{vib}}}\left( {{T}_{\rm{vib}}} \right){{T}_{\rm{vib}}}}{{{K}_{\rm{vib}}}\left( {{T}_{\rm{vib}}} \right){{Z}_{\rm{vib}}}}. \\ 
\end{aligned}
\end{equation}
Thus, the vibrational kinetic model recovers the Euler equations.

By neglecting all terms of order higher than the first order in the expansion of Eq.(\ref{eq:expansionDandF}), Eq.(\ref{eq:epsFuncVib}) can be expressed as
\begin{equation}   \label{eq:conFuncVibSim1}
\varepsilon \left( {{\mathcal{D}}^{\left( 0 \right)}}f_{{}}^{\left( 0 \right)}+{\boldsymbol{c}}\frac{\partial f_{{}}^{\left( 0 \right)}}{\partial \boldsymbol{x}} \right)=\frac{{{f}^{tr}}-\left( f_{{}}^{\left( 0 \right)}+f_{{}}^{\left( 1 \right)} \right)}{\tau }+\frac{{{f}^{\rm{rot}}}-{{f}^{\rm{tr}}}}{{{Z}_{\rm{rot}}}\tau }+\frac{{{f}^{\rm{vib}}}-{{f}^{\rm{tr}}}}{{{Z}_{\rm{vib}}}\tau }.
\end{equation}

The partial derivative of the distribution function $f^{\left(0 \right)}$ with respect to the macroscopic variables is given by:
\begin{equation}   \label{eq:macroPartialDerivative}
\begin{aligned}
  & \frac{\partial {{f}^{\left( 0 \right)}}}{\partial \rho }=\frac{{{f}^{\left( 0 \right)}}}{\rho }, \\ 
 & \frac{\partial {{f}^{\left( 0 \right)}}}{\partial {{U}_{i}}}=\frac{1}{R{{T}_{\rm{tr}}}}{{c}_{i}}{{f}^{\left( 0 \right)}}, \\ 
 & \frac{\partial {{f}^{\left( 0 \right)}}}{\partial {{T}_{\rm{tr}}}}=\frac{{{f}^{\left( 0 \right)}}}{{{T}_{\rm{tr}}}}\left( -\frac{3}{2}+\frac{1}{2R{{T}_{\rm{tr}}}}{{c}^{2}} \right), \\ 
 & \frac{\partial {{f}^{\left( 0 \right)}}}{\partial {{T}_{\rm{rot}}}}=\frac{{{f}^{\left( 0 \right)}}}{{{T}_{\rm{rot}}}}\left( -1+\frac{1}{mR{{T}_{\rm{rot}}}}{{\eta }_{\rm{rot}}} \right), \\ 
 & \frac{\partial {{f}^{\left( 0 \right)}}}{\partial {{T}_{\rm{vib}}}}=\frac{{{f}^{\left( 0 \right)}}}{{{T}_{\rm{vib}}}}\left( -\frac{{{K}_{\rm{vib}}}\left( {{T}_{\rm{vib}}} \right)}{2}+\frac{1}{mR{{T}_{\rm{vib}}}}{{\eta }_{\rm{vib}}} \right). \\ 
\end{aligned}
\end{equation}

Based on Eq.(\ref{eq:macroPartialDerivative}), the left-hand side of Eq.(\ref{eq:conFuncVibSim1}) can be rewritten as:
\begin{equation}   \label{eq:conFuncVibSim1LHS}
{{\mathcal{D}}^{\left( 0 \right)}}f_{{}}^{\left( 0 \right)}+{{{c}}_{{i}}}\frac{\partial f_{{}}^{\left( 0 \right)}}{\partial {x}_{i}} = \left( 
\begin{aligned}
  & \left( 
  \begin{aligned}
    &\frac{\partial {{f}^{\left( 0 \right)}}}{\partial \rho }{{\mathcal{D}}^{\left( 0 \right)}}\rho 
    +\frac{\partial {{f}^{\left( 0 \right)}}}{\partial {{U}_{i}}}{{\mathcal{D}}^{\left( 0 \right)}}{{U}_{i}} \\
    &+\frac{\partial {{f}^{\left( 0 \right)}}}{\partial {{T}_{\rm{tr}}}}{{\mathcal{D}}^{\left( 0 \right)}}{{T}_{\rm{tr}}}
    +\frac{\partial {{f}^{\left( 0 \right)}}}{\partial {{T}_{\rm{rot}}}}{{\mathcal{D}}^{\left( 0 \right)}}{{T}_{\rm{rot}}}
    +\frac{\partial {{f}^{\left( 0 \right)}}}{\partial {{T}_{\rm{vib}}}}{{\mathcal{D}}^{\left( 0 \right)}}{{T}_{\rm{vib}}} 
  \end{aligned}
  \right)\\  
 & + {{c}_{i}}\left( 
 \begin{aligned}
  &\frac{\partial {{f}^{\left( 0 \right)}}}{\partial \rho }\frac{\partial \rho }{\partial {{x}_{i}}}
  +\frac{\partial {{f}^{\left( 0 \right)}}}{\partial {{U}_{j}}}\frac{\partial {{U}_{j}}}{\partial {{x}_{i}}} \\
  &+\frac{\partial {{f}^{\left( 0 \right)}}}{\partial {{T}_{\rm{tr}}}}\frac{\partial {{T}_{\rm{tr}}}}{\partial {{x}_{i}}}
  +\frac{\partial {{f}^{\left( 0 \right)}}}{\partial {{T}_{\rm{rot}}}}\frac{\partial {{T}_{\rm{rot}}}}{\partial {{x}_{i}}}
  +\frac{\partial {{f}^{\left( 0 \right)}}}{\partial {{T}_{\rm{vib}}}}\frac{\partial {{T}_{\rm{vib}}}}{\partial {{x}_{i}}} 
 \end{aligned}
 \right) \\ 
\end{aligned} \right) = {\rm{X}}.
\end{equation}

According to Eq.(\ref{eq:conFuncVibSim}) and Eq.(\ref{eq:energyFuncDivideSim}), Eq.~(\ref{eq:conFuncVibSim1LHS}) can be simplified as:
\begin{equation}   \label{eq:conFuncVibSim1LHS_Sim}
{\rm{X}} ={{f}^{\left( 0 \right)}}\left( 
\begin{aligned}
  & \left( \begin{aligned}
  & \frac{1}{{{T}_{\rm{tr}}}}\left( -\frac{3}{2}+\frac{1}{2R{{T}_{\rm{tr}}}}{{c}^{2}} \right)\left( \frac{1}{\tau }\left( \frac{{{T}_{\rm{eq}}}-{{T}_{\rm{tr}}}}{{{Z}_{\rm{vib}}}}+\frac{{{T}_{\rm{tr,rot}}}-{{T}_{\rm{tr}}}}{{{Z}_{\rm{rot}}}} \right) \right) \\ 
 & +\frac{1}{{{T}_{\rm{rot}}}}\left( -1+\frac{{{\eta }_{\rm{rot}}}}{mR{{T}_{\rm{rot}}}} \right)\left( \frac{1}{\tau }\left(\frac{{{T}_{\rm{eq}}}-{{T}_{\rm{rot}}}}{{{Z}_{\rm{vib}}}}+\frac{{{T}_{\rm{tr,rot}}}-{{T}_{\rm{rot}}}}{{{Z}_{\rm{rot}}}} \right) \right) \\ 
 & +\frac{1}{{{T}_{\rm{vib}}}}\left( -\frac{{{K}_{\rm{vib}}}\left( {{T}_{\rm{vib}}} \right)}{2}+\frac{{{\eta }_{\rm{vib}}}}{mR{{T}_{\rm{vib}}}} \right)\left( \frac{1}{\tau }\frac{{{K}_{\rm{vib}}}\left( {{T}_{\rm{eq}}} \right){{T}_{\rm{eq}}}-{{K}_{\rm{vib}}}\left( {{T}_{\rm{vib}}} \right){{T}_{\rm{vib}}}}{{{K}_{\rm{vib}}}\left( {{T}_{\rm{vib}}} \right){{Z}_{\rm{vib}}}} \right) \\ 
\end{aligned} \right) \\ 
 & +{{c}_{i}}\left( 
 \begin{aligned}
  & \left( \frac{1}{R{{T}_{\rm{tr}}}}{{c}_{j}} \right)\left( \frac{\partial {{U}_{j}}}{\partial {{x}_{i}}}-\frac{1}{3}\frac{\partial {{U}_{k}}}{\partial {{x}_{k}}}{{\delta }_{ij}} \right) \\ 
 & +\left( \frac{1}{{{T}_{\rm{tr}}}}\left( -\frac{5}{2}+\frac{1}{2R{{T}_{\rm{tr}}}}{{c}^{2}} \right) \right)\frac{\partial {{T}_{\rm{tr}}}}{\partial {{x}_{i}}} \\ 
 & +\left( \frac{1}{{{T}_{\rm{rot}}}}\left( -1+\frac{{{\eta }_{\rm{rot}}}}{mR{{T}_{\rm{rot}}}} \right) \right)\frac{\partial {{T}_{\rm{rot}}}}{\partial {{x}_{i}}} \\ 
 & +\left( \frac{1}{{{T}_{\rm{vib}}}}\left( -\frac{{{K}_{\rm{vib}}}\left( {{T}_{\rm{vib}}} \right)}{2}+\frac{{{\eta }_{\rm{vib}}}}{mR{{T}_{\rm{vib}}}} \right) \right)\frac{\partial {{T}_{\rm{vib}}}}{\partial {{x}_{i}}} \\ 
\end{aligned} 
\right) \\ 
\end{aligned} \right).
\end{equation}

In the final results we take $\varepsilon$ = 1. Therefore, from Eq.~(\ref{eq:conFuncVibSim1}), the following can be obtained
\begin{equation}   \label{eq:finalFunc}
f_{{}}^{\left( 1 \right)}=\frac{{{f}^{\rm{tr}}}-f_{{}}^{\left( 0 \right)}}{\tau }+\frac{{{f}^{\rm{rot}}}-{{f}^{\rm{tr}}}}{{{Z}_{\rm{rot}}}\tau }+\frac{{{f}^{\rm{vib}}}-{{f}^{\rm{tr}}}}{{{Z}_{\rm{vib}}}\tau }-{\rm{X}}.
\end{equation}


By taking moments of the distribution function $f={{f}^{\left( 0 \right)}}+{{f}^{\left( 1 \right)}}$, the following results are derived:
\begin{equation}   \label{eq:finalMoment}
\begin{aligned}
 & {{p}_{{\rm{tr}},ij}}=2\mu \frac{\partial {{U}_{i}}}{\partial {{x}_{j}}}=2\tau {{p}_{\rm{tr}}}\frac{\partial {{U}_{i}}}{\partial {{x}_{j}}}, \\ 
 & {{q}_{i}}={{q}_{{\rm{tr}},i}}+{{q}_{{\rm{rot}},i}}+{{q}_{{\rm{vib}},i}}, \\ 
 & {{q}_{{\rm{tr}},i}}={{\lambda }_{\rm{tr}}}\frac{\partial {{T}_{{\rm{tr}}}}}{\partial {{x}_{i}}}, \\ 
 & {{q}_{{\rm{rot}},i}}={{\lambda }_{\rm{rot}}}\frac{\partial {{T}_{\rm{rot}}}}{\partial {{x}_{i}}},\\
 & {{q}_{{\rm{vib}},i}}={{\lambda }_{\rm{vib}}}\frac{\partial {{T}_{\rm{vib}}}}{\partial {{x}_{i}}}, \\ 
\end{aligned}
\end{equation}
where,
\begin{equation}   \label{eq:finalMomentPara}
\begin{aligned}
 & {{\lambda }_{\rm{tr}}}=\mu R\frac{3}{2}{{B}_{\rm{tr}}}, \, {{\lambda }_{\rm{rot}}}=\mu R {{B}_{\rm{rot}}}, \, {{\lambda }_{\rm{vib}}}=\mu R\frac{{{K}_{\rm{vib}}}\left( {{T}_{vib}} \right)}{2}{{B}_{\rm{vib}}}, \\ 
 & {{B}_{\rm{tr}}}=\frac{5}{3}\frac{1}{{{A}_{\rm{tt}}}}, \, {{B}_{\rm{rot}}}=\frac{1}{{{A}_{\rm{rr}}}}, \, {{B}_{\rm{vib}}}=\frac{1}{{{A}_{\rm{vv}}}}, \\ 
 & {{A}_{\rm{tt}}}=\frac{2}{3}+\frac{1}{3{{Z}_{\rm{rot}}}}\left( 1-{{\omega }_{0}} \right)+\frac{1}{3{{Z}_{\rm{vib}}}}\left( 1-{{\omega }_{2}} \right), \\ 
 & {{A}_{\rm{rr}}}=\delta +\frac{1}{{{Z}_{\rm{rot}}}}\left( 1-{{\omega }_{1}} \right)\left( 1-\delta  \right)+\frac{1}{{{Z}_{\rm{vib}}}}\left( 1-{{\omega }_{3}} \right)\left( 1-\delta  \right), \\ 
 & {{A}_{\rm{vv}}}=1. \\ 
\end{aligned}
\end{equation}

Eq.(\ref{eq:finalMomentPara}) indicates that the higher-order variables including stress and heat flux are nonzero. By substitution of the derived constitutive relations into Eq. (\ref{eq:conFuncVib}), the vibrational kinetic model recovers the N-S equations.


