% \cite{Trutnau} Nie udowadnia potrzebnego wzoru.

\subsection{Space-time process}
\label{sub:space_time}

Here, we revert to our global assumption that $X=(\Omega, \F, \Ft, (\theta_t), (X_t), (\Prb_x))$ is a symmetric Hunt process.
By $\st{X}=(\st{\Omega}, \st{\F}, (\st{X}_t), (\st{\Prb}_{(t_0,x)}))$ we denote its \emph{space\nobreakdash-time process}. Here,
\begin{align*}
    \st{\Omega} &:= (0,\infty)\tim\Omega, \\
    \st{\F} &:= \sigma\{\mathcal{B}((0,\infty))\tim\F \}, \\
    \st{\Prb}_{(t_0,x)} &:= \delta_{t_0} \otimes \Px,
    \quad (t_0,x)\in\st{E}_\Cem, \\
    \st{X}_t(\tau,\omega) &:=
        \begin{cases}
            (\tau+t,X_t(\omega)) & \text{when } t<\zeta(\omega) , \\
            (\infty,\Delta) & \text{otherwise},
        \end{cases}
\end{align*}
where $\st{E}_\Cem  := (0,\infty) \tim E \cup \{(\infty, \Cem)\}$. Here, $\delta_{t_0}$ denotes the Dirac delta measure at a point $t_0\in(0,\infty)$ and the point $\{(\infty, \Cem)\}$ is the cemetery state of $\Xbrevet$. The space\nobreakdash-time process $\Xbrevet$ is a non\nobreakdash-symmetric Hunt process with respect to the following admissible filtration
\begin{align*}
    \st{\F}_t := \sigma\{\mathcal{B}((0,\infty)) \tim \F_t\}.
\end{align*}

Denote the expected value on the space $(\st{\Omega}, \st{\F}, \st{\Prb}_{(t_0,x)})$ by $\Ev_{(t_0,x)}$.
A conditional expectation of any $\st{\F}_\infty$-measurable $\Phi\colon \st{\Omega}\to\R$ given $\st{\F}_t$ can be written as
\begin{align}
\label{eq:E-sp-tim}
    \Ev_{(t_0,x)} [\Phi|\st{\F}_t]
    =
    \Ev_x[\Phi(t_0,\cdot)|\F_t],
    \quad
    \st{\Prb}_{(t_0,x)}\text{-a.s.}
\end{align}
Indeed, for any $A\in\mathcal{B}((0,\infty))$ and $B\in\F_t$
\begin{align*}
    \Ev_{(t_0,x)} (\Phi \ind_{A\tim B})
    &=
    \ind_A(t_0) \Ev_x( \Ev_x[\Phi(t_0,\cdot)|\F_t] \ind_B)
    =
    \Ev_{(t_0,x)} ( \Ev_x[\Phi(t_0,\cdot)|\F_t] \ind_{A\tim B}).
\end{align*}

We provide a brief overview of the essential properties of the space-time process, primarily following \cite[Section~16]{Sharpe}.
We denote the Lebesgue measure on $(0,\infty)$ by $\dr$ and write the space $L^2((0,\infty)\times E,\mathcal{B}((0,\infty)\times E),\dr \otimes m)$  shortly as $L^2(\dr \otimes m)$.
Let $\Pbrevet$ be the semigroup of the space\nobreakdash-time process $\Xbrevet$. Then $\st{P}_t$ can be written as
\begin{align*}
    \st{P}_t f(r,x) = P_t[f(r+t,\cdot)](x),
    \quad
    f\in L^2(\dr \otimes m).
\end{align*}
Its adjoint operator $\bst{P}_t$ on $L^2(\dr \otimes m)$ is given by
\begin{align*}
    \bst{P}_t g (r,x) = \ind_{[0,r)}(t) P_t[g(r-t,\cdot)](x),
    \quad
    g\in L^2(\dr \otimes m).
\end{align*}
At the same time, the semigroup $\Pbstt$ is associated with the \emph{backward space\nobreakdash-time process} $\Xbstt$ defined on the same family of probability spaces
$(\st{\Omega}, \st{\F}, (\st{\Prb}_{(t_0,x)}))$ by
\begin{align*}
    \bst{X}_t(\tau,\omega) :=
    \begin{cases}
        (\tau-t,X_t(\omega)) & \text{for } t<\tau \wedge \zeta(\omega) , \\
        (\infty, \Cem) & \text{otherwise}.
    \end{cases}
\end{align*}
To rephrase, $\Xbstt$ represents the Cartesian product of $\Xt$ and the uniform motion to the left on $(0,\infty)$ with killing at $0$.
%In other words, the process $\Xbstt$ is dual to $\Xbrevet$.

Note that the measure $\dr \otimes m$ is excessive with respect to the semigroup $\Pbrevet$. Indeed, for $\st{B}\in\mathcal{B}((0,\inft)\times E)$, by the symmetry of $\Pt$, we can write
\begin{align*}
    \intb_0^\inft \intE
        \st{P}_t \ind_{\st{B}}
    \dms \dr
    &=
    \intb_0^\inft \intE
        P_t[\ind_{\st{B}} (r+t,\cdot)](x)
    \,m(\dx)\dr
    =
    \intb_0^\inft \intE
       \ind_{\st{B}} (r+t,x) P_t1(x)
    \,m(\dx)\dr
    \\
    &\leq
    \intb_0^\inft \intE
       \ind_{\st{B}} (r+t,x)
    \,m(\dx)\dr
    =
    \intb_t^\inft \intE
       \ind_{\st{B}} (r,x)
    \,m(\dx)\dr
    \leq
    \dr \otimes m (\st{B}).
\end{align*}

At the end of this subsection,
we prove a non\nobreakdash-symmetric variant of equation \eqref{eq:RevuzSym} for the space\nobreakdash-time process. This result will be useful in 
Section~\ref{sec:Sharp_bracket}.
\begin{lem}
\label{lem:RevuzST}
    Let $\At$ be a PCAF related to the space\nobreakdash-time process $\Xbrevet$ described above. Let $\nu$ be the Revuz measure of $\At$ (related to the reference measure $\dr \otimes m$). Then $\nu$ satisfies
    \begin{align}
    \label{eq:RevuzST}
        \int\limits_{\mathclap{(0,\inft)\tim E}} f \hat{h} \,\dd \nu
        &=
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
        \Ev_{(r,x)} \left(
            \int\limits_0^t f(\st{X}_s) \,\dd A_s
        \right)
        \, \dr m(\dx)
    \end{align}
    for any $f\in\mathcal{B}^e((0,\infty)\tim E)_+$ and $\alpha$\nobreakdash-coexcessive function $\hat{h}$ ($\alpha\ge0$).
\end{lem}

Before we derive the proof of this lemma, we need to introduce the notion of the $\alpha$\nobreakdash-subprocess following \cite[Exercise (12.34)]{Sharpe}. Fix $\alpha>0$. We want to define the process $\subpr{\st{X}}$, which is obtained by killing $\Xbrevet$ at a random and independent time $T^\alpha$ following the exponential distribution with parameter $\alpha$. To be precise, let
\begin{align*}
    \subpr{\st{\Omega}} &:= (0,\inft)\tim \st{\Omega}, \\
    \subpr{\st{\F}} &:= \sigma\{\mathcal{B}((0,\infty))\tim\st{\F} \}, \\
    \subpr{\lambda}(\dd\xi) &:=  \alpha e^{-\alpha\xi} \dd \xi, \\
    \subpr{\st{\Prb}}_{(t_0,x)} &:= \subpr{\lambda} \otimes \st{\Prb}_{(t_0,x)},
    \quad (t_0,x)\in\st{E}_\Cem, \\
    \st{X}_t(\xi,\tau,\omega) &:=  \st{X}_t(\tau,\omega),\\
    \subpr{\st{X}}_t(\xi,\tau,\omega) &:=
        \begin{cases}
            \st{X}_t(\xi,\tau,\omega) & \text{when } t<\xi , \\
            (\infty,\Delta) & \text{otherwise}.
        \end{cases}
\end{align*}
Let
$T^\alpha(\xi,\tau,\omega):=\xi$ and
$\subpr{\zeta}:=\zeta \wedge T^\alpha$
be the lifetime of $\subpr{\st{X}}$.
We call $\subpr{\st{X}}$ the \emph{$\alpha$-subprocess} of $\Xbrevet$.
The semigroup of the process $\subpr{\st{X}}$ is $(e^{-\alpha t}\st{P}_t)$. We use the notation
$\Ev_{(t_0,x)}$
either for the expected value on the spaces
$(\st{\Omega}, \st{\F}, \st{\Prb}_{(t_0,x)})$
or
$(\subpr{\st{\Omega}}, \subpr{\st{\F}}, \subpr{\st{\Prb}}_{(t_0,x)})$.
Similarly, we define the $\alpha$-subprocess of $\bst{X}$ denoted by $\bst{X}^\alpha$.

\begin{proof}[Proof of Lemma~\ref{lem:RevuzST}]
    Recall that the semigroup of $\st{X}^\alpha$ is $(e^{-\alpha t}\st{P}_t)$.
    Consequently, as $\hat{h}$ is $\alpha$\nobreakdash-coexcessive for $\Xbrevet$, the measure $\hat{h} m$ is excessive for $\st{X}^\alpha$.
    Additionally, the mapping
    $[0,\inft)\ni t\mapsto \hat{h}(\bst{X}^\alpha_t)$ is $\subpr{\Prb}_m$\nobreakdash-almost surely right continuous; see Proposition (4.2) and Theorem (4.8) in \cite{blumenthal_getoor}. Due to self\nobreakdash-duality of $\Xt$ (see \eqref{eq:self-dual}), the mapping
    $(0,\zeta^\alpha)\ni t\mapsto \hat{h}(\st{X}^\alpha_{t-})$ is $\subpr{\Prb}_m$\nobreakdash-almost surely left continuous.

    Let $A^\alpha_t$ denote the PCAF $\At$ stopped at time $T^\alpha$.
    As a consequence of the above observations, we can invoke Corollary~(8.11) of \cite{gs_Naturality} and write
    \begin{align*}
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}}
        &\Ev_{(r,x)} \left(
            \int\limits_0^t f(\st{X}^\alpha_{s-}) \hat{h}(\st{X}^\alpha_{s-}) \,\dd A^\alpha_s
        \right)
        \,\dr m(\dx)
        \\
        &=
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
        \Ev_{(r,x)} \left(
            \int\limits_0^t f(\st{X}^\alpha_{s-}) \,\dd A^\alpha_s
        \right)
        \,\dr m(\dx).
    \end{align*}

    Given that $\At$ is continuous and the discontinuity points of the sample paths $t\mapsto \st{X}^\alpha_t$ are at most countable, we may reformulate the above equation as follows:
    \begin{align*}
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}}
        &\Ev_{(r,x)} \left(
            \int\limits_0^t f(\st{X}^\alpha_s) \hat{h}(\st{X}^\alpha_s) \,\dd A^\alpha_s
        \right)
        \,\dr m(\dx)
        \\
        &=
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
        \Ev_{(r,x)} \left(
            \int\limits_0^t f(\st{X}^\alpha_s) \,\dd A^\alpha_s
        \right)
        \,\dr m(\dx).
    \end{align*}
    We clam that we can replace $\st{X}^\alpha_s$ and $A^\alpha_s$ by $\st{X}_s$ and $A_s$ in the above formula.
    Denote
    $B_t := \int_0^t f(\st{X}_s) \,\dd A_s$
    and 
    $B_t^\alpha := \int_0^t f(\st{X}^\alpha_s) \,\dd A^\alpha_s
    = B_{t\wedge T^\alpha}$
    .
    We can write
    \begin{align*}
        &\lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
        \Ev_{(r,x)} \left(
            \int\limits_0^t f(\st{X}^\alpha_s) \,\dd A^\alpha_s
        \right)
        \,\dr m(\dx)
        \\
        &=
        \lim_{t\to0^+}
        \left[ \,
            \frac{1}{t}
            \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
            \Ev_{(r,x)} B_t^\alpha \ind_{\{T^\alpha > t\}}
            \,\dr m(\dx)
            +
            \frac{1}{t}
            \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
            \Ev_{(r,x)} B_t^\alpha \ind_{\{T^\alpha \leq t\}}
            \,\dr m(\dx)
        \right]
        .
    \end{align*}
    When $\st{\omega}\in\subpr{\st{\Omega}}$ is such that $T^\alpha(\st{\omega}) > t$, then $B_t^\alpha (\st{\omega}) = B_t (\st{\omega})$. Moreover, as $B_t$ and $T^\alpha$ are independent, we can write
    $\Ev_{(r,x)} B_t^\alpha \ind_{\{T^\alpha > t\}}
    =
    \Ev_{(r,x)} B_t \cdot \Ev_{(r,x)} \ind_{\{T^\alpha > t\}}
    =
    e^{-\alpha t}\Ev_{(r,x)} B_t$. Therefore
    \begin{align}
    \label{eq:RevuzST_eq1}
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
        \Ev_{(r,x)} B_t^\alpha \ind_{\{T^\alpha > t\}}
        \,\dr m(\dx)
        =
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
        \Ev_{(r,x)} B_t
        \,\dr m(\dx).
    \end{align}
    When the right\nobreakdash-hand side of \eqref{eq:RevuzST_eq1} is infinite, then the claim is obviously true. Assume that it is finite. Then, since $B_t^\alpha \leq B_t$, we get
    $
    \Ev_{(r,x)} B_t^\alpha \ind_{\{T^\alpha \leq t\}}
    \leq
    \Ev_{(r,x)} B_t \ind_{\{T^\alpha \leq t\}}
    =
    \Ev_{(r,x)} B_t \cdot \Ev_{(r,x)} \ind_{\{T^\alpha \leq t\}}
    =
    (1-e^{-\alpha t}) \Ev_{(r,x)} B_t
    $.
    Therefore,
    \begin{align*}
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
        &\Ev_{(r,x)} B_t^\alpha \ind_{\{T^\alpha \leq t\}}
        \,\dr m(\dx)
        \\
        &\leq
        \lim_{t\to0^+}
        (1-e^{-\alpha t})
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
        \Ev_{(r,x)} B_t
        \,\dr m(\dx)
        =
        0.
    \end{align*}
    Summarizing, we show that 
    \begin{align*}
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
        &\Ev_{(r,x)} \left(
            \int\limits_0^t f(\st{X}^\alpha_s) \,\dd A^\alpha_s
        \right)
        \,\dr m(\dx)
        \\
        &=
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
        \Ev_{(r,x)} \left(
            \int\limits_0^t f(\st{X}_s) \,\dd A_s
        \right)
        \,\dr m(\dx)
        .
    \end{align*}
    Analogously, one can show that
    \begin{align*}
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}}
        &\Ev_{(r,x)} \left(
            \int\limits_0^t f(\st{X}^\alpha_s) \hat{h}(\st{X}^\alpha_s) \,\dd A^\alpha_s
        \right)
        \,\dr m(\dx)
        \\
        &=
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}}
        \Ev_{(r,x)} \left(
            \int\limits_0^t f(\st{X}_s) \hat{h}(\st{X}_s) \,\dd A_s
        \right)
        \,\dr m(\dx)
        .
    \end{align*}

    To summarize,
    \begin{align*}
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}}
        &\Ev_{(r,x)} \left(
            \int\limits_0^t f(\st{X}_s) \hat{h}(\st{X}_s) \,\dd A_s
        \right)
        \,\dr m(\dx)
        \\
        &=
        \lim_{t\to0^+}
        \frac{1}{t}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{h}(r,x)
        \Ev_{(r,x)} \left(
            \int\limits_0^t f(\st{X}_s) \,\dd A_s
        \right)
        \,\dr m(\dx).
    \end{align*}
    Finally, since $\nu$ is the Revuz measure of $\At$, it follows from \eqref{eq:RevuzAF} that the left\nobreakdash-hand side is equal to $\int_{(0,\inft)\tim E} f \hat{h} \,\dd \nu$.
\end{proof}


\subsection{Martingale}
\label{sub:martingale}



For any $x\in E_\Cem$ a real valued process $((M_t),\Ft,\Px)$ is a \emph{martingale} provided $\Ev_x[M_t|\F_s]=M_s$ $\Px$-a.s. for all $s\leq t$. We say that $M=((M_t),\Ft,\Pxx)$ is a \emph{martingale} when $((M_t),\Ft,\Px)$ is a martingale for all $x\in E_\Cem$.



Let $M=((M_t),\Ft,\Pxx)$ be a martingale such that
$M_0=0$
and
$\Ev_x M_t^2 < \infty$ for $t>0, x\in E_\Cem$.
There exists
a unique integrable and predictable increasing process
$\langle M \rangle$ starting at zero such that $((M_t^2 - \langle M \rangle_t),\Ft,\Pxx)$ is a martingale.
In particular,
\begin{align}
\label{eq:sharp_square}
    \Ev_x \langle M \rangle_t = \Ev_x M_t^2,
    \quad
    \text{for all }
    t\geq0, x\in E_\Cem.
\end{align}
In addition, whenever $\Mt$ is an AF, $\langle M \rangle$ is
a unique PCAF (up to $\equi{m}$-equivalence) such that $((M_t^2 - \langle M \rangle_t),\Ft,\Pxx)$ is a martingale.
We call the process $\langle M \rangle$ the \emph{sharp bracket} (or \emph{predictable quadratic variation}) of $\Mt$.
For more details, we refer to Section~A.3 of \cite{fot}. See also Section~4 of \cite{Trutnau} and Th\'eor\`eme~3 in Meyer \cite[III]{Meyer}.

The \emph{square bracket} of the process $\Mt$, denoted by $[M]$, may be defined by
\begin{align*}
    [M]_t := \langle M^c \rangle_t + \sum_{s\le t} \Delta M^2_s,
\end{align*}
where $\Delta X_t := X_t - X_{t-}$ and $M^c_t$ is the continuous part of $\Mt$; see (A.3.6) in \cite{fot}.
Observe that $[M]_t=\langle M \rangle_t$ for continuous $\Mt$.



Let $1\le p<\infty$. The Burkholder--Davies--Gundy inequality states that:
\begin{align}
\label{sim:bdg}
 \Ev_x |M_T|^p \asymp \Ev_x([M]_T)^{p/2},
 \quad
 T>0, x\in E_\Cem.
\end{align}
It should be noted that, in general, the square bracket $[M]$ cannot be replaced by the sharp bracket $\langle M \rangle$. However, as demonstrated in Lenglart, L\'{e}pingle, and Pratelli \cite[Remarque~4.2]{llp} and Barlow, Jacka, and Yor \cite[(4.b’), Table~4.1, p.~162]{bjy}, the following one-sided estimates hold: if $2\le p\le \infty$, then
\begin{align}
\label{eq:brackets-}
 \Ev_x (\langle M \rangle_t)^{p/2} & \lesssim \Ev_x ([M]_t)^{p/2},
 \quad
 t>0, x\in E_\Cem,
\end{align}
and, when $1\le p \le 2$,
\begin{align}\label{eq:brackets+}
 \Ev_x ([M]_t)^{p/2} & \lesssim \Ev_x (\langle M \rangle_t)^{p/2}
 \quad
 t>0, x\in E_\Cem.
\end{align}

\section{Sharp bracket of parabolic martingale}
\label{sec:Sharp_bracket}

Fix $T > 0$ and $f\in\LpE$.
In the present article, we consider the so\nobreakdash-called \emph{parabolic martingale}:
\begin{align}
\label{eq:Mt}
    M_t  := P_{(T-t)\vee 0}f(X_{t\wedge T}) - P_T f(X_0).
\end{align}
The process $\Mt$ is a martingale $P_{T-t}f(X_t) - P_T f(X_0)$ starting at zero and stopped at $T$ with
$M_t = f(X_T) - P_T f(X_0)$ for $t\ge T$.

The parabolic martingale was first used in Ba{\~n}uelos and M{\'e}ndez-Hern{\'a}ndez~\cite{bm} for Brownian motion to obtain $L^p$-estimates for the {Beurling}--{Ahlfors} operator.
Further applications may be found in Applebaum and Ba{\~n}uelos~\cite{ab} and Ba{\~n}uelos and Bogdan~\cite{bb} where more general L{\'e}vy processes are considered.
See also \cite{bkp}, where the parabolic martingale was used to derive the Hardy--Stein identity in Orlicz spaces.

The main result of this section is the following relation between the sharp bracket of the martingale $\Mt$ and the carr\'{e} du champ operator $\Gamma$:
\begin{align}
    \label{eq:sharpMt}
    \langle M \rangle_t
    \equi{m}
    \int\limits_0^{t\wedge T} 2\Gamma [P_{T-s}f](X_s) \dss
    =
    \int\limits_0^{t\wedge T} \intEXs (P_{T-s}f(y) - P_{T-s}f(X_s))^2 \,J(X_s,\dy)\ds
    ,
\end{align}
when the function $f$ belongs to $\DE$; see Corollary~\ref{cor:sharpMt} below. Here, $\equi{\excm}$ is the equivalence relation defined by \eqref{eq:AFeq} and $\Gamma$ is given by \eqref{eq:carre}.
This result generalizes Lemma~3.1 of \cite{lw}, which requires some continuity assumption on the semigroup $\Pt$.
While the main idea of the proof remains the same, omitting the mentioned assumption requires employing the Revuz correspondence for certain functionals.

\begin{rem}
    We would like to clarify certain inaccuracies that have appeared in the literature in the context of identity \eqref{eq:sharpMt}.
    Since the process is pure-jump, the martingale $\Mt$ is not continuous in general and $[M]\neq\langle M \rangle$, hence the same statement does not hold for the square bracket $[M]$.
    While the sharp bracket $\langle M \rangle$ admits a continuous version, the same assertion cannot be assumed for $\Mt$, as was done in \cite[Proof of Lemma~3.1]{lw}. Due to this error, the authors conclude \eqref{eq:sharpMt} with $\langle M \rangle$ replaced by $[M]$; see \cite[(3.2)]{lw}.

    The same incorrect equation appears in \cite{bbl} for $\Xt$, assuming it is a pure-jump L{\'e}vy process; see the first displayed equation on page 471 therein. The authors refer to \cite{ab}, where the following identity is displayed; see \cite[(3.4)]{ab}. Rewriting it to our context,
    \begin{align*}
        [ M ]_t
        =
        \int\limits_0^{t\wedge T} \intRn (P_{T-s}f(X_{s-}+y) - P_{T-s}f(X_{s-}))^2 \,\tilde{N}(\ds,\dy)
        ,
    \end{align*}
    where $\tilde{N}$ is a compensated Poisson random measure of $\Xt$. This identity is an application of It\^o's formula. The authors of \cite{bbl} incorrectly rewrite the above equation in the form of \eqref{eq:sharpMt} with $\langle M \rangle$ replaced by $[M]$.

    Nevertheless, we want to stress that the mentioned inaccuracies do not affect the correctness of the main results of \cite{bbl} and \cite{lw}. Due to estimates \eqref{eq:brackets-} and \eqref{eq:brackets+}, the reasoning in \cite{bbl} can be easily corrected. The main result of \cite{lw}, however, remains irreparable due to a different issue; see Remark~\ref{rem:GlessH} below.
\end{rem}

Let us return to the discussion of the proof of the relation \eqref{eq:sharpMt}.
Since the martingale $\Mt$ is not an additive functional, we cannot apply the Revuz correspondence directly. Nevertheless, its time\nobreakdash-space counterpart is an additive functional:
\begin{align}
\label{eq:Mt-sp-tim}
    \st{M}_t(\tau,\omega)
    :=
    \begin{cases}
        P_{T-\tau-t} f(X_t(\omega)) - P_{T-\tau}f(X_0(\omega)) & \text{if } t+\tau\le T, \\
        f(X_{T-\tau}(\omega)) - P_{T-\tau}f(X_0(\omega)) & \text{if } \tau\le T <t+\tau, \\
        0 & \text{if } T <\tau.
    \end{cases}
\end{align}
Writing compactly,
\begin{align*}
    \st{M}_t(\tau,\omega)
    =
    P_{(T-\tau-t)\vee 0} f(X_{[t\wedge(T-\tau)]\vee 0}(\omega))
    -
    P_{(T-\tau)\vee 0} f(X_0(\omega)).
\end{align*}
Note that $\langle \st{M} \rangle$ is a PCAF.
Observe that $\st{M}_t(0,\cdot) = M_t$ and $\st{M}_0=0$.

We begin by showing that $\st{M}$ is indeed a martingale. 
\begin{prop}
    The process $\st{M}=((\st{M}_t),(\st{\F}_t),(\st{\Prb}_{(t_0,x)})$ given by \eqref{eq:Mt-sp-tim} is a martingale.
\end{prop}
\begin{proof}
    According to the fact that $\st{M}$ is the process $P_{T-\tau-t} f(X_t) - P_{T-\tau}f(X_0)$ stopped at $t=T-\tau$, it is enough to consider $t+\tau\le T$.
    Employing the Markov property of the Hunt process $\Xt$, we have
    \begin{align}
    \label{eq:MarkovProp-Pt}
        P_{T-t_0-t} f(X_t) = \Ev_{X_t} f(X_{T-t_0-t})
        =
        \Ev_x [f(X_{T-t_0})|\F_t],
        \quad
        \Px\text{-a.s.}
    \end{align}
    for all $x\in E_\Cem$. Let $0\le s\le t\le T-t_0$. Due to \eqref{eq:E-sp-tim} and \eqref{eq:MarkovProp-Pt},
    \begin{align*}
        \Ev_{(t_0,x)} [\st{M}_t | \st{\F}_s]
        &=
        \Ev_x [ P_{T-t_0-t} f(X_t)| \F_s] - P_{T-t_0}f(x)
        \\
        &=
        \Ev_x [ \Ev_x [f(X_{T-t_0})|\F_t]| \F_s] - P_{T-t_0}f(x)
        \\
        &=
        \Ev_x [ f(X_{T-t_0})| \F_s] - P_{T-t_0}f(x),
        \quad
        \Prb_{(t_0,x)}\text{-a.s.}
    \end{align*}
    Again, by \eqref{eq:MarkovProp-Pt},
    \begin{align*}
        \Ev_x [ f(X_{T-t_0})| \F_s] - P_{T-t_0}f(x)
        =
        P_{T-t_0-s} f(X_s) -  P_{T-t_0}f(x)
        =
        \st{M}_s,
        \quad
        \Prb_{(t_0,x)}\text{-a.s.}
    \end{align*}
    Since $x\in E_\Cem$ and $t_0>0$ were chosen arbitrarily, the proof is complete.
\end{proof}

We are ready to prove the main theorem of this section.

\begin{thm}
\label{thm:sharpMt}
    Let $f\in\DE$. Let $\st{M}$ be the martingale given by \eqref{eq:Mt-sp-tim}. Then
    \begin{align}
    \label{eq:At}
        \langle \st{M} \rangle_t
        \equi{\dr \otimes m}
        \int\limits_0^t 2\Gamma [P_{T-\tau-s}f](X_s(\omega)) \ind_{(0,T]}(\tau+s) \dss,
    \end{align}
    where $\Gamma$ is the carr\'{e} du champ operator given by \eqref{eq:carre} and $\equi{\excm}$ is the equivalence relation defined by \eqref{eq:AFeq}.
\end{thm}
\begin{proof}
    Observe that the additive functional on the right-hand side of \eqref{eq:At} takes the form \eqref{eq:AtInt} with $\st{X}_s$ and
    $g(t,x):=2\Gamma [P_{T-t}f](x) \ind_{(0,T]}(t)$. Therefore, its Revuz measure is
    \begin{align*}
        2\Gamma [P_{T-t}f](x) \ind_{(0,T]}(t) m(\dx)\dt.
    \end{align*}

    We denote by $\nu$ the Revuz measure of $\langle\st{M}\rangle$ and take an arbitrary bounded $\alpha$\nobreakdash-coexcessive function $\hat{f}$ with respect to the space-time process $\Xbrevet$.
    By applying \eqref{eq:RevuzST} and \eqref{eq:sharp_square}, we derive
    \begin{align}
    \label{eq:sharpMt-proof-0}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{f} \,\dd \nu
        &=
        \lim_{h\to0^+}
        \frac{1}{h}
        \int\limits_0^\inft \intE \hat{f}(t,x)
        \Ev_{(t,x)}
            \langle\st{M}\rangle_h
        \,m(\dx)\dt
        \\ \notag
        &=
        \lim_{h\to0^+}
        \frac{1}{h}
        \int\limits_0^\inft \intE \hat{f}(t,x)
        \Ev_{(t,x)}
            \st{M}_h^2
        \,m(\dx)\dt.
    \end{align}

    If $h+t\le T$, then
    $\Ev_x P_{T-t-h}f(X_h)=P_hP_{T-t-h}f(x) = P_{T-t}f(x)$. Hence, by \eqref{eq:E-sp-tim},
    \begin{align}
    \label{eq:sharpMt-proof-1}
        \Ev_{(t,x)} \st{M}_h^2
        &=
        \Ev_x \st{M}_h^2(t,\cdot)
        =
        \Ev_x (P_{T-t-h}f(X_h))^2 - 2 P_{T-t}f(x) \Ev_x P_{T-t-h}f(X_h)
        +
        (P_{T-t}f(x))^2
        \notag \\
        &=
        P_h [(P_{T-t-h}f)^2](x)
        -
        (P_{T-t}f(x))^2.
    \end{align}
    Moreover, by Lemma~\ref{lem:difPtPTmtf2},
    we get
    \begin{align}
    \label{eq:sharpMt-proof-2}
        P_h [(P_{T-t-h}f)^2]
        -
        (P_{T-t}f)^2
        &=
        \int\limits_0^h 2P_s(\Gamma[P_{T-t-s}f]) \dss
        \\ \notag
        &=
        h \int\limits_0^1 2P_{hs}(\Gamma[P_{T-t-hs}f]) \dss.
    \end{align}
    Here, the integral on the right\nobreakdash-hand side is understood in the Bochner sense in $\LE{1}$.

    Similarly, when $t\le T <h+t$,
    \begin{align}
    \label{eq:sharpMt-proof-1.2}
        \Ev_{(t,x)} \st{M}_h^2
        &=
        P_{T-t} [f^2](x)
        -
        (P_{T-t}f(x))^2
    \end{align}
    and
    \begin{align}
    \label{eq:sharpMt-proof-2.2}
        P_{T-t} [f^2]
        -
        (P_{T-t}f)^2
        &=
        \int\limits_0^{T-t} 2P_s(\Gamma[P_{T-t-s}f]) \dss
        \\ \notag
        &=
        h \int\limits_0^1 2P_{hs}(\Gamma[P_{T-t-hs}f]) \ind_{[0,T-t]}(hs) \dss.
    \end{align}

    Obviously, $\Ev_{(t,x)} \st{M}_h^2=0$ for $T <t$.

    Combining \eqref{eq:sharpMt-proof-0}, \eqref{eq:sharpMt-proof-1}, \eqref{eq:sharpMt-proof-2}, \eqref{eq:sharpMt-proof-1.2}, and \eqref{eq:sharpMt-proof-2.2}, we can write
    \begin{align*}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{f} \,\dd \nu
        &=
        \lim_{h\to0^+}
        \int\limits_0^T \intE \hat{f}(t,\cdot)
        \int\limits_0^1
        2P_{hs}(\Gamma[P_{T-t-hs}f])
        \times \\
        &\quad\times
        \left[
            \ind_{(0,T-h]}(t) + \ind_{[0,T-t]}(hs)\ind_{(T-h,T]}(t)
        \right]
        \,\ds\dm\dt
        \\
        &=
        \lim_{h\to0^+}
        \int\limits_0^T
        \int\limits_0^1
        \intE 2 \hat{f}(t,\cdot)
        P_{hs}(\Gamma[P_{T-t-hs}f])
        \times \\
        &\quad\times
        \left[
            \ind_{(0,T-h]}(t) + \ind_{[0,T-t]}(hs)\ind_{(T-h,T]}(t)
        \right]
        \dms\ds\dt.
    \end{align*}
    The above follows from an application of Tonelli's theorem.
    Note that if $t\in(0,T-h]$, then $t\leq T-h \leq T-hs$, hence $\ind_{[0,T-t]}(hs)=1$.
    Therefore, for all $t\in(0,T]$ we have
    $\ind_{(0,T-h]}(t) + \ind_{[0,T-t]}(hs)\ind_{(T-h,T]}(t) = \ind_{[0,T-t]}(hs)$.
    Now, we claim that
    \begin{align*}
        \lim_{h\to0^+}
        \int\limits_0^T
        \int\limits_0^1
        &\intE 2 \hat{f}(t,\cdot)
        P_{hs}(\Gamma[P_{T-t-hs}f])
        \ind_{[0,T-t]}(hs)
        \dms\ds\dt
        \\
        &=
        \int\limits_0^T
        \int\limits_0^1
        \lim_{h\to0^+}
        \intE 2 \hat{f}(t,\cdot)
        P_{hs}(\Gamma[P_{T-t-hs}f])
        \dms
        \ind_{[0,T-t]}(hs)
        \dss\dt.
    \end{align*}
    For all sufficiently small $h\ge0$, due to the boundedness of $\hat{f}$,
    \begin{align*}
        \intE 2 \hat{f}(t,\cdot)
        P_{hs}(\Gamma[P_{T-t-hs}f])
        \dms
        &\le
        2
        \intE
        \Gamma[P_{T-t-hs}f]
        \dms
        \sup_{(r,x)\in(0,T]\tim E} \abs{\hat{f}(r,x)}
        \\
        &=
        2
        \E[
        P_{T-t-hs}f
        ]
        \sup_{(r,x)\in(0,T]\tim E} \abs{\hat{f}(r,x)}
        \\
        &\le
        2
        \E[f]
        \sup_{(r,x)\in(0,T]\tim E} \abs{\hat{f}(r,x)}
        <
        \inft.
    \end{align*}
    At this point, we made use of the assumption that $f\in\DE$. The dominated convergence theorem implies our claim.

    Lemma~\ref{lem:difPtPTmtf2} states that the mapping $[0,T-t)\ni r\mapsto P_{r}(\Gamma[P_{T-t-r}f])\in\LE{1}$ is continuous. Thus, $P_{hs}(\Gamma[P_{T-t-hs}f])\to\Gamma[P_{T-t}f]$ in $\LE{1}$ as $h\to0^+$. Hence,
    \begin{align*}
        \lim_{h\to0^+}
        \intE 2 \hat{f}(t,\cdot)
        P_{hs}(\Gamma[P_{T-t-hs}f])
        \dms
        =
        \intE 2 \hat{f}(t,\cdot)
        \Gamma[P_{T-t}f]
        \dms.
    \end{align*}
    Clearly,
    $
        \ind_{[0,T-t]}(hs)
        \to
        1
    $
    for every $t\in(0,T]$ as $h\to0^+$.

    Following the above observations, we obtain
    \begin{align*}
        \int\limits_{\mathclap{(0,\inft)\tim E}} \hat{f} \,\dd \nu
        &=
        \int\limits_0^T
        \int\limits_0^1
        \intE 2 \hat{f}(t,\cdot)
        \Gamma[P_{T-t}f]
        \dms
        \ds\dt
        \\
        &=
        \int\limits_0^\inft
        \intE
        \hat{f}(t,x)\cdot 2\Gamma[P_{T-t}f](x) \ind_{(0,T]}(t) \,m(\dx)\dt.
    \end{align*}

    The above identity can be extended to any non\nobreakdash-negative $\hat{f}\in\C_c((0,\inft)\tim E)$. Indeed, $\hat{f}$ can be approximated by the bounded $n$\nobreakdash-coexcessive functions
    $\hat{f}_n:=n\hat{R}_n \hat{f}$, where
    $\hat{R}_n$ is the coresolvent of the space-time process $(\st{X}_t)_{t\ge0}$.
    Since $\hat{f}_n\to\hat{f}$ in $\LE{2}$ as $n\to\inft$,
    there exists a subsequence $(\hat{f}_{n_k})_{k\in\N}$ such that $\hat{f}_{n_k}\to\hat{f}$ almost everywhere as $k\to\inft$.

    Finally, since $\hat{f}$ is arbitrary non\nobreakdash-negative function in $\C_c((0,\inft)\tim E)$, we obtain the following equality of the Revuz measures:
    \begin{align*}
        \nu(\dt,\dx) = 2\Gamma [P_{T-t}f](x) \ind_{(0,T]}(t) m(\dx)\dt
        .
    \end{align*}
    The statement of the theorem follows from the uniqueness of the PCAF with a given Revuz measure.
\end{proof}

With the above theorem at hand, due to the fact that $\langle \st{M} \rangle_t(0,\cdot) = \langle M\rangle_t$, we obtain the desired result.

\begin{cor}
\label{cor:sharpMt}
    Let $f\in\DE$. Let $\Mt$ be the martingale given by \eqref{eq:Mt}. Then the equivalence~\eqref{eq:sharpMt} holds.
\end{cor}


\section{Square functions}
\label{sec:square_fun}

\subsection{Square function $G$}

Our starting point is the following square function:
\begin{align*}
    G(x) =
    \left(
        \int\limits_0^\inft \Gamma [P_tf](x) \dts
    \right)^{1/2}.
\end{align*}
It does not possess the desired boundedness of $p$\nobreakdash-norm for all $1<p<\infty$. In \cite{bbl}, it was shown that for the Dirichlet form corresponding to the Cauchy process, the square function $G$ may be too large for certain $f \in \LpE$ with $1 < p < 2$; see \cite[Example~2]{bbl}.
As we will see later in Subsection~\ref{sub:H_func}, the square function $H$ is affected by the same problem; see Example~\ref{cex:Cauchy2} below. This is the reason for working with the operator $\Gampri$ instead of $\Gamma$.

However, the authors of \cite{bbl} demonstrated that $\normLp{G} \asymp \normLp{f}$ for $2 < p < \infty$ in the context of symmetric L{\'e}vy processes in the Euclidean space. These results were later extended to the non-symmetric case by Ba{\~n}uelos and Kim in \cite{bk}.

For the broader class of processes considered here, the lower bound for $\normLp{G}$ remains valid when $2 < p < \infty$. As shown in the next subsection, the Hardy\nobreakdash--Stein identity leads to the following result.
\begin{prop}
    Impose Assumption~\ref{ass:SS}.
    Let $2<p<\infty$ and $f\in\LpE$. Then,
    \begin{align*}
        \normLp{f} \lesssim \normLp{G} .
    \end{align*}
\end{prop}
The above results follow directly from $\widetilde{G} \le \sqrt{2} G$ and the estimate for $\widetilde{G}$, which is provided in Theorem~\ref{thm:Gprim_less_2inf} below.

\subsection{Square function $\widetilde{G}$}
\label{sub:Gprim_func}

Let us now consider the following square function:
\begin{align*}
    \widetilde{G}(x) & := 
    \left(
        \int\limits_0^\inft \Gampri[P_tf](x) \dts 
    \right)^{1/2}
    .
\end{align*}

The square function $\widetilde{G}$ overcomes the unboundedness issue for $1<p<2$ raised in Example~2 of \cite{bbl}. By employing the Hardy\nobreakdash--Stein identity, we deduce the following two estimates.

\begin{thm}
\label{thm:Gprim_less_12}
    Let $1<p\le2$ and $f\in\LpE$. Then,
    \begin{align*}
        \normLp{\widetilde{G}} \lesssim \normLp{f}.
    \end{align*}
\end{thm}
\begin{thm}
\label{thm:Gprim_less_2inf}
    Impose Assumption~\ref{ass:SS}.
    Let $2\le p<\infty$ and $f\in\LpE$. Then,
    \begin{align*}
        \normLp{f} \lesssim \normLp{\widetilde{G}} .
    \end{align*}
\end{thm}

In the next two proofs, we repeat mainly the argument used in \cite[Proofs of Lemma~4.3 and Lemma~4.5]{bbl}.

\begin{proof}[Proof of Theorem~\ref{thm:Gprim_less_12}.]
    Denote $f^*(x):=\sup_{t\ge0}|P_tf(x)|$. Since $p\le2$,
    \begin{align*}
         (\widetilde{G}(x))^2
         & =
         \int\limits_0^\inft \Gampri[P_tf](x) \dt
         \\
         & =
         (f^*(x))^{2 - p} \int\limits_0^\inft \Gampri[P_tf](x) |f^*(x)|^{p - 2} \dts
         \\
         & \le
         (f^*(x))^{2 - p} \int\limits_0^\inft \Gampri[P_tf](x) |P_tf(x)|^{p - 2} \dts .
    \end{align*}
    By Hölder's inequality, inequality \eqref{neq:HS_12_bezSS}, and Stein's maximal theorem~\eqref{neq:Stein},
    \begin{align*}
         \intE (\widetilde{G}(x))^p\,m(\dx)
         & \le
         \intE (f^*(x))^{(2 - p) p / 2} \left(\int\limits_0^\inft \Gampri[P_tf](x) |P_tf(x)|^{p - 2} \dts\right)^{p / 2}\,m(\dx)
         \\
         & \le
         \left(\intE (f^*(x))^p\,m(\dx)\right)^{1 - p / 2} \left(\int\limits_0^\inft  \intE \Gampri[P_tf](x) |P_tf(x)|^{p - 2}\,m(\dx)\dt \right)^{p / 2} \\
         & \lesssim
         \left(\intE (f^*(x))^p\,m(\dx)\right)^{1 - p / 2} \left(\intE |f(x)|^p\,m(\dx) \right)^{p / 2} \\
         & \asymp
         \intE |f(x)|^p\,m(\dx) .
    \end{align*}
    Therefore,
    \begin{align*}
     \intE (\widetilde{G}(x))^{p}\,m(\dx) & \lesssim \intE |f(x)|^p\,m(\dx) .
    \end{align*}
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:Gprim_less_12}.]
    Denote $f^*(x):=\sup_{t\ge0}|P_tf(x)|$.
    Due to the strong stability of the semigroup, estimate~\eqref{sim:HS_2pinf} is valid.
    By this, Hölder's inequality, and Stein's maximal theorem~\eqref{neq:Stein}, we obtain
    \begin{align*}
     \intE |f(x)|^p\,m(\dx) & \asymp \int\limits_0^\inft  \intE \Gampri[P_tf](x) |P_tf(x)|^{p - 2}\,m(\dx)\dt \\
     & \le \int\limits_0^\inft \intE \Gampri[P_tf](x) |f^*(x)|^{p - 2}\,m(\dx)\dt  \\
     & = \intE (\widetilde{G}(x))^2 |f^*(x)|^{p - 2}\,m(\dx) \\
     & \le \left(\intE (\widetilde{G}(x))^{p}\,m(\dx)\right)^{2/p} \left(\intE |f^*(x)|^p\,m(\dx)\right)^{1 - 2/p} \\
     & \asymp \left(\intE (\widetilde{G}(x))^{p}\,m(\dx)\right)^{2/p} \left(\intE |f(x)|^p\,m(\dx)\right)^{1 - 2/p} .
    \end{align*}
    This proves the desired inequality:
    \begin{align*}
     \intE |f(x)|^p\,m(\dx) & \lesssim \intE (\widetilde{G}(x))^{p}\,m(\dx) .
    \end{align*}
\end{proof}

When the Dirichlet form corresponds to the pure\nobreakdash-jump L\'evy process, then the square function $\widetilde{G}$ possesses the both-side $L^p$-estimates for the entire range of $1<p<\infty$, as shown in Section~4 of \cite{bbl}.
However, this does not hold in general, as demonstrated in Example~\ref{cex:Brown} below.
Before we move on to this example, we would like to make some comments on the conclusions derived from it.
\begin{rem}
\label{rem:GlessH}
    The result below shows that the statement of Theorem~3.4 in \cite{lw} is not valid. The problem lies in the proof of Lemma~3.3, where the inequality $G(x)\le \sqrt{2}H(x)$ is stated.
    It was incorrectly assumed that $P_t[P_tf(k(\cdot,y))](x)$ is equal to $P_{2t}f(k(x,y))$ for some function $k$; see assumption~(A4) therein.
    This statement may be true, in the case of $E=\Rn$, $k(x+y)=x+y$, and translationally invariant semigroup $\Pt$, as shown in the proof of Lemma~4.2 in \cite{bbl}.
    Nevertheless, the following calculations confirm that this error is irreparable in general.
\end{rem}

\begin{ex}[Brownian motion on interval with removed segment]
\label{cex:Brown}
    The present example was proposed by Mateusz Kwaśnicki. The goal is to demonstrate that, for $2<p<\infty$, there is generally no uniform constant $C_p$ satisfying
    $\normLp{\widetilde{G}} \le C_p \normLp{f}$ for all $f\in\LpE$. Consequently, the same conclusion applies to the function $G$.

    \emph{Idea.}
        We construct a discrete approximation of the reflected Brownian motion on the interval $[0, \tfrac{\pi}{4}] \cup [\tfrac{3\pi}{4}, \pi]$ with additional jumps between $\tfrac{\pi}{4}$ and $\tfrac{3\pi}{4}$. The intensity of the jumps are chosen so that the function $\cos x$ becomes an eigenfunction of the generator.

        In other words, this process is an approximation of the reflected Brownian motion in $[0, \pi]$, but with segments of paths lying on the part $(\tfrac{\pi}{4}, \tfrac{3\pi}{4})$ deleted.

        By the approximation, we mean the following process:
        a Markov chain with continuous time
        which can be viewed as a reflected symmetric nearest-neighbor random walk $\Xt$ on $\{1, 2, \ldots, 4 n\}$, with parts of paths corresponding to $\{(t,X_t) : X_t \in \{n + 1, n + 2, \ldots, 3 n\}\}$ removed.

        To work with the standard notation for the generator matrix of a Markov chain, we reindex the state space:
        we shift the states $3 n + 1, 3 n + 2, \ldots, 4 n$ to the left and call them $n + 1, n + 2, \ldots, 2 n$.
        Therefore, $E = \{1, 2, \ldots, 2n\}$. The space $E$ is equipped with the counting measure $m$.



    \emph{Generator.}
        The generator of the process $\Xt$ is expressed as the following $2n \times 2n$ matrix $A=[a_{i,j}]_{i,j=1}^{2n}$:

        \begin{align*}
        A = \left(
        \setlength{\arraycolsep}{2pt}
        \begin{array}{*{14}{c}}
            -1 & 1 & 0 & 0 & \cdots & 0 & 0 & 0 & 0 & \cdots & 0 & 0 & 0 & 0 \\
            1 & -2 & 1 & 0 & \cdots & 0 & 0 & 0 & 0 & \cdots & 0 & 0 & 0 & 0 \\
            0 & 1 & -2 & 1 & \cdots & 0 & 0 & 0 & 0 & \cdots & 0 & 0 & 0 & 0 \\
            0 & 0 & 1 & -2 & \cdots & 0 & 0 & 0 & 0 & \cdots & 0 & 0 & 0 & 0 \\
            \vdots & \vdots & \vdots & \vdots & \ddots & \vdots & \vdots & \vdots & \vdots & \ddots & \vdots & \vdots & \vdots & \vdots \\
            0 & 0 & 0 & 0 & \cdots & -2 & 1 & 0 & 0 & \cdots & 0 & 0 & 0 & 0 \\
            0 & 0 & 0 & 0 & \cdots & 1 & \alpha^*_n & \alpha_n & 0 & \cdots & 0 & 0 & 0 & 0 \\
            0 & 0 & 0 & 0 & \cdots & 0 & \alpha_n & \alpha^*_n & 1 & \cdots & 0 & 0 & 0 & 0 \\
            0 & 0 & 0 & 0 & \cdots & 0 & 0 & 1 & -2 & \cdots & 0 & 0 & 0 & 0 \\
            \vdots & \vdots & \vdots & \vdots & \ddots & \vdots & \vdots & \vdots & \vdots & \ddots & \vdots & \vdots & \vdots & \vdots \\
            0 & 0 & 0 & 0 & \cdots & 0 & 0 & 0 & 0 & \cdots & -2 & 1 & 0 & 0 \\
            0 & 0 & 0 & 0 & \cdots & 0 & 0 & 0 & 0 & \cdots & 1 & -2 & 1 & 0 \\
            0 & 0 & 0 & 0 & \cdots & 0 & 0 & 0 & 0 & \cdots & 0 & 1 & -2 & 1 \\
            0 & 0 & 0 & 0 & \cdots & 0 & 0 & 0 & 0 & \cdots & 0 & 0 & 1 & -1
        \end{array}\right), %\normalsize
        \end{align*}
        where
        \begin{align*}
            \alpha_n & := \frac{1}{1 + \cot \tfrac{\pi}{8 n}}
        \end{align*}
        and
        $\alpha^*_n:=-1-\alpha_n$.
        In other words, the jumping kernel is given by
        $J(x,\dy) = J(x,y) m(\dy)$ and
        $J(i,j) := a_{i,j}$ for $i\neq j$, where
        \begin{align*}
            a_{i,j}
            =
            \begin{cases}
                1 & \text{when } |i-j|=1 \text{ and } \{i,j\}\neq\{n,n+1\}, \\
                \alpha_n & \text{when } \{i,j\}=\{n,n+1\}, \\
                0 & \text{when } |i-j|>1 .
            \end{cases}
        \end{align*}
        The jumping density $J(x,y)$ is illustrated in Figure \ref{fig:jumps} below.

    \begin{figure}[h]
    \centering
        \begin{tikzpicture}[scale=1.8]
        \small
            % Oś pozioma
            \draw[->] (-0.3,0) -- (8.3,0) node[right] {$x$};

            % Zaznaczenia na osi
            \draw (0,0) -- (0,-0.11) node[below] {$0$};
            \draw (2,0) -- (2,-0.11) node[below] {$\frac{\pi}{4}$};
            \draw (6,0) -- (6,-0.11) node[below] {$\frac{3\pi}{4}$};
