    \emph{Eigenfunction.}
    We consider the following function on $E$:
    \begin{align*}
        f(k) & := \begin{cases}
          \cos \tfrac{(2 k - 1) \pi}{8 n} & \text{if } k \le n , \\
          \cos \tfrac{(2 k - 1 + 4 n) \pi}{8 n} & \text{if } k > n .
         \end{cases}
    \end{align*}

    Now, we will show that $f$ is an eigenfunction of $A$, namely
    \begin{align*}
        A f(k) = -\lambda_n f(k),
    \end{align*}
    where
    \begin{align*}
        \lambda_n := 2 (1 - \cos \tfrac{\pi}{4 n}) = 4 \sin^2 \tfrac{\pi}{8 n} .
    \end{align*}
    Observe that $f(2 n + 1 - k) = -f(k)$ and $A f(2 n + 1 - k) = -A f(k)$, hence it is enough to consider $k \le n$.
    By the sum-to-product formula, for $k = 2, 3, \ldots, n - 1$, we get
    \begin{align*}
        A f(k) & = f(k + 1) + f(k - 1) - 2 f(k) \\
        & = \cos \tfrac{(2 k + 1) \pi}{8 n} + \cos \tfrac{(2 k - 3) \pi}{8 n} - 2 \cos \tfrac{(2 k - 1) \pi}{8 n} \\
        & = 2 \cos \tfrac{(2 k - 1) \pi}{8 n} \cos \tfrac{\pi}{4 n} - 2 \cos \tfrac{(2 k - 1) \pi}{8 n} = -\lambda_n f(k) .
    \end{align*}
    Similarly, for $k = 1$
    \begin{align*}
        A f(1) & = f(2) - f(1) \\
        & = \cos \tfrac{3 \pi}{8 n} - \cos \tfrac{\pi}{8 n} \\
        & = \cos \tfrac{3 \pi}{8 n} + \cos \tfrac{-\pi}{8 n} - 2 \cos \tfrac{\pi}{8 n}
        \\
        &=
        2\cos\tfrac{\pi}{8n}\cos\tfrac{\pi}{4n}
        -
        2 \cos \tfrac{\pi}{8 n}.
    \end{align*}
    Thus, again $A f(1) = -\lambda_n f(1)$. Finally, when $k = n$, we have
    \begin{align*}
        A f(n) & = \alpha_n (f(n + 1) - f(n)) + (f(n - 1) - f(n)) \\
        & = \alpha_n (\cos \tfrac{(6 n + 1) \pi}{8 n} - \cos \tfrac{(2 n - 1) \pi}{8 n}) + \cos \tfrac{(2 n - 3) \pi}{8 n} - \cos \tfrac{(2 n - 1) \pi}{8 n} \\
        & = -2 \alpha_n \cos \tfrac{(2 n - 1) \pi}{8 n} + 2 \sin \tfrac{(n - 1) \pi}{4 n} \sin \tfrac{\pi}{8 n} \\ 
        & = 2 \left(-\alpha_n + \frac{\sin \tfrac{(n - 1) \pi}{4 n} \sin \tfrac{\pi}{8 n}}{\cos \tfrac{(2 n - 1) \pi}{8 n}}\right) \cos \tfrac{(2 n - 1) \pi}{8 n} .
    \end{align*}
    Note that the parameter $\alpha_n$ is chosen so that the right-hand side is equal to $-\lambda_n f(n)$. Indeed,
    \begin{align*}
        & \left(-\alpha_n + \frac{\sin \tfrac{(n - 1) \pi}{4 n} \sin \tfrac{\pi}{8 n}}{\cos \tfrac{(2 n - 1) \pi}{8 n}} \right) \\
        & \qquad = \frac{-\sin \tfrac{\pi}{8 n}}{\sin \tfrac{\pi}{8 n} + \cos \tfrac{\pi}{8 n}} + \frac{\tfrac{\sqrt{2}}{2} (\cos \tfrac{\pi}{4 n} - \sin \tfrac{\pi}{4 n}) \sin \tfrac{\pi}{8 n}}{\tfrac{\sqrt{2}}{2} (\cos \tfrac{\pi}{8 n} + \sin \tfrac{\pi}{8 n})} \\
        & \qquad = -\frac{(1 - \cos \tfrac{\pi}{4 n} + \sin \tfrac{\pi}{4 n}) \sin \tfrac{\pi}{8 n}}{\cos \tfrac{\pi}{8 n} + \sin \tfrac{\pi}{8 n}} \\
        & \qquad = -\frac{(2 \sin^2 \tfrac{\pi}{8 n} + 2 \sin \tfrac{\pi}{8 n} \cos \tfrac{\pi}{8 n}) \sin \tfrac{\pi}{8 n}}{\cos \tfrac{\pi}{8 n} + \sin \tfrac{\pi}{8 n}} \\
        & \qquad = -2 \sin^2 \tfrac{\pi}{8 n} = -\frac{\lambda_n}{2} \, .
    \end{align*}

    \emph{Square functions.}
    According to the earlier part, since $f$ is an eigenfunction of the generator $A$,
    the semigroup operator $P_t$ acting on $f$ is given by
    $P_t f(k) = e^{-\lambda_n t} f(k)$.
    Recall that the square function $\widetilde{G}$ for the function $f$ is given by
    \begin{align*}
        (\widetilde{G}(x))^2 = \int\limits_0^\infty \intEx (P_t f(y) - P_t f(x))^2 \chi(P_tf(x),P_tf(y))
        \,J(x, y) m(\dy) \dt.
    \end{align*}
    Since $\int_0^\inft e^{-\lambda_n t} \dts= 1/\lambda_n$ and $m$ is the counting measure, we may write
    \begin{align*}
        (\widetilde{G}(k))^2 & = \frac{1}{\lambda_n} \sum_{l \ne k} (f(l) - f(k))^2 \chi(f(k),f(l)) J(k, l) .
    \end{align*}
    Moreover, $\widetilde{G}(2 n + 1 - k) = \widetilde{G}(k)$.
    When $k = 1, 2, \ldots, n - 1$, we have $0<f(k+1)<f(k)$ and
    \begin{align*}
        (\widetilde{G}(k))^2 & = \frac{1}{\lambda_n} (f(k + 1) - f(k))^2 = \frac{4 (\sin \tfrac{k \pi}{4 n} \sin \tfrac{\pi}{8 n})^2}{4 \sin^2 \tfrac{\pi}{8 n}} = \sin^2 \tfrac{k \pi}{4 n} .
    \end{align*}
    Also, if $k = n$, then $|f(n)|=|f(n+1)|=-f(n)$, hence
    \begin{align*}
        (\widetilde{G}(n))^2 & = \frac{\alpha_n}{2 \lambda_n}  (f(n + 1) - f(n))^2 \\
        & =
        \frac{(2 \cos \tfrac{(2 n - 1) \pi}{8 n})^2}{8 \sin^2 \tfrac{\pi}{8 n} (1 + \cot \tfrac{\pi}{8 n})} \\
        & = \frac{(\sqrt{2} (\cos \tfrac{\pi}{8 n} + \sin \tfrac{\pi}{8 n}))^2}{8 \sin \tfrac{\pi}{8 n} (\sin \tfrac{\pi}{8 n} + \cos \tfrac{\pi}{8 n})} \\
        & = \frac{\sin \tfrac{\pi}{8 n} + \cos \tfrac{\pi}{8 n}}{4 \sin \tfrac{\pi}{8 n}} = \frac{1 + \cot \tfrac{\pi}{8 n}}{4} \, .
    \end{align*}
    Now, the $p$\nobreakdash-norm of $\widetilde{G}$ is given by
    \begin{align}
    \label{eq:cex_mateusz}
        \normLp{\widetilde{G}}^p & = 2 \sum_{k = 1}^{n - 1} \sin^p \tfrac{k \pi}{4 n} + 2 (\widetilde{G}(n))^p .
    \end{align}
    The first term may be written as
    \begin{align*}
        2 \sum_{k = 1}^{n - 1} \sin^p \tfrac{k \pi}{4 n}
        =
        2 n \sum_{k = 1}^{n} \frac{1}{n}\sin^p \tfrac{k \pi}{4 n} - 2\left(\frac{\sqrt{2}}{2}\right)^p.
    \end{align*}
    Note, that the sum on the right\nobreakdash-hand side is the Riemann sum of the function $2\sin^p \tfrac{\pi x}{4}$ over $[0,1]$.
    Therefore, the first term on the right\nobreakdash-hand side of \eqref{eq:cex_mateusz} is asymptotically equal to $c_1 n$, where $c_1 := 2 \int_0^1 \sin^p \tfrac{\pi x}{4} \dxs > 0$.


    The second term in \eqref{eq:cex_mateusz} is asymptotically equal to $2 (\tfrac{1}{4} \cdot \tfrac{8 n}{\pi})^{p/2}=2(\tfrac{2n}{\pi})^{p/2}$.
    Hence, for $p > 2$,
    \begin{align*}
         \normLp{\widetilde{G}}^p & \sim \frac{2^{1 + p/2}}{\pi^{p/2}} \, n^{p/2}.
    \end{align*}
    Particularly, we see that $\widetilde{G}(n)$ is the dominating term in the $p$\nobreakdash-norm of $\widetilde{G}$.
    On the other hand,
    \begin{align*}
         \normLp{f}^p & = 2 \sum_{k = 1}^n \cos^p \tfrac{k \pi}{4 n} \sim c_2 n ,
    \end{align*}
    where $c_2 := 2 \int_0^1 (\cos \tfrac{\pi x}{4})^p \dxs > 0$. Finally,
    \begin{align*}
        \frac{\normLp{\widetilde{G}}}{\normLp{f}} & \sim \frac{2^{1/p + 1/2}}{\pi^{1/2} c_2^{1/p}} \, n^{1/2 - 1/p} .
    \end{align*}
    This proves that for $2<p<\infty$ there is no universal constant $C_p>0$ such that
    \begin{align*}
        \normLp{\widetilde{G}} & \le C_p \normLp{f} .
    \end{align*}
    What is more, since $\widetilde{G} \le \sqrt{2} G$,  the above statement holds also for the square function $G$.
\end{ex}

\subsection{Square function $H$}
\label{sub:H_func}

The next square function we will analyze is the following:
\begin{align*}
    H(x) & :=
    \left(
        \int\limits_0^\inft P_t \Gamma [P_tf](x) \dts 
    \right)^{1/2}
    .
\end{align*}

The function $H$ overcomes the problems with $\widetilde{G}$ demonstrated for $2<p<\inft$ in Example~\ref{cex:Brown}.
Indeed, the following $L^p$-estimates hold.
\begin{thm}
\label{thm:H_less_2inf}
    Impose Assumption~\ref{ass:coserv}. Let $2\le p<\infty$ and $f\in\LpE$. Then,
    \begin{align*}
        \normLp{H} \lesssim \normLp{f}.
    \end{align*}
\end{thm}
\begin{thm}
\label{thm:H_great_12}
    Impose Assumptions~\ref{ass:coserv} and \ref{ass:SS}.
    Let $1<p\le 2$ and $f\in\LpE\cap\LE{2}$. Then,
    \begin{align*}
        \normLp{f} \lesssim \normLp{H}.
    \end{align*}
\end{thm}
\begin{prop}
\label{thm:H_great_3inf}
    Impose Assumption~\ref{ass:SS}.
    Let $3\le p<\infty$ and $f\in\LpE$. Then,
    \begin{align*}
        \normLp{f} \lesssim \normLp{H}.
    \end{align*}
\end{prop}

The last statement is a straightforward consequence of Proposition~\ref{prop:Hprim_great_3inf} below, due to $\widetilde{H} \le \sqrt{2} H$.
The rest of the estimates can be shown employing the martingale $\Mt$ introduced in Subsection~\ref{sub:martingale} and the Burkholder--Davies--Gundy inequality; see the proofs at the end of the current subsection.
However, the square function $H$ shares the same issue as $G$, namely, since it is defined by the operator $\Gamma$ instead of $\Gampri$, it is too large when $1<p<2$. To demonstrate this, we adopt Example~2 of \cite{bbl}, see Example~\ref{cex:Cauchy2} below.
Moreover, the lower bound of $\normLp{H}$ is still an open question for the range $2<p<3$.

\begin{ex}
\label{cex:Cauchy2}
    Consider the Dirichlet form on the Euclidean space $E = \Rn$ ($n\ge2$) associated with the Cauchy process ($\alpha$-stable process with $\alpha=1$), that is, $J(x, \dy) = J(x,y)\dy$, where
    \begin{align*}
        J(x, y) = \frac{\mathcal{A}_{n,1}}{|y - x|^{n + 1}}.
    \end{align*}
    Here
    $\mathcal{A}_{n,\alpha} := 2^\alpha \Gamma((n+\alpha)/2) \pi^{-n/2}/\abs{\Gamma(-\alpha/2)}$,
    where $\alpha\in(0,2)$;
    see \cite[(2.11)]{bbl}.
    In this context, $\Gamma(\cdot)$ stands for the Gamma function.
    The semigroup is given by the following transition density:
    \begin{align*}
        p_t(x,y) = \frac{c_n t}{(t^2+|y-x|^2)^{(n+1)/2}}
    \end{align*}
    and $c_n = \Gamma((n+1)/2) \pi^{-(n+1)/2}$.

    Denote the ball of radius $r$ centered at a point $x$ by $B(x,r)$.
    Let $h(x):=\abs{x}^{-(n+1)/2}$ and $f(x):=h(x)\ind_{B(0,1)}(x)$.
    Note that $f$ belongs to $L^p(\dx)$ for $1<p<2n/(n+1)<2$.
    We claim that the square function $H$ of the function $f$ is identically equal to infinity.
    The problem fundamentally arises from the rapid growth of $\Gamma [P_tf]$ as $t$ tends to zero.

    To illustrate this, we introduce the following function:
    \begin{align*}
        v(x,t) := \begin{cases}
		P_th(x), & \text{for } t>0,\\
		h(x), & \text{for } t=0.
	\end{cases}
    \end{align*}
    Note that $h$ is locally integrable on $\Rn$ and vanishes at infinity, hence the function $v$ is well\nobreakdash-defined and continuous except at the point $(x,t)=(0,0)$.

    We first calculate $P_tf(x)$. Observe that $p_t(x,y)$ satisfies the following scaling property
    \begin{align*}
        p_t(x,y) = \frac{1}{t^n} p_1\!\left( \tfrac{x}{t}, \tfrac{y}{t} \right).
    \end{align*}
    Obviously $h(x) = t^{-(n+1)/2}h(x/t)$.
    Therefore,
    \begin{align*}
        P_tf(x) &=
        c_n \int\limits_{\mathclap{B(0,1)}} \frac{1}{t^{(n+1)/2}}\, h\!\left(\tfrac{y}{t}\right)\cdot \frac{1}{t^n}\,p_1\!\left( \tfrac{x}{t}, \tfrac{y}{t} \right)\dys
        \\
        &=
        c_n \int\limits_{\mathclap{B(0,1/t)}} \frac{1}{t^{(n+1)/2}}\, h\!\left(y\right)\cdot \frac{1}{t^n}\,p_1\!\left( \tfrac{x}{t}, y \right) t^n\dys
        \\
        &=
        t^{-(n+1)/2} v_t\!\left( \tfrac{x}{t}, 1  \right),
    \end{align*}
    where
    \begin{align*}
        v_s(x,t) :=
        \int\limits_{\mathclap{B(0,1/s)}}
        h(y)p_t(x,y) \dys.
    \end{align*}
    Analogously,
    \begin{align*}
        v(x,t) = t^{-(n+1)/2} v\!\left( \tfrac{x}{t}, 1  \right),
        \quad
        t>0,\,x\in\Rn.
    \end{align*}

    Now we can rewrite the square function of $f$ as follows:
    \begin{align}
    \label{eq:cex:GCauchy2}
        (H(x))^2
        &=
        \mathcal{A}_{n,1}
        \int\limits_0^{\infty}\int\limits_{\Rn}\int\limits_{\Rn}
        \frac{(P_tf(y)-P_tf(z))^2}{|z-y|^{n+1}}
        \,
        p_t(x,z)
        \dys\dz\dt
        \notag\\	
        &=
        \mathcal{A}_{n,1}
        \int\limits_0^{\infty}\int\limits_{\Rn}\int\limits_{\Rn}
        \frac{1}{t^{n+1}}
        \cdot
        \frac{(v_t(\tfrac{y}{t},1)-v_t(\tfrac{z}{t},1))^2}{|z-y|^{n+1}}
        \,
        p_t(x,z)
        \dys\dz\dt
        \notag\\	
        &=
        \mathcal{A}_{n,1}
        \int\limits_0^{\infty} \int\limits_{\Rn} \int\limits_{\Rn}
        \frac{1}{t}
        \cdot
        \frac{(v_t(y,1)-v_t(\tfrac{z}{t},1))^2}{|z-ty|^{n+1}}
        \,
        p_t(x,z)
        \dys\dz\dt
        \notag\\	
        &=
        \mathcal{A}_{n,1}
        \int\limits_0^{\infty} \int\limits_{\Rn} \int\limits_{\Rn}
        t^{n-1}
        \cdot
        \frac{(v_t(y,1)-v_t(z,1))^2}{|tz-ty|^{n+1}}
        \,
        p_t(x,tz)
        \dys\dz\dt
        \notag\\	
        &=
        \mathcal{A}_{n,1} c_n
        \int\limits_{\Rn} \int\limits_{\Rn}
        \int\limits_0^{\infty}
        \frac{1}{t}
        \cdot
        \frac{(v_t(y,1)-v_t(z,1))^2}{|z-y|^{n+1} (t^2+\abs{tz-x}^2)^{(n+1)/2}}
        \dts\dy\dz.
    \end{align}
    In the last line, we used Tonelli's theorem.
    Observe that $v_t(y,1)\to v(y,1)>0$ as $t\to0^+$. Therefore, we have the following asymptotic equivalence of the integrand. For $x\neq0$,
    \begin{align*}
        \frac{1}{t}
        \cdot
        \frac{(v_t(y,1)-v_t(z,1))^2}{|z-y|^{n+1} (t^2+\abs{tz-x}^2)^{(n+1)/2}}
        \sim
        \frac{(v(y,1)-v(z,1))^2}{|z-y|^{n+1}\abs{x}^{n+1}}
        \cdot
        \frac{1}{t},
        \quad
        \text{as }
        t\to0^+,
    \end{align*}
    and when $x=0$,
    \begin{align*}
        \frac{1}{t}
        \cdot
        \frac{(v_t(y,1)-v_t(z,1))^2}{|z-y|^{n+1} (t^2+\abs{tz-x}^2)^{(n+1)/2}}
        \sim
        \frac{(v(y,1)-v(z,1))^2}{|z-y|^{n+1}(1+\abs{z}^2)^{(n+1)/2}}
        \cdot
        \frac{1}{t^{n+2}},
        \quad
        \text{as }
        t\to0^+.
    \end{align*}
    In both cases, the inner integral of \eqref{eq:cex:GCauchy2} diverges to infinity. Therefore, $H\equiv\inft$.
\end{ex}

\begin{proof}[Proof of Theorem~\ref{thm:H_less_2inf}]
    Initially, we assume that $f\in\DE$. For $p\ge2$, Jensen's inequality yields
    \begin{align*}
     \intE (H(x))^{p}\,m(\dx)
     & =
     \intE \left(\int\limits_0^\inft P_t\Gamma[P_tf](x)  \dts\right)^{p/2}\,m(\dx)
     \\
     & =
     \intE \left(\Ev_x \int\limits_0^\inft \Gamma[P_tf](X_t) \dts\right)^{p/2}\,m(\dx)
     \\
     & \le
     \intE \Ev_x \left(\int\limits_0^\inft \Gamma[P_tf](X_t) \dts\right)^{p/2}\,m(\dx)
     \\
     & =
     \lim_{T \to \inft} \intE \Ev_x \left(\int\limits_0^T \Gamma[P_tf](X_t) \dts\right)^{p/2}\,m(\dx) .
    \end{align*}
    In the last line, we used the monotone convergence theorem.
    Since the semigroup is conservative, we can utilize self-duality of the process $\Xt$ (see~\eqref{eq:duality}) to write
    \begin{align*}
     \intE (H(x))^{p}\,m(\dx) & \le \lim_{T \to \inft} \intE \Ev_x \left(\int\limits_0^T \Gamma[P_{T-t}f](X_t) \dt\right)^{p/2}\,m(\dx) .
    \end{align*}
    Let $\Mt$ be the martingale given by \eqref{eq:Mt}.
    By the assumption $f\in\DE$ and Corollary~\ref{cor:sharpMt},
    \begin{align*}
        \intE \Ev_x \left(\int\limits_0^T \Gamma[P_{T-t}f](X_t) \dt\right)^{p/2}\,m(\dx) =
        2^{-p/2}
        \intE \Ev_x (\langle M \rangle_T)^{p/2}\,m(\dx).
    \end{align*}
    Employing the Burkholder--Davies--Gundy inequality~\eqref{sim:bdg}, together with inequality \eqref{eq:brackets-}, we obtain
    \begin{align*}
         \intE (H(x))^{p}\,m(\dx)
         & \lesssim
         \lim_{T \to \inft} \intE \Ev_x (\langle M \rangle_T)^{p/2}\,m(\dx) \\
         & \lesssim
         \lim_{T \to \inft} \intE \Ev_x ([M]_T)^{p/2}\,m(\dx) \\
         & \lesssim
         \lim_{T \to \inft} \intE \Ev_x |M_T|^p\,m(\dx) \\
         & = \lim_{T \to \inft} \intE \Ev_x |f(X_T) - P_Tf(x)|^p\,m(\dx) .
    \end{align*}
    Since $|a + b|^p \le 2^{p - 1} (|a|^p + |b|^p)$, we get
    \begin{align*}
         \intE (H(x))^{p}\,m(\dx)
         & \lesssim
         \lim_{T \to \inft} \intE (\Ev_x |f(X_T)|^p + |P_Tf(x)|^p)\,m(\dx) \\
         & = \lim_{T \to \inft} \intE (P_T [|f|^p](x) + |P_Tf(x)|^p)\,m(\dx).
    \end{align*}
    Due to the contraction property of $\Pt$, it follows that $\normLp{P_Tf}^p\le \normLp{f}^p$.
    By the conservativeness of $\Pt$, we have
    $\int_E P_T [|f|^p](x)\,m(\dx)=\int_E |f(x)|^p\,m(\dx)$.
    Summarizing,
    \begin{align*}
        \intE (H(x))^{p}\,m(\dx)  & \lesssim \intE |f(x)|^p\,m(\dx).
    \end{align*}

    At this point, we relax the assumption $f\in\DE$.
    Let $f$ be an arbitrary function in $\LpE$.
    Since the Dirichlet form is regular, we may take the sequence $(f_n)$ of compactly supported functions from $\DE$ such that it converges almost everywhere to $f$.

    By $H[f_n]$ we denote the square function $H$ applied to $f_n$.
    Then, by Fatou's lemma,
    \begin{align*}
        \intE (H(x))^{p}\,m(\dx)
        & \leq
        \lim_{n\to\inft} \intE (H[f_n](x))^{p}\,m(\dx)
        \\
        & \lesssim
        \lim_{n\to\inft} \intE |f_n(x)|^p\,m(\dx)
        =
        \intE |f(x)|^p\,m(\dx).
    \end{align*}
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:H_great_12}]
    As in the previous proof, we start with $f\in\DE$. We now consider the case $p<2$; hence by Jensen's inequality, we obtain
    \begin{align*}
         \intE (H(x))^{p}\,m(\dx) & = \intE \left(\int\limits_0^\inft P_t \Gamma[P_tf](x) \dts\right)^{p/2}\,m(\dx)
         \\
         & =
         \intE \left(\Ev_x \int\limits_0^\inft \Gamma[P_tf](X_t) \dts\right)^{p/2}\,m(\dx)
         \\
         & \ge
         \intE \Ev_x \left(\int\limits_0^\inft \Gamma[P_tf](X_t) \dts\right)^{p/2}\,m(\dx)
         \\
         & =
         \lim_{T \to \inft} \intE \Ev_x \left(\int\limits_0^T \Gamma[P_tf](X_t) \dts\right)^{p/2}\,m(\dx) .
    \end{align*}
    The last line follows from the monotone convergence theorem.
    By self-duality of the process $\Xt$ (formula~\eqref{eq:duality}),
    \begin{align*}
     \intE (H(x))^{p}\,m(\dx) & \ge \lim_{T \to \inft} \intE \Ev_x \left(\int\limits_0^T \Gamma[P_{T-t}f](X_t) \dts\right)^{p/2}\,m(\dx) .
    \end{align*}
    We again employ the martingale $\Mt$ given by \eqref{eq:Mt}.
    Given that $f\in\DE$, we deduce from Corollary~\ref{cor:sharpMt} that
    \begin{align*}
        \intE \Ev_x \left(\int\limits_0^T \Gamma[P_{T-t}f](X_t) \dt\right)^{p/2}\,m(\dx) =
        2^{-p/2}
        \intE \Ev_x (\langle M \rangle_T)^{p/2}\,m(\dx),
    \end{align*}
    By the Burkholder--Davies--Gundy inequality~\eqref{sim:bdg}, together with inequality \eqref{eq:brackets+}, we get
    \begin{align*}
         \intE (H(x))^{p}\,m(\dx)
         & \gtrsim
         \lim_{T \to \inft} \intE \Ev_x (\langle M \rangle_T)^{p/2}\,m(\dx)
         \\
         & \gtrsim
         \lim_{T \to \inft} \intE \Ev_x ([M]_T)^{p/2}\,m(\dx)
         \\
         & \gtrsim
         \lim_{T \to \inft} \intE \Ev_x |M_T|^p\,m(\dx)
         \\
         & =
         \lim_{T \to \inft} \intE \Ev_x |f(X_T) - P_Tf(x)|^p\,m(\dx) .
    \end{align*}
    By the elementary estimate $|a + b|^p \ge 2^{1 - p} |a|^p - |b|^p$, we get
    \begin{align*}
         \intE (H(x))^{p}\,m(\dx) 
         & \gtrsim
         \lim_{T \to \inft} \intE (\Ev_x |f(X_T)|^p - 2^{p - 1} |P_Tf(x)|^p)\,m(\dx)
         \\
         & =
         \lim_{T \to \inft} \intE (P_T [|f|^p](x) - 2^{p - 1}  |P_Tf(x)|^p)\,m(\dx).
    \end{align*}
    By the conservativeness of $\Pt$, we have
    $\int_E P_T [|f|^p](x)\,m(\dx)=\int_E |f(x)|^p\,m(\dx)$.
    Moreover, under Assumption~\ref{ass:SS},
    $\lim_{T \to \inft} \int_E |P_Tf(x)|^p\,m(\dx) = 0$. Hence, finally,
    \begin{align*}
     \intE (H(x))^{p}\,m(\dx)  & \gtrsim \intE |f(x)|^p\,m(\dx) .
    \end{align*}

    We relax the assumption $f\in\DE$, consider an arbitrary $f\in\LpE\cap\LE{2}$, and approximate $f$ by $P_sf$ for some $s>0$.
    Observe that since $f\in\LE{2}$, we have $P_sf\in\DE$.

    Denote by $H[P_sf]$ the square function $H$ acting on $P_sf$, namely, $H[P_sf]$ is given by
    \begin{align*}
        H[P_sf](x) = \left(
        \int\limits_0^\inft P_t \Gamma [P_tP_sf](x) \dts 
        \right)^{1/2}
        =
        \left(
        \int\limits_0^\inft P_t \Gamma [P_{s+t}f](x) \dts 
        \right)^{1/2}
        .
    \end{align*}
    By the monotone convergence theorem,
    \begin{align}
    \label{eq:PsH[Psf]}
        (H(x))^2
        &=
        \lim_{s\to0^+} \int\limits_s^\inft P_t \Gamma [P_tf](x) \dts
        =
        \lim_{s\to0^+} \int\limits_0^\inft P_sP_t \Gamma [P_tP_sf](x) \dts
        \notag \\
        &=
        \lim_{s\to0^+} P_s(H[P_sf]^2)(x).
    \end{align}

    Since the result holds for $P_sf$,
    \begin{align*}
        \intE (H[P_sf](x))^{p}\,m(\dx)  & \gtrsim \intE |P_sf(x)|^p\,m(\dx).
    \end{align*}
    Combining this with the monotone convergence theorem and Jensen's inequality, we obtain
    \begin{align*}
        \intE (H(x))^{p}\,m(\dx) 
        &=
        \lim_{s\to0^+}
        \intE \left(P_s(H[P_sf]^2)(x)\right)^{p/2}\,m(\dx)
        \ge
        \lim_{s\to0^+}
        \intE (H[P_sf](x))^{p}\,m(\dx)
        \\
        & \gtrsim
        \lim_{s\to0^+}
        \intE |P_sf(x)|^p\,m(\dx)
        =
        \intE |f(x)|^p\,m(\dx).
    \end{align*}
    The last line follows from
    the strong continuity of the semigroup $\Pt$.
\end{proof}

\subsection{Square function $\widetilde{H}$}
\label{sub:Hprim_func}

The last subsection is dedicated to the last square function:
\begin{align*}
    \widetilde{H}(x) & =
    \left(
        \int\limits_0^\inft P_t \Gampri[P_tf](x)\dts 
    \right)^{1/2}.
\end{align*}

We conjecture that the above function resolves the issue of $L^p$-unboundedness, which affects $\widetilde{G}$ for $p>2$ (see Example~\ref{cex:Brown}) and $H$ for $1<p<2$ (see Example~\ref{cex:Cauchy2}).
However, the method for establishing Littlewood--Paley estimates for this function remains unclear at this point.
Methods based on the Hardy--Stein identity seem to be well-suited for the functions $G$ and $\widetilde{G}$,
whereas martingale methods appear to be more applicable to the function $H$.

On the one hand, we are able to obtain the upper bound directly from Theorem~\ref{thm:H_less_2inf} and the fact that $\widetilde{H} \le \sqrt{2} H$.
\begin{prop}
\label{prop:Hprim_less_2inf}
    Impose Assumption~\ref{ass:coserv}. Let $2\le p<\infty$ and $f\in\LpE$. Then,
    \begin{align*}
        \normLp{\widetilde{H}} \lesssim \normLp{f}.
    \end{align*}
\end{prop}
On the other hand, when $p$ is sufficiently large for the estimate $|P_t f|^{p - 2} \le P_t(|f|^{p - 2})$ a.e. to hold, one may adapt the procedure from the proof of Theorem~\ref{thm:Gprim_less_12}, which is based on the Hardy--Stein identity, to obtain the lower bound of $\widetilde{H}$.
Nevertheless, it remains an open question whether this statement holds for $p\in(2,3)$.
\begin{prop}
\label{prop:Hprim_great_3inf}
    Impose Assumption~\ref{ass:SS}.
    Let $3\le p<\infty$ and $f\in\LpE$. Then,
    \begin{align*}
        \normLp{f} \lesssim \normLp{\widetilde{H}}.
    \end{align*}
\end{prop}
\begin{proof}
    Since $p \ge 3$, the function $a\mapsto |a|^{p-2}$ is convex. Thus, by Jensen's inequality,
    $|P_t f|^{p - 2} \le P_t(|f|^{p - 2})$ a.e.
    Therefore, by~\eqref{sim:HS_2pinf}, the symmetry of the operator $P_t$, and Hölder's inequality
    \begin{align*}
     \intE |f(x)|^p\,m(\dx)
     & \asymp
     \int\limits_0^\inft  \intE \Gampri[P_tf](x) |P_t f(x)|^{p - 2} \,m(\dx)\dt
     \\
     & \le
     \int\limits_0^\inft  \intE \Gampri[P_tf](x) P_t(|f|^{p - 2})(x)\,m(\dx)\dt
     \\
     & =
     \int\limits_0^\inft
     \intE P_t \Gampri[P_tf](x) |f(x)|^{p - 2}\,m(\dx)\dt
     \\
     & =
     \intE (\widetilde{H}(x))^2 |f(x)|^{p - 2}\,m(\dx)
     \\
     & \le
     \biggl(\intE (\widetilde{H}(x))^{p}\,m(\dx)\biggr)^{2/p} \biggl(\intE |f(x)|^p\,m(\dx)\biggr)^{1 - 2/p} .
    \end{align*}
    This implies
    \begin{align*}
     \intE |f(x)|^p\,m(\dx) & \lesssim \intE (\widetilde{H}(x))^{p}\,m(\dx) .
    \end{align*}
\end{proof}


