\subsection{Spherical design}
The concept of spherical $T$-designs introduced by Delsarte and Seidel \cite{DS89} applies to finite subsets of the unit sphere ${\mathbb S}^{d-1}: = \{ \boldsymbol{x} = (x_1, \ldots, x_d) \in \R^{d} \mid \langle \boldsymbol{x}, \boldsymbol{x} \rangle = 1 \}$ in the $d$-dimensional Euclidean space $\R^d$, where for $\boldsymbol{x},\boldsymbol{y}\in \R^d$, its inner product is denoted by
\[ \langle \boldsymbol{x}, \boldsymbol{y} \rangle := \sum_{a = 1}^{d} x_ay_a.\]
Under the identification $\mathbb{H}$ with $\R^4$, for $x\in \mathbb{H}$ we have $N(x)=\langle \boldsymbol{x}, \boldsymbol{x} \rangle $, and hence, $\mathbb{S}^3=\mathbb{H}_1$.

For an integer $\ell\ge0$, denote by ${\rm Hom}_{\ell}(\R^d)$ the $\R$-vector subspace of $\R[x_1, \ldots, x_d]$ consisting of all homogeneous polynomials of degree $\ell$ in $d$ variables.
We write
\[\Delta:= \frac{\partial^2}{\partial x_1^2}+\cdots +\frac{\partial^2}{\partial x_d^2}\]
for the Laplacian operator.
Let 
\[{\rm Harm}_{\ell}(\R^d) :=\{P\in {\rm Hom}_{\ell}(\R^d)\mid \Delta P=0\}\]
be the $\R$-vector space of harmonic polynomials of homogeneous degree $\ell$.
It is well known (see e.g., Theorem 3.2 in \cite{DelsarteGoethalsSeidel77}) that $\dim_\R {\rm Harm}_\ell(\R^d)= \binom{\ell+d-1 }{\ell} - \binom{\ell+d-3}{\ell -2}$ holds for $\ell,d\in \N$ with $\ell\ge2$.

\begin{definition}\label{def:T-design}
For a subset $T$ of $\N$, a non-empty finite subset $X$ of $\mathbb{S}^{d-1}$ is called a {\itshape spherical $T$-design}
if for any $\ell \in T$ and $P \in {\rm Harm}_\ell (\R^d)$ we have that
\[\sum_{\boldsymbol{x} \in X} P(\boldsymbol{x}) = 0.\]
\end{definition}


Alternatively, a finite subset $X\subset \mathbb{S}^{d-1}$ is a spherical $T$-design if $T\subset T(X)$, where $T(X)$ is the harmonic strength of $X$ defined in \eqref{eq:T(X)}.



For a subset $X$ of $\R^d$, we write $-X:=\{-\boldsymbol{x}\mid \boldsymbol{x}\in X\}$. 
A set $X$ is said to be \emph{antipodal} if we have $-X=X$. 
If a finite subset $X\subset \mathbb{S}^{d-1}$ is antipodal, then the harmonic strength $T(X)$ contains all positive odd integers.
Conversely, for a finite subset $X\subset \mathbb{S}^{d-1}$, if $T(X)$ contains all positive odd integers, then $X$ is antipodal (cf.~\cite{MisawaMunemasaSawa}).

For an antipodal finite subset $X$ of $\R^d$, a subset $X'\subset X$ is called \emph{a half set of $X$} if $X$ is a disjoint union of $X'$ and $-X'$; $X'\sqcup (-X')=X$.
It follows that
\begin{equation}\label{eq:antipodal_cardinality}
|X|=2|X'|.
\end{equation}
For any antipodal finite subset $X$ of $\mathbb{S}^{d-1}$ (note that $\boldsymbol{0}\not\in X$), a half set of $X$ always exists, but not unique.
The harmonic strength of the half set satisfies $T(X') \cap 2\Z = \{2\ell \in \N\mid 2\ell\in T(X)\}$ (see e.g. \cite[Lemma 2.2]{HiraoNozakiTasaka}).
It should be noted that $T(X')$ may contain odd integers (see \cite{BannaiZhaoZhuZhu18}).


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Computing the harmonic strength}
We now explain our method to compute the harmonic strength defined in \eqref{eq:T(X)}.
We use the Gegenbauer (or ultraspherical) polynomials which form a class of orthogonal polynomials (cf.~\cite[p.302]{AndrewsAskeyRoy} and \cite[(4.7.23)]{S75}).
For $\lambda>0$, the Gegenbauer polynomial $C_\ell^\lambda(s)\in \R[s]$ of degree $\ell$ is defined by 
the coefficient of $u^\ell$ in the formal power series $\Phi^{\lambda}(s;u):=(1-2su+u^2)^{-\lambda}$:
\[
\Phi^{\lambda}(s;u)=\sum_{\ell \geq 0}C_\ell^\lambda(s)u^\ell.
\]
It is also obtained by the recurrence relation $\ell C_\ell^\lambda(s) = 2(\ell+\lambda-1)s C_{\ell-1}^\lambda(s) -(\ell+2\lambda-2)C_{\ell-2}^\lambda(s)$ for $\ell\ge2$ with $C_0^\lambda(s)=1,\ C_1^\lambda(s)=2\lambda s$.
For example, the case $\ell=2$ is $C_2^{\lambda}(s)=-\lambda +2\lambda (1+\lambda) s^2$.
It follows that $C_\ell^\lambda(1) = \frac{2\lambda (2\lambda+1)(2\lambda+2)\cdots (2\lambda+\ell-1)}{\ell!}$.

\begin{lemma}\label{lem:gegenbauer}
Let $X$ be a finite subset of $\mathbb{S}^{d-1}$.
For $\ell\in \N$, we have that
\[\sum_{\boldsymbol{x},\boldsymbol{y}\in X} C_{\ell}^{(d-2)/2}(\langle \boldsymbol{x},\boldsymbol{y}\rangle ) =0\]
if and only if $\ell\in T(X)$, where $T(X)$ is the harmonic strength of $X$ defined in \eqref{eq:T(X)}.
\end{lemma}
\begin{proof}
Write $c_{\ell,d}:=\dim_\R {\rm Harm}_\ell(\R^d)$.
Let $\{S_{\ell,n}^{(d)}\mid n=1,2,\ldots,c_{\ell,d} \}$ be an orthonormal basis of ${\rm Harm}_\ell(\R^d)$ with respect to the inner product defined for 
$F_1,F_2\in {\rm Harm}_\ell(\R^d)$ by 
\[( F_1,F_2) :=\frac{1}{|\mathbb{S}^{d-1}|} \int_{\boldsymbol{x}\in \mathbb{S}^{d-1}} F_1(\boldsymbol{x})F_2(\boldsymbol{x})d\sigma(\boldsymbol{x}).\]


From the addition theorem \cite[Theorem 9.6.3]{AndrewsAskeyRoy}, for $\ell\in \N$ and $\boldsymbol{x},\boldsymbol{y}\in \mathbb{S}^{d-1}$, one has
\[ \sum_{n=1}^{c_{\ell,d}}S_{\ell,n}^{(d)}(\boldsymbol{x})S_{\ell,n}^{(d)}(\boldsymbol{y}) = \frac{c_{\ell,d}}{|\mathbb{S}^{d-1}|} C_\ell^{(d-2)/2}(\langle \boldsymbol{x},\boldsymbol{y}\rangle).\]
Let $Z_n := \sum_{\boldsymbol{x}\in X}S_{\ell,n}^{(d)}(\boldsymbol{x})\in \R$.
Then we have
\[\sum_{n=1}^{c_{\ell,d}}Z_n^2= \sum_{\boldsymbol{x},\boldsymbol{y}\in X}\sum_{n=1}^{c_{\ell,d}}S_{\ell,n}^{(d)}(\boldsymbol{x})S_{\ell,n}^{(d)}(\boldsymbol{y}) = \frac{c_{\ell,d}}{|\mathbb{S}^{d-1}|}  \sum_{\boldsymbol{x},\boldsymbol{y}\in X} C_{\ell}^{(d-2)/2}(\langle \boldsymbol{x},\boldsymbol{y}\rangle )  .\]
Thus, the result follows from the definition: $\ell \in T(X)$ if and only if $Z_n=0$ holds for all $n=1,2,\ldots, c_{\ell,d}$.
\end{proof}


\begin{proposition} \label{prop:gene}
Let $d\geq 3$.
For a finite subset $X$ of $\mathbb{S}^{d-1}$ and $\ell\in \N$, we have that $\ell \in T(X)$ if and only if 
the coefficient of $u^\ell$ in $\sum_{\boldsymbol{x},\boldsymbol{y} \in X}\Phi^{(d-2)/2}(\langle \boldsymbol{x},\boldsymbol{y} \rangle;u)$ is zero. 
\end{proposition}
\begin{proof}
    Since 
\begin{align*}
\sum_{\boldsymbol{x},\boldsymbol{y} \in X}\Phi^{(d-2)/2}(\langle \boldsymbol{x},\boldsymbol{y} \rangle;u)
&=
\sum_{\boldsymbol{x},\boldsymbol{y} \in X} \sum_{\ell\geq 0} C_\ell^{(d-2)/2}(\langle \boldsymbol{x},\boldsymbol{y}  \rangle) u^\ell   \\
&=
 \sum_{\ell\geq 0} \left(\sum_{\boldsymbol{x},\boldsymbol{y} \in X}C_\ell^{(d-2)/2}(\langle \boldsymbol{x}, \boldsymbol{y} \rangle)\right) u^\ell, 
\end{align*}
the result follows from Lemma \ref{lem:gegenbauer}.
\end{proof}

The power series $\sum_{\boldsymbol{x},\boldsymbol{y} \in X}\Phi^{(d-2)/2}(\langle \boldsymbol{x},\boldsymbol{y} \rangle;u)\in \R[[u]]$ as in Proposition \ref{prop:gene} can be computed from the \emph{distance distribution} $R_X:=\{(s, A_s(X))\mid s \in A(X)\cup\{1\}\}$ of $X$, where for $s\in \R$, we write
\begin{equation}\label{eq:d_a}
A_s(X):=|\{(\boldsymbol{x},\boldsymbol{y})\in X\times X\mid \langle \boldsymbol{x},\boldsymbol{y}\rangle=s\}|
\end{equation}
and 
\begin{equation}\label{eq:A(X)}
A(X):=\{\langle \boldsymbol{x},\boldsymbol{y}\rangle \mid \boldsymbol{x},\boldsymbol{y}\in X, \ \boldsymbol{x}\neq\boldsymbol{y}\}
\end{equation}
denotes the set of inner products of two distinct elements in $X\subset \mathbb{S}^{d-1}$.
Note that $A_1(X)=|X|$.
With this, one has
\begin{equation*}\label{eq:Phi_A(X)}
\sum_{\boldsymbol{x},\boldsymbol{y} \in X} \Phi^{(d-2)/2}(\langle \boldsymbol{x},\boldsymbol{y} \rangle;u)=\sum_{s\in A(X)\cup\{1\}}A_s(X) \Phi^{(d-2)/2}(s;u).
\end{equation*}
Our strategy is to express the above right-hand side in terms of simple rational functions in $u$ and check the conditions under which the coefficient of $u^\ell$ vanishes.

Below, we only use the case $d=4$. In this case, we simply write
\[\Phi(s;u):=\Phi^{1}(s;u)=\frac{1}{1-2su+u^2}.\]



