\subsection{Proof of Theorem \ref{thm:harmonic_strength}}
To prove Theorem \ref{thm:harmonic_strength}, we use the theory of invariant polynomials.
Let ${\rm Hom}_{\ell}(\C^2)$ denote the $\C$-vector subspace of $\C[z_1, z_2]$ consisting of all homogeneous polynomials of degree $\ell$ in two variables.
Let us recall an action of the group $\mathbb{H}_1$ on ${\rm Hom}_\ell (\C^2)$.

We first note that a quaternion $x \in \mathbb{H}$ can be written as $x=z_1+z_2j $ for some $z_1,z_2\in \C$:
\[x = x_1 + x_2 i + x_3 j + x_4 k = (x_1 + x_2 i) + (x_3 + x_4 i) j.\]
For $x=z_1+z_2j\in \mathbb{H}$, we set 
\[ C_x := \begin{pmatrix} z_1&z_2\\ -\overline{z_2}&\overline{z_1}\end{pmatrix},\]
where $\overline{z}$ denotes the complex conjugate for $z\in \C$.
The matrix $C_x$ lies in the special unitary group $SU(2)=\{A\in U(2)\mid \det A=1\}$ if $x\in \mathbb{H}_1$.
Moreover, the map
\begin{equation}\label{eq:map_C_x}
\mathbb{H}_1\longrightarrow SU(2),\ \varepsilon\longmapsto C_{\varepsilon}
\end{equation}
is an injective group homomorphism.
This shows that for $\varepsilon\in \mathbb{H}_1$ and $ P\in {\rm Hom}_{\ell}(\C^2)$, setting
\[ (\varepsilon P)(z_1,z_2):=P\big( (z_1,z_2)C_\varepsilon\big)\]
we obtain an action of $\mathbb{H}_1$ on the space ${\rm Hom}_{\ell}(\C^2)$.

Let $G$ be a finite subgroup of $\mathbb{H}_1$, which can be viewed as a subgroup of $SU(2)$ via \eqref{eq:map_C_x}.
Denote by ${\rm Hom}_{\ell}(\C^2)^G=\{P\in {\rm Hom}_{\ell}(\C^2)\mid  \varepsilon P=P, \ \forall \varepsilon \in G\}$ the $\C$-vector space of $G$-invariant homogeneous polynomials, and by
\[\Psi_G(u):=\sum_{\ell\geq 0} \dim_\C {\rm Hom}_\ell (\C^2)^G u^\ell\]
the \emph{Molien series} (or Hilbert--Poincar\'{e} series) of $G$.
It is well known (cf.~\cite[Theorem 4.3.2]{Smith}) that the Molien series $\Psi_G(u)$ can be calculated by
\[  \Psi_G(u)= \frac{1}{|G|} \sum_{\varepsilon \in G} \frac{1}{\det (I-uC_\varepsilon)}.\]


We now prove that, for a finite subgroup $G$ of $\mathbb{H}_1$, the formal power series $(1/|G|^2)\sum_{x,y \in G} \Phi(\langle x,y \rangle;u)$ coincides with the Molien series $\Psi_G(u)$ of $G$. 

\begin{lemma}\label{lem:SU(2)}
Let $G$ be a finite subgroup of $\mathbb{H}_1$. Then we have  
\[\Psi_G(u)= \frac{1}{|G|^2}\sum_{x,y \in G} \Phi(\langle x,y \rangle; u),\]
where the inner product $\langle x,y \rangle$ is given by $\langle x_1+x_2 i+x_3 j +x_4 k,y_1+y_2i+y_3 j+y_4 k \rangle=x_1y_1+x_2y_2+x_3y_3+x_4y_4$ via the identification $\mathbb{H}$ with $\R^4$.
\end{lemma}
\begin{proof}
From Lemma \ref{lem:quaternion_orthogonal}, for $x,y\in \mathbb{H}_1$, we have $\langle x,y\rangle = \langle 1,x^{-1}y\rangle$.
Thus, it follows that 
\begin{align*}
\frac{1}{|G|^2}\sum_{x,y \in G} \Phi(\langle x,y \rangle; u)&=
\frac{1}{|G|}\sum_{x \in G} \frac{1}{1-2\langle 1,x \rangle u+u^2}    \\
&=\frac{1}{|G|}\sum_{x\in G} \frac{1}{1-2x_1 u+u^2} \\
&= \frac{1}{|G|}\sum_{x \in G}\frac{1}{\det (I-u C_x)},
\end{align*}
where $\det (I-u C_x)=1-2x_1 u+u^2$ is easily verified. 
\end{proof}

For a finite subgroup $G\subset \mathbb{H}_1$ viewed as a finite subgroup of $SU(2)$, the Molien series $\Psi_G(u)$ is explicitly calculated as follows \cite[Section 4.5]{Sbook}: 
\begin{table}[h]
    \centering
    \caption{Molien series of $G$}
    \label{tab:molien}
    \begin{tabular}{|c|c|} \hline
    $G$ & $\Psi_G(u)$
    \\ \hline \hline 
       $C_n$  &  $\displaystyle{\frac{1-u^{2n}}{(1-u^2)(1-u^n)^2}=\frac{1+u^{n}}{(1-u^2)(1-u^n)}}$\\ \hline 
       $D_{2n}$ &$\displaystyle{\frac{1-u^{4n+4}}{(1-u^4)(1-u^{2n})(1-u^{2n+2})}=\frac{1+u^{2n+2}}{(1-u^4)(1-u^{2n})}}$  \\ \hline
