T(C_n)=\mathbb{O}^+ \qquad (n\geq 2),  
\]
and 
\[T(D_{2n}) =\{2\ell \in \N \mid 0<\ell < n, \ \ell \equiv 1\bmod 2  \} \cup 
\mathbb{O}^{+}\qquad  (n\geq 2). 
\]
\end{theorem}

