\subsection{Proof of Theorem \ref{thm:LP_bound}}
In order to give a lower bound on the cardinality of a spherical $T$-design, we recall a useful inequality due to Delsarte--Goethals--Seidel \cite{DelsarteGoethalsSeidel77}.

Let 
\[ Q_\ell^{(d)}(s):=\frac{d+2\ell-2}{d-2} C_{\ell}^{(d-2)/2}(s)\]
be the scaled Gegenbauer polynomial used in \cite{DelsarteGoethalsSeidel77}.
With this normalization, we have $Q_\ell^{(d)}(1)=\dim_\R {\rm Harm}_\ell(\R^d)$.
As examples, one has
\begin{equation}\label{eq:Q_l^{d}}
\begin{aligned}
Q_2^{(d)}(s) &=\frac{1}{2} (d+2) \left(d s^2-1\right),\quad Q_3^{(d)}(s) =\frac{1}{6} d (d+4) s \left((d+2) s^2-3\right),\\
Q_4^{(4)}(s) &=5\left( 16 s^4-12 s^2+1\right),\quad Q_6^{(4)}(s) =7 \left(64 s^6-80 s^4+24 s^2-1\right).
\end{aligned}
\end{equation}


Hereafter, we fix $d=4$.
Recall that the polynomials $Q_\ell(s)=Q_\ell^{(4)}(s)$ form a basis of the polynomial algebra $\R[s]$, and every polynomial $F(s)\in \R[s]$ of degree $r$ can be written uniquely in the form
\begin{equation}
\label{eq:F}
F(s) = \sum_{\ell = 0}^{r} f_\ell Q_{\ell} (s),
\end{equation}
called the \emph{Gegenbauer expansion} of $F(s)$.
Note that, since the polynomials $Q_\ell(s)$ are the orthogonal polynomials on the closed interval $[-1, 1]$ with respect to the inner product of the weight function $(1 - s^2)^{1/2}$, the coefficient $f_\ell\in \R$ given in \eqref{eq:F} can be computed from
\[
f_\ell = \frac{ \int_{-1}^{1} F(s) Q_{ \ell} (s) (1 - s^2)^{\frac12} \; ds}{ \int_{-1}^{1} Q_\ell(s)^2(1 - s^2)^{\frac12} \; ds}.
\]


\begin{lemma}\label{lem:LP_bound}
Let $X\subset \mathbb{S}^3$ be a spherical $T$-design and $F(s)\in \R[s]$ of degree $r$.
Suppose that the Gegenbauer expansion \eqref{eq:F} of $F(s)$ satisfies 
 $f_\ell \leq 0 $
 for all $\ell \not\in T$ (we call $F(s)$ a test function).
Then we have the inequality
\[ f_0|X|^2-F(1)|X| \ge \sum_{s\in A(X)} F(s)A_s(X),\]
where $A_s(X)$ and $A(X)$ are defined in \eqref{eq:d_a} and \eqref{eq:A(X)}, respectively. 
\end{lemma}
\begin{proof}
This is an immediate consequence of \cite[Lemma 3.1]{HiraoNozakiTasaka} (see also \cite[Corollary 3.8]{DelsarteGoethalsSeidel77}). 
\end{proof}

We are now in a position to show Theorem \ref{thm:LP_bound}.

\begin{proof}[Proof of Theorem \ref{thm:LP_bound}]
(i) This was shown in \cite[Theorem 3.2]{HiraoNozakiTasaka}, but we repeat the proof.
Let $X'$ be a half set of an antipodal spherical $\{10,4,2\}$-design $X$ of $\mathbb{S}^3$.
From \eqref{eq:antipodal_cardinality} it suffices to show that $|X'|\ge12$.
Let 
\[ F_{2T}(s):= \frac{1}{11264} Q_{10}(s) + \frac{1}{2560} Q_{4} (s) + 
\frac{1}{768} Q_{2} (s) + \frac{3}{1024}.\]
Applying this to Lemma \ref{lem:LP_bound}, we obtain
\begin{equation}\label{eq:F_{2T}_ineq} 
 \frac{3}{1024} |X'|^2 - F_{2T}(1)|X'| \ge \sum_{s\in A(X')} F_{2T}(s)A_s(X').
\end{equation}
Note that the polynomial $F_{2T}$ has the following factorization:
\begin{equation}\label{eq:F_{2T}}
F_{2T}(s)= s^2 \left(s + \frac{1}{2} \right)^2 \left(s - \frac{1}{2} \right)^2 \left( \left(s^2 - \frac78\right)^2 + \frac34\right).
\end{equation}
It follows from \eqref{eq:F_{2T}} that $F_{2T}(s)\ge0$ for any $s\in [-1,1]$.
Since $A(X')\subset (-1,1)$, we obtain the inequality $\sum_{s\in A(X')} F_{2T}(s)A_s(X')\ge0$, and hence,
\[ |X'| \ge \frac{1024}{3} F_{2T}(1)=12.\]

(ii) Let $X'$ be a half set of an antipodal spherical $\{14,10,6,4,2\}$-design $X$ of $\mathbb{S}^3$.
Consider
\begin{align*}
F_{2O}(s)&:= \frac{1}{245760} Q_{14}(s) + \frac{1}{135168} Q_{10}(s) + \frac{1}{114688} Q_6(s) + \frac{1}{49152} Q_4(s) 
   + \frac{1}{147456 }Q_2(s) + \frac{1}{8192}.
\end{align*}
With this, Lemma \ref{lem:LP_bound} gives the inequality $ \frac{1}{8192} |X'|^2 - F_{2O}(1)|X'| \ge \sum_{s\in A(X')} F_{2O}(s)A_s(X')$.
From the another expression
\begin{equation}\label{eq:F_{2O}}
F_{2O}(s)=s^2\left( s+\frac12\right)^2  \left( s-\frac12\right)^2 \left(  s^2-\frac12\right)^2 \left(\left(s^2- \frac78 \right)^2 +\frac14 \right),
\end{equation}
we see that $F_{2O}(s)\ge0$ for any $s\in [-1,1]$.
Therefore, one gets the desired inequality 
\[ |X'| \ge 8192 F_{2O}(1)= 24.\]

(iii) 
Let $X'$ be a half set of an antipodal spherical $\{10,8,6,4,2\}$-design $X$ of $\mathbb{S}^3$.
Applying 
\begin{equation}\label{eq:F_{2I}}
\begin{aligned}
F_{2I}(s) &:= 
- \frac{1}{1114112} Q_{16}(s)
- \frac{11}{4915200} Q_{14}(s)
+ \frac{21}{1802240} Q_{10}(s)
+ \frac{17}{491520} Q_{8}(x) \\
&\quad + \frac{11}{163840} Q_{6}(s)
+ \frac{177}{1638400} Q_4(s)
+ \frac{149}{983040} Q_2(s)
+ \frac{3}{16384} \\
&= s^2 \left(s - \frac{\tau^{-1}}{2} \right)^2
\left(s + \frac{\tau^{-1}}{2} \right)^2
\left(s - \frac{\tau}{2} \right)^2
\left(s + \frac{\tau}{2} \right)^2 \left(s^2 - \frac14\right)^2
\left( \frac{6}{5} - s^2 \right)
\end{aligned}
\end{equation}
to Lemma \ref{lem:LP_bound}, we obtain 
$\frac{3}{16384} |X'|^2 - F_{2I}(1)|X'|\ge 0$ (note that the coefficients of $Q_{16}$ and $Q_{14}$ in the Gegenbauer expansion of $F_{2I}$ are negative).
Hence, it holds that
\[ |X'|\ge  \frac{16384}{3} F_{2I}(1) = 60.\]
\end{proof}

\begin{remark}
By finding a test function of degree $17$, which is different from our $F_{2I}(s)$, Andreev \cite[Theorem 1]{Andreev} proved that every spherical $11$-design $X\subset \mathbb{S}^3$ satisfies $|X|\ge120$ (see also \cite[Theorem 6]{BoyvalenkovDanev01}).
\end{remark}


From the above proofs, we are led to the following definition.

\begin{definition}
\begin{itemize}
\item[(i)] An antipodal spherical $\{10,4,2\}$-design $X$ of $\mathbb{S}^3$ is said to be \emph{minimal} when $|X|=24$.
\item[(ii)] An antipodal spherical $\{14,10,6,4,2\}$-design $X$ of $\mathbb{S}^3$ is said to be \emph{minimal} when $|X|=48$.
\item[(iii)] An antipodal spherical $\{10,8,6,4,2\}$-design $X$ of $\mathbb{S}^3$ is said to be \emph{minimal} when $|X|=120$.
\end{itemize}
\end{definition}

Using the expressions \eqref{eq:F_{2T}}, \eqref{eq:F_{2O}} and \eqref{eq:F_{2I}} of our test functions, one can control the set $A(X)$ of inner products for the above minimal antipodal spherical $T$-designs $X$. 

\begin{corollary}\label{cor:angles}
\begin{itemize}
\item[(i)] An antipodal spherical $\{10,4,2\}$-design $X$ of $\mathbb{S}^3$ is minimal if and only if
\[A(X) \subset \left\{-1,\pm \frac12,0\right\}.\]
\item[(ii)] An antipodal spherical $\{14,10,6,4,2\}$-design $X$ of $\mathbb{S}^3$ is minimal if and only if 
\[A(X)\subset \left\{-1,\pm \frac{1}{\sqrt{2}},\pm \frac12,0\right\}.\]
\item[(iii)] An antipodal spherical $\{10,8,6,4,2\}$-design $X$ of $\mathbb{S}^3$ is minimal if and only if
\[A(X)\subset \left\{-1,\pm \frac{\tau^{-1}}{2},\pm \frac{\tau}{2}, \pm \frac12,0\right\}.\]
\end{itemize}
\end{corollary}
\begin{proof}
For a half set $X'$ of an antipodal spherical $\{10,4,2\}$-design $X$ of $\mathbb{S}^3$, it follows from \eqref{eq:F_{2T}_ineq} that the equality $|X'|=12$ holds if and only if $F_{2T}(s)=0$ for all $s\in A(X')$.
Thus, the result follows from the expression in \eqref{eq:F_{2T}}.
The other two cases are obtained in much the same way as above and are therefore omitted.
\end{proof}



