\section{Application to modular forms}\label{sec:order}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Orders and modular forms}
Let $F$ be a totally real number field and $R$ its ring of integers.
The $F$-vector space 
\[D(F):=\{x_1+x_2i+x_3j+x_4k\mid x_1,\ldots,x_4\in F\}\]
forms an $F$-algebra, called the \emph{quaternion algebra over $F$}.
A subring $O\subset D(F)$ is an \emph{$R$-order} if there exists a basis $\{b_1,b_2,b_3,b_4\}$ of $D(F)$ such that $O=Rb_1\oplus R b_2\oplus Rb_3\oplus R b_4$. 
Note that the set $N(O)$ of all norm values of $O$ is a subset of $R$ (cf.~\cite[Chapter 10]{Voight2021}).
An $R$-order of $D$ is said to be \emph{maximal} if it is not properly contained in another $R$-order of $D$.

Recall our orders from the introduction.
Let $F_{2T}=\Q,\ F_{2O}=\Q\big(\sqrt{2}\big)$ and $F_{2I}=\Q\big(\sqrt{5}\big)$.
From \eqref{eq:def_exceptional_groups}, we see that each $G\in\{2T,2O,2I\}$ is a subset of $F_G^4$.
Let $R_G$ be the ring of integers of $F_G$, i.e., $R_{2T}=\Z, R_{2O}=\Z[\sqrt{2}], R_{2I}=\Z[\tau]$ with $\tau=\frac{1+\sqrt{5}}{2}$, and $\mathcal{O}_G=\langle G\rangle_{R_G}$ the $R_G$-subalgebra of the quaternion algebra over $F_G$ generated by $G$.
Then, $\mathcal{O}_G$ is a maximal $R_G$-order (cf.~\cite[Chapter 11]{Voight2021}).
Its basis is given in Table \ref{table:orders}.
For $G\in \{2T,2O,2I\}$, we define the map $\iota_G:R_G\rightarrow\Z$ by
\begin{equation}\label{eq:def_iota}
\begin{aligned}
&\iota_{2T}(a)=a, \quad (a\in \Z=R_{2T}),\\
&\iota_{2O}(a+b\sqrt{2})=a, \quad (a+b\sqrt{2}\in \Z+\Z\sqrt{2}=R_{2O}),\\
&\iota_{2I}(a+b\tau)=a, \quad (a+b\tau\in \Z+\Z\tau=R_{2I}).
\end{aligned}
\end{equation}

For $G\in \{2T,2O,2I\}$, let
\[\mathcal{Q}_G(x):=\iota_G(N(x)).\]
For $m\in \N$, we study the following finite subset of $\R^4$:
\[ \mathcal{O}_{G,m}=\{ x\in \mathcal{O}_G\mid \mathcal{Q}_G(x)=m\}.\]
We give explicit formulas for $|\mathcal{O}_{G,m}|$.
For this, let $\sigma_k(m)=\sum_{d\mid m}d^k$ be the divisor function.
We set $\sigma_k(m/2)=0$ if $m$ is odd.

\begin{proposition}\label{prop:counting}
\begin{itemize}
\item[(i)] For $m\in \N$, we have $|\mathcal{O}_{2T,m}| = 24\left(\sigma_1(m)-2\sigma_1\left(\frac{m}{2}\right)\right)>0$. 
Moreover, $\mathcal{O}_{2T,1}=2T$. 
\item[(ii)] For $m\in \N$, we have $|\mathcal{O}_{2O,m}| = 240\left(5\sigma_3(m)-4\sigma_3\left(\frac{m}{2}\right)\right)>0$. 
Moreover, $\mathcal{O}_{2O,1}=2O$. 
\item[(iii)] For $m\in \N$, we have $|\mathcal{O}_{2I,m}| =  240\sigma_3(m)>0$. 
Moreover, $\mathcal{O}_{2I,1}=2I\cup \tau\, 2I$. 
\end{itemize}
\end{proposition}
\begin{proof}
For each $G\in \{2T,2O,2I\}$, we first observe that $\mathcal{Q}_G(x)\in \Z$ for $x\in \mathcal{O}_G$ defines a positive definite integral quadratic form (for background on quadratic forms, see \cite[Chapter 6]{Ogg}).
This implies that the spherical theta function $\theta_{G,P}(z)=\sum_{x\in \mathcal{O}_G} P(x) q^{\mathcal{Q}_G(x)} \ (q=e^{2\pi i z})$ defined in \eqref{eq:theta}, is a modular form (cf.~\cite[\S4.9]{Miyake}, \cite[\S6]{Ogg}).
Then, using the theory of modular forms, we express the generating function $\theta_{G,1}(z)=\sum_{m\ge0}| \mathcal{O}_{G,m} |q^{m}$ in terms of the Eisenstein series $E_2(z)=1-24\sum_{m\ge1}\sigma_1(m)q^{m}$ and $E_4(z)=1+240\sum_{m\ge1}\sigma_3(m)q^{m}$.
For the theory of modular forms for the congruence subgroup, see \cite{DS}.
The quadratic form $\mathcal{Q}_G(x)$ is also used to give a description of $\mathcal{O}_{G,1}$ (we solve the Diophantine equation $\mathcal{Q}_G(x)=1$ with the aid of Mathematica).


For the Hurwitz order $\mathcal{O}_{2T}$, let $x=r_1+r_2 i+ r_3 j+ r_4 \omega\in \mathcal{O}_{2T}$ with $r_1,r_2,r_3,r_4\in \Z$.
Then one obtains
\[\mathcal{Q}_{2T}(x)= r_1^2+r_2^2+r_3^2+r_4^2-r_1r_4-r_2r_4-r_3r_4,\]
which defines a positive definite integral quadratic form of level 2 and discriminant 4.
Hence, the spherical theta function $\theta_{2T,P}(z)$ for $P\in {\rm Harm}_\ell(\R^4)$ is a modular form of weight $2+\ell$ for $\Gamma_0(2)$.
The space of modular forms of weight $2$ for $\Gamma_0(2)$ is 1-dimensional spanned by $2E_2(z)-E_2(2z)$.
Therefore, we have
\[\theta_{2T,1}(z)=2E_2(2z)-E_2(z) =1+24q+24q^2+96q^3+24q^4+\cdots. \]
By finding integral solutions to the equation $r_1^2+r_2^2+r_3^2+r_4^2-r_1r_4-r_2r_4-r_3r_4=1$, we obtain $\mathcal{O}_{2T,1}=2T$.
Below is an example of Mathematica code to compute the set $\mathcal{O}_{2T,1}$:

\verb|Solve[r1^2+r2^2+r3^2+r4^2-r1*r4-r2*r4-r3*r4==1, {r1,r2,r3,r4}, Integers]|

\

For the case $\mathcal{O}_{2O}$, using the integral basis of $\Z[\sqrt{2}]$, we write $x=(y_1+z_1\sqrt{2})+(y_2+z_2\sqrt{2})\alpha +(y_3+z_3\sqrt{2})\beta+(y_4+z_4\sqrt{2})\alpha \beta \in \mathcal{O}_{2O}$ with $y_j,z_j\in \Z$.
Then we have
\begin{align*}
 \mathcal{Q}_{2O}(x) &= y_{1}^2+y_{1} y_{4}+2 y_{1} z_{2}+2 y_{1}
   z_{3}+y_{2}^2+y_{2} y_{3}+2 y_{2} z_{1}+2 y_{2}
   z_{4}+y_{3}^2+2 y_{3} z_{1}\\
 &+2 y_{3} z_{4}+y_{4}^2+2
   y_{4} z_{2}+2 y_{4} z_{3}+2 z_{1}^2+2 z_{1} z_{4}+2
   z_{2}^2+2 z_{2} z_{3}+2 z_{3}^2+2 z_{4}^2,
\end{align*}
which is positive definite.
%The symmetric matrix of the quadratic form is 
%\[\frac12 \begin{pmatrix} 2 & 0 & 0 & 2 & 0 & 2 & 1 & 0 \\
% 0 & 4 & 2 & 0 & 2 & 0 & 0 & 2 \\
% 0 & 2 & 2 & 0 & 1 & 0 & 0 & 2 \\
% 2 & 0 & 0 & 4 & 0 & 2 & 2 & 0 \\
% 0 & 2 & 1 & 0 & 2 & 0 & 0 & 2 \\
% 2 & 0 & 0 & 2 & 0 & 4 & 2 & 0 \\
% 1 & 0 & 0 & 2 & 0 & 2 & 2 & 0 \\
% 0 & 2 & 2 & 0 & 2 & 0 & 0 & 4 \end{pmatrix}.\]
The level and the discriminant of the above quadratic form is 2 and 16, respectively.
Hence, $\theta_{2O,P}(z)$ for $P\in {\rm Harm}_\ell(\R^4)$ is a modular form of weight $4+\ell$ for $\Gamma_0(2)$.
Note that the space of modular forms of weight $4$ for $\Gamma_0(2)$ is 2-dimensional.
Due to the Strum bound \cite[Corollary 9.20]{Stein}, expressing $\theta_{2O,1}(z)$ in terms of the Eisenstein series requires the coefficient of $q$, namely, $|\mathcal{O}_{2O,1}|$.
Now, let the computer calculate integer solutions to $\mathcal{Q}_{2O}(x)=1$ to get an explicit description of $\mathcal{O}_{2O,1}$. 
The result is $\mathcal{O}_{2O,1}=2O$. 
Hence, $|\mathcal{O}_{2O,1}|=48$ and we get
\[ \theta_{2O,1}(z)=5 E_4(z)-4 E_4(2z) = 1+48q+624q^2+1344q^3+5232q^4+\cdots.\]



For the case $\mathcal{O}_{2I}$, we also write $x=(y_1+z_1\tau)+(y_2+z_2\tau)i +(y_3+z_3\tau)\zeta +(y_4+z_4\tau)i\zeta \in \mathcal{O}_{2I}$ with $y_j,z_j\in \Z$.
It holds that
\begin{align*} 
\mathcal{Q}_{2I}(x) &= y_{1}^2+y_{1} y_{4}+y_{1} z_{3}-y_{1}
   z_{4}+y_{2}^2-y_{2} y_{3}+y_{2} z_{3}+y_{2}
   z_{4}+y_{3}^2+y_{3} z_{1}\\
   &+y_{3} z_{2}+y_{4}^2-y_{4}
   z_{1}+y_{4} z_{2}+z_{1}^2+z_{1} z_{3}+z_{2}^2+z_{2}
   z_{4}+z_{3}^2+z_{4}^2.
   \end{align*}
This is a positive definite integral quadratic form of level 1 and discriminant 1.
Thus, $\theta_{2I,P}(z)$ for $P\in {\rm Harm}_\ell(\R^4)$ is a modular form of weight $4+\ell$ for ${\rm SL}_2(\Z)$.
Since the underlying vector space is 1-dimensional, we get
\[ \theta_{2I,1}(z)=E_4(z) = 1+240q+2160q^2+6720q^3+17520q^4+\cdots.\]
One can check that the set $\mathcal{O}_{2I,1}$ of integer solutions to the equation $\mathcal{Q}_{2I}(x)=1$ has 240 points. Moreover, we obtain $\mathcal{O}_{2I,1}=2I \cup \tau\, 2I$, meaning that the set $\mathcal{O}_{2I,1}$ consists of two copies of $2I$.
This completes the proof.
\end{proof}




\begin{remark}
As the formula $|\mathcal{O}_{2I,m}| = 240\sigma_3(m)$ suggests, the $\Z[\tau]$-order $\mathcal{O}_{2I}$ has a connection with the $E_8$ lattice (an even integral unimodular lattice in $\R^8$).
Let $\kappa_4 : D(\Q(\tau))\rightarrow \Q^8$ be the $\Q$-linear map defined by 
\[ \kappa_4\big( (a_1+b_1\tau)+(a_2+b_2\tau)i+(a_3+b_3\tau)j+(a_4+b_4\tau)k\big)=(a_1,b_1,a_2,b_2,a_3,b_3,a_4,b_4).\]
Then, the image $\kappa_4\big(\mathcal{O}_{2I}\big)$ is isometric to the $E_8$ lattice.
Furthermore, the map $\kappa_4$ gives a bijection from $\mathcal{O}_{2I,m}$ to the $2m$-shell of the $E_8$ lattice.
This is because for $x=(a_1+b_1\tau)+(a_2+b_2\tau)i+(a_3+b_3\tau)j+(a_4+b_4\tau)k\in\mathcal{O}_{2I}$, it holds that
\[\iota_{2I}(N(x))=a_1^2+b_1^2+\cdots+a_4^2+b_4^2=\langle \kappa_4(x),\kappa_4(x)\rangle,\] 
where we have used $\tau^2=\tau+1$.
For more details, see \cite[Chapter 8]{ConwaySloan}. 
\end{remark}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Proof of Theorem \ref{thm:dim=0}}

We first prove \eqref{eq:G_acts_on_O_{G,m}}.
For this, recall that the multiplication by a quaternion yields an orthogonal transformation (Lemma \ref{lem:quaternion_orthogonal}).

\begin{proposition}\label{prop:O_strength}
Let $G\in\{2T,2O,2I\}$. 
For all $m\in \N$, we have $T(G)\subset T\big(\mathcal{O}_{G,m}\big)$.
In particular, the equality $T(G)=T\big(\mathcal{O}_{G,1}\big)$ holds.
\end{proposition}
\begin{proof}
Let $m\in \N$.
For $\varepsilon\in G$ and $x\in \mathcal{O}_{G,m}$, since $N(x\varepsilon)=N(x)$, it holds that $x\varepsilon \in \mathcal{O}_{G,m}$.
This shows that $G$ acts on the set $\mathcal{O}_{G,m}$. 
Hence, we have a $G$-orbit decomposition 
\begin{equation}\label{eq:orbit_decomp} 
\mathcal{O}_{G,m} = \bigsqcup_{x\in S_m} xG
\end{equation}
of $\mathcal{O}_{G,m}$ as a disjoint union of $\{xG \mid x\in S_m\}$ for some $S_m\subset \mathcal{O}_{G,m}$.
By Lemma \ref{lem:quaternion_orthogonal}, the $G$-orbit $xG$ is an orthogonal transformation of $\sqrt{N(x)} G$.
It is well known that, for $P\in {\rm Harm}_\ell (\R^4)$ and $g\in O(\R^4)$, we have $gP\in {\rm Harm}_\ell (\R^4)$, where $(gP)(x):=P(g(x))$.
Therefore, $T(G)= T(xG)$ holds for any $x\in S_m$.
Finally, the result follows from the fact that $T(X_1\sqcup X_2)$ contains $ T(X_1)\cap T(X_2)$.

Let us turn to the case $m=1$.
From Proposition \ref{prop:counting}, for $G\in \{2T,2O\}$, we have $G=\mathcal{O}_{G,1}$.
Thus, $T(G)=T\big(\mathcal{O}_{G,1}\big)$.
For the case $G=2I$, since $T(2I)\subset T\big(\mathcal{O}_{2I,1}\big)$, it suffices to show $T(2I)\supset T\big(\mathcal{O}_{2I,1}\big)$.
Suppose $\ell\in T\big(\mathcal{O}_{2I,1}\big)$.
By Proposition \ref{prop:counting} (iii), for all $P\in {\rm Harm}_\ell(\R^4)$ one has
\[ 0=\sum_{x\in \mathcal{O}_{2I,1}} P(x)=\sum_{x\in 2I} P(x) + \sum_{x\in 2I} P(\tau x)=(1+\tau^\ell ) \sum_{x\in 2I} P( x).\]
Thus, $\ell \in T(2I)$.
This completes the proof.
\end{proof}

We are now in a position to prove Theorem \ref{thm:dim=0}.

\begin{proof}[Proof of Theorem \ref{thm:dim=0}]
We first prove that $\dim_\C \Theta(G,\ell)=0 \Rightarrow \ell \in T(G)$.
Suppose $\ell \not\in T(G)$.
Then, by Lemma \ref{prop:O_strength}, $\ell \not\in T\big(\mathcal{O}_{G,1}\big)$.
This shows that there exists $P\in {\rm Harm}_\ell(\R^4)$ such that $\theta_{G,P}(z)\neq0$.
Hence, $\dim_\C\Theta(G,\ell)\ge1$.

Let us turn to the proof of $ \ell \in T(G)\Rightarrow \dim_\C \Theta(G,\ell)=0$.
For $\ell \in T(G)$, by Lemma \ref{prop:O_strength}, $\ell \in T\big(\mathcal{O}_{G,m}\big)$ holds for all $m\in\N$.
Hence, $\theta_{G,P}=0$ for all $P\in {\rm Harm}_\ell (\R^4)$.
Thus, $\dim_\C\Theta(G,\ell)=0$.
We have done.
\end{proof}

\begin{remark}\label{rem:HNT}
In our previous paper \cite[\S6]{HiraoNozakiTasaka}, as an application of the uniqueness, we gave a decomposition of the $m$-shell of the $D_4$ lattice in terms of a disjoint union of the orthogonal transformations (up to scaler) of the $D_4$ root system.
We have the same structure: For any $m>0$, there exists a finite subset $U_m$ of the orthogonal transformation group $O(\R^4)$ such that 
\[\left\{ \frac{x}{\sqrt{N(x)}} \ \middle| \  x\in \mathcal{O}_{G,m}\right\}=\bigsqcup_{g\in U_m} g (G).\]
This is because the orbit $xG$ in \eqref{eq:orbit_decomp} is an orthogonal transformation of $\sqrt{N(x)} G$.
\end{remark}


