    \centering
    \includegraphics[width=0.336\linewidth]{FigS1.pdf}
    \caption{The full spectrum of Hamiltonian \eqref{eq:SM_ham_cont}, which includes four bands that form two pairs degenerate at $\Gamma$ point. We disregard the two higher energy bands when considering superconducting pairing as they are not present at the Fermi energy.}
    \label{fig:SM_full_spectrum}
\end{figure}

\section{Self-consistent solutions of the gap equations}
To determine the phase diagram of the superconducting states in the studied model, we first diagonalize the Hamiltonian of Eq.~\eqref{eq:SM_ham_cont}, obtaining four bands split into two doublets, one of which lies close to the Fermi energy. We take these two lowest-energy bands at the $\Gamma$ point and also include the parabolic band $\epsilon_M$. We label the dispersions of these three bands $\epsilon_i(\mathbf{k})$. Within this subspace, we consider interactions as discussed in the main text:
\begin{equation}
    H_\text{int} = -\frac{1}{N} \sum_{\mathbf{k}, \mathbf{k'}} \left[  V_1(\mathbf{k}, \mathbf{k'}) \sum_i c^\dagger_{i\mathbf{k}\uparrow} c^\dagger_{i-\mathbf{k}\downarrow} c_{i-\mathbf{k'}\downarrow} c_{i\mathbf{k'}\uparrow} +   V_2(\mathbf{k}, \mathbf{k'}) \sum_{i\neq j} c^\dagger_{i\mathbf{k}\uparrow} c^\dagger_{i-\mathbf{k}\downarrow} c_{j-\mathbf{k'}\downarrow} c_{j\mathbf{k'}\uparrow} \right]
\end{equation}
where $V_n(\mathbf{k}, \mathbf{k'}) = V_{ns}f_s(\mathbf{k})f_s(\mathbf{k'}) + V_{nd}f_d(\mathbf{k})f_d(\mathbf{k'})$ and $f_s(\mathbf{k}) = \cos(k_x) + \cos(k_y)$, $f_d(\mathbf{k}) = \cos(k_x) - \cos(k_y)$ are the $s_\pm$ and $d$ channel interaction form factors, respectively. We also keep in mind that the parabolic band $\epsilon_M$ (now labeled $\epsilon_3(\mathbf{k})$) is located at the M point, so in that case $\mathbf{k}$ in the interaction form factors is understood to mean $\mathbf{k}+\mathbf{Q}$ with $\mathbf{Q}=(\pi, \pi)$. We can now introduce the $s_\pm$ and $d$ order parameters for each of the bands considered in the model:
\begin{equation}
    \Delta^{(i)}(\mathbf{k}) = \Delta_{s}^{(i)} f_s(\mathbf{k}) + \Delta_{d}^{(i)} f_d(\mathbf{k})
\end{equation}
\begin{equation}
    \Delta^{(i)}_s = -\frac{1}{N} \sum_{\mathbf{k'}} \left[ V_{1s} f_s(\mathbf{k'}) \langle c_{i-\mathbf{k'}\downarrow} c_{i\mathbf{k'}\uparrow} \rangle + V_{2s}f_s(\mathbf{k'}) \sum_{j\neq i} \langle c_{j-\mathbf{k'}\downarrow} c_{j\mathbf{k'}\uparrow} \rangle \right]
\end{equation}
\begin{equation}
    \Delta^{(i)}_d = -\frac{1}{N} \sum_{\mathbf{k'}} \left[ V_{1d} f_d(\mathbf{k'}) \langle c_{i-\mathbf{k'}\downarrow} c_{i\mathbf{k'}\uparrow} \rangle + V_{2d}f_d(\mathbf{k'}) \sum_{j\neq i} \langle c_{j-\mathbf{k'}\downarrow} c_{j\mathbf{k'}\uparrow} \rangle \right]
\end{equation}
The expectation values are calculated using standard Matsubara Green function approach in Nambu space. We first define a Bogoliubov-de Gennes Hamiltonian as follows:
\begin{equation}
    H^\text{(b)}_\text{BdG}(\mathbf{k}) = \begin{pmatrix}
        H_\text{b}(\mathbf{k}) & \Delta(\mathbf{k}) \\
        \Delta(\mathbf{k})^\dagger & -H_\text{b}(-\mathbf{k})
    \end{pmatrix},
    \, \, \, \,
    H_\text{b}(\mathbf{k}) = \begin{pmatrix}
        \epsilon_{1}(\mathbf{k}) & 0 & 0 \\
        0 & \epsilon_{2}(\mathbf{k}) & 0 \\
        0 & 0 & \epsilon_{3}(\mathbf{k})
    \end{pmatrix},
    \, \, \, \,
    \Delta(\mathbf{k}) = \begin{pmatrix}
        \Delta^{(1)}(\mathbf{k}) & 0 & 0 \\
        0 & \Delta^{(2)}(\mathbf{k}) & 0 \\
        0 & 0 & \Delta^{(3)}(\mathbf{k})
    \end{pmatrix},
\end{equation}
and then define the Green function as $G^\text{(b)}(i\omega_n, \mathbf{k}) = (i\omega_n - H^\text{(b)}_\text{BdG}(\mathbf{k}))^{-1}$. The expectation values are then Matsubara frequency sums of appropriate matrix elements of $G^\text{(b)}(i\omega_n, \mathbf{k})$.

The gap equations are solved self-consistently starting from a random initial condition. The phase diagram is established by choosing a cutoff point of $\Delta_c = 10^{-4}$ eV: if both $s_\pm$ and $d$ order parameters exceed $\Delta_c$, the phase is labeled mixed $s_\pm+d$, and when only one of the $s_\pm$ or $d$ order parameters exceeds $\Delta_c$, the phase is labeled pure $s_\pm$ or pure $d$.

To calculate the density of states at the two iron sublattices, we transform the Hamiltonian $H_\text{BdG}^\text{(b)}(\mathbf{k})$ with the superconducting order parameters obtained through the self-consistent procedure from the band basis back to the sublattice/orbital basis using the unitary transformation determined during the original diagonalization of $H_0(\mathbf{k})$ of Eq.~\eqref{eq:SM_ham_cont}. We find the retarded Green function for the Bogoliubov-de Gennes Hamiltonian in the sublattice/orbital space $H^\text{(l)}_\text{BdG}(\mathbf{k})$ as $G^{\text{(l)}}(\omega + i\eta, \mathbf{k}) = (\omega + i\eta - H^\text{(l)}_\text{BdG}(\mathbf{k}))^{-1}$. With that, we get the A/B sublattice-resolved density of states $n_A(\omega), n_B(\omega)$ as:
\begin{equation}
    n_A(\omega) = - \frac{1}{\pi} \text{Im} \sum_{\mathbf{k}} \left( G^{\text{(l)}}_{11}(\omega+i\eta, \mathbf{k}) + G^{\text{(l)}}_{22}(\omega+i\eta, \mathbf{k}) \right)
\end{equation}
\begin{equation}
    n_B(\omega) = - \frac{1}{\pi} \text{Im} \sum_{\mathbf{k}} \left( G^{\text{(l)}}_{33}(\omega+i\eta, \mathbf{k}) + G^{\text{(l)}}_{44}(\omega+i\eta, \mathbf{k}) \right)
\end{equation}

