 \subsection{From BSDE to Nash equilibrium}\label{sec:sufficient}

To identify the FBSDE system and subsequently the BSDE that any mean-field equilibrium must satisfy we first solve the representative investor's optimization problem for any fixed externality using the martingale optimality principle. Subsequently, we solve the fixed-point problem to characterize MFG equilibria. 

 \subsubsection{Optimization}\label{sec:MOP}

 To solve the representative investor's utility optimization problem for a given externality, we introduce the auxiliary process
 \begin{equation}\label{eqn:R}
 		R^{\Pi,C}_t=\alpha \frac{ X_t^{1-\gamma}  }{1-\gamma} e^{Y_t} + \int_0^t f\left(C_s\nu_s^{-\theta},  \alpha \frac{X_s^{1-\gamma}}{1-\gamma}e^{Y_s}\right)\,ds, \qquad t \in [0,T],
 \end{equation}
 where $Y$ denotes the first component of the (unique) solution to a BSDE of the form 
 \begin{equation} \label{BSDE1}
 		-dY_t=g_t\,dt-Z_t\,dW_t-Z^0_t\,dW^0_t,\qquad Y_T=-\theta(1-\gamma)\log\nu_T,
 \end{equation}
where the driver $g$ is to be determined such that the following conditions are satisfied:  
\begin{itemize}
 	\item for each admissible investmet-consumption pair $(\Pi,C)$ the process $R^{\Pi,C}$ is a supermartingale,
 	\item for some admissible investmet-consumption pair $(\Pi^*,C^*)$ the process $R^{\Pi^*,C^*}$ is a martingale,
 	\item the initial values $R_0^{\Pi,C}$ are independent of the choice of $(\Pi,C)$. 
 \end{itemize}

 The following remark justifies our approach. It shows that under the above assumptions, the pair $(\Pi^*,C^*)$ is an optimal strategy.

 \begin{remark}
 	From the definition of the utility processes $V^{\Pi,C}$ and $R^{\Pi,C}$, we know that
 	\begin{itemize}
 		\item the process $V^{\Pi,C}_t+\int_0^t f(C_s\nu_s^{-\theta},V_s^{\Pi,C})\,ds$ is a local martingale
 		\item the process $\alpha\frac{X_t^{1-\gamma}}{1-\gamma} e^{Y_t} + \int_0^t f(C_s\nu_s^{-\theta}, \alpha \frac{X_s^{1-\gamma}}{1-\gamma}e^{Y_s}  )\,ds$ is 
		a local supermartingale,
	\end{itemize} 
and that
\[
	V^{\Pi,C}_T = \alpha\frac{(X^{\Pi,C}_T)^{1-\gamma}}{1-\gamma} e^{Y_T}. 
\]	

Thus, by the comparison principle in \cite[proof of Proposition 2.2, Step 3]{Xing2017}, it holds that
\[
		\alpha\frac{(X^{\Pi,C}_t)^{1-\gamma}}{1-\gamma} e^{Y_t} \geq V^{\Pi,C}_t, \qquad t \in [0,T].
\]
Since the left-hand side of the above inequality is independent of $(\Pi,C)$ at time $t=0$ we see that
%\[
%		\alpha \frac{x^{1-\gamma}}{1-\gamma} \geq V^{\Pi,C}_0
%\]
%and so
\[		
	\alpha	\frac{x^{1-\gamma}}{1-\gamma} \geq \sup_{\Pi,C} V_0^{\Pi,C}.
\]
Since $R^{\Pi^*,C^*}$ is assumed to be a martingale, the following equality holds for some process $(Z,Z^0)$:
\[
	\alpha \frac{ (X_t^{\Pi^*,C^*})^{1-\gamma}  }{1-\gamma} e^{Y_t} + \int_0^t f\left(C^*_s \nu_s^{-\theta},  \alpha \frac{(X_s^{\Pi^*,C^*})^{1-\gamma}}{1-\gamma}e^{Y_s}\right)\,ds=\int_0^tZ_s\,dW_s+\int_0^t Z^0_s\,dW^0_s, \quad t \in [0,T].
\]

It follows that the process 
\[
	\alpha \frac{ (X^{\Pi^*,C^*})^{1-\gamma}  }{1-\gamma} e^{Y} 
\]	
satisfies the recursive utility equation. As a result, 
\[
	V_t^{\Pi^*,C^*} = \alpha \frac{ (X_t^{\Pi^*,C^*})^{1-\gamma}  }{1-\gamma} e^{Y_t}, \qquad t \in [0,T].
\]	
In particular, 
$
	V_0^{\Pi^*,C^*}=\alpha \frac{ x^{1-\gamma}  }{1-\gamma} e^{Y_0} 
$	
from which we conclude that $(\Pi^*,C^*)$ is an optimal strategy. 
 \end{remark}

