 		c^*_t=\delta^\psi e^{  -\theta(\psi-1)\log\nu^*_t  } (\alpha e^{Y_t})^{ -\frac{\psi}{\widetilde\theta} }=\delta^\psi e^{-\theta(\psi-1)\mathbb E[	\widehat c^*_t|\mathcal F^0_t	]} e^{-\theta(\psi-1)\mathbb E[\widehat X^*_t|\mathcal F^0_t]} (\alpha e^{Y_t})^{-\frac{\psi}{\widetilde\theta}},
 \end{equation}
 which implies that the conditional expectation $\mathbb E[\widehat c^*_t|\mathcal F^0_t]$ satisfies the equation
 \begin{equation*}
 		\mathbb E[\widehat c^*_t|\mathcal F^0_t]=~\mathbb E[ \psi\log\delta	 ] - \mathbb E[\theta(\psi-1)]\mathbb E[	 \widehat c^*_t |\mathcal F^0_t	] - \mathbb E[\theta(\psi-1)]\mathbb E[\widehat X^*_t|\mathcal F^0_t] -  \mathbb E\left[\frac{\psi}{\widetilde\theta}\log\alpha\right]  -  \mathbb E\left[ \left.\frac{\psi}{\widetilde\theta} Y_t \right|\mathcal F^0_t\right].
\end{equation*}		
Thus, %({\bf Don't we need $c^*_T = 1$ somewhere? At least the notation above is a bit unclear; I guess this only holds on $[0,T)$})
\[		
 	\mathbb E[\widehat c^*_t|\mathcal F^0_t]=~ \frac{1}{1+\mathbb E[\theta(\psi-1)]}\left\{       \mathbb E[ \psi\log\delta]-\mathbb E[ \theta(\psi-1) ]\mathbb E[\widehat X^*_t|\mathcal F^0_t]		- \mathbb E\left[ \frac{\psi}{\widetilde\theta}\log\alpha  \right]	-\mathbb E\left[\left.  \frac{\psi}{\widetilde\theta}Y_t  \right|\mathcal F^0_t \right]		\right\}
\]
and so
\begin{equation}\label{fixed-point-nu}
\begin{split}
	\widehat\nu^*_t & ~ =\mathbb E[\widehat X^*_t|\mathcal F^0_t] + \mathbb E[\widehat c^*_t|\mathcal F^0_t] \\
	& ~ =\frac{1}{1+\mathbb E[ \theta(\psi-1) ]}\left\{   \mathbb E[ \psi\log\delta ] - \mathbb E\left[ \frac{\psi}{\widetilde\theta}\log\alpha   \right] - \mathbb E\left[ \left. \frac{\psi}{\widetilde\theta} Y_t\right|\mathcal F^0_t   \right]        \right\} + \frac{1}{1+\mathbb E[ \theta(\psi-1)  ]}\mathbb E[ \widehat X^*_t|\mathcal F^0_t ].
\end{split}
\end{equation}
Define 	
\[
	\widetilde Y:=Y+\theta(1-\gamma)\mathbb E[\widehat X^*|\mathcal F^0].
\]
	This process satisfies the backward equation with zero terminal condition 
\begin{equation}\label{MF-BSDE-1}
	\begin{split}
		\widetilde Y_t =&~-\theta(1-\gamma)\int_t^T \mathbb E\left[\left.    	r_s+\pi^*_sh_s-c^*_s-\frac{1}{2}(\pi^*_s)^2(\sigma^2_s+(\sigma^0_s)^2)	\right|\mathcal F^0_s	 \right]  \,ds \\
		&~+ \int_t^T  ~\left\{ \frac{Z^2_s+(Z^0_s)^2}{2} +(1-\gamma)r_s+\frac{1-\gamma}{2\gamma} \frac{	(h_s+\sigma_s Z_s+\sigma^0_sZ^0_s)^2		}{\sigma^2_s+(\sigma^0_s)^2}  \right. \\ 
		&~ \left. \qquad +\frac{1-\gamma}{\psi-1} \delta^\psi(\nu^*_s)^{-\theta(\psi-1)} (\alpha e^{Y_s})^{ -\frac{\psi}{\widetilde\theta} } -\delta\widetilde\theta\right\}\,ds\\
		&~ - \int_t^TZ_s\,dW_s-\int_t^T\left\{ Z^0_s+\theta(1-\gamma) \mathbb E[\pi^*_s\sigma^0_s |\mathcal F^0_s	] \right\} \,dW^0_s.
		%	=&~-\theta(1-\gamma)\int_t^T\mathbb E[ r_s|\mathcal F^0_s	]\,ds + \int_t^T \Big\{  (1-\gamma)r_s-\delta\widetilde\theta \Big\}  \,ds+\theta(1-\gamma)\int_t^T\mathbb E[ c^*_s|\mathcal F^0_s	]\,ds +\int_t^T \frac{1-\gamma}{\psi-1}c^*_s  \,ds\\
		%		&~+\int_t^T\mathcal J_{\widetilde Z,\widetilde Z^0}(s)\,ds - \int_t^T\widetilde Z_s\,dW_s-\int_t^T\widetilde Z^0_s\,dW^0_s,
	\end{split}
\end{equation}
	To bring this equation into standard BSDE format we set
\begin{equation}\label{change:Z}
	\widetilde Z:=Z,\qquad \widetilde Z^0:=Z^0+\theta(1-\gamma)\mathbb E[\pi^*\sigma^0|\mathcal F^0]=Z^0+\theta(1-\gamma)\mathbb E\left[ \left.  \frac{h+\sigma Z+\sigma^0Z^0}{\gamma( \sigma^2+(\sigma^0)^2  )}\sigma^0   \right|\mathcal F^0       \right],
\end{equation}
where the second equality is equivalent to 
\begin{equation}\label{change:Z-0}
	Z^0=\widetilde Z^0-\frac{\theta(1-\gamma)\mathbb E\left[\left.     \frac{\sigma^0(  h+\sigma\widetilde Z+\sigma^0\widetilde Z^0   )}{\gamma(  \sigma^2+(\sigma^0)^2    )}		    \right|\mathcal F^0     \right]}{   1+\mathbb E\left[ \left.  	\frac{\theta(1-\gamma)(\sigma^0)^2}{\gamma( \sigma^2+(\sigma^0)^2  )}				  \right|\mathcal F^0   \right]   }.
\end{equation}
%Taking the first equality in \eqref{change:Z} and \eqref{change:Z-0} into \eqref{MF-BSDE-1}, we get 
Moreover, using the definition of $\widetilde Y$, the equalities in \eqref{consumption-equilibrium-1} and \eqref{fixed-point-nu} imply that {on $[0,T)$}
\begin{equation}\label{equilibrium-consumption}
	\begin{split}
		c^* 
		=&~\delta^\psi \alpha^{ -\frac{  \psi }{\widetilde\theta} }\exp\left(  -\theta(\psi-1)\widehat\nu^*-\frac{\psi}{\widetilde\theta}Y							         \right)\\
		=&~\delta^\psi \alpha^{ -\frac{  \psi }{\widetilde\theta} }\exp\left(  		-\frac{\theta(\psi-1)}{1+\mathbb E[ \theta(\psi-1) ]}\left\{   \mathbb E[\psi\log\delta]  - \mathbb E\left[ 	\frac{\psi}{\widetilde\theta}\log\alpha	   \right]	    \right\}	+\frac{\theta(\psi-1)}{1+\mathbb E[\theta(\psi-1)]}	\mathbb E\left[ \left. \frac{\psi}{\widetilde\theta}\widetilde Y	\right|\mathcal F^0	 \right]	-\frac{\psi}{\widetilde\theta}\widetilde Y				         \right)\\
		=&~\exp\left(   -\frac{\theta(\psi-1)}{1+\mathbb E[ \theta(\psi-1) ]}\left\{        \mathbb E[\psi\log\delta]  - \mathbb E\left[ 	\frac{\psi}{\widetilde\theta}\log\alpha	   \right]	  -\mathbb E\left[  \left.		\frac{\psi}{\widetilde\theta}\widetilde Y \right|\mathcal F^0      \right]          \right\}		+\psi\log\delta-\frac{\psi}{\widetilde\theta}\log\alpha-\frac{\psi}{\widetilde\theta}\widetilde Y		          \right).
	\end{split}
\end{equation}

Taking the first equality in \eqref{change:Z} and \eqref{change:Z-0} into the first equality in \eqref{consumption-optimization}, we get the equilibrium investment process
     \begin{equation}\label{equilibrium-investment}
	\pi^*=\frac{ h+\sigma \widetilde Z + \sigma^0\widetilde Z^0	}{\gamma(	\sigma^2+(\sigma^0)^2	)}  -  \frac{	\sigma^0\theta(1-\gamma)\mathbb E\left[\left.     \frac{\sigma^0(  h+\sigma\widetilde Z+\sigma^0\widetilde Z^0   )}{\gamma(  \sigma^2+(\sigma^0)^2    )}		    \right|\mathcal F^0     \right]			}{\gamma(	\sigma^2+(\sigma^0)^2		)   \left(   1+\mathbb E\left[ \left.  	\frac{\theta(1-\gamma)(\sigma^0)^2}{\gamma( \sigma^2+(\sigma^0)^2  )}				  \right|\mathcal F^0   \right]  \right)  }
\end{equation}
Taking the first equality in \eqref{change:Z} and \eqref{change:Z-0} into \eqref{MF-BSDE-1}, we get 
   \begin{equation}\label{MF-BSDE:tilde-Y}
	\begin{split}
		\widetilde Y_t%=&~-\theta(1-\gamma)\int_t^T \mathbb E\left[\left.    	r_s+\pi^*_sh_s-c^*_s-\frac{1}{2}(\pi^*_s)^2(\sigma^2_s+(\sigma^0_s)^2)	\right|\mathcal F^0_s	 \right]  \,ds \\
		% 		&~+ \int_t^T  ~\left\{ \frac{Z^2_s+(Z^0_s)^2}{2} +(1-\gamma)r_s+\frac{1-\gamma}{2\gamma} \frac{	(h_s+\sigma_s Z_s+\sigma^0_sZ^0_s)^2		}{\sigma^2+(\sigma^0)^2} +\frac{1-\gamma}{\psi-1} \delta^\psi(\nu^*_s)^{-\theta(\psi-1)} (\alpha e^{Y_s})^{ -\frac{\psi}{\widetilde\theta} } -\delta\widetilde\theta\right\}\,ds\\
		% 		&~ - \int_t^TZ_s\,dW_s-\int_t^T\left\{ Z^0_s+\theta(1-\gamma) \mathbb E[\pi^*_s\sigma^0_s |\mathcal F^0_s	] \right\} \,dW^0_s\\
		=&~-\theta(1-\gamma)\int_t^T\mathbb E[ r_s|\mathcal F^0_s	]\,ds + \int_t^T \Big\{  (1-\gamma)r_s-\delta\widetilde\theta \Big\}  \,ds+\theta(1-\gamma)\int_t^T\mathbb E[ c^*_s|\mathcal F^0_s	]\,ds \\
		&~+\int_t^T \frac{1-\gamma}{\psi-1}c^*_s  \,ds+\int_t^T\mathcal J_{\widetilde Z,\widetilde Z^0}(s)\,ds - \int_t^T\widetilde Z_s\,dW_s-\int_t^T\widetilde Z^0_s\,dW^0_s,
	\end{split}
\end{equation}
where $c^*$ is given by \eqref{equilibrium-consumption}, and $\mathcal J_{\widetilde Z,\widetilde Z^0}$ collects all terms containing $\widetilde Z$ and $\widetilde Z^0$, which is the same as \cite[Appendix B]{Fu2023}, with $\gamma$ there replaced by $1-\gamma$.  








The following theorem summarizes the findings of this subsection.
\begin{theorem}\label{thm:BSDE-to-NE}
%If the BSDE with the driver \eqref{driver-MOP} admits a solution $$(Y,Z,Z^0)\in L^\infty\times H^2_{BMO}\times H^2_{BMO},$$ then the optimization problem \eqref{utility-max} admits an optimal control $(\Pi^*,C^*) \in \mathcal A$, which is characterized by the equation \eqref{consumption-optimization}. Moreover, 
If the mean field BSDE \eqref{MF-BSDE:tilde-Y} admits a solution $(\widetilde Y,\widetilde Z, \widetilde Z^0)\in L^\infty\times H^2_{BMO}\times H^2_{BMO}$, then the mean-field portfolio game admits an equilibrium consumption rate $c^*\in L^\infty$ and an equilibrium investment rate $\pi^*\in H^2_{BMO}$ given by \eqref{equilibrium-consumption} and \eqref{equilibrium-investment}, respectively. %Let $X^*$ be the corresponding wealth process it holds that $(c^*X^*,\pi^*X^*)\in\mathcal A$.  
\end{theorem}

 \begin{remark}
 Theorem \ref{thm:BSDE-to-NE} only considers the consumption and investment in equilibrium. 
 	The best response can also be studied if the dynamics of $\nu$ is assumed to follow some SDE.
 \end{remark}
