\subsection{From Nash equilibrium to BSDE}\label{sec:necessary}

So far we derived a BSDE whose solution yields a mean-field equilibrium to our portfolio game. We proceed to prove that {\sl any} Nash equilibrium satisfies the previously obtained BSDE. 

In what follows we denote by $f_1$ and $f_2$ the derivatives of the aggregator $f$ w.r.t. the first and the second argument, respectively. In particular, 
\begin{equation}\label{eq:f_2}
	f_2(C,V)=\frac{	\delta C^{1-\frac{1}{\psi}}		}{1-\frac{1}{\psi}} \left(  1-\frac{1}{\widetilde\theta} \right) (1-\gamma) \big((1-\gamma) V\big)^{-\frac{1}{\widetilde\theta}}-\delta\widetilde\theta %\leq -\delta\widetilde\theta. 
\end{equation}
We start with the following necessary maximum principle for Epstein-Zin preferences.
\begin{proposition}\label{prop:maximum-principle}
{Let $\nu$ be an $\mathcal F^0$ progressively measurable process such that $\mathbb E\left[ \int_0^T \nu_t^\beta \,ds + \nu_T^\beta \right]<\infty$ for each $\beta\in\mathbb R$.} Let $(\Pi^*,C^*):=(\Pi^*(\nu),C^*(\nu))\in\mathcal A$ be an optimal control of \eqref{utility-max} and $(X^*,V^*):=(X^*(\nu),V^*(\nu))$ be the corresponding state process. Define the following (well posed) system of adjoint equations: 
	\begin{equation}\label{eq:adjoint}
		\left\{\begin{split}
			-dp_t=&~r_tp_t\,dt-q_t\,dW_t-q^0_t\,dW^0_t:=r_tp_t\,dt-\widetilde q^\top_t\,d\widetilde W_t,\quad p_T=-\alpha U'(X^*_T\nu^{-\theta}_T)\nu^{-\theta}_TQ_T\\
			dQ_t=&~ f_2( C^*_t\nu^{-\theta}_t, V^*_t )Q_t\,dt, \quad Q_0=-1.
		\end{split}\right.
	\end{equation}
	 Then, it holds that 
	\begin{equation}\label{optimality}
		ph+q\sigma+q\sigma^0=0,\qquad p+f_1(C^*\nu^{-\theta},V^*)\nu^{-\theta}Q=0.
	\end{equation}
\end{proposition}

\begin{proof}
	{\bf Step 1.} {\sl A priori estimates.} We start with a series of a priori estimates.
	\begin{itemize} \item We first consider the utility process. For any admissible pair $(\Pi,C)$ it follows from  
%	
%	
%	
%{\bf Step 1.1:} {\it the estimate of states $V^{\Pi,C}$.} 
%
\cite[Theorem 4.6]{Seifried-2015} that
\begin{equation}\label{power-bound}
		Y^{\gamma}	\leq	V^{\Pi,C}\leq U_{\gamma}\circ U^{-1}_{\frac{1}{\psi}}( Y^{\frac{1}{\psi}} ),
\end{equation}
where (following the notation in \cite{Seifried-2015})
\[
	Y^{\varrho}_t:=e^{\delta t}\mathbb E\left[\left. \int_t^T \delta e^{-\delta s} U_{\varrho}(C_s\nu^{-\theta}_s)\,ds +  e^{-\delta T}U_{\varrho}(C_T\nu^{-\theta}_T)   \right|\mathcal F_t   \right]   \quad   \textrm{ and }\quad U_{\varrho}(C):=\alpha\frac{C^{1-\varrho}}{1-\varrho}.          
\] 

Our assumptions on the consumption plan $C$ guarantee that the lower bound of the utility process $V^{\Pi,C}$ belongs to $\bigcap_{\beta>0}  S^\beta $. Since 
\[
	U_\gamma\circ U_{\frac{1}{\psi}}^{-1}(x)=\frac{1}{1-\gamma} \left\{ \left(  1-\frac{1}{\psi}  \right)x\right\}^{  \frac{1-\gamma}{1-\frac{1}{\psi}} }, 
\]	
the upper bound  also belongs to $\bigcap_{\beta>0} S^\beta $. Moreover, it follows from \eqref{power-bound}  that $(1-\gamma)V^{\Pi,C}\geq 0$. Hence,
\[
	f_2(C,V)\leq-\delta\widetilde\theta. 
\]

\item We proceed to bound the adjoint variables. By \eqref{eq:f_2}, the process $Q$ satisfies
\[
	0>Q_t=-\exp\left(  \int_0^t  f_2(  C^*_s, V^*_s    )\,ds   \right) \geq - e^{-\delta\widetilde\theta t}. 
\] 
Moreover, the processes $p$ and $q$ satisfy 
\begin{equation*}
	\begin{split}
		 0< p_t=\mathbb E\left[\left. -e^{\int_t^T r_s\,ds} \alpha  ( X_T^* )^{-\gamma}\nu_T^{-\theta(1-\gamma)}  Q_T    \right|\mathcal F_t  \right]\leq \mathbb E\left[\left.  e^{\int_t^Tr_s\,ds-\delta\widetilde\theta T}\alpha(X^*_T)^{-\gamma} \nu_T^{-\theta(1-\gamma)}	\right|\mathcal F_t \right].
	\end{split}
\end{equation*}
Since $X^*_T=C_T^*$ and because $C^*_T$ is integrable to all powers we deduce that 
$
 	p\in\bigcap_{\beta>0}S^\beta.
$ 
Since $$\int_t^T\widetilde q^\top_s\,d\widetilde W_s=\int_t^Tr_sp_s\,ds+p_T-p_t,$$ this implies that 
$$
		\mathbb E\left[ 	\left(  \int_0^T q^2_s\,ds   \right)^{\beta}	+ 	 \left(  \int_0^T (q^0_s)^2\,ds   \right)^{\beta}    \right]<\infty, \quad \textrm{ for all }\beta>0.
$$
\item Let us fix an admissible strategy $(\Pi,C)$ and consider the variational system 
\begin{equation}\label{eq:variational}
	\left\{\begin{split}
		d\mathcal X_t=&~\Big\{ r_t\mathcal X_t +( \Pi_t-\Pi^*_t	)h_t  - (C_t-C^*_t)\Big\}\,dt + ( \Pi_t-\Pi^*_t	)\sigma_t\,dW_t+(\Pi_t-\Pi^*_t)\sigma^0_t\,dW^0_t, \\
		-d\mathcal V_t=&~\Big\{  f_1( C^*_t\nu^{-\theta}_t,V^*_t )(C_t-C^*_t)\nu^{-\theta}_t + f_2( C^*_t\nu^{-\theta}_t,V^*_t )\mathcal V_t \Big\}\,dt - \mathcal Z_t\,dW_t-\mathcal Z^0_t\,dW^0_t,\\
		\mathcal X_0=&~0,  \quad \mathcal V_T=\alpha U'(X^*_T\nu^{-\theta}_T)\mathcal X_T\nu^{-\theta}_T. 
	\end{split}\right.
\end{equation}
By \cite[Proposition 6.2.1]{Pham-2008},
\[
\mathcal V_t=\mathbb E\left[ \left.\mathcal V_T e^{\int_t^T f_2(C^*_s\nu^{-\theta}_s,V^*_s)\,ds} + \int_t^T   f_1(	C^*_s\nu^{-\theta}_s, V^*_s	)   (C_s-C^*_s)\nu^{-\theta}_s e^{ \int_t^s  f_2(	C^*_s\nu^{-\theta}_s,V^*_s	) \,dr } \,ds \right|\mathcal F_t      \right],
\]
which implies that $\mathcal V\in \bigcap_{\beta>0}S^\beta$. Hence,
$$
\mathbb E\left[ 	\left(  \int_0^T \mathcal Z^2_s\,ds   \right)^{\beta}+	\left(  \int_0^T (\mathcal Z^0_s)^2\,ds   \right)^{\beta}	  \right]<\infty, \quad \textrm{ for all }\beta>0.
$$
\end{itemize}

