 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

{\bf Step 2. }{\sl Integration by parts}. 
To identify the initial value $\mathcal V_0$ in the varitional system \eqref{eq:variational} we apply an integration by parts to obtain that  
\begin{equation}\label{MP-int-by-part:1}
	\begin{split}
		%&~\alpha U'(X^*_T \mu^{-\theta}_T )\mathcal X_T\mu^{-\theta}_T Q_T = 	
		& ~  \mathcal V_TQ_T \\
	%	= &~ \mathcal V_0 Q_0 + \int_0^T \mathcal V_t\,dQ_t+\int_0^T Q_t\,d\mathcal V_t \\
		=&~-\mathcal V_0+\int_0^T\mathcal V_t f_2(  C^*_t \nu^{-\theta}_t,V^*_t )Q_t\,dt -\int_0^T Q_t\Big\{  f_1(C^*_t\nu^{-\theta}_t,V^*_t)( 	C_t-C^*_t )\nu^{-\theta}_t  
		+ f_2(C^*_t\nu^{-\theta}_t,V^*_t)\mathcal V_t  \Big\}\,dt \\
		& ~~~ + \int_0^T Q_t\mathcal Z_t\,dW_t + \int_0^T Q_t\mathcal Z^0_t\,dW^0_t \\
		=&~-\mathcal V_0-\int_0^T Q_t f_1(C^*_t\nu^{-\theta}_t,V^*_t)(	C_t-C^*_t )\nu^{-\theta}_t\,dt + \int_0^T Q_t\mathcal Z_t\,dW_t + \int_0^TQ_t\mathcal Z^0_t\,dW^0_t 
	\end{split}
\end{equation}
and
\begin{equation}\label{MP-int-by-part:2}
	\begin{split}
		%&~-\mathcal X_T\alpha U'(X^*_T \mu^{-\theta}_T )\mu^{-\theta}_TQ_T=
		& ~ \mathcal X_Tp_T\\
	%	=&~\int_0^T\mathcal X_t\,dp_t+\int_0^T p_t\,d\mathcal X_t+[\mathcal X,p]_T\\
		=&~  \int_0^T\mathcal X_tq_t\,dW_t + \int_0^T\mathcal X_tq^0_t\,dW^0_t +\int_0^T p_t\Big\{  	 h_t (\Pi_t-\Pi^*_t) - (C_t-C^*_t)			     \Big\}\,dt \\
		&~~~+ \int_0^T\sigma_t p_t   (\Pi_t-\Pi^*_t) \,dW_t + \int_0^T\sigma^0_tp_t( \Pi_t-\Pi^*_t	)\,dW^0_t+\int_0^T\sigma_tq_t     (\Pi_t-\Pi^*_t)		  \,dt + \int_0^T \sigma^0_tq^0_t(\Pi_t-\Pi^*_t)\,dt    \\
		=&~ \int_0^T \Big\{ 	p_th_t  (\Pi_t-\Pi^*_t) - p_t (C_t-C^*_t) + \sigma_t q_t  (\Pi_t-\Pi^*_t)	+\sigma^0_tq^0_t(\Pi_t-\Pi^*_t)		      \Big\}\,dt\\
		&~~~+\int_0^T \mathcal X_t q_t\,dW_t+\int_0^T \mathcal X_t q^0_t\,dW^0_t+\int_0^T\sigma_t p_t    (\Pi_t-\Pi^*_t) \,dW_t+\int_0^T\sigma_t p^0_t    (\Pi_t-\Pi^*_t) \,dW^0_t.
	\end{split}
\end{equation}
Summing up \eqref{MP-int-by-part:1} and \eqref{MP-int-by-part:2} shows that
\begin{equation*}
	\begin{split}
		\mathcal V_0=&~\int_0^T (	p_th_t+q_t\sigma_t + q^0_t\sigma^0_t	) (\Pi_t-\Pi^*_t)\,dt - \int_0^T\left(p_t+Q_tf_1( C^*_t\nu^{-\theta}_t,V^*_t)\nu^{-\theta}_t\right) (C_t-C^*_t)\,dt\\
		&~+ \int_0^T\left\{ Q_t\mathcal Z_t  + \mathcal X_t q_t +  \sigma_t p_t   (\Pi_t-\Pi^*_t) \right\}\,dW_t + \int_0^T\left\{  Q_t\mathcal Z^0_t  + \mathcal X_tq^0_t +  \sigma^0_t p_t   (\Pi_t-\Pi^*_t)\right\}\,dW_t .
	\end{split}
\end{equation*} 
In view of Step 1, the stochastic process
\[
 	\int_0^\cdot\left\{ Q_t\mathcal Z_t  + \mathcal X_t q_t  +  \sigma_t p_t   (\Pi_t-\Pi^*_t) \right\}\,dW_t+\int_0^\cdot\left\{ Q_t\mathcal Z^0_t  + \mathcal X_t q^0_t  +  \sigma^0_t p_t   (\Pi_t-\Pi^*_t) \right\}\,dW^0_t 
\]	
is a true martingale. Thus,
 \begin{equation}\label{tilde-V-0}
 		\mathcal V_0=\mathbb E\left[\int_0^T (	p_th_t+q_t\sigma_t+q^0_t\sigma^0_t	) (\Pi_t-\Pi^*_t)\,dt - \int_0^T\left(p_t+Q_tf_1( C^*_t\nu^{-\theta}_t,V^*_t )\nu^{-\theta}_t \right) (C_t-C^*_t)\,dt \right]. 
 \end{equation}

