{\bf Step 3:} {\it A perturbation result.} We now prove perturbation results for state processes from which we then conclude our maximum principle. 

We denote for any admissible pair $(\Pi,C)$ and any $\rho>0$ by $(X^\rho,V^\rho)$ the state process corresponding to the control 
\[
	\left(\Pi^*+\rho(\Pi-\Pi^*), C^*+\rho(C-C^*)  \right).
\]
\begin{itemize}
	\item We first establish the convergence of the processes $X^\rho-X^*$ and $\frac{X^\rho-X^*}{\rho}-\mathcal X$ where $\mathcal X$ was defined in \eqref{eq:variational}. The dynamics of the process $X^\rho-X^*$ follows the  linear SDE 
\begin{equation*}
	\left\{\begin{split}
		d(X^\rho_t-X^*_t)  =&~ r_t(X^\rho_t-X^*_t)\,dt +\rho h_t(  \Pi_t-\Pi^*_t  )\,dt + \rho\sigma_t( \Pi_t-\Pi^*_t )\,dW_t \\
		& ~~~ +\rho\sigma^0_t( \Pi_t-\Pi^*_t )\,dW^0_t- \rho(C_t-C^*_t)\,dt \\
		X^\rho_0-X^*_0 =&~0  
	\end{split}\right.
\end{equation*}
and for each $\beta>0$,
\begin{equation*}
	\begin{split}
		& ~ \mathbb E\left[ \sup_{0\leq t\leq T} | 	X^\rho_t-X^*_t		|^\beta   \right] \\
		\leq&~  C\rho^\beta \mathbb E\left[  \left(  \int_0^T |\Pi_s-\Pi^*_s|+| C_s-C^*_s		|\,ds		  \right)^\beta     \right] + C\rho^\beta\mathbb E\left[ \left( \int_0^T	(\Pi_s-\Pi^*_s)^2\,ds		    \right)^{\frac{\beta}{2}}     \right]\\
		\rightarrow&~0,\quad \textrm{as }\rho\rightarrow 0.
	\end{split}
\end{equation*}
Moreover, uniqueness result of linear SDEs yields that a.s. 
\[
	\frac{X^\rho-X^*}{\rho} - {\cal X} = 0.
\]

\item Next, we consider the convergence of the processes $V^\rho-V^*$ and $\frac{V^\rho-V^*}{\rho}-\mathcal V$ where $\mathcal V$ was also defined in \eqref{eq:variational}. The BSDE for the process $V^\rho-V^*$ can be linearized as 
\begin{equation*}
	\left\{\begin{split}
		-d(V^\rho_t-V^*_t)=&~ (C^\rho_t-C^*_t)\nu^{-\theta}_t\int_0^1 f_1(	C^*_t\nu^{-\theta}_t+\lambda(C^\rho_t-C^*_t)\nu^{-\theta}_t, V^\rho_t	)\,d\lambda  \\
		&~ +  (V^\rho_t-V^*_t) \int_0^1 f_2( 	C^*_t\nu^{-\theta}_t,V^*_t+\lambda(V^\rho_t-V^*_t)	   )\,d\lambda \\
		&~-(	Z^\rho_t-Z^*_t	)\,dW_t -(	Z^{0,\rho}_t-Z^{0,*}_t		)\,dW^0_t 	\\
		:=&~ \Big\{A_t(V^\rho_t-V^*_t)	+B_t	\Big\}\,dt  -(	Z^\rho_t-Z^*_t	)\,dW_t	 -(	Z^{0,\rho}_t-Z^{0,*}_t		)\,dW^0_t,		\\
		V^\rho_T-V^*_T=&~\alpha (  X^\rho_T-X^*_T	) \nu^{-\theta}_T  \int_0^1 U'(	X^*_T\nu^{-\theta}_T+\lambda(  X_T^\rho-X^*_T   )\nu^{-\theta}_T		)\,d\lambda. 	%\left[  \frac{\delta(	c^\rho_t X^\rho_t			)^{1-\frac{1}{\psi}}}{1-\frac{1}{\psi}}	(1-\frac{1}{\widetilde\theta})	 	(1-\gamma)\int_0^1 \Big\{ (1-\gamma)(	 V^*_t+\lambda(V^\rho_t-V^*_t)			)	\Big\}^{  -\frac{1}{\widetilde\theta} }\,d\lambda   -\delta\widetilde\theta 	   \right](V^\rho_t-V^*_t)\,dt \\
	%	&~+\delta( c^\rho_tX^\rho_t-c^*_tX^*_t ) \Big\{  (1-\gamma)V^*_t  \Big\}^{1-\frac{1}{\widetilde\theta}}			\int_0^1 \Big\{	 c^*_tX^*_t+\lambda( c^\rho_tX^\rho_t-c^*_tX^*_t )		  \Big\}^{-\frac{1}{\psi}}\,d\lambda\,dt - (Z^\rho_t-Z^*_t)\,dW_t,
	\end{split}\right.
\end{equation*}

We note that 
\[
	B\in\bigcap_{\beta >0}S^\beta \quad \mbox{and} \quad V_T^\rho-V^*_T\in\bigcap_{\beta>0}S^\beta. 
\]	

The above BSDE admits a unique solution if $B$ is truncated by replacing $B$ with $B\wedge n$ for some $n \in \bN$; the corresponding solution is denoted by $(\Delta V^n,\Delta Z^n)$. Standard comparison arguments show that  $\Delta V^n$ is increasing in $n$; we denote the pointwise limit by $\Delta V$. Since
\[
	\Delta V^n_t=\mathbb E\left[ \left.   e^{  \int_t^T A_s \,ds    }     (V^\rho_T-V^*_T)+\int_t^T  e^{ \int_t^sA_r\,dr   } (B_s\wedge n)  \,ds   \right|\mathcal F_t				\right],
\]
it follows by monotone convergence that
\[
	\Delta V_t=\mathbb E\left[ \left.   e^{  \int_t^T A_s \,ds    }     (V^\rho_T-V^*_T)+\int_t^T  e^{ \int_t^sA_r\,dr   } B_s   \,ds   \right|\mathcal F_t				\right],
\]
and so it follows from the previous result that 
\[
	\lim_{\rho\rightarrow 0}\mathbb E\left[	\sup_{0\leq t\leq T} | \Delta V_t|^\beta\right]=0 \quad \mbox{for any $\beta>0$}.
\]

We now apply a similar argument to the process $\frac{V^\rho-V^*}{\rho}-\mathcal V$. The BSDE for this process can be linearized as
\begin{equation*}
	\left\{\begin{split}
		  -d\left( \frac{V^\rho_t-V^*_t}{\rho}-\mathcal V_t \right) 
		 =&~\Big\{   \left( \frac{V^\rho_t-V^*_t}{\rho}-\mathcal V_t \right)\int_0^1 f_2( C^*_t\nu^{-\theta}_t, V^*_t+\lambda( V^\rho_t-V^*_t ) )\,d\lambda\\
		&~+\mathcal V_t \int_0^1 \Big\{   f_2( C^*_t\nu^{-\theta}_t,  V^*_t+\lambda(  V^\rho_t-V^*_t )   )  - f_2(C^*_t\nu^{-\theta}_t,V^*_t  )			     \Big\}\,d\lambda \\
		&~+(C_t-C^*_t)\nu^{-\theta}_t \int_0^1 \Big\{  f_1(C^*_t\nu^{-\theta}_t+\lambda( C^\rho_t-C^*_t  )\nu^{-\theta}_t, V^*_t			)\,d\lambda  - f_1(  C^*_t\nu^{-\theta}_t , V^*_t  ) \Big\} \,d\lambda \\
		&~-\left(\frac{Z^\rho_t-Z^*_t}{\rho} - \mathcal Z_t\right)\,dW_t -\left(\frac{Z^{0,\rho}_t-Z^{0,*}_t}{\rho} - \mathcal Z^0_t\right)\,dW^0_t \\
		:=&~	\left\{	\left( \frac{V^\rho_t-V^*_t}{\rho}-\mathcal V_t \right)I_1(t)+I_2(t)+I_3(t) 	\right\}\,dt \\
		&~	-\left(\frac{Z^\rho_t-Z^*_t}{\rho} - \mathcal Z_t\right)\,dW_t	-\left(\frac{Z^{0,\rho}_t-Z^{0,*}_t}{\rho} - \mathcal Z^0_t\right)\,dW^0_t,	\\
		\frac{V^\rho_T-V^*_T}{\rho}-\mathcal V_T=&~ \alpha\mathcal X_T \nu^{-\theta}_T \int_0^1 \left\{  U'( X_T^*\nu^{-\theta}_T+\lambda(X^\rho_T-X^*_T)\nu^{-\theta}_T )-U'(X^*_T\nu^{-\theta}_T) \right\}\,d\lambda.
	\end{split}\right.
\end{equation*}
Truncating the processes $I_2$ and $I_3$ by $n$ the resulting BSDE admits the unique solution  
\[
		(\Delta V)^{\rho,n}_t = \mathbb E\left[	\left.	\left(\frac{V^\rho_T-V^*_T}{\rho}-\mathcal V_T\right)  e^{ \int_t^T I_1(r)			\,dr }	+ \int_t^T e^{\int_t^s I_1(r)\,dr }    (	I_2(s)\wedge n + I_3(s)\wedge n	)\,ds	\right|\mathcal F_t	    \right].
\]
A standard comparison principle along with the monotone convergence  theorem shows that the sequence $(\Delta V)^{\rho,n}$ as $n\rightarrow\infty$ converges pointwise to the process
\[
	(\Delta V)^{\rho}_t = \mathbb E\left[	\left.	\left(\frac{V^\rho_T-V^*_T}{\rho}-\mathcal V_T\right)  e^{ \int_t^T I_1(r)			\,dr }	+ \int_t^T e^{\int_t^s I_1(r)\,dr }    (	I_2(s) + I_3(s) 	)\,ds	\right|\mathcal F_t	    \right].
\]
The previously established convergence of $X^\rho-X^*$ and $V^\rho-V^*$ yields that 
\[
	\lim_{	\rho\rightarrow 0	}\mathbb E\left[ \sup_{0\leq t\leq T} |(\Delta V)^\rho_t|^\beta    \right]=0 \quad \mbox{for each $\beta>0$}.
\]
\end{itemize}

{\bf Step 4.} {\sl Conclusion.} In view of \eqref{tilde-V-0} and the previously established convergence of the processes $\frac{V^\rho-V^*}{\rho}-\mathcal V$,  it holds for  any admissible $(\Pi,C)$ that
\begin{equation}\label{inequ:gradient}
	\begin{split}
		0 & ~ \geq \frac{V^\rho_0-V^*_0}{\rho}  \rightarrow	\mathcal V_0 \\
		&~ = \mathbb E\left[ \int_0^T (	p_th_t+q_t\sigma_t +q^0_t\sigma^0_t	) 
		(\Pi_t-\Pi^*_t)\,dt - \int_0^T\left(p_t+Q_tf_1( C^*_t,V^*_t )\nu^{-\theta}_t  \right) (C_t-C^*_t)\,dt\right].
	\end{split}
\end{equation} 

\end{proof}

\begin{remark}
	The inequality \eqref{inequ:gradient} should be compared with the utility gradient method in \cite[Theorem 3.4]{Seifried-2015}, where no adjoint variables were introduced: 
	\begin{equation*}
		\begin{split}
		&~V_0^C-V_0^{C^*}\\
		\leq&~ \mathbb E\left[ \int_0^T e^{\int_t^s f_2(C^*_s\nu^{-\theta}_s,V^*_s)\,ds} f_1( C^*\nu^{-\theta}_s,V^*_s  )(C_s-C^*_s)\nu^{-\theta}_s\,ds  + \alpha e^{\int_0^T f_2(C^*_s\nu^{-\theta}_s.V^*_s)\,ds} U'(C^*_T\nu^{-\theta}_T)\nu^{-\theta}_T(C_T-C^*_T)						\right],
		\end{split}	
\end{equation*}
where we recall $V_0^C$ is the utility index corresponding to the consumption plan $C$. 
	 To obtain our BSDE \eqref{driver-MOP} from any given optimal strategy (or equilibrium strategy), a version of utility gradient inequality in terms of adjoint variables in the spirit of \eqref{inequ:gradient} is required.
\end{remark}
