 	\]
 	Since $Z$, $Z^0$ and $\pi^*$ belong to $H^2_{BMO}$, it follows from \eqref{eq:Z-Z0-p-q-pi} that the processes $\frac{q}{p}$ and $\frac{q^0}{p}$ also belong to $H^2_{BMO}$. The same holds for the process $\vartheta$, due to  \eqref{eq:q/p}. Thus, the third condition in \eqref{reverse} holds.

 	{\bf Step 3.} If $(\pi^*,c^*)$ is an equilibrium strategy satisfying all conditions in \eqref{reverse}, then it follows from Step 1 that it can be characterized by the mean field BSDE \eqref{MF-BSDE:tilde-Y} via \eqref{pi-Z-Z0-widetilde} and \eqref{c-Y-widetilde}.
 	In particular, the relation \eqref{c-Y-widetilde} implies that 
 	\[
 		\widetilde Y= 	-\frac{\widetilde\theta}{\psi}\log c^*-\frac{\theta\widetilde\theta(\psi-1)}{\psi}\mathbb E[  \log c^* |\mathcal F^0 ]+\widetilde\theta\log\delta-\log\alpha,			\quad \text{on }[0,T)
 	\]
 	 which implies $\widetilde Y\in L^\infty$ since $c^*\in L^\infty$ by \eqref{reverse} and $\widetilde Y_T=0$. Using the relations \eqref{eq:Z-Z0-p-q-pi} and \eqref{eq:q/p} again, we have $Z$ and $Z^0$ belong $H^2_{BMO}$ by \eqref{reverse}.  

 	{\bf Step 4.} In this final step, we prove the correspondence of uniqueness for equilibrium strategies and BSDE solutions. On the one hand, if there are two distinct solutions of \eqref{MF-BSDE:tilde-Y} in $L^\infty\times H^2_{BMO}\times H^2_{BMO}$, then there are two distinct equilibrium investment and consumption rates in $L^\infty\times H^2_{BMO}$ by \eqref{pi-Z-Z0-widetilde} and \eqref{c-Y-widetilde}. 

 On the other hand, if there exists at most one solution to the BSDE in $L^\infty\times H^2_{BMO}\times H^2_{BMO}$ but there are two distinct equilibrium strategies satisfying \eqref{reverse}, then we derive a contradiction by Step 3.
 \end{proof}

 \begin{remark}\label{rem:reverse}
 	The third condition in \eqref{reverse} is consistent with the reverse H\"older inequality in \cite{ET-2015,FR-2011,Fu-2021,Fu2023}, where time additive utility (exponential or power utility) is considered. In general, this condition is necessasry to establish the one-to-one correspondence between the equilibrium investment and the $Z$-component of solution to some (F)BSDE in the BMO space. However, this condition can be dropped if either the following two conditions holds: 
	\begin{itemize}
 		\item If only common noise exists, i.e. $\sigma=0$, then \eqref{pi-Z-Z0-widetilde} yields a one-to-one correspondence between $\pi^*$ and $Z^0$, which implies that $\pi^*\in H^2_{BMO}$ is equivalent to $Z^0\in H^2_{BMO}$, even without the third condition in \eqref{reverse}. This also implies the equivalence between $\pi^*\in L^\infty$ and $Z^0\in L^\infty$.
 	\item  If all coefficients are deterministic, then $\widetilde Z=\widetilde Z^0=0$ and $\pi^*\in H^2_{BMO}$ trivially holds, if it exists.
\end{itemize}
%Moreover, the equilibrium investment rate and consumption rate are restricted to $L^\infty\times L^\infty$. 
 \end{remark}


