			&~+\frac{\widetilde Z+\widetilde Z'}{2}\Delta Z   \\
			&~+\frac{\gamma(1-\gamma)\widetilde\sigma^\top\widetilde\sigma}{2}\left\{ 	2f^h+f^\sigma(	\widetilde Z+\widetilde Z'	) +f^{\sigma^0}( \widetilde Z^0+\widetilde Z^{0'} ) - \frac{	\theta\gamma f^{\sigma^0}\mathbb E\left[\left.	2f^{\sigma^0h}+f^{\sigma^0\sigma}(\widetilde Z+\widetilde Z' )+f^{\sigma^0\sigma^0}(\widetilde Z^0+\widetilde Z^{0'})	\right|\mathcal F^0	\right]				}{1+\mathbb E\left[ \left. \theta\gamma f^{\sigma^0\sigma^0} \right|\mathcal F^0  \right]}		      \right\}    f^\sigma\Delta Z  \\ 
						&~+\frac{\gamma(1-\gamma)\widetilde\sigma^\top\widetilde\sigma}{2}\left\{ 	2f^h+f^\sigma(	\widetilde Z+\widetilde Z'	) +f^{\sigma^0}( \widetilde Z^0+\widetilde Z^{0'} ) - \frac{	\theta\gamma f^{\sigma^0}\mathbb E\left[\left.	2f^{\sigma^0h}+f^{\sigma^0\sigma}(\widetilde Z+\widetilde Z' )+f^{\sigma^0\sigma^0}(\widetilde Z^0+\widetilde Z^{0'})	\right|\mathcal F^0	\right]				}{1+\mathbb E\left[ \left. \theta\gamma f^{\sigma^0\sigma^0} \right|\mathcal F^0  \right]}		      \right\}   f^{\sigma^0}\Delta Z^0 \\ 
			&~		+\frac{1}{2}\left\{   \widetilde Z^0+\widetilde Z^{0'} - \frac{	\theta\gamma\mathbb E\left[ \left. 2f^{\sigma^0h}+f^{\sigma^0\sigma}(	\widetilde Z+\widetilde Z'	)+f^{\sigma^0\sigma^0}(  \widetilde Z^0+\widetilde Z^{0'}   ) 			     \right|\mathcal F^0  \right]						}{1+\mathbb E\left[\left. \theta\gamma f^{\sigma^0\sigma^0} \right|\mathcal F^0 \right]}					\right\}   \Delta Z^0					\\
			:=&~\theta\Delta\widetilde{\mathcal J}  + \mathcal C\Delta Z+\mathcal C^0\Delta Z^0
	%	\end{split}
	\end{align*}
}
with $f^a$ and $f^{ab}$ defined in \cite[Appendix B]{Fu2023}.


All terms in the definition of $\Delta\mathcal J$ that do not contain $\theta$ are linear terms of $(\Delta Z,\Delta Z^0)$ and hence can be dropped by a change of measure:
\[
		\frac{d\mathbb Q}{d\mathbb P}=\mathcal E\left\{ \int_0^\cdot \mathcal C_{s}		  \,dW_s+\int_0^\cdot	\mathcal C^0_s	 \,dW^0_s  \right\}.
\]
%where
