%		\mathcal C^0= &~     \frac{1}{2}\left\{   \widetilde Z^0+\widetilde Z^{0'} - \frac{	\theta\gamma\mathbb E\left[ \left. 2f^{\sigma^0h}+f^{\sigma^0\sigma}(	\widetilde Z+\widetilde Z'	)+f^{\sigma^0\sigma^0}(  \widetilde Z^0+\widetilde Z^{0'}   ) 			     \right|\mathcal F^0  \right]						}{1+\mathbb E\left[\left. \theta\gamma f^{\sigma^0\sigma^0} \right|\mathcal F^0 \right]}					\right\}. 
