Since $\widetilde Z$, $\widetilde Z^0$, $\widetilde Z'$ and $\widetilde Z^{0'}$ are in $H^2_{BMO}$, $(W^{\mathbb Q}, W^{0,\mathbb Q})$ is a $\mathbb Q$-Brownian motion, where
\begin{equation*}
	\left\{\begin{split}
		W^{\mathbb Q}_\cdot =&~ W_\cdot-\int_0^\cdot \mathcal C_s\,ds,  \\
		W^{0,\mathbb Q}_\cdot =&~ W^0_\cdot - \int_0^\cdot \mathcal C^0_s\,ds.
	\end{split}\right. 
\end{equation*} 
As a result, 
\begin{equation*}
	\begin{split}
		\Delta Y_t = \theta(1-\gamma)\int_t^T\mathbb E[ \Delta c^*_s |\mathcal F^0_s ]\,ds + \int_t^T\frac{1-\gamma}{\psi-1}  \Delta c^*_s  \,ds+\theta\int_t^T \Delta\mathcal{\widetilde J}_s \,ds-\int_t^T\Delta Z_s\,dW_s^{\mathbb Q}-\int_t^T\Delta Z^0_s\,dW^{0,\mathbb Q}_s.
	\end{split}
\end{equation*}
It\^o's formula and standard estimate imply that  
\begin{equation*}
	\begin{split}
		&~\esssup_{\omega,t\leq s\leq T}(\Delta Y_s)^2 +  \| \Delta Z\|^2_{BMO,\mathbb Q} +  	\| \Delta Z^0\|_{BMO,\mathbb Q}^2\\
		\leq&~ C\int_t^T \esssup_{\omega,t\leq r\leq s}(\Delta Y_r)^2   \,ds + \theta  C\| \Delta Z\|^2_{BMO,\mathbb Q} + \theta C	\| \Delta Z^0\|_{BMO,\mathbb Q}^2,
	\end{split}
\end{equation*}
where $C$ depends on $R$.
It implies $\Delta Y=\Delta Z=\Delta Z^0=0$ by Gr\"onwall's inequality and letting $\theta$ be small enough.
\end{proof}



