\section{Wellposedness under deterministic parameters}\label{sec:existence}

 This section proves the existence of an equilibrium in closed form for models with deterministic parameters\footnote{They may depend on an initial distribution capturing initial heterogeneity.}. Moreover, we verify that this closed form equilibrium investment rate and consumption rate is the unique in $L^\infty\times L^\infty_+$, without additional integrability assumptions. Here, $L^\infty_+$ is the subspace of $L^\infty$ where all elements are strictly positive.
 Both the MFG and the $N$-player game are considered. 



\subsection{The MFG}


{\bf Uniqueness in $L^\infty\times L^\infty_+$.}  	Let $(\widetilde Y,\widetilde Z,\widetilde Z^0)$ and $(\widetilde Y',\widetilde Z',\widetilde Z^{0'})$ be solutions to the BSDE \eqref{MF-BSDE:tilde-Y} in $L^\infty\times L^\infty\times L^\infty$ and let
\[
\Delta Y:=\widetilde Y-\widetilde Y', \quad \Delta Z:=\widetilde Z-\widetilde Z', \quad \Delta Z^0:=\widetilde Z^0-\widetilde Z^{0'}. 
\]	
The triple $(\Delta Y,\Delta Z,\Delta Z^{0})$ satisfies the BSDE
\begin{equation*}
	\begin{split}
		\Delta Y_t=&~\int_t^T \left(A_{1,s}\mathbb E\left[\left. \frac{\psi}{\widetilde\theta} \Delta Y_s   \right|\mathcal F^0_s   \right]+ A_{2,s}\Delta Y_s\right)\,ds +\int_t^T\left( A_{3,s}\mathbb E[A_{4,s} \Delta Z_s|\mathcal F^0_s] + A_{5,s}\mathbb E[A_{6,s} \Delta Z^0_s|\mathcal F^0_s] \right)\,ds\\
		&~+\int_t^T \left( A_{7,s}\Delta Z_s+A_{8,s}\Delta Z^0_s  \right) \,ds  -\int_t^T\Delta Z_s\,dW_s-\int_t^T\Delta Z^0_s\,dW^0_s,
	\end{split}
\end{equation*}
where all coefficients $A_i$ belong to $L^\infty$ since $(\widetilde Y,\widetilde Z,\widetilde Z^0)$ and $(\widetilde Y',\widetilde Z',\widetilde Z^{0'})$ are assumed to be in $L^\infty\times L^\infty\times L^\infty$. Standard estimates show that 
\begin{equation*}
	\begin{split}
		&~\mathbb E\left[  (\Delta Y_t)^2 \right]+\mathbb E\left[ \int_t^T (	\Delta Z_s)^2+(\Delta Z^0_s)^2\,ds     \right]\\
		=&~2\mathbb E\left[\int_t^T \left( A_{1,s}\Delta Y_s\mathbb E\left[\left. \frac{\psi}{\widetilde\theta} \Delta Y_s   \right|\mathcal F^0_s   \right]+A_{2,s}(\Delta Y_s)^2 + A_{3,s}\Delta Y_s\mathbb E\left[ A_{4,s}\Delta Z_s|\mathcal F^0_s   \right]+A_{5,s}\Delta Y_s\mathbb E[A_{6,s}\Delta Z^0_s|\mathcal F^0_s]	\right)		\,ds  \right]\\
		&~+2\mathbb E\left[  \int_t^T   \Delta Y_s  \left( A_{7,s}\Delta Z_s+A_{8,s}\Delta Z^0_s  \right) \,ds   \right]\\
		\leq&~	C\mathbb E\left[  \int_t^T (	\Delta Y_s	)^2\,ds  \right]+		\frac{1}{2}\mathbb E\left[ \int_t^T (	\Delta Z_s	)^2+(  \Delta Z^0_s  )^2 \,ds  \right],
	\end{split}
\end{equation*}
which implies by Gr\"onwall's inequality $\Delta Y=\Delta Z=\Delta Z^0=0$.  


Note that $(\pi,c)\in L^\infty\times L^\infty_+$ implies the first two conditions in \eqref{reverse} automatically hold. Moreover, recalling the second point in Remark \ref{rem:reverse}, we know that there exists at most one equilibrium investment rate and consumption rate in $L^\infty\times L^\infty_+$.



{\bf Closed form solution.}
If the model parameters are deterministic, then $\widetilde Z=\widetilde Z^0=0$, which implies that 
\[
	Z=0,\qquad Z^0=-\frac{\theta(1-\gamma)\mathbb E\left[  \frac{\sigma^0 h}{\gamma(\sigma^2+(\sigma^0)^2)}   \right]}{	1+\mathbb E\left[  \frac{\theta(1-\gamma)(\sigma^0)^2}{ \gamma(  \sigma^2+(\sigma^0)^2  )  }    \right]		},
\]	
and
\[	
	\pi^*=\frac{h}{\gamma(\sigma^2+(\sigma^0)^2)}  -\frac{\sigma^0}{\gamma( \sigma^2+(\sigma^0)^2  )}\times \frac{\theta(1-\gamma)\mathbb E\left[  \frac{\sigma^0 h}{\gamma(\sigma^2+(\sigma^0)^2)}   \right]}{	1+\mathbb E\left[  \frac{\theta(1-\gamma)(\sigma^0)^2}{ \gamma(  \sigma^2+(\sigma^0)^2  )  }    \right]		} \in L^\infty. 
\]
Taking the above equalities into the driver of $\widetilde Y$, we get that
\begin{equation}\label{eq:Y-widetilde}
	\begin{split}
		\widetilde Y_t=&~-\theta(1-\gamma)\int_t^T \mathbb E\left[    	r_s+\pi^*_sh_s-c^*_s-\frac{1}{2}(\pi^*_s)^2(\sigma^2_s+(\sigma^0_s)^2)			    \right]  \,ds \\
				&~+ \int_t^T  ~\left\{ \frac{ (Z^0_s)^2}{2} +(1-\gamma)r_s+\frac{1-\gamma}{2\gamma} \frac{	(h_s +  \sigma^0_sZ^0_s)^2		}{\sigma^2_s+(\sigma^0_s)^2} +\frac{1-\gamma}{\psi-1} c^*_s -\delta\widetilde\theta\right\}\,ds\\
				=&~\int_t^T	\left\{   \theta(1-\gamma)\mathbb E[c^*_s] +\frac{1-\gamma}{\psi-1}c^*_s	  \right\}  		\,ds\\
				&~-\theta(1-\gamma)\int_t^T\mathbb E\left[ 	r_s+\pi^*_sh_s-\frac{1}{2}(\pi^*_s)^2(\sigma^2_s+(\sigma^0_s)^2)	    \right]\,ds\\
				&~+\int_t^T   \left\{ \frac{ (Z^0_s)^2}{2} +(1-\gamma)r_s+\frac{1-\gamma}{2\gamma} \frac{	(h_s +  \sigma^0Z^0)^2		}{\sigma^2+(\sigma^0)^2}   -\delta\widetilde\theta\right\}\,ds.
%				:=&~\int_t^T	\left\{   \theta(1-\gamma)\mathbb E[c^*_s] +\frac{1-\gamma}{\psi-1} c^*_s \right\}  			\,ds + \int_t^T A_s\,ds.
	\end{split}
\end{equation}
We now show that the above equation can be reduced to a Riccati equation. To this end,  
we set 
\begin{equation}\label{eq:A}
	\begin{split}
		A:=\frac{(Z^0)^2}{2}+(1-\gamma)r+\frac{1-\gamma}{2\gamma} \frac{		(h+\sigma^0Z^0)^2			}{\sigma^2+(\sigma^0)^2}-\delta\widetilde\theta - \theta(1-\gamma)\mathbb E\left[  r+\pi^*h-\frac{1}{2}(\pi^*)^2(\sigma^2+(\sigma^0)^2)		   \right].
	\end{split}
\end{equation}
Moreover, from \eqref{c-Y-widetilde} we get that 
\begin{equation}\label{c-Y-hat}
	\begin{split}
		c^*%=&~\delta^\psi \alpha^{ -\frac{  \psi }{\widetilde\theta} }\exp\left(  -\theta(\psi-1)\widehat\nu-\frac{\psi}{\widetilde\theta}Y							         \right)\\
		%=&~\delta^\psi \alpha^{ -\frac{  \psi }{\widetilde\theta} }\exp\left(  		-\frac{\theta(\psi-1)}{1+\mathbb E[ \theta(\psi-1) ]}\left\{   \mathbb E[\psi\log\delta]  - \mathbb E\left[ 	\frac{\psi}{\widetilde\theta}\log\alpha	   \right]	    \right\}	+\frac{\theta(\psi-1)}{1+\mathbb E[\theta(\psi-1)]}	\mathbb E\left[ \left. \frac{\psi}{\widetilde\theta}\widetilde Y	\right|\mathcal F^0	 \right]	-\frac{\psi}{\widetilde\theta}\widetilde Y				         \right)\\
		=&~\exp\left(   -\frac{\theta(\psi-1)}{1+\mathbb E[ \theta(\psi-1) ]}\left\{        \mathbb E[\psi\log\delta]  - \mathbb E\left[ 	\frac{\psi}{\widetilde\theta}\log\alpha	   \right]	  -\mathbb E\left[  \left.		\frac{\psi}{\widetilde\theta}\widetilde Y \right|\mathcal F^0      \right]          \right\}		+\psi\log\delta-\frac{\psi}{\widetilde\theta}\log\alpha-\frac{\psi}{\widetilde\theta}\widetilde Y		          \right)\\
		=&~\exp\left(   \frac{\theta(\psi-1)}{1+\mathbb E[ \theta(\psi-1) ]}     \mathbb E\left[  \left.		\widehat Y \right|\mathcal F^0      \right]           	-\widehat Y		          \right),
	\end{split}
\end{equation}
where
\[
\widehat Y:= -\psi\log\delta+\frac{\psi}{\widetilde\theta}\log\alpha+\frac{\psi}{\widetilde\theta}\widetilde Y.	     
\]
Expressing the optimal consumption plan $c^*$ in terms of $\widehat Y$ as shown in \eqref{c-Y-hat} and recalling the equation \eqref{eq:Y-widetilde} we see that  
\begin{equation*}
	\begin{split}
		\widehat Y' &~ = -\frac{\psi}{\widetilde\theta}   \theta(1-\gamma) \mathbb E\left[ \exp\left(   \frac{\theta(\psi-1)}{1+\mathbb E[ \theta(\psi-1) ]}\mathbb E[\widehat Y]- \widehat Y         \right)\right]  -\frac{\psi}{\widetilde\theta}\frac{1-\gamma}{\psi-1} \exp\left(   \frac{\theta(\psi-1)}{1+\mathbb E[ \theta(\psi-1) ]}\mathbb E[\widehat Y]- \widehat Y         \right)      -\frac{\psi}{\widetilde\theta}A\\
		& = ~ -   \theta(\psi-1) \mathbb E\left[ \exp\left(   \frac{\theta(\psi-1)}{1+\mathbb E[ \theta(\psi-1) ]}\mathbb E[\widehat Y]- \widehat Y         \right)\right]  -  \exp\left(   \frac{\theta(\psi-1)}{1+\mathbb E[ \theta(\psi-1) ]}\mathbb E[\widehat Y]- \widehat Y         \right)      -\frac{\psi}{\widetilde\theta}A.\\
	\end{split}
\end{equation*} 
Taking expectations we get that
 \begin{equation*}
  		\mathbb E[\widehat Y]'= -(\mathbb E\left[   \theta(\psi-1)\right]+1 )\mathbb E\left[ \exp\left(   \frac{\theta(\psi-1)}{1+\mathbb E[ \theta(\psi-1) ]}\mathbb E[\widehat Y]- \widehat Y         \right)\right]       -\mathbb E\left[\frac{\psi}{\widetilde\theta}A \right]
\end{equation*}
from which we conclude that
% 	\Rightarrow \frac{		\theta(\psi-1)	}{ \mathbb E\left[   \theta(\psi-1)\right]+1 } \mathbb E[\widehat Y]'   =&~ - \theta(\psi-1)\mathbb E\left[ \exp\left(   \frac{\theta(\psi-1)}{1+\mathbb E[ \theta(\psi-1) ]}\mathbb E[\widehat Y]- \widehat Y         \right)\right]       -  \frac{ \theta(\psi-1)}{ \mathbb E\left[   \theta(\psi-1)\right]+1  }\mathbb E\left[\frac{\psi}{\widetilde\theta}A \right]\\
% 	\Rightarrow 
\begin{align*}
\frac{		\theta(\psi-1)	}{ \mathbb E\left[   \theta(\psi-1)\right]+1 } \mathbb E[\widehat Y]' -\widehat Y'= \exp\left(   \frac{\theta(\psi-1)}{1+\mathbb E[ \theta(\psi-1) ]}\mathbb E[\widehat Y]- \widehat Y         \right) -  \frac{ \theta(\psi-1)}{ \mathbb E\left[   \theta(\psi-1)\right]+1  }\mathbb E\left[\frac{\psi}{\widetilde\theta}A \right]+\frac{\psi}{\widetilde\theta}A.
 \end{align*}

 Let us now put 
 \[
 	\mathring Y:=\frac{		\theta(\psi-1)	}{ \mathbb E\left[   \theta(\psi-1)\right]+1 } \mathbb E[\widehat Y] -\widehat Y 
	\quad \mbox{and} \quad \breve Y=\exp(\mathring Y).
 \]
Then, 
\begin{equation*}
	\mathring Y'=e^{\mathring Y} -  \frac{ \theta(\psi-1)}{ \mathbb E\left[   \theta(\psi-1)\right]+1  }\mathbb E\left[\frac{\psi}{\widetilde\theta}A \right]+\frac{\psi}{\widetilde\theta}A
\end{equation*}
and so the function $\breve Y$ satisfies the Riccati equation 
 \[
 	\breve Y'=\breve Y^2+\left(  -  \frac{ \theta(\psi-1)}{ \mathbb E\left[   \theta(\psi-1)\right]+1  }\mathbb E\left[\frac{\psi}{\widetilde\theta}A \right]+\frac{\psi}{\widetilde\theta}A  \right)\breve Y
 \]
 with the terminal condition
 \begin{equation}\label{eq:D}
 		\breve Y_T=\exp\left( 	\frac{\theta(\psi-1)}{\mathbb E[\theta(\psi-1)]+1}\mathbb E\left[   -\psi\log\delta+\frac{\psi}{\widetilde\theta}\log\alpha			  \right]	-\left(	-\psi\log\delta+\frac{\psi}{\widetilde\theta}\log\alpha		   \right)					      \right):=D.
 \end{equation}

 The unique solution of the above Riccati equation is given by
 \[
 	\breve Y_t=D\left\{     \exp\left( \int_t^T B_r\,dr  \right) + D\int_t^T\exp\left(  \int_t^s B_r\,dr  \right)\,ds         \right\}
 \]
 where
 \begin{equation}\label{eq:B}
 		B=\left(  -  \frac{ \theta(\psi-1)}{ \mathbb E\left[   \theta(\psi-1)\right]+1  }\mathbb E\left[\frac{\psi}{\widetilde\theta}A \right]+\frac{\psi}{\widetilde\theta}A  \right).
 \end{equation}
 Thus, we have shown the following result, which includes \cite[Theorem 2.6]{Riedel-2024} as a special case.
 \begin{theorem}
 	Assume $h$, $\sigma$ and $\sigma^0$ are deterministic,
 	the {\it unique} equilibrium investment and consumption plan have the following closed form expression
 	\[
 			\pi^*_t=\frac{h_t}{\gamma(\sigma^2_t+(\sigma^0_t)^2)}  -\frac{\sigma^0_t}{\gamma( \sigma^2_t+(\sigma^0_t)^2  )}\times \frac{\theta(1-\gamma)\mathbb E\left[  \frac{\sigma^0_t h_t}{\gamma(\sigma^2_t+(\sigma^0_t)^2)}   \right]}{	1+\mathbb E\left[  \frac{\theta(1-\gamma)(\sigma^0_t)^2}{ \gamma(  \sigma^2_t+(\sigma^0_t)^2  )  }    \right]		},\quad t\in[0,T]
 	\]
 	and
 	\begin{equation*}
 		\left\{\begin{split}
 		c^*_t=&~D\left\{     \exp\left( \int_t^T B_r\,dr  \right) + D\int_t^T\exp\left(  \int_t^s B_r\,dr  \right)\,ds         \right\},\quad t\in[0,T),\\
 		c^*_T=&~1,
 		\end{split}\right. 
 \end{equation*}
 	where $A$, $D$ and $B$ are given by \eqref{eq:A}, \eqref{eq:D} and \eqref{eq:B}. 

 	{As a special case, the simple equilibrium strategy obtained in \cite{Riedel-2024} is unique in $L^\infty\times L^\infty_+$.}
 \end{theorem}

