 \subsection{The $N$-player game}
Having solved the MFG, solving $N$-player games requires only minor modifications of previously given arguments. In the $N$-player game we set 
 	$$
 	\nu = \left( \prod_{j \neq i} C^j \right)^{\frac{1}{N-1}}.
 	$$
A lengthy yet relatively straightforward computation yields the equilibrium investment strategy
% 	For this reason, we consider the second form of externality directly, and by the same approach,  for the $N$-player game we can also get a closed form equilbrium investment:
\begin{equation*}
	\begin{split}
		\pi^{i,*}_t=\frac{h^i_t}{	\gamma^i(\sigma^i)^2+\left( 	\gamma^i-\frac{\theta^i(1-\gamma^i)}{N-1}		  \right)(\sigma^{i0}_t)^2			} - \frac{\theta^i (1-\gamma^i)\sigma^{i0}_t}{ \gamma^i(\sigma^{i}_t)^2 + \left( \gamma^i-\frac{\theta^i(1-\gamma^i)}{N-1}  \right)(\sigma^{i0}_t)^2  } \frac{\phi^N_t}{1+\psi^N_t},\quad t\in[0,T]
	\end{split}
\end{equation*}
where 
\[
	\phi^N:=\frac{1}{N-1}\sum_{j=1}^N \frac{	 h^j\sigma^{j0}		}{\gamma^j(\sigma^j)^2+\left(   \gamma^j -\frac{\theta^j(1-\gamma^j)}{N-1} \right)(	 \sigma^{j0}	)^2			}
\]
and
\[
	\psi^N:=\frac{1}{N-1}\sum_{j=1}^N \frac{\theta^j(1-\gamma^j)(\sigma^{j0})^2}{   \gamma^j(\sigma^{j})^2+\left(  \gamma^j-\frac{\theta^j(1-\gamma^j)}{N-1}  \right)(\sigma^{j0})^2      },
\]
and the equilibrium consumption plan
\[
	c^{i,*}_t=D^i\left\{	\exp\left( 	\int_t^T B^i_r\,dr  \right)	  + D^i\int_t^T\exp\left(  \int_t^s B^i_r\,dr	 \right)\,ds	\right\}, ~t\in[0,T), \text{ and } c^{i,*}_T=1,
\]
where the coefficients $B^i$ and $D^i$ are given by
\[
		B^i=b^iA^i-\frac{a^i}{1+\frac{1}{N-1}\sum_{i=1}^N a^i} \frac{1}{N-1}\sum_{i=1}^N b^iA^i,
\]
\[
	b^i=\frac{\frac{\psi^i-1}{1-\gamma^i}}{		1-\frac{\theta^i(\psi^i-1)}{N-1}			},\quad a^i=\frac{\theta^i(\psi^i-1)}{	1-\frac{\theta^i(\psi^i-1)}{N-1}		},
\]
\begin{equation*}
	\begin{split}
		A^i=&~-\theta^i(1-\gamma^i)\frac{1}{N-1}\sum_{j\neq i}\left\{   r^j+\pi^{j,*}h^j-\frac{1}{2}\left( (\sigma^j)^2+(\sigma^{j0})^2		\right)(\pi^{j,*})^2   \right\}+\frac{ (Z^{i0})^2}{2}+\frac{1}{2}\sum_{j\neq i}(Z^{ij})^2\\
		&~+(1-\gamma^i)r^i+\frac{1-\gamma^i}{2\gamma^i} \frac{  ( h^i  +  \sigma^{i0}Z^{i0}  )^2  }{ (\sigma^i)^2+(\sigma^{i0})^2  } -\delta^i\widetilde \theta^i,
	\end{split}
\end{equation*}
\begin{equation*}
	\begin{split}
	Z^{i0} = & -\frac{\frac{\theta^{i} (1-\gamma^{i})}{N-1}}{1 - \frac{\theta^{i} (1-\gamma^{i}) (\sigma^{i0})^2}{(N-1) \gamma^{i}   \left((\sigma^{j})^2 + (\sigma^{j0})^2 \right)}} 
