	& + \frac{\frac{\theta^{i} (1-\gamma^{i})}{N-1}}{1 - \frac{\theta^{i} (1-\gamma^{i}) (\sigma^{i0})^2}{(N-1)\gamma^{i} \left((\sigma^{j})^2 + (\sigma^{j0})^2 \right)}} 
	\cdot \frac{1}{1 + \psi^{N}} \sum_{i=1}^{N} 
	\frac{\frac{\theta^{i} (1-\gamma^{i}) (\sigma^{i0})^2}{(N-1) \gamma^{i}  \left((\sigma^{j})^2 + (\sigma^{j0})^2 \right)}}{1 - \frac{\theta^{i} (1-\gamma^{i}) (\sigma^{i0})^2}{(N-1)   \gamma^{i}   \left((\sigma^{j})^2 + (\sigma^{j0})^2 \right)}} 
