\section{Additional results and proofs}

\subsection{Auxiliary Lemmas}

\begin{lemma}
  \label{lem:primal_est_bias}
    Under Assumptions~\ref{a:riesz} and \ref{a:margin}, the bias for $\hat{\theta}_L$ is bounded by
    \begin{align*}
      \E[\hat{\theta}_L] - \theta_L & \lesssim \left(\|\hat{\bm{b}} - \bm{b}\|_\infty   + \|\hat{\bm{c}} - \bm{c}\|_\infty\right)^{1 + \alpha} +  \left(1 + \sup_{x \in \mathcal{X}}\|\hat{\bm{b}}(x) - \bm{b}(x)\|_2\right)r_n + \|\hat{\bm{b}} - \bm{b}\|_2 \|\hat{\bm{c}} - \bm{c}\|_2
    \end{align*}
\end{lemma}

\begin{lemma}
  \label{lem:jacobian}
  Define $Q(\bm{p}) =  \left(A \;\text{diag}(\bm{p})A'\right)^{-1}$ and $ H(\bm{p}) = \text{diag}(\bm{p})A'Q(\bm{p})A$, where $\text{diag}(\bm{p})$ denotes the diagonal matrix with the vector $\bm{p}$ on the diagonal. The Jacobian of $\bm{p}_L^\eta(\bm{b}, \bm{c})$ and $\bm{p}_U^\eta(\bm{b}, \bm{c})$ with respect to $\bm{b} \in \R^J$ and $\bm{c} \in \R^K$ are:
  \begin{align*}
    \nabla_{\bm{b}} \bm{p}^\eta_L(\bm{b}, \bm{c}) & = \text{diag}(\bm{p}^\eta_L(\bm{b}, \bm{c})) A'Q(\bm{p}^\eta_L(\bm{b}, \bm{c})) & \quad & \nabla_{\bm{c}} \bm{p}^\eta_L(\bm{b}, \bm{c}) & = \eta \ \text{diag}(\bm{p}_L^\eta(\bm{b}, \bm{c})) \left(I_K - H(\bm{p}^\eta_L(\bm{b}, \bm{c}))\right)\\
    \nabla_{\bm{b}} \bm{p}^\eta_U(\bm{b}, \bm{c}) & = \text{diag}(\bm{p}^\eta_U(\bm{b}, \bm{c})) A'Q(\bm{p}^\eta_U(\bm{b}, \bm{c})) & \quad & \nabla_{\bm{c}} \bm{p}^\eta_U(\bm{b}, \bm{c}) & = \eta \ \text{diag}(\bm{p}_U^\eta(\bm{b}, \bm{c})) \left(I_K - H(\bm{p}^\eta_U(\bm{b}, \bm{c}))\right)
  \end{align*}
\end{lemma}

\begin{lemma}
  \label{lem:entropic_est_bias}
    Define $S_{\bm{b}}(\eta) = \max_{\bm{b}, \bm{c}} \|\nabla_{\bm{b}}\bm{p}_{L}^\eta(\bm{b}, \bm{c})\|_2$, $S_{\bm{c}}(\eta) = \max_{\bm{b}, \bm{c}} \|\nabla_{\bm{c}}\bm{p}_{L}^\eta(\bm{b}, \bm{c})\|_2$, and $S_{\bm{b},\bm{c}}(\eta) = \max_{\bm{b}, \bm{c}, k} \|\nabla^2_{\bm{b},\bm{c}} p_{Lk}^\eta(\bm{b}, \bm{c})\|_2$. Under Assumption~\ref{a:riesz}, the bias for $\hat{\theta}^\eta_L$ relative to $\theta^\eta_L$ is bounded by
    \begin{align*}
      \E[\hat{\theta}_L^\eta] - \theta_L^\eta & \lesssim r_n + S_{\bm{b}}(\eta) \left(r_n + \|\hat{\bm{b}} - \bm{b}\|_2\|\hat{\bm{c}} - \bm{c}\|_2\right) + S_{\bm{c}}(\eta)\left(r_n + \|\hat{\bm{c}} - \bm{c}\|_2^2\right)\\
      & \quad  + S_{\bm{b}, \bm{c}}(\eta) \left(\|\hat{\bm{b}} - \bm{b}\|_2^2 + \|\hat{\bm{c}} - \bm{c}\|_2^2\right)\left(1 + \sum_{k=1}^K \|\hat{c}_k - c_k\|_\infty\right)
    \end{align*}
\end{lemma}


\subsection{Proofs}



\begin{proof}[Proof of Lemma~\ref{lem:mis_class}]
  We will show the proof for plugin lower-bound basis, $\widehat{B}_L(x)$; the proof for the plugin upper-bound basis, $\widehat{B}_U(x)$, is analogous.
  Note that for a fixed value of the covariates $x$, if $\widehat{B}_L(x) \not \in \mathcal{B}_L^\ast(x)$ then this implies that there must exist some bases that are feasible but not optimal, and that $\widehat{B}_L(x)$ is at most a second-best basis.
  Therefore, the sub-optimality gap for a second-best basis is upper bounded by the sub-optimality gap for $\widehat{B}_L(x)$, and so
  \begin{align*}
   \Delta_L(x) &  \leq \langle \bm{c}(X), A_{\widehat{B}_L(x)} \bm{b}(X) \rangle  - \langle \bm{c}(X), A_{B^\ast_L(x)}^{-1} \bm{b}(X) \rangle\\
    & = \langle \bm{c}(X),  A_{\widehat{B}_L(x)}  \bm{b}(X) \rangle - \langle \hat{\bm{c}}(X),  A_{B^\ast_L(x)}^{-1} \hat{\bm{b}}(X) \rangle  +  \langle \hat{\bm{c}}(X),  A_{B^\ast_L(x)}^{-1} \hat{\bm{b}}(X) \rangle - \langle \bm{c}(X),  A_{B^\ast_L(x)}^{-1} \bm{b}(X)  \rangle\\
    & \leq \langle \bm{c}(X),  A_{\widehat{B}_L(x)}  \bm{b}(X) \rangle - \langle \hat{\bm{c}}(X),  A_{\widehat{B}_L(x)}^{-1} \hat{\bm{b}}(X) \rangle  +  \langle \hat{\bm{c}}(X),  A_{B^\ast_L(x)}^{-1} \hat{\bm{b}}(X) \rangle - \langle \bm{c}(X),  A_{B^\ast_L(x)}^{-1} \bm{b}(X)  \rangle\\
    & = \langle \bm{c}(X), (A_{\widehat{B}_L(x)} - A_{B^\ast_L(x)}) (\bm{b}(X) - \hat{\bm{b}}(X)) \rangle + \langle \hat{\bm{c}}(X) - \bm{c}(X), (A_{B^\ast_L(x)}^{-1} - A_{\widehat{B}_L(x)}^{-1}) \hat{\bm{b}}(X) \rangle\\
  \end{align*}
  where the second inequality uses the fact that $\widehat{B}_L(x)$ is an optimal basis for the estimated constraints $\hat{\bm{b}}(X)$ and objective $\hat{\bm{c}}(X)$. Next, by H\"{o}lder's inequality, we have for 
  \[\tilde{C} \equiv \max\left\{\sup_{x \in \mathcal{X}}\sup_{B,B' \in \mathcal{B}} \|(A_{\widehat{B}_L(x)} - A_{B^\ast_L(x)})'\bm{c}(x)\|_1,  \sup_{x \in \mathcal{X}}\sup_{B,B' \in \mathcal{B}} \|(A_{\widehat{B}_L(x)} - A_{B^\ast_L(x)}) \hat{\bm{b}}(x) \|_1 \right\}< \infty,
  \]
  \begin{align*}
    & \langle \bm{c}(X), (A_{\widehat{B}_L(x)} - A_{B^\ast_L(x)}) (\bm{b}(X) - \hat{\bm{b}}(X)) \rangle + \langle \hat{\bm{c}}(X) - \bm{c}(X), (A_{B^\ast_L(x)}^{-1} - A_{\widehat{B}_L(x)}^{-1}) \hat{\bm{b}}(X) \rangle \\
    & \leq \tilde{C} \left(\|\hat{\bm{b}}(X) - \bm{b}(X)\|_\infty + \|\hat{\bm{c}}(X) - \bm{c}(X)\|_\infty\right)\\
    & \leq \tilde{C} \left(\sup_{x\in\mathcal{X}} \|\hat{\bm{b}}(x) - \bm{b}(x)\|_\infty  + \sup_{x \in \mathcal{X}} \|\hat{\bm{c}}(x) - \bm{c}(x)\|_\infty\right)
  \end{align*}

  So, $\widehat{B}_L(x) \not \in \mathcal{B}_L^\ast(x)$ implies that $\Delta_L(x) \leq \ \tilde{C} \left(\|\hat{\bm{b}} - \bm{b}\|_\infty  + \|\hat{\bm{c}} - \bm{c}\|_\infty\right) $. Using this and the margin condition, we have
  \begin{align*}
    P\left(\widehat{B}_L(X) \not \in \mathcal{B}_L^\ast(X)\right) & \leq P\left(0 < \Delta_L(x) \leq \ \tilde{C} \left(\|\hat{\bm{b}} - \bm{b}\|_\infty  + \|\hat{\bm{c}} - \bm{c}\|_\infty\right)\right)\\
    & \lesssim \left(\|\hat{\bm{b}} - \bm{b}\|_\infty  + \|\hat{\bm{c}} - \bm{c}\|_\infty\right)^\alpha.
  \end{align*}

  Next, note that the expected sub-optimality of the plugin basic feasible solution is
  \begin{align*}
    & \; \E\left[\<\bm{c}(X), A_{\widehat{B}_L(X)}^{-1} \bm{b}(X)\> - \<\bm{c}(X), A_{B^\ast_L(X)}^{-1} \bm{b}(X)\> \right]\\
    = & \; \E\left[\bbone\{\widehat{B}_L(X) \not \in \mathcal{B}_L^\ast(X)\} \left(\<\bm{c}(X), A_{\widehat{B}_L(X)}^{-1} \bm{b}(X)\> - \<\bm{c}(X), A_{B^\ast_L(X)}^{-1} \bm{b}(X)\> \right)\right]\\
    & \leq \E\left[\bbone\{\widehat{B}_L(X) \not \in \mathcal{B}_L^\ast(X)\} \left(\langle \bm{c}(X), (A_{\widehat{B}_L(x)} - A_{B^\ast_L(x)}) (\bm{b}(X) - \hat{\bm{b}}(X)) \rangle + \langle \hat{\bm{c}}(X) - \bm{c}(X), (A_{B^\ast_L(x)}^{-1} - A_{\widehat{B}_L(x)}^{-1}) \hat{\bm{b}}(X) \rangle \right) \right]\\
    & \leq \tilde{C} P(\widehat{B}_L(X) \not \in \mathcal{B}_L^\ast(X))  \left(\|\hat{\bm{b}} - \bm{b}\|_\infty  + \|\hat{\bm{c}} - \bm{c}\|_\infty\right) \\
    & \lesssim \left(\|\hat{\bm{b}} - \bm{b}\|_\infty  + \|\hat{\bm{c}} - \bm{c}\|_\infty\right)^{1 + \alpha}
  \end{align*}
  where the first inequality uses the bound on $ \<\bm{c}(X), A_{\widehat{B}_L(X)}^{-1} \bm{b}(X)\> - \<\bm{c}(X), A_{B^\ast_L(X)}^{-1} \bm{b}(X)\>$ when $\widehat{B}_L(x) \not \in B_L^\ast(x)$, the second inequality uses H\"{o}lder's inequality, and the final inequality uses the bound on $P(\widehat{B}(X) \neq B^\ast(X))$.
\end{proof}






\begin{proof}[Proof of Lemma~\ref{lem:primal_est_bias}]

  First, note that we can decompose the bias into
  \begin{align*}
    \E[\hat{\theta}_L] - \theta_L & = \E\left[\left\<\hat{\bm{c}}(X), A^{-1}_{\widehat{B}_L(X)} \left(\hat{\bm{b}}(x) + \hat{\bm{\varphi}}^{(b)}(O)\right)\right\>\right]\\
      & \quad + \E\left[\left\<\hat{\bm{\varphi}}^{(c)}(O),  A^{-1}_{\widehat{B}_L(X)} \hat{\bm{b}}(X)\right\> - \left\<\bm{c}(X),  A^{-1}_{B^\ast_L(X)} \bm{b}(X)\right\>\right]\\
      & = \E\left[\<\bm{c}(X),  A^{-1}_{\widehat{B}_L(X)} \bm{b}(X)\> - \<\bm{c}(X),  A^{-1}_{B^\ast_L(X)} \bm{b}(X)\>\right] \tag{i}\\
      & \quad + \E\left[\left\<\hat{\bm{c}}(X), A^{-1}_{\widehat{B}_L(X)} \left(\hat{\bm{b}}(x) + \hat{\bm{\varphi}}^{(b)}(O) - \bm{b}(X)\right) \right\>\right] \tag{ii}\\
      & \quad + \E\left[\left\<\hat{\bm{c}}(X) + \hat{\bm{\varphi}}^{(c)}(O) - \bm{c}(X), A^{-1}_{\widehat{B}_L(X)} \bm{b}(X)\right\>\right] \tag{iii}\\
      & \quad + \E\left[\left\<\hat{\bm{\varphi}}^{(c)}(O), A^{-1}_{\widehat{B}_L(X)} (\hat{\bm{b}}(X) - \bm{b}(X))\right\>\right] \tag{iv}
  \end{align*}
  We have bounded (i) in Lemma~\ref{lem:mis_class}.
  To bound (ii), note that by Assumption~\ref{a:rates},
  \begin{align*}
    (ii) & = \E\left[\left\<A^{-1 \prime}_{\widehat{B}_L(X)}\hat{\bm{c}}(X),  \left(\hat{\bm{b}}(x) + \hat{\bm{\varphi}}^{(b)}(O) - \bm{b}(X)\right) \right\>\right]\\
    & \lesssim \sup_{x \in \mathcal{X}} \|A^{-1 \prime}_{\widehat{B}_L(x)}\hat{\bm{c}}(x)\|_2 r_n\\
    & \leq \sup_{B \in \mathcal{B}} \|A^{-1}_{B}\|_2 \sup_{x \in \mathcal{X}}\|\hat{\bm{c}}(x)\|_2 r_n\\
    & \lesssim r_n,
  \end{align*}
  because by construction for each basis $B$ the matrix $A_B$ is invertible, and $\hat{\bm{c}}(x)$ is bounded for all $x$.
  We can similarly bound (iii) to get $(iii) \lesssim r_n$.
  Finally, for term (iv), we have that
  \begin{align*}
    (iv) & = \underbrace{\E\left[\left\<\hat{\bm{c}}(X) + \hat{\bm{\varphi}}^{(c)}(O) - \bm{c}(X), A_{\widehat{B}_L(X)} (\hat{\bm{b}}(X) - \bm{b}(X))\right\>\right]}_{(iva)} + \underbrace{\E\left[\left\<\hat{\bm{c}}(X) - \bm{c}(X), A_{\widehat{B}_L(X)} (\hat{\bm{b}}(X) - \bm{b}(X))\right\>\right]}_{(ivb)}
  \end{align*}
  By Assumption~\ref{a:rates}
  \[
  |(iva)| \lesssim \max_{B \in \mathcal{B}} \|A_B^{-1\prime}\|_2 \sup_{x \in \mathcal{X}} \|\hat{\bm{b}}(x) - \bm{b}(x)\|_2 r_n \lesssim \sup_{x \in \mathcal{X}} \|\hat{\bm{b}}(x) - \bm{b}(x)\|_2 r_n.
  \]
  By Cauchy-Schwarz, 
  \begin{align*}
    |(ivb)| \leq \max_{B \in \mathcal{B}} \|A_B^{-1\prime}\|_2 \E\left[\|\hat{\bm{b}}(X) - \bm{b}(X)\|_2 \|\hat{\bm{c}}(X) - \bm{c}(X)\|_2\right] \lesssim \|\hat{\bm{b}} - \bm{b}\|_2 \|\hat{\bm{c}} - \bm{c}\|_2
  \end{align*}
  Putting together the bounds gives the result.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:primal_est_rate}]
  We decompose the estimation error $\hat{\theta}_L - \theta_L$ into
  \begin{align*}
    \hat{\theta}_L - \theta_L & = \tilde{\theta}_L - \E[\tilde{\theta}_L]\\
    & \quad + \E[\hat{\theta}_L] - \theta_L \tag{$\ast$}\\
    & \quad + (\hat{\theta}_L - \E[\hat{\theta}_L]) - (\tilde{\theta}_L - \E[\tilde{\theta}_L]) \tag{$\ast\ast$}
  \end{align*}
  Term ($\ast$) is a bias term, which we have bounded in Lemma~\ref{lem:primal_est_bias}.
  It remains to bound ($\ast\ast$).
  Define 
  \begin{align*}
    h(O) & = \left\<\bm{c}(X), A_{\widehat{B}_L(X)} \left(\bm{b}(X) + \bm{\varphi}^{(b)}(O)\right)\right\> + \left\<\bm{\varphi}^{(c)}(O), A_{\widehat{B}_L(X)} \bm{b}(X)\right\>\\
    \hat{h}(O) & = \left\<\hat{\bm{c}}(X), A_{\widehat{B}_L(X)} \left(\hat{\bm{b}}(X) + \hat{\bm{\varphi}}^{(b)}(O)\right)\right\> + \left\<\hat{\bm{\varphi}}^{(c)}(O), A_{\widehat{B}_L(X)} \hat{\bm{b}}(X)\right\>.\\
  \end{align*}
  Then by \citet{kennedy_semiparametric_2024}, Lemma 1, we have that 
  \[
    (\hat{\theta}_L - \E[\hat{\theta}_L]) - (\tilde{\theta}_L - \E[\tilde{\theta}_L]) = O_p\left(\frac{1}{\sqrt{n}}\|\hat{h} - h\|_2\right)
  \]
  Now note that we can decompose the difference into
  \begin{align*}
     \hat{h}(O) - h(O) & =   \<\hat{\bm{c}}(X) A_{\widehat{B}_L(X)}(\hat{\bm{b}}(X) + \hat{\bm{\varphi}}^{(b)}(O) - \bm{b}(X) - \bm{\varphi}^{(b)}(O))\>\\
    & \qquad  + \<\hat{\bm{c}}(X) - \bm{c}(X), A_{\widehat{B}_L(X)} (\bm{b}(X) +\bm{\varphi}^{(b)}(O))\> \\
    & \qquad + \<\hat{\bm{\varphi}}^{(c)}(O) - \bm{\varphi}^{(c)}(O), A_{\widehat{B}_L(X)} \bm{b}(X)\>\\
    & \qquad + \<\hat{\bm{\varphi}}^{(c)}(O), A_{\widehat{B}_L(X)} (\hat{\bm{b}}(X) - \bm{b}(X))\>.
  \end{align*}
  By Assumption~\ref{a:riesz}, $\|\hat{\bm{b}}(x) - \bm{b}(x)\|_\infty = o_p(1)$, $\|\hat{\bm{c}}(x) - \bm{c}(x)\|_\infty = o_p(1)$, $\|\hat{\bm{\varphi}}^{(b)} - \bm{\varphi}^{(b)}\|_\infty = o_p(1)$, and $\|\hat{\bm{\varphi}}^{(c)} - \bm{\varphi}^{(c)}\|_\infty = o_p(1)$, so $\hat{h}(o) - h(o) = o_p(1)$ for any data point $o \in \mathcal{O}$. Therefore,  $ (\hat{\theta}_L - \E[\hat{\theta}_L]) - (\tilde{\theta}_L - \E[\tilde{\theta}_L]) = o_p(n^{-1/2})$.
  Combining these two bounds gives the result.


\end{proof}


\begin{proof}[Proof of Corollary~\ref{cor:primal_est_normal_unique}]

  Define $\check{\theta}_L = \frac{1}{n} \sum_{i=1}^n \left\<\bm{c}(X_i), A_{B^\ast_L(X_i)} \left(\bm{b}(X_i) + \bm{\varphi}^{(b)}(O_i)\right)\right\> + \left\<\bm{\varphi}^{(c)}(O_i), A_{B^\ast_L(X_i)} \bm{b}(X_i)\right\>$. Note that $\E[\check{\theta}_L] = \theta_L$.
  To show Corollary~\ref{cor:primal_est_normal_unique} it suffices to show that 
  \[
    \tilde{\theta}_L - \E[\tilde{\theta}_L] - (\check{\theta}_L - \theta_L) = o_p(n^{-1/2}).
  \]
  From the proof of Theorem~\ref{thm:primal_est_rate}, this reduces to showing that
  \[
    \E\left[\left(\left\<\bm{c}(X), (A_{\hat{B}_L(X)} - A_{B^\ast_L(X)}) \left(\bm{b}(X) + \bm{\varphi}^{(b)}(O)\right)\right\> + \left\<\bm{\varphi}^{(c)}(O),(A_{\hat{B}_L(X)} - A_{B^\ast_L(X)})\bm{b}(X)\right\> \right)^2\right] = o(1).
  \]
  To show this, note that this term is bounded by
  \begin{align*}
    &\E\left[\bbone\{\hat{B}_L(X) \neq B^\ast_L(X)\}\left(\left\<\bm{c}(X), (A_{\widehat{B}_L(X)} - A_{B^\ast_L(X)}) \left(\bm{b}(X) + \bm{\varphi}^{(b)}(O)\right)\right\> + \left\<\bm{\varphi}^{(c)}(O),(A_{\widehat{B}_L(X)} - A_{B^\ast_L(X)})\bm{b}(X)\right\> \right)^2\right]\\
    \leq & \tilde{C} P(\hat{B}_L(X) \neq B^\ast_L(X))
  \end{align*}
  for some constant $\tilde{C}$. Now from Lemma~\ref{lem:mis_class}, the mis-classification probability $ P(\hat{B}_L(X) \neq B^\ast_L(X)) \leq \left(\|\hat{\bm{b}} - \bm{b}\|_\infty + \|\hat{\bm{c}} - \bm{c}\|_\infty\right)^\alpha = o_p(1) $ under the conditions of Corollary~\ref{cor:primal_est_normal}.

\end{proof}

\begin{proof}[Proof of Lemma~\ref{lem:jacobian}]


  Since $\bm{p}^\eta_L(\bm{b}(x),\bm{c}(x)) = \exp\left(-A'\lambda(\bm{b}(x), \bm{c}(x)) + \eta \bm{c}(x)\right)$,
  \begin{align*}
    \nabla_{\bm{b}} p_L^\eta(\bm{b}, \bm{c}) & = - \text{diag}( p(\bm{b}, \bm{c}) ) \ A'\nabla_{\bm{b}} \lambda_L^\eta(\bm{b}, \bm{c})\\
    \nabla_{\bm{c}} p_L^\eta(\bm{b}, \bm{c}) & =  \text{diag}(p(\bm{b}, \bm{c})) \left(\eta I - A'\nabla_{\bm{c}} \lambda_L^\eta(\bm{b}, \bm{c})\right).\\
  \end{align*}
  Now because $\lambda_L^\eta(\bm{b}, \bm{c})$ is the unique solution to the dual of the entropic regularized primal problem, the vector $\lambda_L^\eta, \bm{b}, \bm{c}$ satisfy the following zero gradient condition
  \[
    G_L(\bm{\lambda}, \bm{b}, \bm{c}) = -A \exp\left(-A'\bm{\lambda} + \eta \bm{c}\right) + \bm{b} = 0.
  \]
  Taking the Jacobians of $G_L$ with respect to $\bm{\lambda}, \bm{b}$ and $\bm{c}$, we have that
  \begin{align*}
    \nabla_{\bm{\lambda}} G_L & = A \ \text{diag}(\bm{p}(\bm{b}, \bm{c})) A'\\
    \nabla_{\bm{b}} G_L & = I\\
    \nabla_{\bm{c}} G_L &= -\eta \ A \ \text{diag}(\bm{p}(\bm{b}, \bm{c})).
  \end{align*}
  So by the implicit function theorem the Jacobians of $\lambda_L^\eta(\bm{b}, \bm{c})$ with respect to $\bm{b}$ and $\bm{c}$ are
  \begin{align*}
    \nabla_{\bm{b}} \bm{\lambda}_L^\eta(\bm{b}, \bm{c}) & = -\left(\nabla_{\bm{\lambda}} G_L\right)^{-1} \nabla_{\bm{b}} G_L = -(A \ \text{diag}(\bm{p}(\bm{b}, \bm{c})) \ A')^{-1}\\\\
    \nabla_{\bm{c}} \lambda_L^\eta(\bm{b}, \bm{c}) & = -\left(\nabla_{\bm{\lambda}} G_L\right)^{-1} \nabla_{\bm{c}} G_L = \eta \left( A \ \text{diag}(\bm{p}(\bm{b}, \bm{c})) \ A'\right)^{-1} A \ \text{diag}(\bm{p}(\bm{b}, \bm{c})).\\
  \end{align*}
  Putting together the pieces gives the result for the Jacobian of $\bm{p}_L^\eta(\bm{b}, \bm{c})$. The result for $\bm{p}_U^\eta(\bm{b}, \bm{c})$ follows similarly, but the signs are different. Specifically, since $\bm{p}_U(\bm{b},\bm{c}) = \exp\left(A'\bm{\lambda}(\bm{b}, \bm{c}) + \eta \bm{c}\right)$,
  \begin{align*}
    \nabla_{\bm{b}} \bm{p}_U^\eta(\bm{b}, \bm{c}) & = \text{diag}( \bm{p}(\bm{b}, \bm{c}) ) \ A'\nabla_{\bm{b}} \bm{\lambda}_L^\eta(\bm{b}, \bm{c})\\
    \nabla_{\bm{c}} \bm{p}_U^\eta(\bm{b}, \bm{c}) & =  \text{diag}(\bm{p}(\bm{b}, \bm{c})) \left(\eta I + A'\nabla_{\bm{c}} \bm{\lambda}_L^\eta(\bm{b}, \bm{c})\right).\\
  \end{align*}
  Now because $\bm{\lambda}_U^\eta(\bm{b}, \bm{c})$ is the unique solution to the dual of the entropic regularized primal problem, the functions $\bm{\lambda}_U^\eta, \bm{b}, \bm{c}$ satisfy the following zero gradient condition
  \[
    G_U(\bm{\lambda}, \bm{b}, \bm{c}) = A \exp\left(A'\bm{\lambda} + \eta \bm{c}\right) - \bm{b} = 0.
  \]
  Taking the Jacobians of $G_U$ with respect to $\bm{\lambda}, \bm{b}$ and $\bm{c}$, we have that
  \begin{align*}
    \nabla_{\bm{\lambda}} G_U & = A \ \text{diag}(\bm{p}(\bm{b}, \bm{c})) A'\\
    \nabla_{\bm{b}} G_U & = -I\\
    \nabla_{\bm{c}} G_U &= \eta \ A \ \text{diag}(\bm{p}(\bm{b}, \bm{c})).
  \end{align*}
  So by the implicit function theorem the Jacobian of $\lambda_L^\eta(\bm{b},\bm{c})$ with respect to $\bm{b}$ and $\bm{c}$ are
  \begin{align*}
    \nabla_{\bm{b}} \bm{\lambda}_L^\eta(\bm{b}, \bm{c}) & = -\left(\nabla_{\bm{\lambda}} G_L\right)^{-1} \nabla_{\bm{b}} G_L = -(A \ \text{diag}(\bm{p}(\bm{b}, \bm{c})) \ A')^{-1}\\\\
    \nabla_{\bm{c}} \bm{\lambda}_L^\eta(\bm{b}, \bm{c}) & = -\left(\nabla_{\bm{\lambda}} G_L\right)^{-1} \nabla_{\bm{c}} G_L = \eta \left( A \ \text{diag}(\bm{p}(\bm{b}, \bm{c})) \ A'\right)^{-1} A \ \text{diag}(\bm{p}(\bm{b}, \bm{c})).\\
  \end{align*}
  Putting together the pieces gives the result for the Jacobian of $\bm{p}_U^\eta(\bm{b}, \bm{c})$.
\end{proof}



\begin{proof}[Proof of Lemma~\ref{lem:entropic_est_bias}]
    To control the bias, we can write
  \begin{align*}
    \E[\hat{\theta}^\eta_L] - \theta^\eta_L & = \E\left[\left\<\hat{\bm{c}}(X) +  \hat{\bm{\varphi}}^{(c)}(O) - \bm{c}(X),\hat{\bm{p}}_L^\eta(X)\right\> \right] \tag{i}\\
    & \quad + \E\left[\left\<\hat{\bm{c}}(X), \hat{\bm{p}}_L^\eta(X) + \nabla_{\bm{b}}\hat{\bm{p}}_L^\eta(X) \hat{\bm{\varphi}}^{(b)}(O) + \nabla_{\bm{c}}\hat{\bm{p}}_L^\eta(X) \hat{\bm{\varphi}}^{(c)}(O) - \bm{p}_L^\eta(X)\right\>\right] \tag{ii}\\
    & \quad + \E\left[\left\<\bm{c}(X) - \hat{\bm{c}}(X), \hat{\bm{p}}_L^\eta(X) - \bm{p}_L^\eta(X)\right\>\right] \tag{iii}
  \end{align*}

  The first term (i) can be bounded as in the proof of Lemma~\ref{lem:primal_est_bias}.
  The second term (ii) can be written as
  \begin{align*}
    (ii) & = \sum_{k=1}^K \E\left[\hat{c}_k(X)\left(\hat{p}_{Lk}^\eta(X) - p_{Lk}^\eta(X) + \nabla_{\bm{b}}p_{Lk}^\eta(\hat{\bm{b}}(x), \hat{\bm{c}}(x)) \bm{\varphi}^{(b)}(O) + \nabla_{\bm{c}}p_{Lk}^\eta(\hat{\bm{b}}(x), \hat{\bm{c}}(x)) \bm{\varphi}^{(c)}(O)  \right)\right]
  \end{align*}

  \noindent For each $x \in \mathcal{X}$ and $k=1,\ldots,K$, we can use a second-order Taylor expansion of $p_{Lk}^\eta(\bm{b}(x), \bm{c}(x))$ around $(\hat{\bm{b}}(x), \hat{\bm{c}}(x)) \in \R^{ J + K}$ to get that
  \begin{align*}
    \hat{p}_{Lk}^\eta(x) - p_{Lk}^\eta(x) & = \nabla_{\bm{b}} p_{Lk}^\eta(\hat{\bm{b}}(x), \hat{\bm{c}}(x)) \cdot (\hat{\bm{b}}(x) - \bm{b}(x)) + \nabla_{\bm{c}} p_{Lk}^\eta(\hat{\bm{b}}(x), \hat{\bm{c}}(x)) \cdot (\hat{\bm{c}}(x) - \bm{c}(x))\\
    & \quad  + (\hat{\bm{c}}(x) - \bm{c}(x), \hat{\bm{b}}(x) - \bm{b}(x))' \nabla^2_{\bm{b},\bm{c}} p_{Lk}^\eta(\tilde{\bm{b}}(x), \tilde{\bm{c}}(x)) (\hat{\bm{c}}(x) - \bm{c}(x), \hat{\bm{b}}(x) - \bm{b}(x)),
  \end{align*}
  for some $\tilde{\bm{b}}(x)$ and $\tilde{\bm{c}}(x)$ between $(\hat{\bm{b}}(x), \hat{\bm{c}}(x))$ and $(\bm{b}(x), \bm{c}(x))$, where $\nabla^2_{\bm{b},\bm{c}} p_{Lk}^\eta(\tilde{\bm{b}}(x), \tilde{\bm{c}}(x))$ denotes the Hessian matrix of $p_{Lk}^\eta(\bm{b}(x), \bm{c}(x))$ with respect to $b_1(x),\ldots,b_J(x),c_1(x),\ldots,c_K(x)$ evaluated at $(\tilde{\bm{b}}(x), \tilde{\bm{c}}(x))$.
  Substituting this in to (ii) gives us
  \begin{align*}
    (ii) & = \sum_{k=1}^K \E\left[\hat{c}_k(X)\nabla_{\bm{b}}p_{Lk}^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X)) \left(\hat{\bm{b}}(X) + \hat{\bm{\varphi}}^{(b)}(O) - \bm{b}(X)\right)\right] \tag{iia}\\
    & + \sum_{k=1}^K \E\left[\hat{c}_k(X)\nabla_{\bm{c}}p_{Lk}^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X)) \left(\hat{\bm{c}}(X) + \hat{\bm{\varphi}}^{(c)}(O) - \hat{\bm{c}}(X) \right)\right] \tag{iib}\\
    & + \sum_{k=1}^K \E\left[\hat{c}_k(X) (\hat{\bm{c}}(X) - \bm{c}(X), \hat{\bm{b}}(X) - \bm{b}(X))' \nabla^2_{\bm{b},\bm{c}} p_{Lk}^\eta(\tilde{\bm{b}}(X), \tilde{\bm{c}}(X)) (\hat{\bm{c}}(X) - \bm{c}(X), \hat{\bm{b}}(X) - \bm{b}(X))\right] \tag{iic}
  \end{align*}
  Focusing on term (iia) first, let $S_{\bm{b}}(\eta) = \max_{\bm{b}, \bm{c}} \|\nabla_{\bm{b}}\bm{p}_{L}^\eta(\bm{b}, \bm{c})\|_2$, we have that
  \begin{align*}
  \left|(iia)\right| &= \left|\E\left[\sum_{k=1}^K\hat{c}_k(X)\nabla_{\bm{b}}p_{Lk}^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X)) \left(\hat{\bm{b}}(X) + \hat{\bm{\varphi}}^{(b)}(O) - \bm{b}(X)\right)\right]\right|\\
  &  = \left|\E\left[\left\<\nabla_{\bm{b}}\bm{p}_L^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X))'\hat{\bm{c}}(X),  \hat{\bm{b}}(X) + \hat{\bm{\varphi}}^{(b)}(O) - \bm{b}(X)\right\>\right]\right|\\
  &\lesssim \sup_{x \in \mathcal{X}} \|\nabla_{\bm{b}}\bm{p}_L^\eta(\hat{\bm{b}}(Xx), \hat{\bm{c}}(x))'\hat{\bm{c}}(x)\|_2 r_n\\
  & \leq \sup_{x \in \mathcal{X}} \|\nabla_{\bm{b}}\bm{p}_L^\eta(\hat{\bm{b}}(x), \hat{\bm{c}}(x))\|_2 \sup_{x \in \mathcal{X}}\|\hat{\bm{c}}(x)\|_2 r_n\\
  & \lesssim S_{\bm{b}}(\eta) r_n
\end{align*}  
Similarly,  defining $S_{\bm{c}}(\eta) = \max_{\bm{b}, \bm{c}} \|\nabla_{\bm{c}}\bm{p}_{L}^\eta(\bm{b}, \bm{c})\|_2$, we can bound term (iib) as
  \begin{align*}
  \left|(iib)\right| &= \left|\E\left[\sum_{k=1}^K\hat{c}_k(X)\nabla_{\bm{c}}p_{Lk}^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X)) \left(\hat{\bm{c}}(X) + \hat{\bm{\varphi}}^{(c)}(O) - \bm{c}(X)\right)\right]\right|\\
  &  = \left|\E\left[\left\<\nabla_{\bm{c}}\bm{p}_L^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X))'\hat{\bm{c}}(X),  \hat{\bm{c}}(X) + \hat{\bm{\varphi}}^{(c)}(O) - \bm{c}(X)\right\>\right]\right|\\
  &\lesssim \sup_{x \in \mathcal{X}} \|\nabla_{\bm{c}}\bm{p}_L^\eta(\hat{\bm{b}}(x), \hat{\bm{c}}(x))'\hat{\bm{c}}(x)\|_2 r_n\\
  & \leq \sup_{x \in \mathcal{X}} \|\nabla_{\bm{c}}\bm{p}_L^\eta(\hat{\bm{b}}(x), \hat{\bm{c}}(x))\|_2 \sup_{x \in \mathcal{X}}\|\hat{\bm{c}}(x)\|_2 r_n\\
  & \lesssim S_{\bm{c}}(\eta) r_n
\end{align*}

Finally, we can bound term (iic) as
\begin{align*}
  (iic) & \lesssim \sum_{k=1}^K \E\left[\|\nabla^2_{\bm{b},\bm{c}} p_{Lk}^\eta(\tilde{\bm{b}}(X), \tilde{\bm{c}}(X))\|_2\left(\|\hat{\bm{c}}(X) - \bm{c}(X)\|_2^2 + \|\hat{\bm{b}}(X) - \bm{b}(X)\|_2^2\right)\right]\\
  & \lesssim S_{\bm{b},\bm{c}}(\eta) \left(\|\hat{\bm{b}} - \bm{b}\|_2^2 + \|\hat{\bm{c}} - \bm{c}\|_2^2\right),
\end{align*}
where $S_{\bm{b},\bm{c}}(\eta) = \max_{\bm{b}, \bm{c}, k} \|\nabla^2_{\bm{b},\bm{c}} p_{Lk}^\eta(\bm{b}, \bm{c})\|_2$ is the operator norm of the Hessian matrix of $p_{Lk}^\eta(\bm{b}, \bm{c})$ with respect to $\bm{b}$ and $\bm{c}$.

Finally, for term (iii) we can similarly use a second order Taylor expansion to write it as
\begin{align*}
  (iii) &= \sum_{k=1}^K \E\left[(\hat{c}_k(X) - c_k(X)) \nabla_{\bm{b}}p_{Lk}^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X))(\hat{\bm{b}}(X) - \bm{b}(X))\right] \tag{iiia}\\
  & \quad + \sum_{k=1}^K \E\left[(\hat{c}_k(X) - c_k(X)) \nabla_{\bm{c}}p_{Lk}^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X))(\hat{\bm{c}}(X) - \bm{c}(X))\right] \tag{iiib}\\
  & \quad + \sum_{k=1}^K \E\left[(\hat{c}_k(X) - c_k(X)) (\hat{\bm{c}}(X) - \bm{c}(X), \hat{\bm{b}}(X) - \bm{b}(X))' \nabla^2_{\bm{b},\bm{c}} p_{Lk}^\eta(\tilde{\bm{b}}(X), \tilde{\bm{c}}(X)) (\hat{\bm{c}}(X) - \bm{c}(X), \hat{\bm{b}}(X) - \bm{b}(X))\right] \tag{iiic}.
\end{align*}
Using Cauchy-Schwarz, we can bound term (iiia) as
\begin{align*}
  (iiia) & = \E\left[\left\<\hat{\bm{c}}(X) - \bm{c}(X), \nabla_{\bm{b}}\bm{p}_{L}^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X))(\hat{\bm{b}}(X) - \bm{b}(X))\right\>\right]\\
  & \leq \E\left[\|\hat{\bm{c}}(X) - \bm{c}(X)\|_2 \|\nabla_{\bm{b}}\bm{p}_{L}^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X))\|_2\|\hat{\bm{b}}(X) - \bm{b}(X)\|_2\right]\\&
   \leq \sup_{x \in \mathcal{X}} \|\nabla_{\bm{b}}\bm{p}_{L}^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X))\|_2\ \E\left[\|\hat{\bm{c}}(X) - \bm{c}(X)\|_2\|\hat{\bm{b}}(X) - \bm{b}(X)\|_2\right]\\
   & \leq S_{\bm{b}}(\eta) \sqrt{\E\left[\|\hat{\bm{c}}(X) - \bm{c}(X)\|_2^2\right]}\sqrt{\E\left[\|\hat{\bm{b}}(X) - \bm{b}(X)\|_2^2\right]}\\
   & = S_{\bm{b}}(\eta) \|\hat{\bm{c}} - \bm{c}\|_2 \|\hat{\bm{b}} - \bm{b}\|_2
\end{align*}
Similarly, we can bound term (iiib) as
\begin{align*}
  (iiib) & = \E\left[\left\<\hat{\bm{c}}(X) - \bm{c}(X), \nabla_{\bm{c}}\bm{p}_{L}^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X))(\hat{\bm{c}}(X) - \bm{c}(X))\right\>\right]\\
  & \leq \E\left[\|\hat{\bm{c}}(X) - \bm{c}(X)\|_2 \|\nabla_{\bm{c}}\bm{p}_{L}^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X))\|_2\|\hat{\bm{c}}(X) - \bm{c}(X)\|_2\right]\\&
   \leq \sup_{x \in \mathcal{X}} \|\nabla_{\bm{c}}\bm{p}_{L}^\eta(\hat{\bm{b}}(X), \hat{\bm{c}}(X))\|_2\ \E\left[\|\hat{\bm{c}}(X) - \bm{c}(X)\|_2^2\right]\\
   & = S_{\bm{c}}(\eta) \|\hat{\bm{c}} - \bm{c}\|_2^2.
\end{align*}
Finally  we can bound term (iiic) as
\begin{align*}
  (iiic) & \leq \sum_{k=1}^K \E\left[\left|\hat{c}_k(X) - c_k(X)\right| \|\nabla^2_{\bm{b},\bm{c}} p_{Lk}^\eta(\tilde{\bm{b}}(X), \tilde{\bm{c}}(X))\|_2\left(\|\hat{\bm{b}}(X) - \bm{b}(X)\|_2^2 + \|\hat{\bm{c}}(X) - \bm{c}(X)\|_2^2\right)\right]\\
  & \leq \sup_{x \in \mathcal{X}} \|\nabla^2_{\bm{b},\bm{c}} p_{Lk}^\eta(\tilde{\bm{b}}(X), \tilde{\bm{c}}(X))\|_2 \E\left[\left|\hat{c}_k(X) - c_k(X)\right|\right]\left(\|\hat{\bm{b}}(X) - \bm{b}(X)\|_2^2 + \|\hat{\bm{c}}(X) - \bm{c}(X)\|_2^2\right)\\
  & \leq S_{\bm{b},\bm{c}}(\eta) \sum_{k=1}^K \E\left[\left|\hat{c}_k(X) - c_k(X)\right|\left(\|\hat{\bm{b}}(X) - \bm{b}(X)\|_2^2 + \|\hat{\bm{c}}(X) - \bm{c}(X)\|_2^2\right)\right]\\
  & \leq S_{\bm{b},\bm{c}}(\eta) \left(\|\hat{\bm{b}} - \bm{b}\|_2^2 + \|\hat{\bm{c}} - \bm{c}\|_2^2\right)\sum_{k=1}^K\|\hat{c}_k - c_k\|_\infty
\end{align*}


  Putting all of these pieces together gives the result.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:entropic_est_rate}]
  We will show the result for the lower bound estimate $\hat{\theta}^\eta_L$; the result for the upper bound estimate $\hat{\theta}^\eta_U$ is analogous. 

  First, note that we can decompose the estimation error $\hat{\theta}^\eta_L - \theta^\eta_L$ into

  \begin{align*}
    \hat{\theta}^\eta_L - \theta^\eta_L & = \tilde{\theta}^\eta_L - \E[\tilde{\theta}^\eta_L]\\
    & \quad  + \E[\hat{\theta}^\eta_L] - \theta^\eta_L \tag{$\ast$}\\
    & \quad + (\hat{\theta}^\eta_L - \E[\hat{\theta}^\eta_L]) - (\tilde{\theta}^\eta_L - \E[\tilde{\theta}^\eta_L]) \tag{$\ast\ast$}
  \end{align*}
We have bounded the bias term ($\ast$) in Lemma~\ref{lem:entropic_est_bias}.
Because $\eta$ is allowed to grow with the sample size $n$, it remains to characterize the rates of growth of the operator norms $S_{\bm{b}}(\eta)$, $S_{\bm{c}}(\eta)$ and $S_{\bm{b},\bm{c}}(\eta)$ as $\eta \to \infty$.
For a matrix $A$, we will use $\sigma_{\max}(A)$ and $\sigma_{\min}(A)$ to denote the largest and smallest singular values of $A$, respectively.
First, for the Jacobian of $\bm{p}_L^\eta(\bm{b}, \bm{c})$ with respect to $\bm{b}$, note that we can write the Jacobian as
\[
\nabla_{\bm{b}}\bm{p}_L^\eta(\bm{b}, \bm{c}) = \text{diag}(\bm{p}_L^\eta(\bm{b}, \bm{c}))^{1/2} \tilde{A}(\eta)^{\dagger},
\]
where $\tilde{A}(\eta) = A \text{diag}(\bm{p}_L^\eta(\bm{b}, \bm{c}))^{1/2}$ and $\tilde{A}(\eta)^{\dagger} = \tilde{A}(\eta)'(\tilde{A}(\eta)\tilde{A}(\eta)')^{-1}$ is the Moore-Penrose pseudo-inverse of $\tilde{A}(\eta)$. Because $A$ is full row-rank, and the elements of $\bm{p}_L^\eta(\bm{b}, \bm{c})$ are strictly greater than zero, $\tilde{A}(\eta)$ is also full row-rank and so $\sigma_{\max}(\tilde{A}(\eta)^{\dagger}) = \frac{1}{\sigma_{\min}(\tilde{A}(\eta))} < \infty$ is bounded. As $\eta \to \infty$, $\bm{p}_L^\eta(\bm{b}, \bm{c})$ converges to a value on the optimal face of the polytope defined by the constraints on the conditional linear program, and so it is a convex combination of the set of optimal basic feasible solutions $\mathcal{B}^\ast_L(x)$. Therefore, $\tilde{A}(\eta)$ converges to a matrix with full row-rank. Similarly, because the solutions to the un-regularized program are bounded, $\bm{p}_L^\eta(\bm{b}, \bm{c})$ will be bounded as $\eta \to \infty$. Therefore, the operator norm of the Jacobian matrix, $\|\nabla_{\bm{b}}\bm{p}_L^\eta(\bm{b}, \bm{c})\|_2 \leq  \frac{\max_k p_{Lk}^\eta(\bm{b}, \bm{c})}{\sigma_{\min}(\tilde{A}(\eta))} \to C$ for some constant $C$ as $\eta \to \infty$, and so $S_{\bm{b}}(\eta) = O(1)$.

For the Jacobian of $\bm{p}_L^\eta(\bm{b}, \bm{c})$ with respect to $\bm{c}$, we can write the Jacobian as
\[
\nabla_{\bm{c}}\bm{p}_L^\eta(\bm{b}, \bm{c}) = \eta \times  \text{diag}(\bm{p}_L^\eta(\bm{b}, \bm{c}))^{1/2} (I_K - \tilde{A}(\eta)'(\tilde{A}(\eta)\tilde{A}(\eta)')^{-1}\tilde{A}(\eta)) \text{diag}(\bm{p}_L^\eta(\bm{b}, \bm{c}))^{1/2}.
\]
Therefore, the operator norm is bounded by
\[
\|\nabla_{\bm{c}}\bm{p}_L^\eta(\bm{b}, \bm{c})\|_2 \leq \eta \max_k p_{Lk}^\eta(\bm{b}, \bm{c}) \|I_K - \tilde{A}(\eta)'(\tilde{A}(\eta)\tilde{A}(\eta)')^{-1}\tilde{A}(\eta)\|_2 = \eta \max_k p_{Lk}^\eta(\bm{b}, \bm{c}),
\]
where we have used the fact that $I_K - \tilde{A}(\eta)'(\tilde{A}(\eta)\tilde{A}(\eta)')^{-1}\tilde{A}(\eta)$ is a residual of a projection matrix and so has eigenvalues all equal to one or zero. This implies that  $S_{\bm{c}}(\eta) = O(\eta)$.

Finally, we consider the operator norm of the Hessian matrix of $p_{Lk}^\eta(\bm{b}, \bm{c})$ with respect to $\bm{b}$ and $\bm{c}$.
Suppressing the dependence on $\bm{b}$ and $\bm{c}$ to make the notation more compact, note that
\begin{align*}
  \frac{\partial}{\partial b_j} Q(\bm{p}) & = - Q(\bm{p})A \text{diag}\left(\pderiv{\bm{p}}{b_j}\right)A' Q(\bm{p})\\
  \frac{\partial}{\partial c_k} Q(\bm{p}) & = - Q(\bm{p})A \text{diag}\left(\pderiv{\bm{p}}{c_k}\right)A' Q(\bm{p})\\
  \frac{\partial}{\partial b_j} H(\bm{p}) & = A' Q(\bm{p})A \text{diag}\left(\pderiv{\bm{p}}{b_j}\right)(I_K - H(\bm{p}))\\
  \frac{\partial}{\partial c_k} H(\bm{p}) & = A' Q(\bm{p})A \text{diag}\left(\pderiv{\bm{p}}{c_k}\right)(I_K - H(\bm{p}))\\
\end{align*}
This implies that the elements of the Hessian matrix are:
\begin{align*}
  \frac{\partial}{\partial b_j}\nabla_{\bm{b}} p_{Lk}^\eta(\bm{b}, \bm{c}) & = A_{\cdot k}' Q(\bm{p}^\eta_L)\pderiv{p_{Lk}^\eta}{b_j} - Q(\bm{p}^\eta_L)A \text{diag}\left(\pderiv{\bm{p}^\eta}{b_j}\right)A' Q(\bm{p}^\eta_L)A_{\cdot k} p_k^\eta\\
  \frac{\partial}{\partial c_{k'}}\nabla_{\bm{b}} p_{Lk}^\eta(\bm{b}, \bm{c}) & = A_{\cdot k}' Q(\bm{p}^\eta_L)\pderiv{p_{Lk}^\eta}{c_{k'}} - Q(\bm{p}^\eta_L)A \text{diag}\left(\pderiv{\bm{p}^\eta}{c_{k'}}\right)A' Q(\bm{p}^\eta_L)A_{\cdot k} p_k^\eta\\
  \frac{\partial}{\partial b_j}\nabla_{\bm{c}} p_{Lk}^\eta(\bm{b}, \bm{c}) & =\eta \pderiv{p_{Lk}^\eta}{b_j} \bm{e}_k' (I - H(\bm{p}^\eta_L))  - \eta p_{Lk}^\eta \bm{e}_k' A' Q(\bm{p}^\eta_L) A \text{diag}\left(\pderiv{\bm{p}}{b_j}\right)(I_K - H(\bm{p}_L^\eta)) \\
  \frac{\partial}{\partial c_{k'}}\nabla_{\bm{c}} p_{Lk}^\eta(\bm{b}, \bm{c}) & =\eta \pderiv{p_{Lk}^\eta}{c_{k'}} \bm{e}_k' (I - H(\bm{p}^\eta_L))  - \eta p_{Lk}^\eta \bm{e}_k' A' Q(\bm{p}^\eta_L) A \text{diag}\left(\pderiv{\bm{p}}{c_{k'}}\right)(I_K - H(\bm{p}_L^\eta)), \\
\end{align*}
where $\bm{e}_k$ is the $k$-th standard basis vector in $\R^K$.
Putting these together, the Hessian matrix is equal to
\[
  \left[\begin{array}{c c c c}
    \nabla^2_{\bm{b}}p_{Lk}^\eta(\bm{b}, \bm{c}) & \nabla^2_{\bm{b},\bm{c}}p_{Lk}^\eta(\bm{b}, \bm{c})\\
    \nabla^2_{\bm{c},\bm{b}}p_{Lk}^\eta(\bm{b}, \bm{c}) & \nabla^2_{\bm{c}}p_{Lk}^\eta(\bm{b}, \bm{c})\\
  \end{array}\right],
\]
where the sub-matrices are defined as follows:
\begin{align*}
  \nabla^2_{\bm{b}}p_{Lk}^\eta(\bm{b}, \bm{c}) & =  Q(\bm{p}^\eta_L)A_{\cdot k} (\nabla_{\bm{b}} p_{Lk}^\eta)' - \left(\nabla_{\bm{b}} \bm{p}_L^\eta \odot \bm{1}_J \left(A'Q(\bm{p}_L^\eta)A_{\cdot k} p_{Lk}^\eta\right)\right) A'Q(\bm{p}_L^\eta)\\
  \nabla^2_{\bm{c},\bm{b}}p_{Lk}^\eta(\bm{b}, \bm{c}) & = Q(\bm{p}^\eta_L) A_{\cdot k} (\nabla_{\bm{c}}  p_{Lk}^\eta)' - \left(\nabla_{\bm{c}} \bm{p}_L^\eta \odot \bm{1}_K \left(A'Q(\bm{p}_L^\eta)A_{\cdot k} p_{Lk}^\eta\right)\right) A'Q(\bm{p}_L^\eta)\\
  \nabla^2_{\bm{b}, \bm{c}}p_{Lk}^\eta(\bm{b}, \bm{c}) & = \eta \left( (I - H(\bm{p}_L^\eta)) \bm{e}_k (\nabla_{\bm{b}} p_{Lk}^\eta)'  - \left(\nabla_{\bm{b}} \bm{p}_L^\eta \odot \bm{1}_J A_{\cdot k}'Q(\bm{p}_L^\eta)Ap_{Lk}^\eta\right)(I_K - H(\bm{p}_L^\eta))\right)\\
  \nabla^2_{\bm{c}}p_{Lk}^\eta(\bm{b}, \bm{c}) & = \eta \left((I - H(\bm{p}_L^\eta)) \bm{e}_k (\nabla_{\bm{c}} p_{Lk}^\eta)'   - \left(\nabla_{\bm{c}} \bm{p}_L^\eta \odot \bm{1}_J A_{\cdot k}'Q(\bm{p}_L^\eta)Ap_{Lk}^\eta\right)(I_K - H(\bm{p}_L^\eta))\right)\\
\end{align*}
where $\odot$ denotes the element-wise product, and $\bm{1}_J$ and $\bm{1}_K$ are vectors of ones of length $J$ and $K$.

From above, we have seen that $\|\nabla_{\bm{b}}\bm{p}_L^\eta(\bm{b}, \bm{c})\|_2 = O(1)$ and $\|\nabla_{\bm{c}}\bm{p}_L^\eta(\bm{b}, \bm{c})\|_2 = O(\eta)$. Similarly, because the operator norms of the various sub matrices in the Hessian including $Q(\bm{p}_L^\eta)$ and $I - H(\bm{p}_L^\eta)$ and the solutions are bounded, we have that
\begin{align*}
  \|\nabla^2_{\bm{b}}p_{Lk}^\eta(\bm{b}, \bm{c})\|_2 & \leq \|\nabla_{\bm{b}} p_{Lk}^\eta\|_2 \|A_{\cdot k}'Q(\bm{p}^\eta_L)\|_2 + \|\nabla_{\bm{b}} \bm{p}_L^\eta\|_2 \|A'Q(\bm{p}_L^\eta)A_{\cdot k} p_{Lk}^\eta\|_2 \|A_{\cdot k}'Q(\bm{p}^\eta_L)\|_2\\
  &  \leq  \|\nabla_{\bm{b}} \bm{p}_L^\eta\|_2  \|A_{\cdot k}'Q(\bm{p}^\eta_L)\|_2 (1 + \|A_{\cdot k}'Q(\bm{p}^\eta_L)\|_2  )\\
  & = O(1),
\end{align*}
and similarly,
\begin{align*}
  \|\nabla^2_{\bm{c}, \bm{b}}p_{Lk}^\eta(\bm{b}, \bm{c})\|_2 & \leq \|\nabla_{\bm{c}} \bm{p}_L^\eta\|_2  \|A_{\cdot k}'Q(\bm{p}^\eta_L)\|_2 (1 + \|A_{\cdot k}'Q(\bm{p}^\eta_L)\|_2  ) = O(\eta)\\
  \|\nabla^2_{\bm{b}, \bm{c}}p_{Lk}^\eta(\bm{b}, \bm{c})\|_2 & \leq \eta \|\nabla_{\bm{b}} \bm{p}_L^\eta\|_2 \|I_K - H(\bm{p}_L^\eta)\|_2 (1 + \|A'Q(\bm{p}_L^\eta)A_{\cdot k}p_{Lk}^\eta\|_2) = O(\eta)\\
    \|\nabla^2_{\bm{c}}p_{Lk}^\eta(\bm{b}, \bm{c})\|_2 & \leq \eta \|\nabla_{\bm{c}} \bm{p}_L^\eta\|_2 \|I_K - H(\bm{p}_L^\eta)\|_2 (1 + \|A'Q(\bm{p}_L^\eta)A_{\cdot k}p_{Lk}^\eta\|_2) = O(\eta^2).
\end{align*}
Therefore, $S_{\bm{b},\bm{c}}(\eta) \leq \|\nabla^2_{\bm{b}}p_{Lk}^\eta(\bm{b}, \bm{c})\|_2 + \|\nabla^2_{\bm{c}}p_{Lk}^\eta(\bm{b}, \bm{c})\|_2 + \|\nabla^2_{\bm{b},\bm{c}}p_{Lk}^\eta(\bm{b}, \bm{c})\|_2 + \|\nabla^2_{\bm{c},\bm{b}}p_{Lk}^\eta(\bm{b}, \bm{c})\|_2 = O(\eta^2)$.




  Next, we control the second part of the decomposition, term ($\ast\ast$), again following \citet{kennedy_semiparametric_2024}, Lemma 1. Specifically, we can write
  \begin{align*}
    h(O) & = \<\bm{c}(X) + \bm{\varphi}^{(c)}(O), \bm{p}_L^\eta(X)\> + \<\bm{c}(X), \nabla_{\bm{b}} \bm{p}^\eta_L(X) \bm{\varphi}^{(b)}(O) + \nabla_{\bm{c}} \bm{p}^\eta_L(X) \bm{\varphi}^{(c)}(O)\>\\
    \hat{h}(O) & =\<\hat{\bm{c}}(X) + \bm{\varphi}^{(c)}(O), \hat{\bm{p}}_L^\eta(X)\> + \<\hat{\bm{c}}(X), \nabla_{\bm{b}} \hat{\bm{p}}^\eta_L(X) \hat{\bm{\varphi}}^{(b)}(O) + \nabla_{\bm{c}} \hat{\bm{p}}^\eta_L(X) \hat{\bm{\varphi}}^{(c)}(O)\>.
  \end{align*}
  Then we decompose the difference into
  \begin{align*}
    \hat{h}(O) - h(O) & = \left\<\hat{\bm{c}}(X) + \bm{\varphi}^{(c)}(O) - \bm{c}(X) - \bm{\varphi}^{(c)}(O), \hat{\bm{p}}_L^\eta(X)\right\>\\
    & \quad + \left\<\bm{c}(X) + \bm{\varphi}^{(c)}(O), \hat{\bm{p}}_L^\eta(X)  - \bm{p}_L^\eta(X)\right\>\\
    & \quad + \left\<\hat{\bm{c}}(X) - \bm{c}(X) , \nabla_{\bm{b}} \hat{\bm{p}}^\eta_L(X) \hat{\bm{\varphi}}^{(b)}(O) + \nabla_{\bm{c}} \hat{\bm{p}}^\eta_L(X) \hat{\bm{\varphi}}^{(c)}(O)\right\>\\
    & \quad + \left\<\bm{c}(X), \nabla_{\bm{b}} \hat{\bm{p}}^\eta_L(X) \hat{\bm{\varphi}}^{(b)}(O) + \nabla_{\bm{c}} \hat{\bm{p}}^\eta_L(X) \hat{\bm{\varphi}}^{(c)}(O) - \nabla_{\bm{b}} \bm{p}^\eta_L(X) \bm{\varphi}^{(b)}(O) + \nabla_{\bm{c}} \bm{p}^\eta_L(X) \bm{\varphi}^{(c)}(O)\right\>.
  \end{align*}
  Now, because each component is consistent, i.e. $\sup_{x \in \mathcal{X}}\|\hat{\bm{b}}(x) - \bm{b}(x)\|_\infty = o_p(1)$ and $\sup_{x \in \mathcal{X}}\|\hat{\bm{c}}(x) - \bm{c}(x)\|_\infty = o_p(1)$, which implies that $\sup_{x \in \mathcal{X}}\|\hat{\bm{p}}_L^\eta(x) - \bm{p}_L^\eta(x)\|_\infty = o_p(1)$, and both $\sup_{o \in \mathcal{O}}\|\hat{\bm{\varphi}}^{(b)}(x) - \bm{\varphi}^{(b)}(o)\|_\infty = o_p(1)$ $\sup_{o \in \mathcal{O}}\|\hat{\bm{\varphi}}^{(c)}(x) - \bm{\varphi}^{(c)}(o)\|_\infty = o_p(1)$, we have that $\sup_{o \in \mathcal{O}}\|\hat{h}(o) - h(o)\|_\infty = o_p(1)$ and so term ($\ast\ast$) is $o_p(\frac{1}{\sqrt{n}})$. This gives the first result.

\end{proof}

\begin{proof}[Proof of Corollary~\ref{cor:entropic_est_approx}]


  We compare $\hat{\theta}^\eta_L$ to $\theta_L$. Following the same logic as in the proof of Theorem~\ref{thm:entropic_est_rate}, we can decompose the difference as
  \begin{align*}
    \hat{\theta}^\eta_L - \theta_L & = \tilde{\theta}^\eta_L - \E[\tilde{\theta}^\eta_L]\\
    & \quad  + \E[\hat{\theta}^\eta_L] - \theta^\eta_L \tag{$\ast$}\\
    & \quad + (\hat{\theta}^\eta_L - \E[\hat{\theta}^\eta_L]) - (\tilde{\theta}^\eta_L - \E[\tilde{\theta}^\eta_L]) \tag{$\ast\ast$}\\
    & \quad + \E[\tilde{\theta}^\eta_L] - \theta_L \tag{$\ast\ast\ast$}
  \end{align*}
  We have already controlled the terms ($\ast)$ and ($\ast\ast$) above, and so we need only control the term ($\ast\ast\ast$). Denote $\bm{p}_L(x) \in \argmin_{\bm{p} \in \mathcal{P}(x)} \<\bm{c}(x), \bm{p}\>$, as a solution to the conditonal linear program without the entropic regularization. Then we can write term $(\ast\ast\ast)$ as
  \begin{align*}
    (\ast\ast\ast)& = \E\left[\frac{1}{n}\sum_{i=1}^n \<\bm{c}(X_i) + \bm{\varphi}^{(c)}(O_i), \bm{p}_L^\eta(X_i)\> + \<\bm{c}(X_i), \nabla_{\bm{b}} \bm{p}^\eta_L(X_i) \bm{\varphi}^{(b)}(O_i) + \nabla_{\bm{c}} \bm{p}^\eta_L(X_i) \bm{\varphi}^{(c)}(O_i)\>\right] - \theta_L\\
    & = \E\left[\frac{1}{n}\sum_{i=1}^n \<\bm{c}(X_i), \bm{p}_L^\eta(X_i)\>\right] - \theta_L\\
    & =  \E\left[\frac{1}{n}\sum_{i=1}^n \<\bm{c}(X_i), \bm{p}_L^\eta(X_i)\> - \<\bm{c}(X_i), \bm{p}_L(X_i)\>\right]
  \end{align*}


  From Theorem 5 in \citet{weed_explicit_2018}, we have that
   if $\eta \geq \frac{R_1(X_i) + R_H(X_i)}{\Delta_L(X_i)}$ for all $i=1,\ldots,n$,  such that $\Delta_L(X_i) > 0$ then
  \begin{align*}
    0 \leq \<\bm{c}(X_i), \bm{p}_L^\eta(X_i)\>  - \<\bm{c}(X_i), \bm{p}_L(X_i)\> & \leq \Delta_L(X_i) \exp\left(-\eta \frac{\Delta_L(X_i)}{R_1(X_i)} + \frac{R_1(X_i) + R_H(X_i)}{R_1(X_i)}\right)\\
  \end{align*}

  This implies that
  \begin{align*}
    0  \leq (\ast\ast\ast) & \leq \E\left[\frac{1}{n}\sum_{i=1}^n \Delta_L(X_i) \exp\left(-\eta \frac{\Delta_L(X_i)}{R_1(X_i)} + \frac{R_1(X_i) + R_H(X_i)}{R_1(X_i)}\right)\right]\\
     & = \E\left[\Delta_L(X) \exp\left(-\eta \frac{\Delta_L(X)}{R_1(X)} + \frac{R_1(X) + R_H(X)}{R_1(X)}\right)\right]\\
     & = O(e^{-\eta})
  \end{align*}
  Combining this with the first result gives the second result.

\end{proof}

\begin{proof}[Proof of Corollary~\ref{cor:entropic_est_approx_margin}]
  From Theorem~\ref{thm:entropic_est_rate}, it suffices to control the difference $\theta_L^\eta - \theta_L$.
  Note that we can decompose this difference into the difference when $\eta$ is larger than $\frac{R_1(x) + R_H(x)}{\Delta_L(x)}$ and when $\eta$ is smaller than this value:
  \begin{align*}
    \theta_L^\eta - \theta_L & = \E\left[\< \bm{c}(X), \bm{p}_L^\eta(X)\> - \<\bm{c}(X), \bm{p}_L(X)\>\right]\\
    & = \E\left[\left(\< \bm{c}(X), \bm{p}_L^\eta(X)\> - \<\bm{c}(X), \bm{p}_L(X)\>\right) \bbone\left\{\eta \geq \frac{R_1(X) + R_H(X)}{\Delta_L(X)}\right\}\right] \tag{i}\\
    & + \E\left[\left(\< \bm{c}(X), \bm{p}_L^\eta(X)\> - \<\bm{c}(X), \bm{p}_L(X)\>\right) \bbone\left\{\eta < \frac{R_1(X) + R_H(X)}{\Delta_L(X)}\right\}\right] \tag{ii}\\
  \end{align*}

  Since the hyperparameter is large relative to the margin in the first term (i), from Theorem 5 in \citet{weed_explicit_2018}, we have that
  \[
    (i) \leq \E\left[\Delta_L(X) \exp\left(-\eta \frac{\Delta_L(x)}{R_1(X)} + \frac{R_1(X) + R_H(X)}{R_1(X)}\right)\right] = O(e^{-\eta}).
  \]
  For the second term (ii), the sub-optimality gap is small relative to the inverse of $\eta$, $\Delta_L(X) < \frac{R_1(X) + R_H(X)}{\eta}$.
  Note that when $\Delta_L(X) = 0$, then $\<\bm{c}(X), \bm{p}_L^\eta(X)\> = \<\bm{c}(X), \bm{p}_L(X)\>$, and
  so by Proposition 4 in \citet{weed_explicit_2018}, and the margin condition in Assumption~\ref{a:margin}, we have that
\begin{align*}
  (ii) & \leq \E\left[\left(\frac{R_H(X)}{\eta}\bbone\left\{0 < \Delta_L(X) < \frac{R_1(X) + R_H(X)}{\eta}\right\}\right)\right]\\
  & \leq \frac{\sup_{x \in \mathcal{X}} R_H(x)}{\eta} P\left(0 < \Delta_L(X) \leq \frac{R_1(X) + R_H(X)}{\eta}\right)\\
  & \lesssim \frac{1}{\eta^{1 + \alpha}} = O\left(\eta^{-(1 + \alpha)}\right).
\end{align*}
Putting together the pieces gives the result.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:primal_policy}]
  First, note that we can write the excess regret as
  \begin{align*}
    \theta_L(\pi^\ast) - \theta_L(\hat{\pi}) &= \theta_L(\pi^\ast) - \hat{\theta}_L(\pi^\ast) + \hat{\theta}_L(\pi^\ast) - \hat{\theta}_L(\hat{\pi}) + \hat{\theta}_L(\hat{\pi}) - \theta_L(\pi^\ast)\\
    & \leq \theta_L(\pi^\ast) - \hat{\theta}_L(\pi^\ast) + \hat{\theta}_L(\hat{\pi}) - \theta_L(\pi^\ast)\\
    & \leq 2 \sup_{\pi \in \Pi} \left|\hat{\theta}_L(\pi) - \theta_L(\pi)\right|\\
    & \leq 2\sup_{\pi \in \Pi} \left|\hat{\theta}_L(\pi) - \E[\theta_L(\pi)]\right| + 2\sup_{\pi \in \Pi} \left|\E[\hat{\theta}_L(\pi)] - \E[\theta_L(\pi)]\right|,
  \end{align*}
  where the first inequality follows from the fact that $\hat{\pi}$ maximizes $\hat{\theta}_L(\pi)$ so $\hat{\theta}_L(\hat{\pi}) \geq \hat{\theta}_L(\pi^\ast)$.
  Note that $\hat{\theta}_L(\pi) - \E[\theta_L(\pi)]$ is a mean-zero empirical process indexed by the policy $\pi$.
  Defining the function $f_\pi(o) =  \left\< \bm{c}(x, \pi(x)), A_{\widehat{B}_L(x, \pi(x))}^{-1} \left(\hat{\bm{b}}(x) + \hat{\bm{\varphi}}^{(b)}(o)\right)\right\>$, and the function class $\mathcal{F} = \{f_\pi: \pi \in \Pi\}$, we can write the first term in the decomposition above as
  \[
    \sup_{\pi \in \Pi} \left|\hat{\theta}_L(\pi) - \E[\theta_L(\pi)]\right| = \sup_{f \in \mathcal{F}} \left|\frac{1}{n}\sum_{i=1}^n f(O_i) - \E[f(O)]\right|.
  \]
  By the regularity conditions in Assumption~\ref{a:regularity}, the function class $\mathcal{F}$ is uniformly bounded, i.e. $\|f_\pi\|_\infty \leq\tilde{C}$ for some $\tilde{C}$, for all $\pi \in \Pi$. Therefore, by Theorem 4.2 in \citet{wainwright_2019}, we have that
  \[
    \sup_{f \in \mathcal{F}} \left|\frac{1}{n}\sum_{i=1}^n f(O_i) - \E[f(O)]\right| \leq 2 \mathcal{R}_n(\mathcal{F}) + \tilde{C} \sqrt{\frac{2 \log(1/\delta)}{n}},
  \]
  with probability at least $1-\delta$. To link the Rademacher complexity of the function class $\mathcal{F}$ to the Rademacher complexity of the policy class $\Pi$, we note that $f$ is a Lipschitz function of $\pi$. To see this, note that by strong duality, the basis $\widehat{B}_L(x, \pi(x))$ corresponding to the optimal BFS also yields an optimal basis for the solution to the dual problem
  \[
    A_{\widehat{B}_L(x, \pi(x))}^{-1\prime}\bm{c}(x, \pi(x)) \in \argmax_{\bm{\lambda} \in \R^J} \<\bm{\lambda}, \hat{\bm{b}}(x)\> \quad \text{s.t. } A'\bm{\lambda} \leq \bm{c}(x, \pi(x)).
  \]
  \citet{mangasarian_lipschitz_1987} show the the solution to this linear program is Lipschitz continuous in the objective vector $\bm{c}(x, \pi(x))$. So, because $\bm{c}(x, \pi(x))$ is Lipschitz continuous in $\pi(x)$, so we have that $A_{\widehat{B}_L(x, \pi(x))}^{-1\prime}\bm{c}(x, \pi(x))$ is Lipschitz continuous in $\pi(x)$. Furthermore, $f_\pi(o)$ is a linear function of $A_{\widehat{B}_L(x, \pi(x))}^{-1\prime}\bm{c}(x, \pi(x))$, so it is also Lipschitz continuous in $\pi(x)$. By the Talagrand contraction principle \citep[e.g. see, Theorem 4.12][]{ledoux_probability_1991}, we have that the Rademacher complexity of the function class $\mathcal{F}$ is bounded by the Rademacher complexity of the policy class $\Pi$, $\mathcal{R}_n(\mathcal{F}) \lesssim \mathcal{R}_n(\Pi)$.

  It remains to bound the second term in the decomposition of the excess regret, $\sup_{\pi \in \Pi} \left|\E[\hat{\theta}_L(\pi)] - \E[\theta_L(\pi)]\right|$. Note that under the strong margin condition in Assumption~\ref{a:margin_strong}, we can directly apply Lemma~\ref{lem:primal_est_bias} to obtain that 
  \[
  \sup_{\pi \in \Pi} \left|\E[\hat{\theta}_L(\pi)] - \E[\theta_L(\pi)]\right| = O_p\left(\|\hat{\bm{b}} - \bm{b}\|_\infty^{1 + \alpha} + r_n\right).
  \]
  Putting together the pieces gives the result.

\end{proof}





\begin{proof}[Proof of Theorem~\ref{thm:entropic_policy}]
  We begin by considering the entropic lower bound. Note that
  \begin{align*}
    \theta_L^\eta(\pi^\ast_\eta) - \theta_L^\eta(\hat{\pi}^\eta) & = \theta_L^\eta(\pi^\ast_\eta) - \hat{\theta}_L^\eta(\pi^\ast_\eta) + \hat{\theta}_L^\eta(\pi^\ast_\eta) - \hat{\theta}_L^\eta(\hat{\pi}^\eta) + \hat{\theta}_L^\eta(\hat{\pi}^\eta) - \theta_L^\eta(\hat{\pi}^\eta)\\
    & \leq \theta_L^\eta(\pi^\ast_\eta) - \hat{\theta}_L^\eta(\pi^\ast_\eta) + \hat{\theta}_L^\eta(\hat{\pi}^\eta) - \theta_L^\eta(\hat{\pi}^\eta)\\
    & \leq 2 \sup_{\pi \in \Pi} \left|\hat{\theta}_L^\eta(\pi) - \theta_L^\eta(\pi)\right|\\
    & \leq 2\sup_{\pi \in \Pi} \left|\hat{\theta}_L^\eta(\pi) - \E\left[\hat{\theta}_L^\eta(\pi)\right]\right| + 2\sup_{\pi \in \Pi} \left|\E\left[\hat{\theta}_L^\eta(\pi)\right] - \theta_L^\eta(\pi)\right|,
  \end{align*}
  where the first inequality follows from the fact that $\hat{\pi}^\eta$ maximizes $\hat{\theta}_L^\eta(\pi)$.

  For the first term, define the function $f_\pi(o) = \<\bm{c}(x, \pi(x)), \hat{\bm{p}}_L^\eta(x, \pi(x)) +  \nabla_{\bm{b}} \hat{\bm{p}}_L^\eta(x, \pi(x)) \hat{\bm{\varphi}}^{(b)}(o)\>$, adn the function class $\mathcal{F} = \{f_\pi \mid \pi \in \Pi\}$. Assumption \ref{a:regularity} ensures that $\mathcal{F}$ is uniformly bounded, and so as with the proof of Theorem~\ref{thm:primal_policy} by Theorem 4.2 in \citet{wainwright_2019}, we have that
  \[
    \sup_{f \in \mathcal{F}} \left|\frac{1}{n}\sum_{i=1}^n f(O_i) - \E[f(O)]\right| \leq 2 \mathcal{R}_n(\mathcal{F}) + \tilde{C} \sqrt{\frac{2 \log(1/\delta)}{n}},
  \]
  with probability at least $1-\delta$. In the proof of Theorem~\ref{thm:entropic_est_rate}, we have shown that the operator norm of the Jacobian of the entropic solution with respect to the objective is bounded by a constant times $\eta$, i.e. $\|\nabla_{\bm{c}} \bm{p}_L^\eta(\bm{b}, \bm{c})\|_2 \lesssim \eta$, and have similarly shown this for the operator norm of the Hessian, $\|\nabla^2_{\bm{c}, \bm{b}} p_{Lk}^\eta(\bm{b}, \bm{c})\|_2 \lesssim \eta$. By Assumption~\ref{a:regularity}, the objective function $\bm{c}(x, \pi(x))$ is Lipschitz continuous in $\pi(x)$, and so $\bm{p}(\bm{b}, \bm{c}(x, \pi(x)))$ and $\nabla_{\bm{b}} \bm{p}(\bm{b}, \bm{c}(x, \pi(x)))$ are Lipschitz continuous in $\pi(x)$ for any $x$ as well, with a Lipschitz constant scaling with $\eta$. So by Talagrand's contraction principle we have that the Rademacher complexity of $\mathcal{F}$ is bounded by $\mathcal{R}_n(\mathcal{F}) \lesssim \eta \mathcal{R}_n(\Pi)$.
  To complete the first claim we must bound the second term in the decomposition above, $\sup_{\pi \in \Pi} \left|\E\left[\hat{\theta}_L^\eta(\pi)\right] - \theta_L^\eta(\pi)\right|$. We can do so by directly applying Lemma~\ref{lem:entropic_est_bias} and the bounds on $S_{\bm{b}}(\eta)$ and $S_{\bm{b},\bm{c}}(\eta)$ from the proof of Theorem~\ref{thm:entropic_est_rate} for each $\pi \in \Pi$ to obtain that
  \[
    \sup_{\pi \in \Pi} \left|\E\left[\hat{\theta}_L^\eta(\pi)\right] - \theta_L^\eta(\pi)\right| = O_p\left(r_n + \eta^2 \|\hat{\bm{b}} - \bm{b}\|_2^2\right),
  \]
  noting that the objective vector $\bm{c}(x, \pi(x))$ is known in this case.

  For the second claim, we can similarly write the excess regret as
    \begin{align*}
    \theta_L(\pi^\ast) - \theta_L(\hat{\pi}^\eta) & = \theta_L(\pi^\ast_\eta) - \hat{\theta}_L^\eta(\pi^\ast) + \hat{\theta}_L^\eta(\pi^\ast) - \hat{\theta}_L^\eta(\hat{\pi}^\eta) + \hat{\theta}_L^\eta(\hat{\pi}^\eta) - \theta_L(\hat{\pi}^\eta)\\
    & \leq \theta_L(\pi^\ast) - \hat{\theta}_L^\eta(\pi^\ast) + \hat{\theta}_L^\eta(\hat{\pi}^\eta) - \theta_L^\eta(\hat{\pi}^\eta)\\
    & \leq 2 \sup_{\pi \in \Pi} \left|\hat{\theta}_L^\eta(\pi) - \theta_L(\pi)\right|\\
    & \leq 2\sup_{\pi \in \Pi} \left|\hat{\theta}_L^\eta(\pi) - \E\left[\hat{\theta}_L^\eta(\pi)\right]\right| + 2\sup_{\pi \in \Pi} \left|\E\left[\hat{\theta}_L^\eta(\pi)\right] - \theta_L(\pi)\right|.
  \end{align*}
  We have just controlled the first term above. To control the second term we can again apply Lemma~\ref{lem:entropic_est_bias} and the argument in the proof of Corollary~\ref{cor:entropic_est_approx} for each $\pi \in \Pi$  to obtain that

  \[
    \sup_{\pi \in \Pi} \left|\E\left[\hat{\theta}_L^\eta(\pi)\right] - \theta_L(\pi)\right| = O_p\left(e^{-\eta} +  r_n + \eta^2 \|\hat{\bm{b}} - \bm{b}\|_2^2\right).
  \]
  Combining these bounds gives the result.

\end{proof}


