\section{Mathematical Appendix}\label{app:math}

\subsection{Proof of \cref{thm:concentration}}

\begin{proof}
The result broadly follows from known Hoeffding bounds for Markov chains. For clarity we restate the relevant result below\footnote{We note that \citet{fan2021hoeffding} only present a one-sided bound, but by standard symmetry arguments this immediately implies the above two-sided bound.}, using our notation and set-up. 

We first define formally the notion of an absolute spectral gap, from \cite{fan2021hoeffding}.
\begin{definition}[Absolute Spectral Gap]
Let \(\mathcal Z\) and \(\pi\) denote the state space and the invariant measure of a Markov chain \(\{Z_i\}_{i\ge1}\). For a function \(f:\mathcal Z\to\mathbb R\), write
\(
\pi(h)\;:=\;\int h(z)\,\pi(dz)
\).
Let
\(
L_2(\pi)\;=\;\{\,h : \pi(h^2)<\infty\}
\)
be the Hilbert space consisting of \(\pi\)-square-integrable functions, and
\(
L_2^0(\pi)\;=\;\{\,h\in L_2(\pi) : \pi(h)=0\}
\)
be its subspace of \(\pi\)\nobreakdash-mean\-zero functions. The transition probability kernel of the Markov chain, denoted by \(P\), is viewed as an operator acting on \(L_2(\pi)\). Let \(\lambda\in[0,1]\) be the operator norm of \(P\) acting on \(L_2^0(\pi)\). Then, \(1-\lambda\) is the \emph{absolute spectral gap} of the Markov chain.
\end{definition}

\begin{proposition}[Hoeffding Bound for Markov Chains - Theorem 1 in \citet{fan2021hoeffding}]\label{prop:hoeffding_markov}
    Let $(Z_i)_{i \geq 1}$ be a Markov Chain with measurable state space $\mc Z$, stationary distribution $\pi$, and absolute spectral gap $1-\lambda \in (0,1]$. Let $f: \mathcal Z \to [0,B]$ be measurable and bounded. Then, for any $\epsilon > 0$,
    \begin{align}
        \bb P_\pi\left(\left |\sum_{i=1}^n f(Z_i) - n\bb E_\pi f(Z_1) \right |\geq \epsilon\right) \leq 2  \exp \left(-\frac{1-\lambda}{1+\lambda}\frac{2\epsilon^2}{B^2} \right)
    \end{align}
    where $1-\lambda$ is the absolute spectral gap of $\pi$. 
\end{proposition}


Now we are ready to prove our results. We start with $C_0(m,n)$. First, note that since $(\bm X_{i,j},N_{i,j})_{i\geq 1}$ is a Markov chain with stationary distribution $\pi$ for every chain $j$, then $(\{\bm X_{i,j},N_{i,j}\}_{j=1}^m)_{i\geq 1}$ is also a Markov chain with stationary distribution $\pi^m := \pi \otimes \pi \underbrace{\otimes...\otimes}_{m-1} \pi$, because the chains are independent. Therefore, if we set $Z_i := \{\bm X_{i,j},N_{i,j}\}_{j=1}^m$ and $f(Z_i) := \max_{j \in [m]}(N_{i,j}) \in [0,B]$, we get by an application of \cref{prop:hoeffding_markov} that 

\begin{align}
    \bb P_\pi\left(\left |\sum_{i=1}^n \max_{j \in [m]}(N_{i,j}) - n\bb E_\pi \max_{j \in [m]}(N_{1,j}) \right |\geq \epsilon\right) \leq 2  \exp \left(-\frac{1-\lambda}{1+\lambda}\frac{2\epsilon^2}{nB^2} \right)
\end{align}

Setting $\delta = 2  \exp \left(-\frac{1-\lambda}{1+\lambda}\frac{2\epsilon^2}{nB^2} \right)$ and re-arranging, we get that with probability $1-\delta$ (under the stationary distribution $\pi$),
\begin{align}
     \left|\sum_{i=1}^n \max_{j \in [m]}(N_{i,j}) - n\bb E_\pi \max_{j \in [m]}(N_{1,j}) \right | \leq B\sqrt{\frac{n(1+\lambda)}{2(1-\lambda)}\ln\left( \frac{2}{\delta}\right)}
\end{align}

Multiplying by $B_0(m)$ and dividing by $n$ on both sides, and adding and subtracting $A_0(m)$ from the LHS gives us the result for $C_0$

\begin{align}
     \left|B_0(m)\frac{1}{n}\sum_{i=1}^n \max_{j \in [m]}(N_{i,j}) - B_0(m)\bb E_\pi \max_{j \in [m]}(N_{1,j}) \right | & \leq B_0(m)B\sqrt{\frac{(1+\lambda)}{2n(1-\lambda)}\ln\left( \frac{2}{\delta}\right)} \\
      \left|B_0(m)\frac{1}{n}\sum_{i=1}^n \max_{j \in [m]}(N_{i,j}) \pm A_0(m) - B_0(m)\bb E_\pi \max_{j \in [m]}(N_{1,j}) \right | & \leq B_0(m)B\sqrt{\frac{(1+\lambda)}{2n(1-\lambda)}\ln\left( \frac{2}{\delta}\right)} \\
      \left|C_0(m,n) - A_0(m) - B_0(m)\bb E_\pi \max_{j \in [m]}(N_{1,j}) \right | & \leq B_0(m)B\sqrt{\frac{(1+\lambda)}{2n(1-\lambda)}\ln\left( \frac{2}{\delta}\right)}
\end{align}
Now we follow similar steps for $C_F(m,n)$. To start, we bound the distance from $\max_{j \in m} \frac{1}{n} \sum_{i=1}^nN_{i,j}$ and $\bb E_\pi[N_{11}]$ in terms of a sum of individual distances using the union bound.

\begin{align}
    \bb P_{\pi}\left(\left| \max_{j \in m} \frac{1}{n} \sum_{i=1}^nN_{i,j} - \bb E_\pi N_{11} \right|\geq \epsilon \right) & = \bb P_{\pi}\left( \max_{j \in m} \frac{1}{n} \sum_{i=1}^nN_{i,j} - \bb E_\pi N_{11} \geq \epsilon \right) \nonumber \\
    & \qquad + \bb P_{\pi}\left( \max_{j \in m} \frac{1}{n} \sum_{i=1}^nN_{i,j} - \bb E_\pi N_{11} \leq -\epsilon \right) \\
    & = \bb P_\pi \left(\bigcup_{j =1}^m \left\{\frac{1}{n}\sum_{i=1}^n N_{i,j} - \bb E_\pi N_{11} \geq \epsilon\right\} \right) \nonumber \\
   & \qquad  + \bb P_\pi \left(\bigcup_{j =1}^m \left\{\frac{1}{n}\sum_{i=1}^n N_{i,j} - \bb E_\pi N_{11} \leq -\epsilon\right\} \right) \\
    & \leq \sum_{j=1}^m\Bigg[ \bb P_\pi \left(\frac{1}{n}\sum_{i=1}^n N_{i,j} - \bb E_\pi N_{11} \geq \epsilon \right) \nonumber\\
   & \qquad + \bb P_\pi \left(\frac{1}{n}\sum_{i=1}^n N_{i,j} - \bb E_\pi N_{11} \leq -\epsilon\right) \Bigg] \\
    & = \sum_{j=1}^m \bb P_\pi \left(\left|\frac{1}{n}\sum_{i=1}^n N_{i,j} - \bb E_\pi N_{11} \right|\geq \epsilon \right) \\
    & = m\bb P_\pi \left(\left|\frac{1}{n}\sum_{i=1}^n N_{i,1} - \bb E_\pi N_{11} \right|\geq \epsilon \right) \\
    & = m\bb P_\pi \left(\left|\sum_{i=1}^n N_{i,1} - n\bb E_\pi N_{11} \right|\geq n\epsilon \right)
\end{align}

Applying \cref{prop:hoeffding_markov} on the Markov Chain $(\bm X_{1,i},N_{1,i})_{i \geq 1}$ with  $f(\bm X_{1,i},N_{1,i}) = N_{1,i} \in [0,B]$ and following the same steps as for $C_0(m,n)$, we similarly recover
\begin{align}
      \left|C_F(m,n) - A_F(m) - B_F(m)\bb E_\pi \max_{j \in [m]}(N_{1,j}) \right | & \leq B_F(m)B\sqrt{\frac{(1+\lambda)}{2n(1-\lambda)}\ln\left( \frac{2m}{\delta}\right)}
\end{align}
which is the result in the Theorem. 
\end{proof}


\begin{proposition}\label{prop:eff_bound}
  Fix $m,K \in \bb N \backslash\{0\}$ and let $\bb P_N$ be a probability measure on $\bb R_+$ strictly positive first moment. Suppose (i) $N_1,...,N_m \overset{iid}{\sim} \bb P_N$, (ii) $c_1(m),...,c_K(m) \geq 0$ and (iii) $\alpha \in [\max_{j \in [K]} c_j(m)/\sum_{j \in [K]} c_j(m),1]$. Then, we have   
  \begin{align}
   \text{E}(m) := \frac{c_{\neg k}(m) + c_k(m) \bb E \max_{j \in [K]}N_j}{\alpha(c_{\neg k}(m) + c_k(m))( K-1 + \bb E N_1)} \leq \frac{\bb E \max_{j \in [K]}N_j}{\bb E N_{1}} =: R(m)
   \end{align}
    where $c_{\neg k}(m) = \sum_{j \neq k}c_j(m)$. The bound is tight.

\end{proposition}

\begin{proof}
   Note $\frac{a+b}{c+d} = \frac{a}{c}\gamma + \frac{b}{d}(1-\gamma)$ where $\gamma = \frac{c}{c+d}$ for any $a,b,c,d \in \bb R$. Applying this to our case, we get 
   \begin{align}
       E(m) = \frac{c_{\neg k}(m)}{\alpha (c_{\neg k}(m)+c_k(m))(K-1)} w + \frac{c_k(m)}{\alpha(c_{\neg k}(m) + c_k(m))}R(m)(1-w) 
   \end{align}
   where $w = \frac{\alpha (c_{\neg k}(m)+c_k(m))}{\alpha (c_{\neg k}(m)+c_k(m))(K-1 + \bb E N_1)} \in [0,1]$. Now we split into two cases for $K=1$ and $K>1$. For the case $K=1$ we only have a single iterative state and so $C_{\neg k}(m) = 0$, $\alpha = 1$. In this case we trivially have $E(m) = R(m)$. Now suppose $K>1$. In this case, since $\alpha(c_{\neg k}(m) + c_k(m)) \geq \max_{j \in [K]}c_j(m)$, we have 
   \begin{align}
       \frac{c_k(m)}{\alpha(c_{\neg k}(m) + c_k(m))} \leq \frac{c_k(m)}{ \max_{j \in [K]}c_j(m)} \leq 1
   \end{align}
   Which means we can bound $E(m)$ by removing the term in front of $R(m)$,
    \begin{align}
       E(m) \leq \frac{c_{\neg k}(m)}{\alpha (c_{\neg k}(m)+c_k(m))(K-1)} w + R(m)(1-w) 
   \end{align}
   By the same logic, we have 
   \begin{align}
       \frac{c_{\neg k}(m)}{\alpha (c_{\neg k}(m)+c_k(m))(K-1)} \leq \frac{c_{\neg k}(m)}{\max_{j \in [K]}c_j(m)(K-1)} = \frac{\sum_{j \neq k}c_j(m)}{\max_{j \in [K]}c_j(m)(K-1)} \leq 1
   \end{align}
    which means
    \begin{align}
       E(m) & \leq w + R(m)(1-w)  \\
       & \leq  R(m) 
   \end{align}
   Where the last line uses the fact that $R(m) \geq 1$ since $N_1\geq 0$. The bound is tight because when $K=1$ we have $E(m) = R(m)$. This completes the proof

\end{proof}


