\section{Additional Details} \label{app:details}

\subsection{Algorithms}

Note here we use $\tilde {\bm x}$ to denote a batch of inputs $[\bm x_1,...,\bm x_m]$ for $m$ different chains, and the same for other variables.

\begin{algorithm}
\caption{Vectorized MCMC algorithm with \texttt{vmap(sample)} function}
\label{alg:standardmcmc_vec}
\begin{algorithmic}[1]
\STATE \textbf{Inputs}: sample $\tilde {\bm x}_0$, seed $\tilde r_0$ 
\FOR{$i \in \{1,...,n\}$}
\STATE generate $\tilde {\bm x}_i, \tilde r_i\gets\verb|vmap(sample)(|\tilde {\x}_{i-1},\tilde r_{i-1}\verb|)|$
\ENDFOR
\STATE \textbf{return} $\tilde {\bm x}_1,\ldots,\tilde {\bm x}_n$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{Vectorized FSM MCMC algorithm with  \texttt{vmap(step)} function}
  \label{alg:fsmmcmc_vec}

\begin{algorithmic}[1]
\STATE \textbf{input:} initial value $\tilde {\bm x}_0$, \# samples $n$
\STATE \textbf{initialize:} $\tilde z = \texttt{vmap(init)}(\tilde {\bm x}_0), \tilde X = \text{list()}, \tilde B = \text{list()}$
\STATE Set $\tilde t=0$ and $\tilde k=0$
\WHILE{$\min_{\tilde t_i \in \tilde t}\{\tilde t_i\} < n$}
\STATE $(\tilde k, \tilde z,\tilde {\texttt{isSample}}) \leftarrow \verb|vmap(step)|(\tilde k, \tilde z)$
    \STATE append current sample value $\tilde {\bm x}$ stored in $\tilde z$ to $\tilde X$
    \STATE append $\tilde {\texttt{isSample}}$ to $\tilde B$
    \STATE update sample counter $\tilde t \gets \tilde t+\tilde {\texttt{isSample}}$
\ENDWHILE
\STATE \textbf{return} $\tilde X[\tilde B]$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[H]
\caption{Transition kernel for elliptical slice sampler with log-pdf $\log p$, covariance matrix $\Sigma$.}
\label{alg:ellip_kernel}
\begin{algorithmic}[1]
\STATE \textbf{Input:} Sample $\bm x$
\STATE Choose ellipse $\bm \nu \sim \mc N(\bm 0, \Sigma)$
\STATE Set threshold $\log y \gets \log p(\bm x) + \log u : u \sim \mc U[0,1]$
\STATE Set bracket $[\theta_\text{min}, \theta_\text{max}]\gets [\theta - 2\pi, \theta] : \theta \sim \mc U[0,2\pi]$
\STATE Make proposal $\bm x' \gets \bm x \cos \theta + \bm \nu \sin \theta$
\WHILE{$\log p(\bm x') > \log y$}
    \STATE Shrink bracket and update proposal:
     \IF{$\theta < 0$} 
     \STATE  $\theta_{\min} \gets \theta$
     \ELSE  
     \STATE $\theta_{\max} \gets \theta$
     \ENDIF
     \STATE $\bm x' \gets \bm x \cos \theta + \bm \nu \sin \theta : \theta \sim \mc U[\theta_{\min}, \theta_{\max}]$
\ENDWHILE
\STATE \textbf{Return} $\bm x'$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{\texttt{bundled\_step} as input to \texttt{amortized\_step}.}
\label{alg:fsm_step_bundled_amortized}
\begin{algorithmic}[1]
\STATE \textbf{Input:} Algorithm state $k$, variables $z$
\STATE \texttt{doComputation} = False
\WHILE{\textbf{not} \texttt{doComputation}}
\STATE $(k,z, \texttt{isSample}, \texttt{doComputation})$$ \gets \texttt{step}(k,z)$
\ENDWHILE
\STATE \textbf{Return} $(k,z, \texttt{isSample},\texttt{doComputation})$
\end{algorithmic}
\end{algorithm}
