\begin{algorithm}
\caption{Gathering meaningful children}
\begin{algorithmic}[1]
\STATE \textbf{function} \textsc{gather\_children}(\textit{node}) \textbf{returns} list of Node
\STATE \quad all\_children $\gets$ $\cup$ \textsc{map}(\textsc{gather\_children}, node.children)
