    \STATE \quad \textbf{return} all\_children \COMMENT{Discard the node, and only return the children}
\ELSE
    \STATE \quad \textbf{return} [Node(node.type, all\_children)]
\ENDIF
\STATE \textbf{end function}
\end{algorithmic}
\end{algorithm}


