\begin{algorithm}
\caption{Collapsing empty states}
\label{alg:collapse-empty-states}
\begin{algorithmic}[1]
\STATE \textbf{function} \textsc{collapse\_empty\_states}(fsm) \textbf{returns} FSM
\STATE \quad edges $\gets$ fsm.edges
\STATE \quad labels $\gets$ fsm.labels
\FORALL{node \textbf{in} \textsc{filter}(\textsc{empty} $\lvert$ \textsc{Not initial} $\lvert$  \textsc{Not final}, fsm.nodes)}
    \IF{node $\in$ node.children}
        \STATE \quad \textbf{continue}
    \ENDIF
    \FORALL{parent, child \textbf{in} \textsc{product}(node.parents, node.children)}
        \STATE \quad new\_edge $\gets$ (parent, child)
        \IF{new\_edge $\in$ edges}
            \STATE \quad \textbf{error} \COMMENT{Edge already exists}
        \ENDIF
        \STATE \quad new\_label $\gets$ \textsc{AND}(parent.label, child.label)
        \IF{\textsc{Impossible}(new\_label)}
            \STATE \quad \textbf{continue}
        \ENDIF
        \STATE \quad edges $\gets$ edges $\cup$ \{new\_edge\}
        \STATE \quad labels $\gets$ labels $\cup$ \{new\_label\}
    \ENDFOR
\ENDFOR
\STATE \quad nodes $\gets$ \textsc{filter}(\textsc{non\_empty}, fsm.nodes)
\STATE \quad \textbf{return} FSM(nodes, edges, labels)
\STATE \textbf{end function}
\end{algorithmic}
\end{algorithm}

